.loading-container {
    text-align: center;
}

.circle-loader {
    position: relative;
    width: 150px;
    height: 150px;
    animation: rotate-ring 3s linear infinite;
}

.ball-loader {
    display: flex;
    gap: 15px;
    justify-content: center;
    align-items: center;
}

.ball {
    font-size: 28px;
    color: white;
    animation: bounce 0.6s ease-in-out infinite;
    animation-delay: calc(var(--i) * 0.15s);
}

@keyframes bounce {
    0%, 100% {
        transform: translateY(0);
        opacity: 0.5;
    }

    50% {
        transform: translateY(-15px);
        opacity: 1;
    }
}

.loading-text {
    margin-top: 12px;
    color: white;
    font-size: 18px;
    text-align: center;
}



