/* Updated styling with class name .h2h-table */
.h2h-table {
    display: grid;
    grid-template-columns: auto; /* Single column */
    column-gap: 20px; /* Adjust the gap between columns */
}

    .h2h-table .match-info {
        list-style: none;
        padding: 0;
        display: flex;
        flex-direction: column;
        align-items: center; /* Align items at the center */
    }

        .h2h-table .match-info li {
            margin-bottom: 10px; /* Adjust the spacing between matches */
        }

        .h2h-table .match-info span {
            display: block;
        }

