.checkmark {
    display: inline-block;
    width: 100%;
    height: 100%;
    border: 5px solid limegreen;
    border-radius: 50%;
    position: relative;
    animation: scaleCircle 2s ease-in-out forwards;
}

    .checkmark::after {
        content: '';
        position: absolute;
        width: 20px;
        height: 30px;
        border: solid limegreen;
        border-width: 0 5px 5px 0;
        transform: rotate(45deg);
        opacity: 0;
        animation: drawTick 2s ease-in-out forwards;
        left: 15px;
        top: 8px;
    }

@keyframes scaleCircle {
    0% {
        transform: scale(0);
    }

    100% {
        transform: scale(1);
    }
}


@keyframes drawTick {
    0% {
        opacity: 0;
        transform: rotate(45deg) scale(0);
    }

    100% {
        opacity: 1;
        transform: rotate(45deg) scale(1);
    }
}

