/* =========================================================
   SWIFTCARE — SOFT GREEN BACKGROUND + STRONG LIME GLASS
   NO WHITE TEXT
   ========================================================= */

.swiftcare-page {
    --forest: #174d2b;
    --forest-light: #1f6337;
    --forest-deep: #10351f;
    /* STRONGER, MORE READABLE LIME */
    --lime: #9bea20;
    --lime-bright: #aaff2f;
    --lime-soft: #c7f86a;
    --lime-deep: #6fae0f;
    /* LIGHT GLASS */
    --glass: rgba(255, 255, 255, 0.72);
    --glass-hover: rgba(255, 255, 255, 0.88);
    --glass-border: rgba(23, 77, 43, 0.18);
    /* DARK READABLE TEXT */
    --text: #174d2b;
    --muted: #355943;
    position: relative;
    min-height: 100vh;
    overflow: hidden;
    color: var(--text);
    /* SOFT GREEN BACKGROUND */
    background: radial-gradient( circle at 10% 5%, rgba(155, 234, 32, 0.25), transparent 25% ), radial-gradient( circle at 90% 20%, rgba(155, 234, 32, 0.19), transparent 28% ), radial-gradient( circle at 50% 100%, rgba(31, 99, 55, 0.12), transparent 35% ), linear-gradient( 135deg, #f0f8ed 0%, #e5f3e2 45%, #edf8e9 100% );
    font-family: Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Arial, sans-serif;
}


    /* =========================================================
   GLOBAL TEXT
   ========================================================= */

    .swiftcare-page h1,
    .swiftcare-page h2,
    .swiftcare-page h3,
    .swiftcare-page h4,
    .swiftcare-page h5,
    .swiftcare-page h6 {
        color: var(--forest) !important;
    }

    .swiftcare-page p {
        color: var(--muted) !important;
    }

    .swiftcare-page a {
        color: var(--forest) !important;
    }


    /* =========================================================
   BACKGROUND TEXTURE
   ========================================================= */

    .swiftcare-page::before {
        content: "";
        position: absolute;
        inset: 0;
        pointer-events: none;
        background: linear-gradient( rgba(23, 77, 43, 0.025) 1px, transparent 1px ), linear-gradient( 90deg, rgba(23, 77, 43, 0.025) 1px, transparent 1px );
        background-size: 60px 60px;
        z-index: 0;
    }


/* =========================================================
   LIME GLOW ORBS
   ========================================================= */

.swiftcare-circle {
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
    z-index: 0;
    filter: blur(5px);
}


.swiftcare-circle-one {
    width: 500px;
    height: 500px;
    top: -250px;
    left: -180px;
    background: radial-gradient( circle, rgba(170, 255, 47, 0.38), rgba(155, 234, 32, 0.12) 45%, transparent 72% );
}


.swiftcare-circle-two {
    width: 550px;
    height: 550px;
    right: -270px;
    top: 35%;
    background: radial-gradient( circle, rgba(155, 234, 32, 0.30), rgba(155, 234, 32, 0.07) 50%, transparent 72% );
}


/* =========================================================
   CONTAINER
   ========================================================= */

.swiftcare-container {
    width: min(1320px, calc(100% - 50px));
    margin: 0 auto;
    position: relative;
    z-index: 2;
}


/* =========================================================
   HERO
   ========================================================= */

.swiftcare-hero {
    position: relative;
    min-height: 780px;
    display: flex;
    align-items: center;
    padding: 95px 0 80px;
}


.swiftcare-hero-grid {
    display: grid;
    grid-template-columns: 1fr 0.95fr;
    gap: 75px;
    align-items: center;
}


/* =========================================================
   WELCOME
   ========================================================= */

.swiftcare-welcome {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    padding: 12px 19px;
    margin-bottom: 28px;
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.70);
    border: 1px solid rgba(111, 174, 15, 0.30);
    backdrop-filter: blur(18px);
    -webkit-backdrop-filter: blur(18px);
    color: var(--forest) !important;
    font-size: 15px;
    font-weight: 800;
    box-shadow: 0 10px 30px rgba(23, 77, 43, 0.10), 0 0 20px rgba(155, 234, 32, 0.10);
}


    .swiftcare-welcome i {
        color: var(--lime-deep) !important;
        font-size: 17px;
    }


.swiftcare-welcome-dot {
    width: 9px;
