    border-radius: 21px;
    background: linear-gradient( 135deg, rgba(155, 234, 32, 0.22), rgba(255, 255, 255, 0.70) );
    border: 1px solid rgba(111, 174, 15, 0.28);
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.75);
}


.swiftcare-care-small {
    margin-bottom: 7px;
    color: var(--lime-deep) !important;
    font-size: 14px;
    font-weight: 850;
    text-transform: uppercase;
    letter-spacing: 1.2px;
}


.swiftcare-care-title {
    color: var(--forest) !important;
    font-size: 26px;
    font-weight: 850;
    margin-bottom: 10px;
}


.swiftcare-care-text {
    color: #3b5f47 !important;
    font-size: 16px;
    line-height: 1.65;
}


/* =========================================================
   ACCESS CARDS
   ========================================================= */

.swiftcare-access-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 14px;
    margin-top: 18px;
}


.swiftcare-access-card {
    padding: 20px;
    min-height: 150px;
    border-radius: 19px;
    background: rgba(255, 255, 255, 0.68);
    border: 1px solid rgba(23, 77, 43, 0.13);
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
    transition: transform .25s ease, background .25s ease, border-color .25s ease, box-shadow .25s ease;
}


    .swiftcare-access-card:hover {
        transform: translateY(-5px);
        background: rgba(255, 255, 255, 0.86);
        border-color: rgba(111, 174, 15, 0.40);
        box-shadow: 0 15px 30px rgba(23, 77, 43, 0.10), 0 0 20px rgba(155, 234, 32, 0.10);
    }


.swiftcare-access-icon {
    width: 46px;
    height: 46px;
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 13px;
    border-radius: 14px;
    background: rgba(155, 234, 32, 0.20);
    border: 1px solid rgba(111, 174, 15, 0.30);
    color: var(--lime-deep) !important;
}


    .swiftcare-access-icon i {
        font-size: 21px;
    }


.swiftcare-access-title {
    color: var(--forest) !important;
    font-size: 17px;
    font-weight: 800;
    margin-bottom: 6px;
}


.swiftcare-access-text {
    color: #45624f !important;
    font-size: 14px;
    line-height: 1.55;
}


/* =========================================================
   ABOUT
   ========================================================= */

.swiftcare-about {
    position: relative;
    padding: 110px 0;
    background: linear-gradient( 180deg, rgba(255, 255, 255, 0.20), rgba(155, 234, 32, 0.08) );
    border-top: 1px solid rgba(23, 77, 43, 0.10);
    border-bottom: 1px solid rgba(23, 77, 43, 0.10);
}


.swiftcare-about-container {
    width: min(1180px, calc(100% - 50px));
    margin: 0 auto;
}


.swiftcare-about-grid {
    display: grid;
    grid-template-columns: 0.9fr 1.1fr;
    gap: 80px;
    align-items: center;
}


/* =========================================================
   SECTION LABEL
   ========================================================= */

.swiftcare-section-label {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 9px 14px;
    margin-bottom: 18px;
    border-radius: 999px;
    background: rgba(155, 234, 32, 0.20);
    border: 1px solid rgba(111, 174, 15, 0.34);
    color: var(--lime-deep) !important;
    font-size: 13px;
    font-weight: 850;
    text-transform: uppercase;
    letter-spacing: 1px;
}


/* =========================================================
   ABOUT TITLE
   ========================================================= */

.swiftcare-about h2 {
    margin: 0;
    color: var(--forest) !important;
    font-size: clamp(40px, 4vw, 62px);
    line-height: 1.05;
    letter-spacing: -2px;
    font-weight: 850;
}


    .swiftcare-about h2 span {
        color: var(--lime-deep) !important;
    }


.swiftcare-about-description {
    margin-top: 25px;
    max-width: 600px;
    color: #3b5f47 !important;
    font-size: 18px;
    line-height: 1.8;
}


/* =========================================================
   VALUES
   ========================================================= */

.swiftcare-values {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 15px;
}


.swiftcare-value {
    display: flex;
    align-items: flex-start;
    gap: 15px;
    padding: 22px;
    min-height: 150px;
    border-radius: 20px;
    background: rgba(255, 255, 255, 0.70);
    border: 1px solid rgba(23, 77, 43, 0.13);
    backdrop-filter: blur(18px);
    -webkit-backdrop-filter: blur(18px);
    transition: transform .25s ease, background .25s ease, border-color .25s ease, box-shadow .25s ease;
}


    .swiftcare-value:hover {
        transform: translateY(-5px);
        background: rgba(255, 255, 255, 0.88);
        border-color: rgba(111, 174, 15, 0.38);
        box-shadow: 0 15px 30px rgba(23, 77, 43, 0.10);
    }


.swiftcare-value-icon {
    width: 46px;
    height: 46px;
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 14px;
    background: rgba(155, 234, 32, 0.20);
    border: 1px solid rgba(111, 174, 15, 0.30);
    color: var(--lime-deep) !important;
}


    .swiftcare-value-icon i {
        font-size: 20px;
    }


.swiftcare-value h4 {
    margin: 2px 0 7px;
    color: var(--forest) !important;
    font-size: 17px;
    font-weight: 800;
}


.swiftcare-value p {
    margin: 0;
    color: #45624f !important;
    font-size: 14px;
    line-height: 1.6;
}


/* =========================================================
   FINAL CTA
   ========================================================= */

.swiftcare-cta {
    position: relative;
    width: min(1000px, calc(100% - 50px));
    margin: 100px auto;
    padding: 70px 40px;
    text-align: center;
    border-radius: 30px;
    background: radial-gradient( circle at 50% 0%, rgba(155, 234, 32, 0.25), transparent 58% ), rgba(255, 255, 255, 0.72);
    border: 1px solid rgba(23, 77, 43, 0.14);
    backdrop-filter: blur(28px);
    -webkit-backdrop-filter: blur(28px);
    box-shadow: 0 35px 80px rgba(23, 77, 43, 0.14), inset 0 1px 0 rgba(255, 255, 255, 0.80);
}


    .swiftcare-cta h2 {
        position: relative;
        margin: 0;
        color: var(--forest) !important;
        font-size: clamp(35px, 4vw, 52px);
        line-height: 1.1;
        font-weight: 850;
    }


    .swiftcare-cta p {
        position: relative;
        max-width: 650px;
        margin: 18px auto 0;
        color: #3b5f47 !important;
        font-size: 18px;
        line-height: 1.7;
    }


/* =========================================================
   LOGIN BUTTON
   ========================================================= */

.swiftcare-login-button {
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 11px;
    margin-top: 30px;
    padding: 16px 28px;
    border-radius: 15px;
    color: #10351f !important;
    text-decoration: none;
    background: linear-gradient( 135deg, #c8ff69, #9bea20 );
    border: 1px solid rgba(111, 174, 15, 0.42);
    font-size: 16px;
    font-weight: 850;
    box-shadow: 0 15px 35px rgba(23, 77, 43, 0.16), 0 0 30px rgba(155, 234, 32, 0.24);
    transition: transform .25s ease, box-shadow .25s ease;
}


    .swiftcare-login-button:hover {
        color: #10351f !important;
        transform: translateY(-4px);
        box-shadow: 0 20px 45px rgba(23, 77, 43, 0.20), 0 0 42px rgba(155, 234, 32, 0.38);
    }


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 1100px) {

    .swiftcare-hero-grid {
        grid-template-columns: 1fr;
        gap: 55px;
    }

    .swiftcare-hero-content {
        max-width: 850px;
    }

    .swiftcare-facility-wrapper {
        max-width: 760px;
    }

    .swiftcare-about-grid {
        grid-template-columns: 1fr;
        gap: 50px;
    }
}


@media (max-width: 750px) {

    .swiftcare-container,
    .swiftcare-about-container {
        width: calc(100% - 30px);
    }

    .swiftcare-hero {
        min-height: auto;
        padding: 75px 0 65px;
    }

    .swiftcare-title {
        font-size: clamp(46px, 14vw, 70px);
        letter-spacing: -2px;
    }

    .swiftcare-description {
        font-size: 17px;
        line-height: 1.7;
    }

    .swiftcare-facility-card {
        padding: 20px;
        border-radius: 24px;
    }

    .swiftcare-facility-header {
        align-items: flex-start;
    }

    .swiftcare-access-grid {
        grid-template-columns: 1fr;
    }

    .swiftcare-about {
        padding: 75px 0;
    }

        .swiftcare-about h2 {
            font-size: 42px;
        }

    .swiftcare-about-description {
        font-size: 16px;
    }

    .swiftcare-values {
        grid-template-columns: 1fr;
    }

    .swiftcare-cta {
        width: calc(100% - 30px);
        margin: 70px auto;
        padding: 50px 22px;
        border-radius: 24px;
    }

        .swiftcare-cta p {
            font-size: 16px;
        }
}


@media (max-width: 500px) {

    .swiftcare-facility-header {
        flex-direction: column;
    }

    .swiftcare-status {
        align-self: flex-start;
    }

    .swiftcare-facility-name {
        font-size: 19px;
    }

    .swiftcare-care-title {
        font-size: 22px;
    }

    .swiftcare-care-text {
        font-size: 15px;
    }

    .swiftcare-access-card {
        min-height: auto;
    }

    .swiftcare-value {
        padding: 18px;
    }

    .swiftcare-enter-button,
    .swiftcare-login-button {
        width: 100%;
        justify-content: center;
    }
}

/* =========================================================
   SWIFTCARE HERO IMAGE
   ========================================================= */

.swiftcare-image-showcase {
    position: relative;
    width: 100%;
    margin-top: 38px;
    max-width: 680px;
    z-index: 2;
}


/* Main glass image frame */
.swiftcare-image-frame {
    position: relative;
    width: 100%;
    height: 280px;
    overflow: hidden;
    border-radius: 26px;
    border: 1px solid rgba(255, 255, 255, 0.24);
    background: rgba(255, 255, 255, 0.10);
    backdrop-filter: blur(18px);
    -webkit-backdrop-filter: blur(18px);
    box-shadow: 0 25px 55px rgba(0, 0, 0, 0.22), inset 0 1px 0 rgba(255, 255, 255, 0.18), 0 0 35px rgba(183, 255, 60, 0.08);
}


/* Your image */
.swiftcare-main-image {
    width: 100%;
    height: 100%;
    display: block;
    object-fit: cover;
    object-position: center;
    transition: transform 0.6s ease;
}


/* Slight zoom on hover */
.swiftcare-image-frame:hover .swiftcare-main-image {
    transform: scale(1.04);
}


/* Image dark/light glass overlay */
.swiftcare-image-overlay {
    position: absolute;
    inset: 0;
    background: linear-gradient( 180deg, rgba(20, 77, 43, 0.05) 20%, rgba(20, 77, 43, 0.35) 100% );
    pointer-events: none;
}


/* =========================================================
   FLOATING IMAGE BADGE
   ========================================================= */

.swiftcare-image-badge {
    position: absolute;
    left: 22px;
    bottom: 22px;
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 13px 18px;
    border-radius: 16px;
    background: rgba(23, 77, 43, 0.78);
    border: 1px solid rgba(255, 255, 255, 0.22);
    backdrop-filter: blur(18px);
    -webkit-backdrop-filter: blur(18px);
    box-shadow: 0 12px 30px rgba(0, 0, 0, 0.22);
    color: #ffffff;
}


/* Badge icon */
.swiftcare-image-badge-icon {
    width: 42px;
    height: 42px;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    border-radius: 12px;
    background: linear-gradient( 135deg, #ddff8c, #b7ff3c );
    color: #174d2b;
    box-shadow: 0 0 20px rgba(183, 255, 60, 0.20);
}


    .swiftcare-image-badge-icon i {
        font-size: 19px;
    }


/* Badge text */
.swiftcare-image-badge strong {
    display: block;
    color: #ffffff;
    font-size: 14px;
    font-weight: 800;
    line-height: 1.3;
}


.swiftcare-image-badge span {
    display: block;
    margin-top: 3px;
    color: rgba(255, 255, 255, 0.72);
    font-size: 12px;
}


/* =========================================================
   LIME GLOW BEHIND IMAGE
   ========================================================= */

.swiftcare-image-glow {
    position: absolute;
    width: 220px;
    height: 220px;
    right: -70px;
    bottom: -80px;
    border-radius: 50%;
    background: rgba(183, 255, 60, 0.20);
    filter: blur(70px);
    z-index: -1;
    pointer-events: none;
}


/* =========================================================
   SMALL TOP HIGHLIGHT
   ========================================================= */

.swiftcare-image-frame::before {
    content: "";
    position: absolute;
    top: 0;
    left: 8%;
    right: 8%;
    height: 1px;
    z-index: 3;
    background: linear-gradient( 90deg, transparent, rgba(220, 255, 145, 0.9), transparent );
}


/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width: 700px) {

    .swiftcare-image-showcase {
        margin-top: 30px;
    }

    .swiftcare-image-frame {
        height: 230px;
        border-radius: 22px;
    }

    .swiftcare-image-badge {
        left: 15px;
        bottom: 15px;
        padding: 10px 13px;
    }

    .swiftcare-image-badge-icon {
        width: 37px;
        height: 37px;
    }

    .swiftcare-image-badge strong {
        font-size: 13px;
    }

    .swiftcare-image-badge span {
        font-size: 11px;
    }
}

/* =========================================================
   SWIFTCARE NAVBAR
   Forest Green + Lime Glassmorphism
   ========================================================= */

.swiftcare-header {
    position: relative;
    z-index: 1000;
    width: 100%;
}


/* Main navbar */
#loginNav {
    position: relative;
    width: 100%;
    min-height: 82px;
    background: linear-gradient( 135deg, rgba(20, 78, 43, 0.92), rgba(27, 94, 51, 0.88) );
    border-bottom: 1px solid rgba(255, 255, 255, 0.16);
    box-shadow: 0 12px 35px rgba(0, 0, 0, 0.16);
    backdrop-filter: blur(22px);
    -webkit-backdrop-filter: blur(22px);
}


    /* subtle lime line underneath */
    #loginNav::after {
        content: "";
        position: absolute;
        left: 5%;
        right: 5%;
        bottom: 0;
        height: 1px;
        background: linear-gradient( 90deg, transparent, rgba(183, 255, 60, 0.55), transparent );
        pointer-events: none;
    }


/* =========================================================
   NAV CONTAINER
   ========================================================= */

.swiftcare-nav-container {
    min-height: 82px;
    padding-left: 28px;
    padding-right: 28px;
}


/* =========================================================
   MENU BUTTON
   ========================================================= */

.swiftcare-menu-button {
    width: 46px;
    height: 46px;
    display: flex;
    align-items: center;
    justify-content: center;
    margin-right: 13px;
    padding: 0;
    border-radius: 14px;
    border: 1px solid rgba(183, 255, 60, 0.25);
    background: rgba(183, 255, 60, 0.10);
    color: #b7ff3c;
    cursor: pointer;
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    transition: all 0.25s ease;
}


    .swiftcare-menu-button i {
        font-size: 25px;
        line-height: 1;
    }


    .swiftcare-menu-button:hover {
        background: rgba(183, 255, 60, 0.18);
        border-color: rgba(183, 255, 60, 0.45);
        color: #d8ff82;
        transform: translateY(-2px);
        box-shadow: 0 8px 22px rgba(0, 0, 0, 0.15), 0 0 20px rgba(183, 255, 60, 0.10);
    }


/* =========================================================
   BRAND
   ========================================================= */

.swiftcare-navbar-brand {
    display: flex !important;
    align-items: center;
    gap: 12px;
    margin: 0 !important;
    padding: 0 !important;
    text-decoration: none !important;
