    border: 1px solid rgba(235, 255, 190, 0.75);
    box-shadow: 0 8px 22px rgba(0, 0, 0, 0.18), 0 0 24px rgba(183, 255, 60, 0.15);
}


    .swiftcare-navbar-logo img {
        width: 100%;
        height: 100%;
        display: block;
        object-fit: contain;
        padding: 5px;
    }


/* Brand text */
.swiftcare-brand-text {
    display: flex;
