}


/* =========================================================
   RIGHT SIDE
   ========================================================= */

.swiftcare-navbar-account {
    display: flex;
    align-items: center;
}


.swiftcare-login-nav {
    display: flex;
    align-items: center;
    gap: 8px;
    margin: 0;
    padding: 0;
    list-style: none;
}


/* =========================================================
   REGISTER
   ========================================================= */

.swiftcare-nav-link {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 11px 15px !important;
    border-radius: 12px;
    color: rgba(255, 255, 255, 0.82) !important;
    text-decoration: none !important;
    font-size: 14px;
    font-weight: 700;
    transition: all 0.25s ease;
}


    .swiftcare-nav-link i {
        color: #b7ff3c;
