    justify-content: center;
    gap: 8px;
    padding: 11px 18px;
    border-radius: 13px;
    color: #17381f !important;
    text-decoration: none !important;
    background: linear-gradient( 135deg, #ddff91, #b7ff3c );
    border: 1px solid rgba(235, 255, 190, 0.80);
    font-size: 14px;
    font-weight: 850;
    box-shadow: 0 8px 22px rgba(0, 0, 0, 0.16), 0 0 20px rgba(183, 255, 60, 0.12);
    transition: all 0.25s ease;
}


    .swiftcare-login-link i {
        font-size: 16px;
    }


    .swiftcare-login-link:hover {
        color: #17381f !important;
        transform: translateY(-2px);
        box-shadow: 0 12px 28px rgba(0, 0, 0, 0.20), 0 0 28px rgba(183, 255, 60, 0.22);
