        display: initial;
    }


    body.scx-authenticated.scx-sidebar-collapsed
    .scx-nav-link {
        justify-content: flex-start;
        gap: 13px;
        padding-left: 13px;
        padding-right: 13px;
    }


    body.scx-authenticated.scx-sidebar-collapsed
    .scx-profile-button span {
        display: inline;
    }


    body.scx-authenticated.scx-sidebar-collapsed
    .scx-profile-button .bi-arrow-right {
        display: inline;
    }
}


