    font-size: 11px;
    transition: transform 0.2s ease;
}


.swiftcare-account-button[aria-expanded="true"]
.swiftcare-account-chevron {
    transform: rotate(180deg);
}


/* =========================================================
   ACCOUNT DROPDOWN
   ========================================================= */

.swiftcare-account-dropdown {
    position: absolute !important;
    top: calc(100% + 8px) !important;
    right: 0 !important;
    left: auto !important;
    min-width: 220px;
    margin: 0 !important;
    padding: 8px;
    border: 1px solid rgba(0,0,0,0.08);
    border-radius: 14px;
    background: white;
    box-shadow: 0 15px 40px rgba(0,0,0,0.16);
    z-index: 99999;
}


/* =========================================================
   DROPDOWN ITEMS
   ========================================================= */

.swiftcare-account-item {
    min-height: 42px;
    display: flex;
    align-items: center;
    gap: 11px;
    padding: 0 12px;
    border-radius: 9px;
    color: #294234;
    font-size: 13px;
    transition: background 0.2s ease, color 0.2s ease;
}


    .swiftcare-account-item:hover {
        background: rgba(35,107,55,0.08);
        color: #236b37;
    }


    .swiftcare-account-item i {
        width: 18px;
        display: flex;
        justify-content: center;
        color: #236b37;
        font-size: 15px;
    }


/* =========================================================
   DROPDOWN DIVIDER
   ========================================================= */

.swiftcare-account-divider {
    margin: 7px 4px;
}


/* =========================================================
   LOGOUT
   ========================================================= */

.swiftcare-account-logout {
    width: 100%;
    border: none;
    background: transparent;
    text-align: left;
    cursor: pointer;
}


    .swiftcare-account-logout:hover {
        background: rgba(220,53,69,0.08);
        color: #c82333;
    }


        .swiftcare-account-logout:hover i {
            color: #c82333;
        }


/* =========================================================
   PUBLIC NAVIGATION
   ========================================================= */

.swiftcare-public-actions {
    height: 100%;
    display: flex;
    align-items: center;
    gap: 18px;
}


.swiftcare-register-link {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    color: white;
    text-decoration: none;
    font-size: 13px;
    font-weight: 600;
    white-space: nowrap;
}


    .swiftcare-register-link:hover {
        color: #b6ff3c;
    }


.swiftcare-login-button {
    min-height: 46px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 7px;
    padding: 10px 10px;
    border-radius: 13px;
    background: #b6ff3c;
    color: #123a21;
    text-decoration: none;
    font-size: 13px;
    font-weight: 700;
    white-space: nowrap;
    align-self: center;
    margin-top: auto;
    margin-bottom: auto;
    transition: transform 0.2s ease, background 0.2s ease;
}


    .swiftcare-login-button:hover {
        background: #c4ff62;
        color: #123a21;
        text-decoration: none;
        transform: translateY(-1px);
    }


/* =========================================================
   IMPORTANT BOOTSTRAP OVERRIDES
   ========================================================= */

#swiftcare-topbar .navbar-nav,
#swiftcare-topbar .nav-item,
#swiftcare-topbar .nav-link {
    margin: 0;
    padding-top: 0;
    padding-bottom: 0;
}


#swiftcare-topbar .dropdown {
    position: relative;
}


#swiftcare-topbar .dropdown-menu {
    margin-top: 0;
}


/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width: 768px) {

    #swiftcare-topbar {
        height: 70px;
        min-height: 70px;
    }


    .swiftcare-topbar-container {
        height: 70px;
        min-height: 70px;
        padding: 0 14px;
    }


    .swiftcare-topbar-logo {
        width: 50px;
        height: 50px;
        flex-basis: 50px;
        border-radius: 14px;
        font-size: 24px;
    }


    .swiftcare-topbar-brand-text {
        margin-left: 10px;
    }


    .swiftcare-topbar-title {
        font-size: 19px;
    }


    .swiftcare-topbar-subtitle {
        font-size: 11px;
    }


    #scx-menu-toggle {
        width: 38px;
        height: 38px;
        flex-basis: 38px;
        margin-right: 8px;
    }


    .swiftcare-account-email {
        display: none;
    }


    .swiftcare-account-button {
        width: 46px;
        height: 46px;
        padding: 0;
        justify-content: center;
        border-radius: 12px;
    }


    .swiftcare-account-icon {
        width: 34px;
        height: 34px;
    }


    .swiftcare-account-chevron {
        display: none;
    }


    .swiftcare-account-dropdown {
        min-width: 205px;
    }


    .swiftcare-public-actions {
        gap: 9px;
    }


    .swiftcare-register-link span {
        display: none;
    }


    .swiftcare-login-button {
        min-height: 42px;
        padding: 0 14px;
    }
}



/* =============================================================
           PAGE
           ============================================================= */

.swiftcare-login-page {
    min-height: calc(100vh - 76px);
    width: 100%;
    display: flex;
    b align-items: center;
    justify-content: center;
    padding: 45px 25px;
    box-sizing: border-box;
    background: radial-gradient( circle at 8% 5%, rgba(182, 255, 60, 0.22), transparent 28% ), radial-gradient( circle at 92% 15%, rgba(117, 190, 65, 0.14), transparent 30% ), radial-gradient( circle at 50% 100%, rgba(182, 255, 60, 0.12), transparent 35% ), linear-gradient( 135deg, #eef9e8 0%, #e5f5df 45%, #f3faef 100% );
}


/* =============================================================
           MAIN CONTAINER
           ============================================================= */

.swiftcare-login-container {
    width: 100%;
    max-width: 1120px;
    min-height: 650px;
    display: grid;
    grid-template-columns: 1fr 1fr;
    overflow: hidden;
    background: #ffffff;
    border-radius: 24px;
    box-shadow: 0 25px 70px rgba(2, 43, 58, 0.14), 0 5px 20px rgba(2, 43, 58, 0.06);
}


/* =============================================================
           LEFT VISUAL PANEL
           ============================================================= */

.swiftcare-login-visual {
    min-height: 650px;
    position: relative;
    overflow: hidden;
    background: #022b3a;
}


.swiftcare-login-image {
    position: absolute;
    inset: 0;
    background-image: url('/images/swiftcare-login.jpg');
    background-size: cover;
    background-position: center;
}


/* =============================================================
           IMAGE OVERLAY
           ============================================================= */

.swiftcare-login-overlay {
    position: absolute;
    inset: 0;
    background: linear-gradient( 135deg, rgba(2, 43, 58, 0.94) 0%, rgba(2, 43, 58, 0.76) 45%, rgba(2, 43, 58, 0.48) 100% );
}


/* =============================================================
           VISUAL CONTENT
           ============================================================= */

.swiftcare-login-visual-content {
    position: relative;
    z-index: 2;
    height: 100%;
    min-height: 650px;
    display: flex;
    flex-direction: column;
    justify-content: center;
    padding: 55px;
    box-sizing: border-box;
    color: #ffffff;
}


.swiftcare-login-visual-icon {
    width: 58px;
    height: 58px;
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 20px;
    border-radius: 16px;
    background: rgba(182, 255, 60, 0.14);
    border: 1px solid rgba(182, 255, 60, 0.32);
    color: #b6ff3c;
    font-size: 27px;
}


.swiftcare-login-visual-brand {
    margin-bottom: 10px;
    color: #b6ff3c;
    font-size: 14px;
    font-weight: 800;
    letter-spacing: 2px;
    text-transform: uppercase;
}


.swiftcare-login-visual-content h1 {
    margin: 0;
    max-width: 470px;
    color: #ffffff;
    font-size: clamp(32px, 4vw, 46px);
    line-height: 1.12;
    font-weight: 800;
    letter-spacing: -1.2px;
}


.swiftcare-login-visual-content p {
    max-width: 430px;
    margin: 22px 0 0;
    color: rgba(255,255,255,0.76);
    font-size: 15px;
    line-height: 1.8;
}


.swiftcare-login-visual-line {
    width: 65px;
    height: 4px;
    margin: 30px 0 20px;
    border-radius: 20px;
    background: #b6ff3c;
}


.swiftcare-login-visual-caption {
    display: flex;
    align-items: center;
    gap: 9px;
    color: rgba(255,255,255,0.76);
    font-size: 12px;
    font-weight: 600;
}


    .swiftcare-login-visual-caption i {
        color: #b6ff3c;
        font-size: 15px;
    }


/* =============================================================
           RIGHT FORM PANEL
           ============================================================= */

.swiftcare-login-form-panel {
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 50px 55px;
    background: #ffffff;
    box-sizing: border-box;
}


.swiftcare-login-form-content {
    width: 100%;
    max-width: 410px;
}


/* =============================================================
           LOGIN HEADER
           ============================================================= */

.swiftcare-login-header {
    margin-bottom: 30px;
}


.swiftcare-login-mobile-icon {
    display: none;
}


.swiftcare-login-welcome {
    display: block;
    margin-bottom: 7px;
    color: #76a900;
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 1.3px;
    text-transform: uppercase;
}


.swiftcare-login-header h2 {
    margin: 0;
    color: #022b3a;
    font-size: 29px;
    font-weight: 800;
    letter-spacing: -0.5px;
}


.swiftcare-login-header p {
    margin: 8px 0 0;
    color: #71808a;
    font-size: 13px;
    line-height: 1.6;
}


/* =============================================================
           FORM
           ============================================================= */

.swiftcare-login-form {
    width: 100%;
}


/* =============================================================
           VALIDATION
           ============================================================= */

.swiftcare-validation {
    margin-bottom: 18px;
    padding: 11px 13px;
    border-radius: 9px;
    background: rgba(220, 53, 69, 0.07);
    color: #b42318;
    font-size: 12px;
}


    .swiftcare-validation:empty {
        display: none;
    }


/* =============================================================
           FIELD
           ============================================================= */

.swiftcare-login-field {
    margin-bottom: 20px;
}


    .swiftcare-login-field label {
        display: block;
        margin-bottom: 8px;
        color: #173d49;
        font-size: 12px;
        font-weight: 700;
    }


.swiftcare-password-label-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
}


    .swiftcare-password-label-row label {
        margin-bottom: 8px;
    }


.swiftcare-forgot-link {
    margin-bottom: 8px;
    color: #729f16;
    font-size: 11px;
    font-weight: 700;
    text-decoration: none;
}


    .swiftcare-forgot-link:hover {
        color: #4f7600;
        text-decoration: underline;
    }


/* =============================================================
           INPUT
           ============================================================= */

.swiftcare-input-wrapper {
    position: relative;
    width: 100%;
}


    .swiftcare-input-wrapper > i:first-child {
        position: absolute;
        left: 15px;
        top: 50%;
        transform: translateY(-50%);
        color: #82939a;
        font-size: 16px;
        pointer-events: none;
        z-index: 2;
    }


.swiftcare-login-input {
    width: 100%;
    height: 50px;
    padding: 0 45px;
    box-sizing: border-box;
    border: 1px solid #dce4e6;
    border-radius: 11px;
    outline: none;
    background: #f9fbfb;
    color: #173d49;
    font-size: 13px;
    transition: border-color 0.2s ease, box-shadow 0.2s ease, background 0.2s ease;
}


    .swiftcare-login-input::placeholder {
        color: #a4afb3;
    }


    .swiftcare-login-input:focus {
        border-color: #9edb38;
        background: #ffffff;
        box-shadow: 0 0 0 4px rgba(182, 255, 60, 0.12);
    }


/* =============================================================
           PASSWORD TOGGLE
           ============================================================= */

.swiftcare-password-toggle {
    position: absolute;
    right: 13px;
    top: 50%;
    transform: translateY(-50%);
    width: 32px;
    height: 32px;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 0;
    border: none;
    border-radius: 7px;
    background: transparent;
    color: #82939a;
    cursor: pointer;
}


    .swiftcare-password-toggle:hover {
        background: rgba(2,43,58,0.06);
        color: #022b3a;
    }


/* =============================================================
           FIELD ERROR
           ============================================================= */

.swiftcare-field-error {
    display: block;
    margin-top: 5px;
    color: #c0392b;
    font-size: 11px;
}


/* =============================================================
           REMEMBER ME
           ============================================================= */

.swiftcare-login-options {
    display: flex;
    align-items: center;
    margin: 3px 0 22px;
}


.swiftcare-remember {
    position: relative;
    display: inline-flex;
    align-items: center;
    gap: 9px;
    color: #66777e;
    font-size: 12px;
    cursor: pointer;
}


.swiftcare-remember-checkbox {
    position: absolute;
    opacity: 0;
    pointer-events: none;
}


.swiftcare-custom-checkbox {
    width: 17px;
    height: 17px;
    display: inline-block;
    border: 1px solid #cbd6d9;
    border-radius: 5px;
    background: #ffffff;
    transition: background 0.2s ease, border-color 0.2s ease;
}


.swiftcare-remember-checkbox:checked + .swiftcare-custom-checkbox {
    border-color: #9bdc32;
    background: #b6ff3c;
}


    .swiftcare-remember-checkbox:checked + .swiftcare-custom-checkbox::after {
        content: "";
        display: block;
        width: 5px;
        height: 9px;
        margin: 2px 5px;
        border-right: 2px solid #123a21;
        border-bottom: 2px solid #123a21;
        transform: rotate(45deg);
    }


/* =============================================================
           LOGIN BUTTON
           ============================================================= */

.swiftcare-login-submit {
    width: 100%;
    min-height: 50px;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    padding: 0 18px;
    border: none;
    border-radius: 11px;
    background: #b6ff3c;
    color: #123a21;
    font-size: 13px;
    font-weight: 800;
    cursor: pointer;
    box-shadow: 0 8px 20px rgba(126, 178, 31, 0.16);
    transition: transform 0.2s ease, background 0.2s ease, box-shadow 0.2s ease;
}


    .swiftcare-login-submit:hover {
        background: #a9f32e;
        transform: translateY(-1px);
        box-shadow: 0 10px 25px rgba(126, 178, 31, 0.22);
    }


    .swiftcare-login-submit:active {
        transform: translateY(0);
    }


    .swiftcare-login-submit i {
        font-size: 16px;
    }


/* =============================================================
           REGISTER
           ============================================================= */

.swiftcare-register-section {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 5px;
    margin-top: 23px;
    color: #78878c;
    font-size: 12px;
}


    .swiftcare-register-section a {
        color: #729f16;
        font-weight: 800;
        text-decoration: none;
    }


        .swiftcare-register-section a:hover {
            color: #4f7600;
            text-decoration: underline;
        }


/* =============================================================
           SECONDARY LINKS
           ============================================================= */

.swiftcare-login-secondary-links {
    display: flex;
    justify-content: center;
    margin-top: 13px;
}


    .swiftcare-login-secondary-links a {
        display: inline-flex;
        align-items: center;
        gap: 6px;
        color: #89969b;
        font-size: 11px;
        text-decoration: none;
        transition: color 0.2s ease;
    }


        .swiftcare-login-secondary-links a:hover {
            color: #022b3a;
        }


/* =============================================================
           EXTERNAL LOGIN
           ============================================================= */

.swiftcare-external-login {
    margin-top: 25px;
}


.swiftcare-divider {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 18px;
    color: #9aa6aa;
    font-size: 11px;
}


    .swiftcare-divider::before,
    .swiftcare-divider::after {
        content: "";
        flex: 1;
        height: 1px;
        background: #e6ebec;
    }


    .swiftcare-divider span {
        padding: 0 12px;
    }


.swiftcare-external-buttons {
    display: flex;
    gap: 10px;
}


.swiftcare-external-button {
    flex: 1;
    min-height: 43px;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 7px;
    padding: 0 12px;
    border: 1px solid #dce4e6;
    border-radius: 9px;
    background: #ffffff;
    color: #36515b;
    font-size: 12px;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.2s ease, border-color 0.2s ease, transform 0.2s ease;
}


    .swiftcare-external-button:hover {
        border-color: #b6ff3c;
        background: #f8fff0;
        transform: translateY(-1px);
    }


/* =============================================================
           SECURITY
           ============================================================= */

.swiftcare-login-security {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 7px;
    margin-top: 25px;
    padding-top: 18px;
    border-top: 1px solid #edf0f1;
    color: #9aa5a9;
    font-size: 10px;
    text-align: center;
}


    .swiftcare-login-security i {
        color: #83b91f;
        font-size: 13px;
    }


/* =============================================================
           MOBILE
           ============================================================= */

@media (max-width: 900px) {

    .swiftcare-login-container {
        max-width: 650px;
        grid-template-columns: 1fr;
    }


    .swiftcare-login-visual {
        min-height: 330px;
    }


    .swiftcare-login-image {
        min-height: 330px;
    }


    .swiftcare-login-visual-content {
        min-height: 330px;
        padding: 40px;
    }


        .swiftcare-login-visual-content h1 {
            font-size: 32px;
        }


        .swiftcare-login-visual-content p {
            margin-top: 14px;
        }


    .swiftcare-login-visual-line {
        margin-top: 20px;
        margin-bottom: 13px;
    }


