.swiftcare-login-image {
    position: absolute;
    inset: 0;
    background-image: url('/Images/old_age.jpg');
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
}

/* =========================================================
   SWIFTCARE ADMIN DASHBOARD
   Glassy / White / Green Theme
   ========================================================= */

:root {
    --admin-green: #b6ff3c;
    --admin-green-dark: #7fcf16;
    --admin-green-soft: rgba(182, 255, 60, 0.14);
    --admin-green-border: rgba(182, 255, 60, 0.35);

    --admin-white: #ffffff;
    --admin-bg: #f7faf5;
    --admin-text: #18321f;
    --admin-muted: #718078;

    --admin-border: rgba(24, 50, 31, 0.08);

    --admin-shadow:
        0 10px 35px rgba(24, 50, 31, 0.07);

    --admin-shadow-hover:
        0 18px 45px rgba(24, 50, 31, 0.12);

    --admin-radius: 18px;
}


/* =========================================================
   PAGE
   ========================================================= */

.admin-dashboard {
    width: 100%;
    min-height: calc(100vh - 76px);
    padding: 20px;
    background: radial-gradient( circle at top right, rgba(182, 255, 60, 0.12), transparent 30% ), var(--admin-bg);
    box-sizing: border-box;
}


/* =========================================================
   DASHBOARD HEADER
   ========================================================= */

.admin-dashboard-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 20px;
    margin-bottom: 28px;
}

.admin-dashboard-heading {
    margin: 0;
    color: var(--admin-text);
    font-size: 28px;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.admin-dashboard-subtitle {
    margin: 7px 0 0;
    color: var(--admin-muted);
    font-size: 14px;
}


/* =========================================================
   HEADER ACTION
   ========================================================= */

.admin-dashboard-action {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    min-height: 43px;
    padding: 0 17px;
    border-radius: 11px;
    background: var(--admin-green);
    color: #17331d;
    border: 1px solid var(--admin-green);
    text-decoration: none;
    font-size: 13px;
    font-weight: 750;
    box-shadow: 0 7px 20px rgba(182, 255, 60, 0.22);
    transition:
        transform 0.2s ease,
        box-shadow 0.2s ease,
        background 0.2s ease;
}

.admin-dashboard-action:hover {
    background: #c4ff65;
    color: #17331d;
    transform: translateY(-2px);
    box-shadow: 0 11px 25px rgba(182, 255, 60, 0.3);
}


/* =========================================================
   STAT CARDS
   ========================================================= */

.admin-stats-grid {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 18px;
    margin-bottom: 25px;
}

.admin-stat-card {
    position: relative;
    min-height: 145px;
    padding: 22px;
    overflow: hidden;
    background: rgba(255, 255, 255, 0.86);
    border: 1px solid var(--admin-border);
    border-radius: var(--admin-radius);
    box-shadow: var(--admin-shadow);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    transition:
        transform 0.25s ease,
        box-shadow 0.25s ease;
}

.admin-stat-card:hover {
    transform: translateY(-4px);
    box-shadow: var(--admin-shadow-hover);
}


/* Green decorative glow */

.admin-stat-card::after {
    content: "";
    position: absolute;
    width: 90px;
    height: 90px;
    right: -35px;
    bottom: -35px;
    border-radius: 50%;
    background: var(--admin-green-soft);
    pointer-events: none;
}


/* =========================================================
   STAT ICON
   ========================================================= */

.admin-stat-icon {
    width: 46px;
    height: 46px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 15px;
    border-radius: 13px;
    background: var(--admin-green-soft);
    color: var(--admin-green-dark);
    font-size: 20px;
}

.admin-stat-card:nth-child(2) .admin-stat-icon {
    background: rgba(182, 255, 60, 0.1);
}

.admin-stat-card:nth-child(3) .admin-stat-icon {
    background: rgba(182, 255, 60, 0.16);
}

.admin-stat-card:nth-child(4) .admin-stat-icon {
    background: rgba(182, 255, 60, 0.12);
}


/* =========================================================
   STAT TEXT
   ========================================================= */

.admin-stat-label {
    display: block;
    margin-bottom: 5px;
    color: var(--admin-muted);
    font-size: 12px;
    font-weight: 600;
}

.admin-stat-value {
    display: block;
    color: var(--admin-text);
    font-size: 27px;
    line-height: 1.1;
    font-weight: 800;
}

.admin-stat-description {
    display: block;
    margin-top: 7px;
    color: #8a968e;
    font-size: 11px;
}


/* =========================================================
   MAIN DASHBOARD GRID
   ========================================================= */

.admin-dashboard-grid {
    display: grid;
    grid-template-columns: minmax(0, 1.65fr) minmax(300px, 0.85fr);
    gap: 20px;
    align-items: start;
}


/* =========================================================
   GLASS CARD
   ========================================================= */

.admin-glass-card {
    background: rgba(255, 255, 255, 0.88);
    border: 1px solid var(--admin-border);
    border-radius: var(--admin-radius);
    box-shadow: var(--admin-shadow);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    overflow: hidden;
}


/* =========================================================
   CARD HEADER
   ========================================================= */

.admin-card-header {
    min-height: 67px;
    padding: 0 20px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 15px;
    border-bottom: 1px solid var(--admin-border);
}

.admin-card-title {
    margin: 0;
    color: var(--admin-text);
    font-size: 15px;
    font-weight: 750;
}

.admin-card-subtitle {
    margin: 4px 0 0;
    color: var(--admin-muted);
    font-size: 11px;
}

.admin-card-header-icon {
    width: 37px;
    height: 37px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 10px;
    background: var(--admin-green-soft);
    color: var(--admin-green-dark);
    font-size: 16px;
}


/* =========================================================
   QUICK ACTIONS
   ========================================================= */

.admin-actions {
    padding: 18px;
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 12px;
}

.admin-action-card {
    position: relative;
    min-height: 105px;
    padding: 16px;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    border: 1px solid var(--admin-border);
    border-radius: 14px;
    background: #ffffff;
    color: var(--admin-text);
    text-decoration: none;
    transition:
        border-color 0.2s ease,
        background 0.2s ease,
        transform 0.2s ease,
        box-shadow 0.2s ease;
}

.admin-action-card:hover {
    color: var(--admin-text);
    border-color: var(--admin-green-border);
    background: rgba(182, 255, 60, 0.055);
    transform: translateY(-3px);
    box-shadow: 0 9px 25px rgba(24, 50, 31, 0.08);
}

.admin-action-icon {
    width: 38px;
    height: 38px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 10px;
    background: var(--admin-green-soft);
    color: var(--admin-green-dark);
    font-size: 17px;
}

.admin-action-title {
    margin-top: 12px;
    font-size: 12px;
    font-weight: 750;
}

.admin-action-description {
    margin-top: 3px;
    color: var(--admin-muted);
    font-size: 10px;
}


/* =========================================================
   RECENT ACTIVITY
   ========================================================= */

.admin-activity-list {
    padding: 8px 20px 14px;
}

.admin-activity-item {
    display: flex;
    align-items: center;
    gap: 13px;
    padding: 14px 0;
    border-bottom: 1px solid rgba(24, 50, 31, 0.06);
}

.admin-activity-item:last-child {
    border-bottom: none;
}

.admin-activity-icon {
    flex: 0 0 38px;
    width: 38px;
    height: 38px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 11px;
    background: var(--admin-green-soft);
    color: var(--admin-green-dark);
    font-size: 15px;
}

.admin-activity-content {
    min-width: 0;
    flex: 1;
}

.admin-activity-title {
    margin: 0;
    color: var(--admin-text);
    font-size: 12px;
    font-weight: 700;
}

.admin-activity-description {
    margin: 3px 0 0;
    color: var(--admin-muted);
    font-size: 10px;
}

.admin-activity-time {
    color: #98a29c;
    font-size: 10px;
    white-space: nowrap;
}


/* =========================================================
   ADMIN PROFILE CARD
   ========================================================= */

.admin-profile-card {
    padding: 23px;
    text-align: center;
}

.admin-profile-avatar {
    width: 74px;
    height: 74px;
    margin: 0 auto 13px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    background: var(--admin-green-soft);
    border: 2px solid rgba(182, 255, 60, 0.5);
    color: var(--admin-green-dark);
    font-size: 29px;
}

.admin-profile-name {
    margin: 0;
    color: var(--admin-text);
    font-size: 16px;
    font-weight: 800;
}

.admin-profile-role {
    margin-top: 4px;
    color: var(--admin-muted);
    font-size: 11px;
}

.admin-profile-status {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    margin-top: 12px;
    padding: 5px 10px;
    border-radius: 20px;
    background: var(--admin-green-soft);
    color: #5b9610;
    font-size: 10px;
    font-weight: 700;
}

.admin-profile-status::before {
    content: "";
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: var(--admin-green-dark);
}


/* =========================================================
   MANAGEMENT SUMMARY
   ========================================================= */

.admin-summary {
    padding: 18px;
}

.admin-summary-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 15px;
    padding: 13px 0;
    border-bottom: 1px solid rgba(24, 50, 31, 0.06);
}

.admin-summary-row:last-child {
    border-bottom: none;
}

.admin-summary-label {
    color: var(--admin-muted);
    font-size: 11px;
}

.admin-summary-value {
    color: var(--admin-text);
    font-size: 12px;
    font-weight: 750;
}

.admin-summary-value.green {
    color: #65a90c;
}


/* =========================================================
   PROGRESS
   ========================================================= */

.admin-progress {
    width: 100%;
    height: 7px;
    margin-top: 7px;
    overflow: hidden;
    border-radius: 20px;
    background: #edf1ec;
}

.admin-progress-bar {
    height: 100%;
    border-radius: inherit;
    background: var(--admin-green);
}


/* =========================================================
   VIEW ALL BUTTON
   ========================================================= */

.admin-view-all {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    color: #6da70f;
    font-size: 11px;
    font-weight: 700;
    text-decoration: none;
}

.admin-view-all:hover {
    color: #4e7d09;
}


/* =========================================================
   WELCOME CARD
   ========================================================= */

.admin-welcome-card {
    position: relative;
    min-height: 170px;
    padding: 25px;
    margin-bottom: 20px;
    overflow: hidden;
    border-radius: var(--admin-radius);
    background:
        linear-gradient(
            135deg,
            #ffffff 0%,
            #fbfff6 100%
        );
    border: 1px solid var(--admin-border);
    box-shadow: var(--admin-shadow);
}

.admin-welcome-card::before {
    content: "";
    position: absolute;
    width: 180px;
    height: 180px;
    right: -55px;
    top: -75px;
    border-radius: 50%;
    background: rgba(182, 255, 60, 0.17);
}

.admin-welcome-card::after {
    content: "";
    position: absolute;
    width: 100px;
    height: 100px;
    right: 80px;
    bottom: -70px;
    border-radius: 50%;
    background: rgba(182, 255, 60, 0.08);
}

.admin-welcome-content {
    position: relative;
    z-index: 2;
}

.admin-welcome-label {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    color: #72a919;
    font-size: 11px;
    font-weight: 750;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.admin-welcome-title {
    margin: 8px 0 5px;
    color: var(--admin-text);
    font-size: 24px;
    font-weight: 850;
}

.admin-welcome-text {
    max-width: 650px;
    margin: 0;
    color: var(--admin-muted);
    font-size: 12px;
    line-height: 1.6;
}


/* =========================================================
   TABLE
   ========================================================= */

.admin-table-wrapper {
    width: 100%;
    overflow-x: auto;
}

.admin-table {
    width: 100%;
    margin: 0;
    border-collapse: collapse;
}

.admin-table th {
    padding: 13px 18px;
    color: #87928b;
    background: #fbfcfa;
    border-bottom: 1px solid var(--admin-border);
    font-size: 10px;
    font-weight: 750;
    text-transform: uppercase;
    letter-spacing: 0.4px;
}

.admin-table td {
    padding: 14px 18px;
    color: var(--admin-text);
    border-bottom: 1px solid rgba(24, 50, 31, 0.05);
    font-size: 11px;
}

.admin-table tbody tr {
    transition: background 0.2s ease;
}

.admin-table tbody tr:hover {
    background: rgba(182, 255, 60, 0.045);
}


/* =========================================================
   STATUS BADGES
   ========================================================= */

.admin-status {
    display: inline-flex;
    align-items: center;
    padding: 5px 9px;
    border-radius: 20px;
    font-size: 9px;
    font-weight: 750;
}

.admin-status-active {
    background: rgba(182, 255, 60, 0.16);
    color: #629b0d;
}

.admin-status-pending {
    background: rgba(255, 193, 7, 0.12);
    color: #a47700;
}

.admin-status-inactive {
    background: rgba(108, 117, 125, 0.1);
    color: #70777c;
}


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 1200px) {

    .admin-stats-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .admin-dashboard-grid {
        grid-template-columns: 1fr;
    }
}


@media (max-width: 768px) {

    .admin-dashboard {
        padding: 22px 15px 35px;
    }

    .admin-dashboard-header {
        align-items: flex-start;
        flex-direction: column;
    }

    .admin-dashboard-heading {
        font-size: 23px;
    }

    .admin-dashboard-action {
        width: 100%;
    }

    .admin-stats-grid {
        grid-template-columns: 1fr;
        gap: 13px;
    }

    .admin-stat-card {
        min-height: 125px;
    }

    .admin-actions {
        grid-template-columns: 1fr;
    }

    .admin-welcome-card {
        padding: 21px;
    }

    .admin-welcome-title {
        font-size: 21px;
    }

    .admin-card-header {
        padding: 0 16px;
    }

    .admin-activity-list {
        padding-left: 16px;
        padding-right: 16px;
    }
}


@media (max-width: 480px) {

    .admin-dashboard {
        padding-left: 11px;
        padding-right: 11px;
    }

    .admin-stat-card {
        padding: 18px;
    }

    .admin-stat-value {
        font-size: 24px;
    }

    .admin-activity-item {
        align-items: flex-start;
    }

    .admin-activity-time {
        display: none;
    }
}


/* =========================================================
   SIDEBAR COMPATIBILITY
   Keeps dashboard aligned with the SwiftCare sidebar.
   The actual width is controlled by your existing
   scx-page-content CSS.
   ========================================================= */

body.scx-authenticated #scx-page-content .admin-dashboard {
    width: 100%;
    box-sizing: border-box;
}


/* =========================================================
   ACCESSIBILITY
   ========================================================= */

.admin-action-card:focus-visible,
.admin-dashboard-action:focus-visible,
.admin-view-all:focus-visible {
    outline: 2px solid var(--admin-green-dark);
    outline-offset: 3px;
}


/* =========================================================
   REDUCED MOTION
   ========================================================= */

@media (prefers-reduced-motion: reduce) {

    .admin-stat-card,
    .admin-action-card,
    .admin-dashboard-action {
        transition: none;
    }
}


/* =========================================================
   SWIFTCARE ADMIN DASHBOARD
   GREEN + WHITE GLASS THEME
   ========================================================= */

.swiftcare-admin-dashboard {
    min-height: calc(100vh - 76px);
    padding: 30px 24px 50px;
    background: radial-gradient( circle at 8% 5%, rgba(182, 255, 60, 0.22), transparent 28% ), radial-gradient( circle at 92% 15%, rgba(117, 190, 65, 0.14), transparent 30% ), radial-gradient( circle at 50% 100%, rgba(182, 255, 60, 0.12), transparent 35% ), linear-gradient( 135deg, #eef9e8 0%, #e5f5df 45%, #f3faef 100% );
}

/* =========================================================
   DASHBOARD HEADER
   ========================================================= */

.swiftcare-admin-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 20px;
    margin-bottom: 30px;
}

.swiftcare-admin-header-left {
    display: flex;
    flex-direction: column;
}

.swiftcare-admin-title {
    margin: 0;
    color: #18351f;
    font-size: 30px;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.swiftcare-admin-subtitle {
    margin-top: 6px;
    color: #66806d;
    font-size: 14px;
}


/* =========================================================
   STATUS BADGE
   ========================================================= */

.swiftcare-admin-status {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 9px 15px;
    border: 1px solid rgba(182, 255, 60, 0.45);
    border-radius: 30px;
    background: rgba(182, 255, 60, 0.16);
    color: #365c22;
    font-size: 12px;
    font-weight: 700;
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
}

.swiftcare-admin-status-dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: #8edb28;
    box-shadow: 0 0 0 4px rgba(142, 219, 40, 0.14);
}


/* =========================================================
   SUMMARY CARDS
   ========================================================= */

.swiftcare-admin-stat-grid {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 18px;
    margin-bottom: 28px;
}

.swiftcare-admin-stat-card {
    position: relative;
    min-height: 145px;
    padding: 22px;
    overflow: hidden;

    border: 1px solid rgba(141, 210, 67, 0.25);
    border-radius: 20px;

    /*
       Slight green tint instead of pure white.
    */
    background:
        linear-gradient(
            145deg,
            rgba(182, 255, 60, 0.20),
            rgba(255, 255, 255, 0.72)
        );

    box-shadow:
        0 12px 30px rgba(74, 112, 45, 0.08),
        inset 0 1px 0 rgba(255, 255, 255, 0.85);

    backdrop-filter: blur(18px);
    -webkit-backdrop-filter: blur(18px);

    transition:
        transform 0.25s ease,
        box-shadow 0.25s ease,
        border-color 0.25s ease;
}

.swiftcare-admin-stat-card::before {
    content: "";
    position: absolute;
    width: 100px;
    height: 100px;
    top: -45px;
    right: -35px;

    border-radius: 50%;

    background: rgba(182, 255, 60, 0.20);
}

.swiftcare-admin-stat-card:hover {
    transform: translateY(-4px);

    border-color: rgba(141, 210, 67, 0.45);

    box-shadow:
        0 18px 38px rgba(74, 112, 45, 0.13),
        inset 0 1px 0 rgba(255, 255, 255, 0.9);
}


/* =========================================================
   STAT CARD TOP
   ========================================================= */

.swiftcare-stat-top {
    position: relative;
    z-index: 2;

    display: flex;
    align-items: center;
    justify-content: space-between;
}

.swiftcare-stat-label {
    color: #64806a;
    font-size: 13px;
    font-weight: 600;
}

.swiftcare-stat-icon {
    width: 42px;
    height: 42px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 12px;

    background: rgba(182, 255, 60, 0.30);
    border: 1px solid rgba(141, 210, 67, 0.30);

    color: #487321;
    font-size: 19px;
}


/* =========================================================
   STAT NUMBER
   ========================================================= */

.swiftcare-stat-number {
    position: relative;
    z-index: 2;

    margin-top: 18px;

    color: #18351f;
    font-size: 32px;
    line-height: 1;
    font-weight: 800;
}


/* =========================================================
   STAT FOOTER
   ========================================================= */

.swiftcare-stat-footer {
    position: relative;
    z-index: 2;

    display: flex;
    align-items: center;
    gap: 6px;

    margin-top: 11px;

    color: #75907b;
    font-size: 11px;
}

.swiftcare-stat-footer i {
    color: #78b52b;
}


/* =========================================================
   MAIN GLASS CONTAINER
   ========================================================= */

.swiftcare-admin-content-grid {
    display: grid;
    grid-template-columns: minmax(0, 1.7fr) minmax(280px, 1fr);
    gap: 20px;
}


/* =========================================================
   GLASS PANEL
   ========================================================= */

.swiftcare-admin-panel {
    border: 1px solid rgba(141, 210, 67, 0.23);
    border-radius: 22px;

    background:
        linear-gradient(
            145deg,
            rgba(255, 255, 255, 0.82),
            rgba(182, 255, 60, 0.10)
        );

    box-shadow:
        0 15px 40px rgba(74, 112, 45, 0.08),
        inset 0 1px 0 rgba(255, 255, 255, 0.9);

    backdrop-filter: blur(18px);
    -webkit-backdrop-filter: blur(18px);

    overflow: hidden;
}


/* =========================================================
   PANEL HEADER
   ========================================================= */

.swiftcare-admin-panel-header {
    display: flex;
    align-items: center;
    justify-content: space-between;

    padding: 20px 22px;

    border-bottom: 1px solid rgba(141, 210, 67, 0.15);
}

.swiftcare-admin-panel-title {
    display: flex;
    align-items: center;
    gap: 10px;

    margin: 0;

    color: #24472b;
    font-size: 16px;
    font-weight: 750;
}

.swiftcare-admin-panel-title i {
    color: #72ad27;
}

.swiftcare-admin-panel-link {
    color: #6a963e;
    text-decoration: none;
    font-size: 12px;
    font-weight: 700;
}

.swiftcare-admin-panel-link:hover {
    color: #355e1b;
}


/* =========================================================
   QUICK ACTIONS
   ========================================================= */

.swiftcare-admin-actions {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 12px;

    padding: 20px;
}

.swiftcare-admin-action {
    display: flex;
    align-items: center;
    gap: 13px;

    min-height: 72px;
    padding: 13px 15px;

    border: 1px solid rgba(141, 210, 67, 0.20);
    border-radius: 15px;

    background: rgba(182, 255, 60, 0.10);

    color: #24472b;
    text-decoration: none;

    transition:
        transform 0.2s ease,
        background 0.2s ease,
        border-color 0.2s ease;
}

.swiftcare-admin-action:hover {
    transform: translateY(-2px);

    background: rgba(182, 255, 60, 0.19);

    border-color: rgba(141, 210, 67, 0.40);

    color: #24472b;
}

.swiftcare-admin-action-icon {
    width: 42px;
    height: 42px;
    min-width: 42px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 12px;

    background: rgba(182, 255, 60, 0.28);

    color: #4f7b25;
    font-size: 18px;
}

.swiftcare-admin-action-content {
    display: flex;
    flex-direction: column;
}

.swiftcare-admin-action-title {
    color: #284d30;
    font-size: 13px;
    font-weight: 750;
}

.swiftcare-admin-action-description {
    margin-top: 3px;

    color: #78917d;
    font-size: 11px;
}


/* =========================================================
   ACTIVITY LIST
   ========================================================= */

.swiftcare-admin-activity {
    padding: 8px 20px 20px;
}

.swiftcare-activity-item {
    display: flex;
    align-items: center;
    gap: 13px;

    padding: 14px 4px;

    border-bottom: 1px solid rgba(141, 210, 67, 0.12);
}

.swiftcare-activity-item:last-child {
    border-bottom: none;
}

.swiftcare-activity-icon {
    width: 38px;
    height: 38px;
    min-width: 38px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 11px;

    background: rgba(182, 255, 60, 0.18);

    color: #5c8d2b;
    font-size: 16px;
}

.swiftcare-activity-content {
    min-width: 0;
    flex: 1;
}

.swiftcare-activity-title {
    color: #315138;
    font-size: 12px;
    font-weight: 700;
}

.swiftcare-activity-time {
    margin-top: 3px;
    color: #8aa08f;
    font-size: 10px;
}


/* =========================================================
   SYSTEM STATUS
   ========================================================= */

.swiftcare-system-status {
    padding: 18px 20px 22px;
}

.swiftcare-system-row {
    display: flex;
    align-items: center;
    justify-content: space-between;

    padding: 13px 0;

    border-bottom: 1px solid rgba(141, 210, 67, 0.12);
}

.swiftcare-system-row:last-child {
    border-bottom: none;
}

.swiftcare-system-name {
    display: flex;
    align-items: center;
    gap: 9px;

    color: #45634c;
    font-size: 12px;
    font-weight: 600;
}

.swiftcare-system-name i {
