.supplier-activity-description {
    margin-top: 2px;
    color: #7b867f;
    font-size: 11px;
}

.supplier-activity-status {
    margin-left: auto;
    padding: 5px 9px;
    border-radius: 20px;
    background: #ffffff;
    color: #216b35;
    font-size: 10px;
    font-weight: 700;
    white-space: nowrap;
}


/* =========================================================
           QUICK INFORMATION
           ========================================================= */

.supplier-info {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 15px;
    margin-top: 18px;
}

.supplier-info-item {
    padding: 16px;
    background: #f8faf8;
    border-radius: 13px;
}

.supplier-info-label {
    margin-bottom: 5px;
    color: #7c8780;
    font-size: 11px;
}

.supplier-info-value {
    color: #173f25;
    font-size: 15px;
    font-weight: 800;
}


/* =========================================================
           RESPONSIVE
           ========================================================= */

@media (max-width: 900px) {

    .supplier-info {
        grid-template-columns: repeat(2, 1fr);
    }
}


@media (max-width: 768px) {

    .supplier-dashboard {
        padding: 18px 12px 30px;
    }

    .supplier-welcome {
        padding: 23px 20px;
        border-radius: 15px;
    }

        .supplier-welcome h1 {
            font-size: 23px;
        }

    .supplier-actions {
        grid-template-columns: 1fr;
        gap: 12px;
    }

    .supplier-action-card {
        min-height: 90px;
        padding: 18px;
    }

    .supplier-section {
        padding: 18px;
    }
}


@media (max-width: 520px) {

    .supplier-info {
        grid-template-columns: 1fr;
    }

    .supplier-welcome h1 {
        font-size: 21px;
    }

    .supplier-action-icon {
        width: 48px;
        height: 48px;
        min-width: 48px;
        font-size: 21px;
    }

    .supplier-action-title {
        font-size: 15px;
    }

    .supplier-action-description {
        font-size: 11px;
    }

    .supplier-activity-status {
        display: none;
    }

    .supplier-action-count {
        min-width: 30px;
        height: 30px;
        font-size: 12px;
        padding: 0 7px;
    }
}


/* =========================================================
           RESIDENT DASHBOARD
           ========================================================= */

.resident-dashboard {
    min-height: calc(100vh - 100px);
    padding: 25px 20px 40px;
    background: #f6f8f7;
}

.resident-dashboard-container {
    max-width: 1250px;
    margin: 0 auto;
}


/* =========================================================
           WELCOME
           ========================================================= */

.resident-welcome {
    position: relative;
    overflow: hidden;
    background: #216b35;
    color: #ffffff;
    border-radius: 18px;
    padding: 28px 30px;
    margin-bottom: 22px;
}

    .resident-welcome::before {
        content: "";
        position: absolute;
        width: 230px;
        height: 230px;
        right: -80px;
        top: -110px;
        border-radius: 50%;
        background: rgba(182,255,60,0.10);
    }

    .resident-welcome::after {
        content: "";
        position: absolute;
        width: 130px;
        height: 130px;
        right: 140px;
        bottom: -90px;
        border-radius: 50%;
        background: rgba(255,255,255,0.05);
    }

.resident-welcome-content {
    position: relative;
    z-index: 2;
}

.resident-welcome h1 {
    margin: 0;
    font-size: 28px;
    font-weight: 800;
    letter-spacing: -0.4px;
}

.resident-welcome p {
    margin: 7px 0 0;
    color: rgba(255,255,255,0.78);
    font-size: 14px;
}

.resident-status {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    margin-top: 18px;
    padding: 8px 13px;
    border-radius: 30px;
    background: rgba(182,255,60,0.14);
    color: #b6ff3c;
    font-size: 13px;
    font-weight: 700;
}

.resident-status-dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: #b6ff3c;
    box-shadow: 0 0 0 4px rgba(182,255,60,0.12);
}


/* =========================================================
           MAIN ACTIONS
           ========================================================= */

.resident-actions {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 18px;
    margin-bottom: 22px;
}

.resident-action-card {
    display: flex;
    align-items: center;
    gap: 17px;
    min-height: 105px;
    padding: 22px;
    background: #ffffff;
    border: 1px solid #e4e9e5;
    border-radius: 17px;
    color: #173f25;
    text-decoration: none;
    box-shadow: 0 4px 16px rgba(23,63,37,0.05);
    transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;
}

    .resident-action-card:hover {
        transform: translateY(-3px);
        border-color: rgba(33,107,53,0.25);
        box-shadow: 0 9px 24px rgba(23,63,37,0.09);
        color: #173f25;
        text-decoration: none;
    }


/* =========================================================
           ACTION ICON
           ========================================================= */

.resident-action-icon {
    width: 54px;
    height: 54px;
    min-width: 54px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 14px;
    background: #b6ff3c;
    color: #173f25;
    font-size: 24px;
}


.resident-action-content {
    min-width: 0;
}

.resident-action-title {
    margin-bottom: 4px;
    font-size: 16px;
    font-weight: 800;
}

.resident-action-description {
    color: #718078;
    font-size: 12px;
    line-height: 1.4;
}

.resident-action-arrow {
    margin-left: auto;
    color: #9aa59f;
    font-size: 18px;
    flex-shrink: 0;
}


/* =========================================================
           INFORMATION SECTION
           ========================================================= */

.resident-section {
    padding: 22px;
    background: #ffffff;
    border: 1px solid #e4e9e5;
    border-radius: 17px;
    box-shadow: 0 4px 16px rgba(23,63,37,0.04);
}

.resident-section-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 15px;
    margin-bottom: 18px;
}

.resident-section-title {
    display: flex;
    align-items: center;
    gap: 10px;
    color: #173f25;
    font-size: 17px;
    font-weight: 800;
}

    .resident-section-title i {
        color: #216b35;
    }

.resident-date {
    color: #7b867f;
    font-size: 12px;
    font-weight: 600;
}


/* =========================================================
           INFORMATION CARDS
           ========================================================= */

.resident-information {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 15px;
}

.resident-information-card {
    padding: 17px;
    background: #f8faf8;
    border-radius: 13px;
    border: 1px solid transparent;
    transition: border-color 0.2s ease, transform 0.2s ease;
}

    .resident-information-card:hover {
        border-color: rgba(33,107,53,0.15);
        transform: translateY(-2px);
    }

.resident-information-icon {
    width: 38px;
    height: 38px;
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 12px;
    border-radius: 10px;
    background: #eef8df;
    color: #216b35;
    font-size: 17px;
}

.resident-information-label {
    margin-bottom: 5px;
    color: #7c8780;
    font-size: 11px;
}

.resident-information-value {
    color: #173f25;
    font-size: 15px;
    font-weight: 800;
}


/* =========================================================
           TODAY'S CARE
           ========================================================= */

.resident-care {
    display: flex;
    flex-direction: column;
    gap: 10px;
    margin-top: 18px;
}

.resident-care-item {
    display: flex;
    align-items: center;
    gap: 14px;
    padding: 14px;
    background: #f8faf8;
    border-radius: 13px;
}

.resident-care-icon {
    width: 42px;
    height: 42px;
    min-width: 42px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 11px;
    background: #eef8df;
    color: #216b35;
    font-size: 18px;
}

.resident-care-content {
    min-width: 0;
}

.resident-care-title {
    color: #173f25;
    font-size: 13px;
    font-weight: 800;
}

.resident-care-description {
    margin-top: 2px;
    color: #7b867f;
    font-size: 11px;
}

.resident-care-status {
    margin-left: auto;
    padding: 5px 10px;
    border-radius: 20px;
    background: #ffffff;
    color: #216b35;
    font-size: 10px;
    font-weight: 700;
    white-space: nowrap;
}


/* =========================================================
           RESPONSIVE
           ========================================================= */

@media (max-width: 1000px) {

    .resident-information {
        grid-template-columns: repeat(2, 1fr);
    }
}


@media (max-width: 768px) {

    .resident-dashboard {
        padding: 18px 12px 30px;
    }

    .resident-welcome {
        padding: 23px 20px;
        border-radius: 15px;
    }

        .resident-welcome h1 {
            font-size: 23px;
        }

    .resident-actions {
        grid-template-columns: 1fr;
        gap: 12px;
    }

    .resident-action-card {
        min-height: 90px;
        padding: 18px;
    }

    .resident-section {
        padding: 18px;
    }
}


@media (max-width: 520px) {

    .resident-information {
        grid-template-columns: 1fr;
    }

    .resident-welcome h1 {
        font-size: 21px;
    }

    .resident-action-icon {
        width: 48px;
        height: 48px;
        min-width: 48px;
        font-size: 21px;
    }

    .resident-action-title {
        font-size: 15px;
    }

    .resident-action-description {
        font-size: 11px;
    }

    .resident-care-status {
        display: none;
    }
}

/* ============================================================
           PAGE
           ============================================================ */

.swift-equipment-page {
    min-height: 100vh;
    background: #f5f8f6;
    padding-bottom: 50px;
}


/* ============================================================
           HEADER
           ============================================================ */

.swift-equipment-header {
    background: linear-gradient( 135deg, #123d22, #1d6338 );
    padding: 20px 30px;
    box-shadow: 0 5px 20px rgba(18, 61, 34, 0.12);
}

.swift-equipment-header-inner {
    max-width: 1400px;
    margin: auto;
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 20px;
}

.swift-equipment-header-left {
    display: flex;
    align-items: center;
    gap: 20px;
}

.swift-equipment-back {
    color: #fff;
    text-decoration: none;
    font-weight: 700;
    white-space: nowrap;
}

    .swift-equipment-back:hover {
        color: #dff5e7;
    }

.swift-equipment-title {
    color: #fff;
    margin: 0;
    font-weight: 800;
}

.swift-equipment-subtitle {
    color: rgba(255,255,255,.75);
    margin: 4px 0 0;
    font-size: 14px;
}


/* ============================================================
           CART BUTTON
           ============================================================ */

.swift-cart-button {
    border: none;
    background: #fff;
    color: #123d22;
    border-radius: 50px;
    padding: 11px 18px;
    display: flex;
    align-items: center;
    gap: 9px;
    font-weight: 800;
    cursor: pointer;
    box-shadow: 0 5px 15px rgba(0,0,0,.12);
    transition: .2s ease;
}

    .swift-cart-button:hover {
        transform: translateY(-2px);
        box-shadow: 0 8px 20px rgba(0,0,0,.18);
    }

.swift-cart-count {
    min-width: 25px;
    height: 25px;
    padding: 0 7px;
    border-radius: 50px;
    background: #1d6338;
    color: #fff;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-size: 12px;
}


/* ============================================================
           TOOLBAR
           ============================================================ */

.swift-equipment-toolbar {
    max-width: 1400px;
    margin: 25px auto;
    padding: 0 25px;
}

.swift-equipment-search-group {
    max-width: 600px;
    position: relative;
}

.swift-equipment-search-icon {
    position: absolute;
    left: 15px;
    top: 50%;
    transform: translateY(-50%);
    color: #819188;
    z-index: 2;
}

.swift-equipment-search {
    width: 100%;
    border: 1px solid #dbe5de;
    background: #fff;
    border-radius: 12px;
    padding: 13px 15px 13px 44px;
    outline: none;
    font-size: 14px;
    transition: .2s ease;
}

    .swift-equipment-search:focus {
        border-color: #2d7b47;
        box-shadow: 0 0 0 4px rgba(45,123,71,.08);
    }


/* ============================================================
           EQUIPMENT GRID
           ============================================================ */

.swift-equipment-grid {
    max-width: 1400px;
    margin: auto;
    padding: 0 25px;
    display: grid;
    grid-template-columns: repeat( auto-fill, minmax(250px, 1fr) );
    gap: 22px;
}


/* ============================================================
           EQUIPMENT CARD
           ============================================================ */

.swift-equipment-card {
    background: #fff;
    border: 1px solid #e5ece7;
    border-radius: 17px;
    overflow: hidden;
    box-shadow: 0 6px 20px rgba(20,55,34,.06);
    transition: .25s ease;
}

    .swift-equipment-card:hover {
        transform: translateY(-4px);
        box-shadow: 0 12px 30px rgba(20,55,34,.12);
    }


.swift-equipment-image-wrapper {
    height: 210px;
    background: #edf4ef;
    overflow: hidden;
}

.swift-equipment-image {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.swift-equipment-icon-placeholder {
    width: 100%;
    height: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #7e9887;
    font-size: 45px;
    background: #edf4ef;
}


.swift-equipment-content {
    padding: 18px;
}

.swift-equipment-name {
    color: #123d22;
    font-weight: 800;
    margin-bottom: 8px;
}

.swift-equipment-description {
    color: #728078;
    font-size: 13px;
    line-height: 1.6;
    min-height: 42px;
}


.swift-equipment-actions {
    display: flex;
    gap: 10px;
    margin-top: 16px;
}

.swift-equipment-view-button,
.swift-equipment-cart-button {
    flex: 1;
    border: none;
    border-radius: 9px;
    padding: 9px 10px;
    font-size: 13px;
    font-weight: 700;
    cursor: pointer;
}

.swift-equipment-view-button {
    background: #edf3ef;
    color: #123d22;
}

.swift-equipment-cart-button {
    background: #123d22;
    color: #fff;
}

    .swift-equipment-cart-button:hover {
        background: #1d6338;
    }


/* ============================================================
           EMPTY EQUIPMENT
           ============================================================ */

.swift-equipment-empty {
    max-width: 700px;
    margin: 80px auto;
    text-align: center;
    padding: 40px;
}

.swift-equipment-empty-icon {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    margin: 0 auto 18px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #e8f1eb;
    color: #1d6338;
    font-size: 30px;
}

.swift-equipment-empty h4 {
    color: #123d22;
    font-weight: 800;
}

.swift-equipment-empty p {
    color: #718277;
}


/* ============================================================
           NO SEARCH RESULTS
           ============================================================ */

.swift-no-equipment-results {
    display: none;
    text-align: center;
    padding: 50px;
    color: #718277;
}


/* ============================================================
           MODALS
           ============================================================ */

.swift-modal {
    border: none;
    border-radius: 18px;
    overflow: hidden;
    box-shadow: 0 20px 60px rgba(0,0,0,.2);
}

.swift-modal-header {
    background: #123d22;
    color: #fff;
    border: none;
    padding: 18px 22px;
}

.swift-modal-title {
    margin: 0;
    font-weight: 800;
}

.swift-modal-subtitle {
    display: block;
    color: rgba(255,255,255,.7);
    font-size: 12px;
    margin-top: 3px;
}

.swift-modal-close {
    border: none;
    background: transparent;
    color: #fff;
    font-size: 18px;
}

.swift-modal-body {
    padding: 25px;
}

.swift-modal-image-container {
    width: 100%;
    max-height: 300px;
    overflow: hidden;
    border-radius: 12px;
    margin-bottom: 20px;
    background: #edf4ef;
}

.swift-modal-image {
    width: 100%;
    max-height: 300px;
    object-fit: cover;
}

.swift-description-label {
    color: #123d22;
    font-size: 13px;
    font-weight: 800;
    margin-bottom: 8px;
}

.swift-description {
    color: #718277;
    line-height: 1.7;
}

.swift-modal-footer {
    border-top: 1px solid #edf0ed;
    padding: 15px 22px;
}

.swift-close-button,
.swift-add-button {
    border: none;
    border-radius: 9px;
    padding: 10px 18px;
    font-weight: 700;
}

.swift-close-button {
    background: #edf0ed;
    color: #435148;
}

.swift-add-button {
    background: #123d22;
    color: #fff;
}


/* ============================================================
           ADD CART PREVIEW
           ============================================================ */

.swift-cart-preview {
    display: flex;
    align-items: center;
    gap: 15px;
    background: #f4f8f5;
    padding: 15px;
    border-radius: 13px;
}

.swift-cart-preview-image,
.swift-cart-preview-placeholder {
    width: 75px;
    height: 75px;
    flex-shrink: 0;
    border-radius: 10px;
    overflow: hidden;
    background: #e5eee8;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #6e8877;
}

    .swift-cart-preview-image img {
        width: 100%;
        height: 100%;
        object-fit: cover;
    }

.swift-cart-preview-name {
    margin: 0;
    color: #123d22;
    font-weight: 800;
}

.swift-cart-preview-description {
    margin: 5px 0 0;
    color: #718277;
    font-size: 13px;
}

.quantity-wrapper {
    margin-top: 22px;
}

.quantity-label {
    display: block;
    font-weight: 700;
    color: #123d22;
    margin-bottom: 7px;
}

.quantity-input {
    width: 100%;
    border: 1px solid #d9e3dc;
    border-radius: 9px;
    padding: 10px;
}


/* ============================================================
           CART OVERLAY
           ============================================================ */

.swift-cart-overlay {
    position: fixed;
    inset: 0;
    background: rgba(8,25,15,.45);
    backdrop-filter: blur(2px);
    opacity: 0;
    visibility: hidden;
    transition: .25s ease;
    z-index: 9998;
}

    .swift-cart-overlay.show {
        opacity: 1;
        visibility: visible;
    }


/* ============================================================
           CART PANEL
           ============================================================ */

.swift-cart-panel {
    position: fixed;
    top: 0;
    right: 0;
    width: min(650px, 95vw);
    height: 100vh;
    background: #fff;
    z-index: 9999;
    transform: translateX(100%);
    transition: transform .3s ease;
    display: flex;
    flex-direction: column;
    box-shadow: -10px 0 40px rgba(0,0,0,.15);
}

    .swift-cart-panel.show {
        transform: translateX(0);
    }


/* ============================================================
           CART HEADER
           ============================================================ */

.swift-cart-header {
    background: #123d22;
    color: #fff;
    padding: 20px 22px;
    display: flex;
    align-items: center;
    justify-content: space-between;
}

    .swift-cart-header h4 {
        margin: 0;
        font-weight: 800;
        font-size: 19px;
    }

.swift-cart-close {
    width: 36px;
    height: 36px;
    border: none;
    border-radius: 50%;
    background: rgba(255,255,255,.12);
    color: #fff;
    cursor: pointer;
}


/* ============================================================
           CART BODY
           ============================================================ */

.swift-cart-body {
    flex: 1;
    overflow-y: auto;
    padding: 20px;
}

.swift-cart-content {
    width: 100%;
}


/* ============================================================
           CART TABLE
           ============================================================ */

.swift-cart-table-wrapper {
    width: 100%;
    overflow-x: auto;
    border: 1px solid #e5ece7;
    border-radius: 13px;
}

.swift-cart-table {
    width: 100%;
    border-collapse: collapse;
    min-width: 500px;
}

    .swift-cart-table thead {
        background: #f3f7f4;
    }

    .swift-cart-table th {
        padding: 14px 15px;
        color: #587062;
        font-size: 11px;
        text-transform: uppercase;
        letter-spacing: .6px;
        font-weight: 800;
        border-bottom: 1px solid #e1e9e3;
    }

    .swift-cart-table td {
        padding: 14px 15px;
        border-bottom: 1px solid #edf1ee;
        vertical-align: middle;
    }

    .swift-cart-table tbody tr:last-child td {
        border-bottom: none;
    }


/* ============================================================
           CART EQUIPMENT
           ============================================================ */

.swift-cart-equipment {
    display: flex;
    align-items: center;
    gap: 12px;
}

.swift-cart-equipment-image {
    width: 58px;
    height: 58px;
    flex-shrink: 0;
    border-radius: 10px;
    overflow: hidden;
    background: #edf4ef;
}

.swift-cart-item-image {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.swift-cart-item-placeholder {
    width: 100%;
    height: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #789080;
    font-size: 20px;
}

.swift-cart-equipment-name {
    color: #123d22;
    font-size: 14px;
    font-weight: 800;
}

.swift-cart-equipment-type {
    color: #829087;
    font-size: 11px;
    margin-top: 3px;
}


/* ============================================================
           CART QUANTITY
           ============================================================ */

.swift-cart-quantity {
    display: inline-flex;
    align-items: center;
    border: 1px solid #dce6df;
    border-radius: 9px;
    overflow: hidden;
    background: #fff;
}

.swift-cart-quantity-btn {
    width: 32px;
    height: 34px;
    border: none;
    background: #f2f6f3;
    color: #123d22;
