    object-fit: cover;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.6);
    border: 3px solid rgba(255, 255, 255, 0.85);
    box-shadow: 0 10px 25px rgba(20, 70, 45, 0.10);
}


.resident-profile-info h3 {
    margin: 0 0 7px;
    color: #1b3028;
    font-size: 21px;
    font-weight: 750;
}


.resident-profile-info p {
    margin: 0;
    color: #788780;
    font-size: 13px;
}


.resident-profile-info i {
    color: #198754;
}


/* ============================================================
   DETAIL ITEMS
   ============================================================ */

.detail-item {
    display: flex;
    flex-direction: column;
    gap: 8px;
    padding: 15px;
    background: rgba(255, 255, 255, 0.28);
    border: 1px solid rgba(255, 255, 255, 0.60);
    border-radius: 15px;
}


.detail-label {
    display: flex;
    align-items: center;
    gap: 7px;
    color: #829089;
    font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}


    .detail-label i {
        color: #198754;
        font-size: 14px;
    }


.detail-item strong {
    color: #263a31;
    font-size: 14px;
    font-weight: 700;
    line-height: 1.5;
    word-break: break-word;
}


/* ============================================================
   TRANSPORT REASON
   ============================================================ */

.detail-section {
    display: flex;
    flex-direction: column;
    gap: 12px;
}


.reason-box {
    padding: 18px;
    color: #465a50;
    font-size: 14px;
    line-height: 1.7;
    background: rgba(255, 255, 255, 0.32);
    border: 1px solid rgba(255, 255, 255, 0.65);
    border-radius: 16px;
}


/* ============================================================
   ROUTE
   ============================================================ */

.location-detail {
    display: flex;
    align-items: flex-start;
    gap: 15px;
    padding: 17px;
    background: rgba(255, 255, 255, 0.30);
    border: 1px solid rgba(255, 255, 255, 0.65);
    border-radius: 17px;
}


.location-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 44px;
    height: 44px;
    min-width: 44px;
    border-radius: 14px;
    background: rgba(255, 255, 255, 0.55);
    border: 1px solid rgba(255, 255, 255, 0.85);
    color: #198754;
    font-size: 19px;
}


.destination-location .location-icon {
    color: #d45d4d;
}


.location-detail > div:last-child {
    display: flex;
    flex-direction: column;
    gap: 5px;
}


.location-detail span {
    color: #829089;
    font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}


.location-detail strong {
    color: #263a31;
    font-size: 14px;
    line-height: 1.6;
    font-weight: 700;
    word-break: break-word;
}


.location-detail small {
    color: #8d9993;
    font-size: 11px;
}


.location-connector {
    display: flex;
    align-items: center;
    height: 35px;
    padding-left: 30px;
    color: #6d8979;
    font-size: 18px;
}


/* ============================================================
   ASSIGNED DRIVER / VEHICLE
   ============================================================ */

.assigned-person {
    display: flex;
    align-items: center;
    gap: 15px;
    padding: 17px;
    background: rgba(255, 255, 255, 0.32);
    border: 1px solid rgba(255, 255, 255, 0.68);
    border-radius: 17px;
}


.assigned-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 50px;
    height: 50px;
    min-width: 50px;
    border-radius: 16px;
    background: rgba(255, 255, 255, 0.58);
    border: 1px solid rgba(255, 255, 255, 0.85);
    color: #198754;
    font-size: 20px;
}


.assigned-person > div:last-child {
    display: flex;
    flex-direction: column;
    gap: 5px;
}


.assigned-person span {
    color: #829089;
    font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}


.assigned-person strong {
    color: #263a31;
    font-size: 15px;
    font-weight: 750;
}


/* ============================================================
   NOT ASSIGNED
   ============================================================ */

.not-assigned-box {
    display: flex;
    align-items: flex-start;
    gap: 15px;
    padding: 19px;
    background: rgba(255, 255, 255, 0.20);
    border: 1px dashed rgba(83, 110, 96, 0.28);
    border-radius: 17px;
}


    .not-assigned-box > i {
        color: #829089;
        font-size: 25px;
    }


    .not-assigned-box strong {
        display: block;
        margin-bottom: 5px;
        color: #42564c;
        font-size: 14px;
        font-weight: 750;
    }


    .not-assigned-box p {
        margin: 0;
        color: #829089;
        font-size: 13px;
        line-height: 1.6;
    }


/* ============================================================
   DIVIDERS
   ============================================================ */

.details-card-body hr {
    margin: 25px 0;
    border: 0;
    border-top: 1px solid rgba(90, 120, 105, 0.12);
}


/* ============================================================
   ERROR / EMPTY STATE
   ============================================================ */

.alert-danger {
    padding: 24px;
    color: #873a36;
    background: rgba(255, 235, 235, 0.55);
    border: 1px solid rgba(230, 150, 150, 0.45);
    border-radius: 18px;
    backdrop-filter: blur(15px);
    -webkit-backdrop-filter: blur(15px);
}


    .alert-danger h5 {
        font-weight: 750;
    }


    .alert-danger pre {
        padding: 15px;
        overflow: auto;
        color: #dce9e2;
        background: rgba(20, 38, 30, 0.90);
        border-radius: 12px;
    }


.transport-details-page .text-center.py-5 {
    padding: 70px 20px !important;
}


    .transport-details-page .text-center.py-5 > i {
        color: #198754;
    }


    .transport-details-page .text-center.py-5 h4 {
        color: #23382e;
        font-weight: 750;
    }


    .transport-details-page .text-center.py-5 p {
        color: #7d8c84;
    }


/* ============================================================
   BUTTON
   ============================================================ */

.transport-details-page .btn-primary {
    padding: 10px 20px;
    color: #ffffff;
    background: #198754;
    border: none;
    border-radius: 12px;
    font-weight: 700;
    box-shadow: 0 8px 20px rgba(25, 135, 84, 0.22);
    transition: all 0.25s ease;
}


    .transport-details-page .btn-primary:hover {
        background: #126c42;
        transform: translateY(-2px);
        box-shadow: 0 13px 28px rgba(25, 135, 84, 0.30);
    }


/* ============================================================
   RESPONSIVE
   ============================================================ */

@media (max-width: 991.98px) {

    .transport-details-page {
        padding: 24px;
    }


    .details-page-header {
        flex-direction: column;
        align-items: flex-start;
    }


    .request-status {
        align-self: flex-start;
    }
}


@media (max-width: 767.98px) {

    .transport-details-page {
        padding: 16px;
    }


    .details-card-body {
        padding: 20px;
    }


    .details-card-header {
        padding: 18px 20px;
    }


    .resident-details-profile {
        align-items: flex-start;
    }


    .header-title h2 {
        font-size: 22px;
    }
}


@media (max-width: 480px) {

    .transport-details-page {
        padding: 10px;
    }


    .header-title {
        gap: 12px;
    }


    .header-icon {
        width: 48px;
        height: 48px;
        min-width: 48px;
        font-size: 21px;
    }


    .header-title h2 {
        font-size: 19px;
    }


    .request-status {
        width: 100%;
        justify-content: center;
    }


    .resident-details-profile {
        flex-direction: column;
    }


    .overview-card {
        min-height: auto;
        padding: 17px;
    }
}


