/* ============================================================
   SWIFTCARE - RESIDENTS PAGE
   GREEN GLASS DESIGN
   ============================================================ */
.sc-residents-page {
    width: 100%;
    min-height: 100vh;
    padding: 24px;
    position: relative;
}


/* ============================================================
   HERO
   ============================================================ */

.sc-residents-hero {
    position: relative;
    overflow: hidden;
    border-radius: 28px;
    min-height: 190px;
    padding: 32px 38px;
    background: linear-gradient( 135deg, #155c2d, #1f7a3d );
    box-shadow: 0 18px 45px rgba(21, 92, 45, 0.18);
}


.sc-residents-hero-bg {
    position: absolute;
    width: 360px;
    height: 360px;
    border-radius: 50%;
    top: -220px;
    right: -90px;
    background: rgba(182, 255, 44, 0.16);
}


.sc-residents-hero::after {
    content: "";
    position: absolute;
    width: 180px;
    height: 180px;
    border-radius: 50%;
    bottom: -110px;
    left: 30%;
    background: rgba(255, 255, 255, 0.06);
}


.sc-residents-hero-content {
    position: relative;
    z-index: 2;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 25px;
    height: 100%;
}


.sc-residents-heading {
    display: flex;
    align-items: center;
    gap: 20px;
}


/* ============================================================
   BACK BUTTON
   ============================================================ */

.sc-back-button {
    width: 48px;
    height: 48px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 15px;
    color: #ffffff;
    text-decoration: none;
    background: rgba(255, 255, 255, 0.12);
    border: 1px solid rgba(255, 255, 255, 0.18);
    backdrop-filter: blur(12px);
    transition: 0.25s ease;
}


    .sc-back-button:hover {
        color: #155c2d;
        background: #b6ff2c;
        transform: translateX(-4px);
    }


/* ============================================================
   TITLE
   ============================================================ */

.sc-residents-title {
    display: flex;
    align-items: center;
    gap: 16px;
}


.sc-residents-icon {
    width: 60px;
    height: 60px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 18px;
    color: #155c2d;
    font-size: 25px;
    background: #b6ff2c;
    box-shadow: 0 8px 20px rgba(0, 0, 0, 0.12);
}


.sc-residents-title h1 {
    margin: 0;
    color: #ffffff;
    font-size: 28px;
    font-weight: 800;
    letter-spacing: -0.5px;
}


.sc-residents-title p {
    margin: 5px 0 0;
    color: rgba(255, 255, 255, 0.72);
    font-size: 14px;
}


/* ============================================================
   RESIDENT COUNT
   ============================================================ */

.sc-residents-count {
    min-width: 185px;
    display: flex;
    align-items: center;
    gap: 14px;
    padding: 14px 18px;
    border-radius: 18px;
    background: rgba(255, 255, 255, 0.12);
    border: 1px solid rgba(255, 255, 255, 0.16);
    backdrop-filter: blur(14px);
}


.sc-count-icon {
    width: 45px;
    height: 45px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 14px;
    color: #155c2d;
    background: #b6ff2c;
    font-size: 20px;
}


.sc-residents-count span {
    display: block;
    color: rgba(255, 255, 255, 0.7);
    font-size: 11px;
}


.sc-residents-count strong {
    display: block;
    color: #ffffff;
    font-size: 24px;
    font-weight: 800;
}


/* ============================================================
   MAIN CONTENT
   ============================================================ */

.sc-residents-content {
    margin-top: 25px;
}


/* ============================================================
   SEARCH CARD
   ============================================================ */

.sc-search-card {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 25px;
    padding: 22px 25px;
    margin-bottom: 24px;
    border-radius: 22px;
    background: rgba(255, 255, 255, 0.72);
    border: 1px solid rgba(255, 255, 255, 0.8);
    box-shadow: 0 12px 35px rgba(21, 92, 45, 0.08);
    backdrop-filter: blur(18px);
}


.sc-search-card-left {
    display: flex;
    align-items: center;
    gap: 14px;
}


.sc-search-heading-icon {
    width: 48px;
    height: 48px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 15px;
    background: #efffce;
    color: #155c2d;
    font-size: 20px;
}


.sc-search-card h4 {
    margin: 0;
    color: #123d22;
    font-size: 16px;
    font-weight: 800;
}


.sc-search-card p {
    margin: 3px 0 0;
    color: #718277;
    font-size: 12px;
}


/* ============================================================
   SEARCH INPUT
   ============================================================ */

.sc-search-box {
    width: 420px;
    max-width: 100%;
    height: 52px;
    display: flex;
    align-items: center;
    padding: 0 14px;
    border-radius: 15px;
    background: rgba(255, 255, 255, 0.85);
    border: 1px solid #e0e9e3;
    transition: 0.25s ease;
}


    .sc-search-box:focus-within {
        border-color: #155c2d;
        box-shadow: 0 0 0 4px rgba(21, 92, 45, 0.08);
    }


    .sc-search-box > i {
        color: #155c2d;
        font-size: 17px;
        margin-right: 10px;
    }


    .sc-search-box input {
        width: 100%;
        border: none;
        outline: none;
        background: transparent;
        color: #123d22;
        font-size: 14px;
    }


        .sc-search-box input::placeholder {
            color: #9aa8a0;
        }


.sc-clear-search {
    border: none;
    width: 30px;
    height: 30px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 9px;
    color: #718277;
    background: transparent;
    opacity: 0;
    cursor: pointer;
    transition: 0.2s ease;
}


    .sc-clear-search:hover {
        background: #efffce;
        color: #155c2d;
    }


/* ============================================================
   MAIN GLASS TABLE
   ============================================================ */

.sc-residents-glass {
    overflow: hidden;
    border-radius: 25px;
    background: rgba(255, 255, 255, 0.78);
    border: 1px solid rgba(255, 255, 255, 0.9);
    box-shadow: 0 18px 50px rgba(21, 92, 45, 0.09);
    backdrop-filter: blur(20px);
}


/* ============================================================
   TABLE HEADER
   ============================================================ */

.sc-table-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 25px 28px;
    border-bottom: 1px solid #e8efea;
}


    .sc-table-header h3 {
        margin: 0;
        color: #123d22;
        font-size: 18px;
        font-weight: 800;
    }


    .sc-table-header p {
        margin: 5px 0 0;
        color: #718277;
        font-size: 12px;
    }


.sc-table-header-icon {
    width: 48px;
    height: 48px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 15px;
    background: #efffce;
    color: #155c2d;
    font-size: 20px;
}


/* ============================================================
   TABLE
   ============================================================ */

.sc-residents-table {
    width: 100%;
    margin: 0;
    color: #123d22;
}


    .sc-residents-table thead th {
        padding: 16px 22px;
        border: none;
        background: rgba(239, 255, 206, 0.55);
        color: #718277;
        font-size: 10px;
        font-weight: 800;
        text-transform: uppercase;
        letter-spacing: 0.8px;
        white-space: nowrap;
    }


    .sc-residents-table tbody td {
        padding: 18px 22px;
        border-bottom: 1px solid #edf2ee;
        vertical-align: middle;
        background: transparent;
        transition: 0.2s ease;
    }


    .sc-residents-table tbody tr {
        transition: 0.2s ease;
    }


        .sc-residents-table tbody tr:hover {
            background: rgba(239, 255, 206, 0.38);
        }


            .sc-residents-table tbody tr:hover td {
                background: transparent;
            }


        .sc-residents-table tbody tr:last-child td {
            border-bottom: none;
        }


/* ============================================================
   PROFILE
   ============================================================ */

.sc-resident-profile-cell {
    display: flex;
    align-items: center;
    gap: 13px;
    min-width: 210px;
}


.sc-profile-image-wrapper {
    width: 52px;
    height: 52px;
    flex-shrink: 0;
    padding: 3px;
    border-radius: 17px;
    background: linear-gradient( 135deg, #b6ff2c, #155c2d );
}


.sc-resident-profile-image {
    width: 100%;
    height: 100%;
    object-fit: cover;
    border-radius: 14px;
    background: #ffffff;
}


.sc-resident-info h5 {
    margin: 0;
    color: #123d22;
    font-size: 14px;
    font-weight: 800;
    white-space: nowrap;
}


.sc-resident-info span {
    display: flex;
    align-items: center;
    gap: 5px;
    margin-top: 5px;
    color: #718277;
    font-size: 11px;
}


/* ============================================================
   CONTACT
   ============================================================ */

.sc-contact-info {
    display: flex;
    flex-direction: column;
    gap: 7px;
    min-width: 220px;
}


.sc-contact-row {
    display: flex;
    align-items: center;
    gap: 8px;
    color: #52665a;
    font-size: 12px;
}


.sc-contact-icon {
    width: 26px;
    height: 26px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 8px;
    color: #155c2d;
    background: #efffce;
    font-size: 11px;
}


/* ============================================================
   DATE
   ============================================================ */

.sc-date-info {
    display: flex;
    align-items: center;
    gap: 9px;
    color: #52665a;
    font-size: 13px;
    white-space: nowrap;
}


.sc-date-icon {
    width: 34px;
    height: 34px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 10px;
    background: #f1f7f3;
    color: #155c2d;
}


/* ============================================================
   ROOM BADGE
   ============================================================ */

.sc-room-badge {
    width: fit-content;
    display: inline-flex;
    align-items: center;
    gap: 7px;
    padding: 8px 12px;
    border-radius: 10px;
    color: #155c2d;
    background: #efffce;
    border: 1px solid rgba(21, 92, 45, 0.1);
    font-size: 12px;
    font-weight: 700;
    white-space: nowrap;
}


.sc-not-provided {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    color: #9aa8a0;
    font-size: 12px;
}


/* ============================================================
   DETAILS BUTTON
   ============================================================ */

.sc-details-button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 9px;
    min-width: 125px;
    padding: 10px 16px;
    border-radius: 12px;
    text-decoration: none;
    color: #155c2d;
    background: #b6ff2c;
    font-size: 12px;
    font-weight: 800;
    transition: 0.25s ease;
    box-shadow: 0 5px 15px rgba(182, 255, 44, 0.2);
}


    .sc-details-button i {
        transition: 0.25s ease;
    }


    .sc-details-button:hover {
        color: #ffffff;
        background: #155c2d;
        transform: translateY(-2px);
        box-shadow: 0 10px 22px rgba(21, 92, 45, 0.22);
    }


        .sc-details-button:hover i {
            transform: translateX(4px);
        }


/* ============================================================
   EMPTY STATES
   ============================================================ */

.sc-empty-residents,
.sc-no-search-results {
    text-align: center;
    padding: 70px 25px;
    border-radius: 25px;
    background: rgba(255, 255, 255, 0.72);
    border: 1px solid rgba(255, 255, 255, 0.85);
    box-shadow: 0 15px 40px rgba(21, 92, 45, 0.08);
}


.sc-no-search-results {
    background: transparent;
    box-shadow: none;
    border: none;
}


.sc-empty-icon {
    width: 75px;
    height: 75px;
    margin: 0 auto 18px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 24px;
    background: #efffce;
    color: #155c2d;
    font-size: 30px;
}


.sc-empty-residents h3,
.sc-no-search-results h4 {
    margin-bottom: 8px;
    color: #123d22;
    font-weight: 800;
}


.sc-empty-residents p,
.sc-no-search-results p {
    margin: 0;
    color: #718277;
    font-size: 13px;
}


/* ============================================================
   RESPONSIVE
   ============================================================ */

@media (max-width: 992px) {

    .sc-residents-page {
        padding: 18px;
    }


    .sc-residents-hero {
        padding: 28px;
    }


    .sc-search-card {
        flex-direction: column;
        align-items: stretch;
    }


    .sc-search-box {
        width: 100%;
    }
}


@media (max-width: 768px) {

    .sc-residents-page {
        padding: 12px;
    }


    .sc-residents-hero {
        padding: 24px 20px;
        border-radius: 22px;
    }


    .sc-residents-hero-content {
        flex-direction: column;
        align-items: flex-start;
    }


    .sc-residents-count {
        width: 100%;
    }


    .sc-residents-heading {
        align-items: flex-start;
    }


    .sc-residents-title {
        align-items: flex-start;
    }


    .sc-residents-icon {
        width: 52px;
        height: 52px;
        font-size: 22px;
    }


    .sc-residents-title h1 {
        font-size: 23px;
    }


    .sc-search-card {
        padding: 18px;
    }


    .sc-table-header {
        padding: 20px;
    }


    .sc-residents-table thead th,
    .sc-residents-table tbody td {
        padding: 15px;
    }
}


@media (max-width: 480px) {

    .sc-residents-title {
        gap: 10px;
    }


    .sc-back-button {
        width: 42px;
        height: 42px;
        border-radius: 13px;
    }


    .sc-residents-title p {
        font-size: 12px;
    }


    .sc-search-card-left {
        align-items: flex-start;
    }


    .sc-details-button {
        min-width: 110px;
        padding: 9px 12px;
        font-size: 11px;
    }
}
