/* ============================================================
   SWIFTCARE RESIDENT DETAILS PAGE
   UNIQUE CLASSES - GREEN / LIME / GLASS DESIGN
   ============================================================ */
.sc-resident-details-page {
    min-height: 100vh;
    padding-bottom: 45px;
    background: radial-gradient(circle at top left, rgba(182, 255, 44, 0.13), transparent 28%), linear-gradient( 135deg, #f4f8f5 0%, #edf5ef 50%, #f8fbf8 100% );
}


/* ============================================================
   HERO
   ============================================================ */

.sc-resident-hero {
    position: relative;
    overflow: hidden;
    padding: 32px 45px 42px;
    background: linear-gradient( 135deg, #155c2d, #0d4722 );
    border-radius: 0 0 32px 32px;
    box-shadow: 0 15px 40px rgba(21, 92, 45, 0.18);
}

    .sc-resident-hero::before {
        content: "";
        position: absolute;
        width: 330px;
        height: 330px;
        top: -180px;
        right: -90px;
        border-radius: 50%;
        background: rgba(182, 255, 44, 0.08);
    }

    .sc-resident-hero::after {
        content: "";
        position: absolute;
        width: 220px;
        height: 220px;
        bottom: -150px;
        left: 20%;
        border-radius: 50%;
        background: rgba(255, 255, 255, 0.04);
    }


/* ============================================================
   HERO TOP
   ============================================================ */

.sc-resident-hero-top {
    position: relative;
    z-index: 2;
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 38px;
}


.sc-resident-back-btn {
    display: inline-flex;
    align-items: center;
    gap: 9px;
    padding: 11px 17px;
    color: #ffffff;
    text-decoration: none;
    font-size: 14px;
    font-weight: 700;
    background: rgba(255, 255, 255, 0.12);
    border: 1px solid rgba(255, 255, 255, 0.16);
    border-radius: 14px;
    backdrop-filter: blur(12px);
    transition: transform 0.2s ease, background 0.2s ease;
}

    .sc-resident-back-btn:hover {
        color: #ffffff;
        background: rgba(255, 255, 255, 0.2);
        transform: translateX(-3px);
    }


.sc-resident-id {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 9px 14px;
    color: #155c2d;
    font-size: 12px;
    font-weight: 800;
    background: #b6ff2c;
    border-radius: 999px;
}


/* ============================================================
   HERO CONTENT
   ============================================================ */

.sc-resident-hero-content {
    position: relative;
    z-index: 2;
    display: flex;
    align-items: center;
    gap: 24px;
}


.sc-resident-image-wrap {
    position: relative;
    flex-shrink: 0;
}


.sc-resident-main-image {
    width: 118px;
    height: 118px;
    object-fit: cover;
    border-radius: 28px;
    border: 5px solid rgba(255, 255, 255, 0.2);
    box-shadow: 0 15px 30px rgba(0, 0, 0, 0.18);
}


.sc-resident-online-dot {
    position: absolute;
    right: 3px;
    bottom: 4px;
    width: 24px;
    height: 24px;
    background: #b6ff2c;
    border: 4px solid #155c2d;
    border-radius: 50%;
}


.sc-resident-main-info h1 {
    margin: 6px 0 10px;
    color: #ffffff;
    font-size: 32px;
    font-weight: 800;
    letter-spacing: -0.7px;
}


.sc-resident-main-info p {
    display: flex;
    align-items: center;
    gap: 8px;
    margin: 0;
    color: rgba(255, 255, 255, 0.72);
    font-size: 14px;
}


.sc-resident-role {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    color: #b6ff2c;
    font-size: 12px;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.8px;
}


/* ============================================================
   CONTENT
   ============================================================ */

.sc-resident-content {
    max-width: 1450px;
    margin: 0 auto;
    padding: 35px 30px 20px;
}


/* ============================================================
   QUICK STATS
   ============================================================ */

.sc-resident-stats {
    margin-bottom: 30px;
}


.sc-resident-stat-card {
    display: flex;
    align-items: center;
    gap: 14px;
    min-height: 105px;
    padding: 18px;
    background: rgba(255, 255, 255, 0.72);
    border: 1px solid rgba(255, 255, 255, 0.85);
    border-radius: 20px;
    box-shadow: 0 10px 30px rgba(17, 74, 35, 0.07);
    backdrop-filter: blur(16px);
    transition: transform 0.25s ease, box-shadow 0.25s ease;
}


    .sc-resident-stat-card:hover {
        transform: translateY(-4px);
        box-shadow: 0 18px 35px rgba(17, 74, 35, 0.11);
    }


.sc-resident-stat-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 48px;
    height: 48px;
    flex-shrink: 0;
    border-radius: 15px;
    font-size: 21px;
}


.sc-stat-green {
    color: #ffffff;
    background: #155c2d;
}


.sc-stat-lime {
    color: #155c2d;
    background: #b6ff2c;
}


.sc-stat-soft {
    color: #155c2d;
    background: #efffce;
}


.sc-stat-dark {
    color: #ffffff;
    background: #2d7a48;
}


.sc-resident-stat-card span {
    display: block;
    margin-bottom: 4px;
    color: #819187;
    font-size: 11px;
    font-weight: 600;
}


.sc-resident-stat-card strong {
    display: block;
    color: #123d22;
    font-size: 15px;
    font-weight: 800;
}


.sc-resident-active {
    color: #218547 !important;
}


/* ============================================================
   INFORMATION CARDS
   ============================================================ */

.sc-resident-info-card {
    height: 100%;
    padding: 25px;
    background: rgba(255, 255, 255, 0.78);
    border: 1px solid rgba(255, 255, 255, 0.9);
    border-radius: 24px;
    box-shadow: 0 12px 35px rgba(17, 74, 35, 0.07);
    backdrop-filter: blur(18px);
}


.sc-resident-card-heading {
    display: flex;
    align-items: center;
    gap: 13px;
    margin-bottom: 25px;
}


.sc-resident-heading-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 46px;
    height: 46px;
    flex-shrink: 0;
    color: #155c2d;
    font-size: 20px;
    background: #efffce;
    border-radius: 14px;
}


.sc-accommodation-icon {
    color: #ffffff;
    background: #155c2d;
}


.sc-equipment-icon {
    color: #155c2d;
    background: #b6ff2c;
}


.sc-resident-card-heading h4 {
    margin: 0 0 3px;
    color: #123d22;
    font-size: 17px;
    font-weight: 800;
}


.sc-resident-card-heading p {
    margin: 0;
    color: #819187;
    font-size: 12px;
}


/* ============================================================
   PERSONAL INFORMATION
   ============================================================ */

.sc-resident-info-list {
    width: 100%;
}


.sc-resident-info-item {
    display: flex;
    align-items: center;
    gap: 15px;
    padding: 10px 0;
}


.sc-resident-info-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 42px;
    height: 42px;
    flex-shrink: 0;
    color: #155c2d;
    background: #f0f7f2;
    border-radius: 13px;
    font-size: 17px;
}


.sc-resident-info-item span {
    display: block;
    margin-bottom: 3px;
    color: #8a998f;
    font-size: 11px;
    font-weight: 600;
}


.sc-resident-info-item strong {
    display: block;
    color: #123d22;
    font-size: 14px;
    font-weight: 750;
    word-break: break-word;
}


.sc-resident-divider {
    height: 1px;
    background: linear-gradient( to right, transparent, #e1ebe4, transparent );
}


/* ============================================================
   ACCOMMODATION
   ============================================================ */

.sc-resident-room-display {
    display: flex;
    align-items: center;
    gap: 17px;
    padding: 22px;
    background: linear-gradient( 135deg, #f4fae8, #efffce );
    border-radius: 20px;
}


.sc-resident-room-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 55px;
    height: 55px;
    color: #155c2d;
    font-size: 24px;
    background: #b6ff2c;
    border-radius: 17px;
}


.sc-resident-room-display span {
    display: block;
    margin-bottom: 3px;
    color: #718277;
    font-size: 12px;
}


.sc-resident-room-display strong {
    color: #123d22;
    font-size: 23px;
    font-weight: 850;
}


.sc-resident-room-status {
    display: flex;
    align-items: center;
    gap: 8px;
    margin-top: 18px;
    padding: 12px 14px;
    color: #20713d;
    font-size: 12px;
    font-weight: 700;
    background: #edf9f0;
    border-radius: 12px;
}


.sc-room-unassigned {
    color: #9b7621;
    background: #fff8e5;
}


/* ============================================================
   EQUIPMENT EMPTY STATE
   ============================================================ */

.sc-resident-equipment-empty {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    min-height: 210px;
    text-align: center;
    border: 2px dashed #dbe8de;
    border-radius: 20px;
    background: rgba(245, 250, 246, 0.6);
}


.sc-resident-empty-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 68px;
    height: 68px;
    margin-bottom: 14px;
    color: #155c2d;
    font-size: 28px;
    background: #efffce;
    border-radius: 20px;
}


.sc-resident-equipment-empty h5 {
    margin-bottom: 6px;
    color: #123d22;
    font-size: 16px;
    font-weight: 800;
}


.sc-resident-equipment-empty p {
    max-width: 400px;
    margin: 0;
    color: #829087;
    font-size: 13px;
}


/* ============================================================
   ACTION SECTION
   ============================================================ */

.sc-resident-action-section {
    margin-top: 32px;
    padding: 26px;
    background: rgba(255, 255, 255, 0.68);
    border: 1px solid rgba(255, 255, 255, 0.9);
    border-radius: 25px;
    box-shadow: 0 12px 35px rgba(17, 74, 35, 0.06);
    backdrop-filter: blur(18px);
}


.sc-resident-action-heading {
    margin-bottom: 20px;
}


    .sc-resident-action-heading h4 {
        margin: 0 0 4px;
        color: #123d22;
        font-size: 18px;
        font-weight: 850;
    }


    .sc-resident-action-heading p {
        margin: 0;
        color: #829087;
        font-size: 13px;
    }


/* ============================================================
   ACTION BUTTONS
   ============================================================ */

.sc-resident-action-btn {
    display: flex;
    align-items: center;
    gap: 15px;
    width: 100%;
    min-height: 92px;
    padding: 16px 20px;
    text-decoration: none;
    border-radius: 20px;
    transition: transform 0.25s ease, box-shadow 0.25s ease;
}


    .sc-resident-action-btn:hover {
        transform: translateY(-4px);
    }


.sc-action-equipment {
    color: #ffffff;
    background: linear-gradient( 135deg, #155c2d, #0d4722 );
    box-shadow: 0 12px 28px rgba(21, 92, 45, 0.2);
}


    .sc-action-equipment:hover {
        color: #ffffff;
        box-shadow: 0 18px 35px rgba(21, 92, 45, 0.3);
    }


.sc-action-transport {
    color: #155c2d;
    background: linear-gradient( 135deg, #b6ff2c, #d7ff78 );
    box-shadow: 0 12px 28px rgba(130, 190, 25, 0.17);
}


    .sc-action-transport:hover {
        color: #155c2d;
        box-shadow: 0 18px 35px rgba(130, 190, 25, 0.25);
    }


.sc-resident-action-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 50px;
    height: 50px;
    flex-shrink: 0;
    font-size: 23px;
    border-radius: 15px;
}


.sc-action-equipment .sc-resident-action-icon {
    color: #155c2d;
    background: #b6ff2c;
}


.sc-action-transport .sc-resident-action-icon {
    color: #ffffff;
    background: #155c2d;
}


.sc-resident-action-text {
    display: flex;
    flex-direction: column;
    flex-grow: 1;
}


    .sc-resident-action-text strong {
        margin-bottom: 4px;
        font-size: 15px;
        font-weight: 850;
    }


    .sc-resident-action-text span {
        font-size: 12px;
        opacity: 0.75;
    }


.sc-resident-action-arrow {
    font-size: 22px;
    transition: transform 0.2s ease;
}


.sc-resident-action-btn:hover
.sc-resident-action-arrow {
    transform: translateX(5px);
}


/* ============================================================
   RESPONSIVE
   ============================================================ */

@media (max-width: 768px) {

    .sc-resident-hero {
        padding: 22px 20px 30px;
        border-radius: 0 0 25px 25px;
    }


    .sc-resident-hero-top {
        margin-bottom: 28px;
    }


    .sc-resident-back-btn span {
        display: none;
    }


    .sc-resident-main-image {
        width: 88px;
        height: 88px;
        border-radius: 22px;
    }


    .sc-resident-main-info h1 {
        font-size: 24px;
    }


    .sc-resident-content {
        padding: 25px 16px 10px;
    }


    .sc-resident-info-card {
        padding: 20px;
    }


    .sc-resident-action-section {
        padding: 20px;
    }
}


@media (max-width: 480px) {

    .sc-resident-hero-content {
        align-items: flex-start;
    }


    .sc-resident-main-info h1 {
        font-size: 21px;
    }


    .sc-resident-role {
        font-size: 10px;
    }


    .sc-resident-id {
        padding: 8px 10px;
        font-size: 10px;
    }


    .sc-resident-stat-card {
        min-height: 90px;
    }


    .sc-resident-action-btn {
        min-height: 82px;
        padding: 14px;
    }
}
/* ============================================================
SWIFTCARE - REQUEST TRANSPORT
UNIQUE PAGE CLASSES
============================================================ */

.sc-transport-page {
    min-height: 100vh;
    padding-bottom: 50px;
    background: radial-gradient( circle at top right, rgba(182, 255, 44, 0.12), transparent 30% ), linear-gradient( 135deg, #f4f8f5 0%, #eef5f0 100% );
}


/* ============================================================
HERO
============================================================ */

.sc-transport-hero {
    position: relative;
    overflow: hidden;
    padding: 42px 45px 48px;
    background: linear-gradient( 135deg, #155c2d, #0d4722 );
}


    .sc-transport-hero::before {
        content: "";
        position: absolute;
        width: 330px;
        height: 330px;
        right: -100px;
        top: -160px;
        border-radius: 50%;
        background: rgba(182, 255, 44, 0.08);
    }


    .sc-transport-hero::after {
        content: "";
        position: absolute;
        width: 180px;
        height: 180px;
        left: 50%;
        bottom: -130px;
        border-radius: 50%;
        background: rgba(255, 255, 255, 0.04);
    }


.sc-transport-hero-content {
    position: relative;
    z-index: 2;
}


.sc-transport-back {
    display: inline-flex;
    align-items: center;
    gap: 9px;
    margin-bottom: 28px;
    padding: 10px 15px;
    border-radius: 12px;
    color: #ffffff;
    text-decoration: none;
    background: rgba(255, 255, 255, 0.09);
    border: 1px solid rgba(255, 255, 255, 0.12);
    transition: all 0.25s ease;
}


    .sc-transport-back:hover {
        color: #b6ff2c;
        background: rgba(255, 255, 255, 0.15);
        transform: translateX(-3px);
    }


.sc-transport-heading {
    display: flex;
    align-items: center;
    gap: 20px;
}


.sc-transport-heading-icon {
    width: 68px;
    height: 68px;
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 20px;
    background: #b6ff2c;
    color: #155c2d;
    font-size: 30px;
    box-shadow: 0 15px 35px rgba(0, 0, 0, 0.15);
}


.sc-transport-eyebrow {
    display: block;
    margin-bottom: 5px;
    color: #b6ff2c;
    font-size: 11px;
    font-weight: 800;
    letter-spacing: 1.5px;
}


.sc-transport-heading h1 {
    margin: 0;
    color: #ffffff;
    font-size: 30px;
    font-weight: 800;
}


.sc-transport-heading p {
    margin: 6px 0 0;
    color: #bdd3c4;
    font-size: 14px;
}


/* ============================================================
MAIN CONTAINER
============================================================ */

.sc-transport-container {
    max-width: 1450px;
    margin: 0 auto;
    padding: 0 30px;
}


/* ============================================================
RESIDENT SUMMARY
============================================================ */

.sc-resident-summary {
    position: relative;
    z-index: 5;
    display: flex;
    align-items: center;
    gap: 22px;
    margin-top: -28px;
    margin-bottom: 30px;
    padding: 22px 25px;
    border-radius: 24px;
    background: rgba(255, 255, 255, 0.78);
    border: 1px solid rgba(255, 255, 255, 0.9);
    box-shadow: 0 20px 50px rgba(21, 92, 45, 0.09), inset 0 1px 0 rgba(255, 255, 255, 0.8);
    backdrop-filter: blur(16px);
}


.sc-resident-image-wrap {
    position: relative;
    flex-shrink: 0;
}


.sc-resident-image {
    width: 82px;
    height: 82px;
    object-fit: cover;
    border-radius: 24px;
    border: 4px solid #efffce;
    box-shadow: 0 10px 25px rgba(21, 92, 45, 0.15);
}


.sc-resident-online {
    position: absolute;
    right: 2px;
    bottom: 4px;
    width: 17px;
    height: 17px;
    border-radius: 50%;
    background: #b6ff2c;
    border: 3px solid #ffffff;
}


.sc-resident-summary-content {
    flex: 1;
}


.sc-resident-label {
    color: #718277;
    font-size: 10px;
    font-weight: 800;
    letter-spacing: 1.2px;
}


.sc-resident-summary h2 {
    margin: 4px 0 12px;
    color: #123d22;
    font-size: 24px;
    font-weight: 800;
}


.sc-resident-meta {
    display: flex;
    flex-wrap: wrap;
    gap: 25px;
}


.sc-resident-meta-item {
    display: flex;
    align-items: center;
    gap: 9px;
}


.sc-resident-meta-icon {
    width: 35px;
    height: 35px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 11px;
    background: #efffce;
    color: #155c2d;
}


.sc-resident-meta-item span,
.sc-resident-meta-item strong {
    display: block;
}


.sc-resident-meta-item span {
    color: #718277;
    font-size: 10px;
}


.sc-resident-meta-item strong {
    color: #123d22;
    font-size: 12px;
}


.sc-resident-status {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 10px 15px;
    border-radius: 12px;
    background: #efffce;
    color: #155c2d;
    font-size: 12px;
    font-weight: 800;
}


    .sc-resident-status i {
        font-size: 17px;
    }


/* ============================================================
FORM CARD
============================================================ */

.sc-transport-form-card {
    overflow: hidden;
    border-radius: 28px;
    background: rgba(255, 255, 255, 0.75);
    border: 1px solid rgba(255, 255, 255, 0.95);
    box-shadow: 0 25px 70px rgba(21, 92, 45, 0.09);
    backdrop-filter: blur(18px);
}


.sc-transport-form-top {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 25px;
    padding: 28px 32px;
    background: linear-gradient( 135deg, rgba(21, 92, 45, 0.98), rgba(13, 71, 34, 0.98) );
}


.sc-form-step {
    display: inline-block;
    margin-bottom: 8px;
    color: #b6ff2c;
    font-size: 10px;
    font-weight: 900;
    letter-spacing: 1.5px;
}


.sc-transport-form-top h3 {
    margin: 0;
    color: #ffffff;
    font-size: 22px;
    font-weight: 800;
}


    .sc-transport-form-top h3 i {
        margin-right: 8px;
        color: #b6ff2c;
    }


.sc-transport-form-top p {
    margin: 7px 0 0;
    color: #bcd2c4;
    font-size: 13px;
}


.sc-form-header-badge {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 11px 15px;
    border-radius: 12px;
    color: #dfffc0;
    background: rgba(182, 255, 44, 0.1);
    border: 1px solid rgba(182, 255, 44, 0.2);
    font-size: 12px;
    font-weight: 700;
}


.sc-transport-form-body {
    padding: 35px 32px 32px;
}


/* ============================================================
FORM SECTIONS
============================================================ */

.sc-form-section-heading {
    display: flex;
    align-items: center;
    gap: 14px;
    margin-bottom: 26px;
}


.sc-form-section-icon {
    width: 48px;
    height: 48px;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    border-radius: 15px;
    background: #efffce;
    color: #155c2d;
    font-size: 20px;
}


.sc-location-icon {
    background: rgba(182, 255, 44, 0.28);
}


.sc-form-section-heading h4 {
    margin: 0;
    color: #123d22;
    font-size: 18px;
    font-weight: 800;
}


.sc-form-section-heading p {
    margin: 4px 0 0;
    color: #718277;
    font-size: 13px;
}


/* ============================================================
FORM FIELDS
============================================================ */

.sc-field-group label {
    display: flex;
    align-items: center;
    gap: 7px;
    margin-bottom: 9px;
    color: #123d22;
    font-size: 13px;
    font-weight: 800;
}


    .sc-field-group label i {
        color: #155c2d;
    }


.sc-transport-input {
    min-height: 52px;
    padding: 12px 15px;
    border: 1px solid #dfe9e2;
    border-radius: 14px;
    background: rgba(255, 255, 255, 0.85);
    color: #123d22;
    box-shadow: none;
    transition: all 0.25s ease;
}


    .sc-transport-input:focus {
        border-color: #155c2d;
        box-shadow: 0 0 0 4px rgba(21, 92, 45, 0.08);
    }


.sc-transport-textarea {
    min-height: 125px;
    resize: vertical;
}


/* ============================================================
ROUTE DIVIDER
============================================================ */

.sc-route-divider {
    display: flex;
    align-items: center;
    gap: 15px;
    margin: 42px 0;
}


    .sc-route-divider > div {
        flex: 1;
        height: 1px;
        background: #e1eae4;
    }


    .sc-route-divider span {
        width: 40px;
        height: 40px;
        display: flex;
        align-items: center;
        justify-content: center;
        border-radius: 50%;
        background: #efffce;
        color: #155c2d;
    }


/* ============================================================
LOCATION CARDS
============================================================ */

.sc-location-card {
    height: 100%;
    padding: 22px;
    border-radius: 20px;
    background: rgba(255, 255, 255, 0.7);
    border: 1px solid #e1eae4;
    transition: all 0.25s ease;
}


    .sc-location-card:hover {
        transform: translateY(-3px);
        box-shadow: 0 15px 35px rgba(21, 92, 45, 0.08);
    }


.sc-pickup-card {
    border-top: 4px solid #155c2d;
}


.sc-destination-card {
    border-top: 4px solid #b6ff2c;
}


.sc-location-card-top {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 18px;
}


.sc-location-marker {
    width: 43px;
    height: 43px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 14px;
    background: #efffce;
    color: #155c2d;
    font-size: 20px;
}


.sc-destination-marker {
    background: rgba(182, 255, 44, 0.3);
}


.sc-location-card-top span {
    display: block;
    color: #718277;
    font-size: 9px;
    font-weight: 800;
    letter-spacing: 1px;
}


.sc-location-card-top h5 {
    margin: 3px 0 0;
    color: #123d22;
    font-size: 15px;
    font-weight: 800;
}


.sc-place-container {
    width: 100%;
}


.sc-places-wrapper {
    width: 100%;
    min-height: 52px;
}


    .sc-places-wrapper gmp-place-autocomplete,
    .sc-places-wrapper google-maps-place-autocomplete {
        width: 100% !important;
    }


.sc-location-status {
    min-height: 20px;
    margin-top: 10px;
    font-size: 12px;
    font-weight: 600;
}


    .sc-location-status.success {
        color: #238a43;
    }


    .sc-location-status.error {
        color: #d84040;
    }


/* ============================================================
ACTIONS
============================================================ */

.sc-transport-actions {
    display: flex;
    justify-content: flex-end;
    gap: 14px;
    margin-top: 42px;
    padding-top: 25px;
    border-top: 1px solid #e1eae4;
}


.sc-cancel-transport {
    min-width: 150px;
    padding: 14px 20px;
    border: 1px solid #d8e3db;
    border-radius: 14px;
    color: #52655a;
    background: #ffffff;
    font-weight: 700;
}


    .sc-cancel-transport:hover {
        color: #123d22;
        background: #f4f8f5;
        border-color: #b9c9be;
    }


.sc-submit-transport {
    min-width: 265px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 14px 20px;
    border-radius: 14px;
    border: none;
    color: #155c2d;
    background: #b6ff2c;
    font-weight: 800;
    box-shadow: 0 12px 25px rgba(182, 255, 44, 0.22);
    transition: all 0.25s ease;
}


    .sc-submit-transport:hover {
        color: #155c2d;
        background: #c5ff52;
        transform: translateY(-2px);
        box-shadow: 0 16px 30px rgba(182, 255, 44, 0.3);
    }


.sc-submit-arrow {
    font-size: 18px;
}


/* ============================================================
VALIDATION
============================================================ */

.sc-transport-validation {
    margin-bottom: 20px;
    padding: 14px 18px;
    border-radius: 14px;
    background: #fff1f1;
    border: 1px solid #ffd5d5;
}


/* ============================================================
RESPONSIVE
============================================================ */

@media (max-width: 991px) {

    .sc-resident-status {
        display: none;
    }
}


@media (max-width: 768px) {

    .sc-transport-hero {
        padding: 30px 20px 42px;
    }

    .sc-transport-container {
        padding: 0 15px;
    }

    .sc-transport-heading {
        align-items: flex-start;
    }

        .sc-transport-heading h1 {
            font-size: 24px;
        }

    .sc-transport-heading-icon {
        width: 56px;
        height: 56px;
        font-size: 24px;
    }

    .sc-resident-summary {
        align-items: flex-start;
        flex-direction: column;
        padding: 22px;
    }

    .sc-resident-meta {
        gap: 15px;
    }

    .sc-transport-form-top {
        align-items: flex-start;
        flex-direction: column;
        padding: 25px 22px;
    }

    .sc-transport-form-body {
        padding: 25px 20px;
    }

    .sc-transport-actions {
        flex-direction: column-reverse;
    }

    .sc-cancel-transport,
    .sc-submit-transport {
        width: 100%;
    }
}


@media (max-width: 480px) {

    .sc-transport-heading {
        gap: 14px;
    }

    .sc-transport-heading-icon {
        width: 48px;
        height: 48px;
        border-radius: 15px;
    }

    .sc-transport-heading p {
        font-size: 12px;
    }

    .sc-resident-image {
        width: 70px;
        height: 70px;
    }

    .sc-resident-summary h2 {
        font-size: 21px;
    }
}

/* ============================================================
   SWIFTCARE EQUIPMENT LIST
   UNIQUE PAGE STYLING
   ============================================================ */
:root {
    --sc-equip-primary: #155C2D;
    --sc-equip-primary-dark: #0D4722;
    --sc-equip-lime: #B6FF2C;
    --sc-equip-lime-soft: #EFFFCE;
    --sc-equip-background: #F4F8F5;
    --sc-equip-card: #FFFFFF;
    --sc-equip-text: #123D22;
    --sc-equip-muted: #718277;
    --sc-equip-border: #E0E9E3;
}


/* ============================================================
   PAGE
   ============================================================ */

.sc-equipment-page {
    width: 100%;
    min-height: 100vh;
    padding: 28px;
    background: var(--sc-equip-background);
}


/* ============================================================
   HEADER
   ============================================================ */

.sc-equipment-header {
    position: relative;
    overflow: hidden;
    margin-bottom: 26px;
    padding: 28px 32px;
    border-radius: 24px;
    background: linear-gradient( 135deg, var(--sc-equip-primary), var(--sc-equip-primary-dark) );
    box-shadow: 0 12px 35px rgba(13, 71, 34, 0.16);
}

    .sc-equipment-header::before {
        content: "";
        position: absolute;
        top: -100px;
        right: -80px;
        width: 280px;
        height: 280px;
        border-radius: 50%;
        background: rgba(255, 255, 255, 0.06);
    }

    .sc-equipment-header::after {
        content: "";
        position: absolute;
        bottom: -120px;
        right: 180px;
        width: 240px;
        height: 240px;
        border-radius: 50%;
        background: rgba(182, 255, 44, 0.08);
    }

.sc-equipment-header-content {
    position: relative;
    z-index: 2;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 24px;
}

.sc-equipment-title-row {
    display: flex;
    align-items: center;
    gap: 18px;
}

.sc-equipment-title-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 64px;
    height: 64px;
    flex-shrink: 0;
    border-radius: 20px;
    background: var(--sc-equip-lime);
    color: var(--sc-equip-primary-dark);
    box-shadow: 0 8px 20px rgba(0, 0, 0, 0.12);
}

    .sc-equipment-title-icon i {
        font-size: 29px;
    }

.sc-equipment-title {
    margin: 0;
    color: #FFFFFF;
    font-size: 28px;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.sc-equipment-subtitle {
    display: block;
    margin-top: 6px;
    color: rgba(255, 255, 255, 0.72);
    font-size: 14px;
}


/* ============================================================
   ORDER EQUIPMENT BUTTON
   ============================================================ */

.sc-order-equipment-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    min-height: 52px;
    padding: 0 22px;
    border-radius: 16px;
    background: var(--sc-equip-lime);
    color: var(--sc-equip-primary-dark);
    text-decoration: none;
    font-size: 14px;
    font-weight: 800;
    white-space: nowrap;
    box-shadow: 0 10px 24px rgba(0, 0, 0, 0.15);
    transition: transform 0.25s ease, box-shadow 0.25s ease, background 0.25s ease;
}

    .sc-order-equipment-btn i {
        font-size: 20px;
    }

    .sc-order-equipment-btn:hover {
        transform: translateY(-3px);
        background: #C6FF4D;
        color: var(--sc-equip-primary-dark);
        box-shadow: 0 16px 30px rgba(0, 0, 0, 0.2);
    }


/* ============================================================
   TABLE CARD
   ============================================================ */

.sc-equipment-table-card {
    overflow: hidden;
    border: 1px solid var(--sc-equip-border);
    border-radius: 24px;
    background: var(--sc-equip-card);
    box-shadow: 0 10px 35px rgba(18, 61, 34, 0.06);
}

.sc-equipment-table-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 24px 28px;
    border-bottom: 1px solid var(--sc-equip-border);
    background: linear-gradient( 180deg, #FFFFFF, #FAFCFB );
}

    .sc-equipment-table-header h2 {
        display: flex;
        align-items: center;
        gap: 10px;
        margin: 0;
        color: var(--sc-equip-text);
        font-size: 19px;
        font-weight: 800;
    }

        .sc-equipment-table-header h2 i {
            color: var(--sc-equip-primary);
            font-size: 22px;
        }

    .sc-equipment-table-header span {
        display: block;
        margin-top: 5px;
        color: var(--sc-equip-muted);
        font-size: 13px;
    }


/* ============================================================
   TABLE WRAPPER
   ============================================================ */

.sc-equipment-table-wrapper {
    width: 100%;
    overflow-x: auto;
}


/* ============================================================
   TABLE
   ============================================================ */

.sc-equipment-table {
    width: 100%;
    min-width: 900px;
    border-collapse: collapse;
}

    .sc-equipment-table thead {
        background: #F7FAF8;
    }

    .sc-equipment-table th {
        padding: 17px 22px;
        border-bottom: 1px solid var(--sc-equip-border);
        color: var(--sc-equip-muted);
        font-size: 11px;
        font-weight: 800;
        letter-spacing: 0.7px;
        text-align: left;
        text-transform: uppercase;
        white-space: nowrap;
    }

    .sc-equipment-table td {
        padding: 20px 22px;
        border-bottom: 1px solid #EDF2EE;
        vertical-align: middle;
        transition: background 0.2s ease;
    }

    .sc-equipment-table tbody tr {
        transition: background 0.2s ease, transform 0.2s ease;
    }

        .sc-equipment-table tbody tr:hover td {
            background: #F8FCF9;
        }

        .sc-equipment-table tbody tr:last-child td {
            border-bottom: none;
        }


/* ============================================================
   EQUIPMENT ITEM
   ============================================================ */

.sc-equipment-item {
    display: flex;
    align-items: center;
    gap: 14px;
    min-width: 220px;
}

.sc-equipment-image {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 56px;
    height: 56px;
    overflow: hidden;
    flex-shrink: 0;
    border: 1px solid var(--sc-equip-border);
    border-radius: 16px;
    background: var(--sc-equip-lime-soft);
}

    .sc-equipment-image img {
        width: 100%;
        height: 100%;
        object-fit: cover;
    }

    .sc-equipment-image i {
        color: var(--sc-equip-primary);
        font-size: 24px;
    }

.sc-equipment-info {
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.sc-equipment-name {
    color: var(--sc-equip-text);
    font-size: 14px;
    font-weight: 800;
}

.sc-equipment-id {
    color: var(--sc-equip-muted);
    font-size: 11px;
}


/* ============================================================
   DESCRIPTION
   ============================================================ */

.sc-equipment-description {
    max-width: 300px;
    color: var(--sc-equip-muted);
    font-size: 13px;
    line-height: 1.55;
}

.sc-equipment-empty {
    color: #A0AEA4;
    font-style: italic;
}


/* ============================================================
   BARCODE
   ============================================================ */

.sc-equipment-barcode {
    min-width: 150px;
}

    .sc-equipment-barcode img {
        display: block;
        width: 140px;
        max-height: 55px;
        padding: 5px;
        border: 1px solid var(--sc-equip-border);
        border-radius: 8px;
        background: #FFFFFF;
        object-fit: contain;
    }

.sc-equipment-barcode-value {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 9px 12px;
    border: 1px solid var(--sc-equip-border);
    border-radius: 10px;
    background: #F8FAF8;
    color: var(--sc-equip-text);
    font-size: 12px;
    font-weight: 700;
}

    .sc-equipment-barcode-value i {
        color: var(--sc-equip-primary);
        font-size: 18px;
    }


/* ============================================================
   STATUS BADGES
   ============================================================ */

.sc-equipment-status {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    padding: 8px 12px;
    border-radius: 100px;
    font-size: 12px;
    font-weight: 800;
    white-space: nowrap;
}

.sc-equipment-status-dot {
    width: 7px;
    height: 7px;
    border-radius: 50%;
}


/* AVAILABLE */

.equipment-status-available {
    background: #E8F8EC;
    color: #167034;
}

    .equipment-status-available .sc-equipment-status-dot {
        background: #20A04A;
        box-shadow: 0 0 0 3px rgba(32, 160, 74, 0.12);
    }


/* IN USE */

.equipment-status-in-use {
    background: #E8F1FF;
    color: #2465B5;
}

    .equipment-status-in-use .sc-equipment-status-dot {
        background: #3A7BD5;
        box-shadow: 0 0 0 3px rgba(58, 123, 213, 0.12);
    }


/* UNDER MAINTENANCE */

.equipment-status-maintenance {
    background: #FFF4DD;
    color: #B56A00;
}

    .equipment-status-maintenance .sc-equipment-status-dot {
        background: #F59E0B;
        box-shadow: 0 0 0 3px rgba(245, 158, 11, 0.12);
    }


/* RETIRED */

.equipment-status-retired {
    background: #FDEBEC;
    color: #B53B42;
}

    .equipment-status-retired .sc-equipment-status-dot {
        background: #D9534F;
        box-shadow: 0 0 0 3px rgba(217, 83, 79, 0.12);
    }


/* DEFAULT */

.equipment-status-default {
    background: #F0F2F1;
    color: #65736A;
}

    .equipment-status-default .sc-equipment-status-dot {
        background: #87938B;
    }


/* ============================================================
   ACTION BUTTONS
   ============================================================ */

.sc-equipment-actions-header {
    text-align: center !important;
}

.sc-equipment-action-buttons {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 9px;
}

.sc-equipment-action-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 40px;
    height: 40px;
    border-radius: 12px;
    text-decoration: none;
    transition: transform 0.2s ease, box-shadow 0.2s ease, background 0.2s ease;
}

    .sc-equipment-action-btn:hover {
        transform: translateY(-2px);
    }


/* VIEW */

.sc-equipment-view-btn {
    background: #EDF8F0;
    color: var(--sc-equip-primary);
}

    .sc-equipment-view-btn:hover {
        background: var(--sc-equip-primary);
        color: #FFFFFF;
        box-shadow: 0 8px 18px rgba(21, 92, 45, 0.2);
    }


/* EDIT */

.sc-equipment-edit-btn {
    background: #EEF4FF;
    color: #326AC0;
}

    .sc-equipment-edit-btn:hover {
        background: #326AC0;
        color: #FFFFFF;
        box-shadow: 0 8px 18px rgba(50, 106, 192, 0.2);
    }


/* ============================================================
   EMPTY STATE
   ============================================================ */

.sc-equipment-empty-state {
    padding: 70px 30px;
    text-align: center;
}

.sc-equipment-empty-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 76px;
    height: 76px;
    margin: 0 auto 18px;
    border-radius: 24px;
    background: var(--sc-equip-lime-soft);
    color: var(--sc-equip-primary);
}

    .sc-equipment-empty-icon i {
        font-size: 34px;
    }

.sc-equipment-empty-state h3 {
    margin: 0 0 8px;
    color: var(--sc-equip-text);
    font-size: 19px;
    font-weight: 800;
}

.sc-equipment-empty-state p {
    max-width: 420px;
    margin: 0 auto;
    color: var(--sc-equip-muted);
    font-size: 14px;
    line-height: 1.6;
}


/* ============================================================
   RESPONSIVE
   ============================================================ */

@media (max-width: 992px) {

    .sc-equipment-page {
        padding: 20px;
    }

    .sc-equipment-header {
        padding: 24px;
    }

    .sc-equipment-title {
        font-size: 24px;
    }
}


@media (max-width: 768px) {

    .sc-equipment-page {
        padding: 14px;
    }

    .sc-equipment-header {
        padding: 22px 20px;
        border-radius: 20px;
    }

    .sc-equipment-header-content {
        flex-direction: column;
        align-items: flex-start;
    }

    .sc-equipment-title-row {
        align-items: flex-start;
    }

    .sc-equipment-title-icon {
        width: 54px;
        height: 54px;
        border-radius: 17px;
    }

        .sc-equipment-title-icon i {
            font-size: 24px;
        }

    .sc-equipment-title {
        font-size: 22px;
    }

    .sc-equipment-subtitle {
        font-size: 13px;
        line-height: 1.5;
    }

    .sc-order-equipment-btn {
        width: 100%;
    }

    .sc-equipment-table-card {
        border-radius: 20px;
    }

    .sc-equipment-table-header {
        padding: 20px;
    }
}


@media (max-width: 480px) {

    .sc-equipment-page {
        padding: 10px;
    }

    .sc-equipment-header {
        margin-bottom: 18px;
    }

    .sc-equipment-title-row {
        gap: 12px;
    }

    .sc-equipment-title {
        font-size: 20px;
    }

    .sc-equipment-table-header h2 {
        font-size: 17px;
    }
}
/* ============================================================
   SWIFTCARE ADMIN DASHBOARD
   ============================================================ */

.sc-dashboard {
    width: 100%;
    min-height: 100%;
    padding: 10px 0 40px;
    color: #123d22;
}


/* ============================================================
   DASHBOARD HEADER
   ============================================================ */

.sc-dashboard-header {
    width: 100%;
    margin-bottom: 30px;
    padding: 34px;
    position: relative;
    overflow: hidden;
    border-radius: 24px;
    background: radial-gradient( circle at top right, rgba(182, 255, 44, 0.18), transparent 35% ), linear-gradient( 135deg, #155c2d, #0d4722 );
    box-shadow: 0 18px 45px rgba(13, 71, 34, 0.16);
}


    /* Decorative glow */

    .sc-dashboard-header::before {
        content: "";
        position: absolute;
        width: 260px;
        height: 260px;
        right: -90px;
        top: -140px;
        border-radius: 50%;
        background: rgba(182, 255, 44, 0.08);
    }

    .sc-dashboard-header::after {
        content: "";
        position: absolute;
        width: 180px;
        height: 180px;
        left: 45%;
        bottom: -130px;
        border-radius: 50%;
        background: rgba(255, 255, 255, 0.04);
    }


.sc-header-content {
    position: relative;
    z-index: 2;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 30px;
}


.sc-header-left {
    max-width: 760px;
}


/* ============================================================
   HEADER BADGE
   ============================================================ */

.sc-header-badge {
    width: fit-content;
    display: inline-flex;
    align-items: center;
    gap: 8px;
    margin-bottom: 15px;
    padding: 8px 13px;
    color: #dfffa5;
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 0.6px;
    border: 1px solid rgba(182, 255, 44, 0.2);
    border-radius: 50px;
    background: rgba(255, 255, 255, 0.07);
    backdrop-filter: blur(8px);
}


    .sc-header-badge i {
        color: #b6ff2c;
        font-size: 15px;
    }


/* ============================================================
   HEADER TEXT
   ============================================================ */

.sc-dashboard-title {
    margin: 0;
    color: #ffffff;
    font-size: clamp(28px, 3vw, 42px);
    font-weight: 800;
    line-height: 1.15;
    letter-spacing: -0.8px;
}


.sc-dashboard-description {
    max-width: 720px;
    margin: 14px 0 0;
    color: #c4d9ca;
    font-size: 15px;
    line-height: 1.7;
}


/* ============================================================
   DATE CARD
   ============================================================ */

.sc-date-card {
    min-width: 250px;
    display: flex;
    align-items: center;
    gap: 14px;
    padding: 16px 18px;
    border-radius: 18px;
    border: 1px solid rgba(255, 255, 255, 0.12);
    background: rgba(255, 255, 255, 0.08);
    backdrop-filter: blur(12px);
}


.sc-date-icon {
    width: 48px;
    height: 48px;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    border-radius: 14px;
    background: #b6ff2c;
    color: #155c2d;
    font-size: 22px;
}


.sc-date-content {
    display: flex;
    flex-direction: column;
    gap: 3px;
}


.sc-date-label {
    color: #b9d0c0;
    font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.7px;
}


.sc-date-value {
    color: #ffffff;
    font-size: 13px;
    font-weight: 700;
    white-space: nowrap;
}


/* ============================================================
   QUICK ACTIONS SECTION
   ============================================================ */

.sc-actions-section {
    width: 100%;
}


.sc-section-header {
    display: flex;
    align-items: flex-end;
    justify-content: space-between;
    gap: 25px;
    margin-bottom: 22px;
}


.sc-section-label {
    margin-bottom: 6px;
    color: #155c2d;
    font-size: 11px;
    font-weight: 800;
    letter-spacing: 1.4px;
}


.sc-section-title {
    margin: 0;
    color: #123d22;
    font-size: 29px;
    font-weight: 800;
    letter-spacing: -0.4px;
}


.sc-section-description {
    margin: 7px 0 0;
    color: #718277;
    font-size: 14px;
}


/* ============================================================
   SYSTEM STATUS
   ============================================================ */

.sc-section-status {
    display: inline-flex;
    align-items: center;
    gap: 9px;
    padding: 10px 15px;
    color: #155c2d;
    font-size: 12px;
    font-weight: 700;
    border: 1px solid #dce9df;
    border-radius: 50px;
    background: #ffffff;
    box-shadow: 0 5px 16px rgba(13, 71, 34, 0.05);
}


.sc-status-dot {
    width: 9px;
    height: 9px;
    display: inline-block;
    border-radius: 50%;
    background: #49b56c;
    box-shadow: 0 0 0 5px rgba(73, 181, 108, 0.12);
}


/* ============================================================
   ACTION GRID
   ============================================================ */

.sc-action-grid {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 22px;
}


/* ============================================================
   ACTION CARD
   ============================================================ */

.sc-action-card {
    position: relative;
    min-height: 280px;
    display: flex;
    flex-direction: column;
    padding: 25px;
    overflow: hidden;
    text-decoration: none;
    border: 1px solid #e0e9e3;
    border-radius: 22px;
    background: linear-gradient( 145deg, #ffffff, #f8fbf9 );
    box-shadow: 0 10px 30px rgba(13, 71, 34, 0.06);
    transition: transform 0.25s ease, box-shadow 0.25s ease, border-color 0.25s ease;
}


    /* Accent */

    .sc-action-card::before {
        content: "";
        position: absolute;
        top: 0;
        left: 0;
        right: 0;
        height: 4px;
        background: linear-gradient( 90deg, #155c2d, #b6ff2c );
        opacity: 0;
        transition: opacity 0.25s ease;
    }


    /* Glow */

    .sc-action-card::after {
        content: "";
        position: absolute;
        width: 180px;
        height: 180px;
        right: -80px;
        bottom: -90px;
        border-radius: 50%;
        background: radial-gradient( circle, rgba(182, 255, 44, 0.13), transparent 70% );
        pointer-events: none;
    }


    .sc-action-card:hover {
        transform: translateY(-7px);
        border-color: rgba(21, 92, 45, 0.2);
        box-shadow: 0 22px 45px rgba(13, 71, 34, 0.13);
    }


        .sc-action-card:hover::before {
            opacity: 1;
        }


/* ============================================================
   CARD TOP
   ============================================================ */

.sc-action-top {
    position: relative;
    z-index: 2;
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
}


.sc-action-icon {
    width: 64px;
    height: 64px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 18px;
    color: #155c2d;
    font-size: 29px;
    background: linear-gradient( 135deg, #efffce, #e3f8df );
    border: 1px solid #d9eddc;
    transition: transform 0.25s ease, background 0.25s ease;
}


.sc-action-card:hover .sc-action-icon {
    transform: scale(1.08);
    background: #b6ff2c;
}


.sc-action-arrow {
    color: #9aa9a0;
    font-size: 21px;
    transition: transform 0.25s ease, color 0.25s ease;
}


.sc-action-card:hover .sc-action-arrow {
    color: #155c2d;
    transform: translate(3px, -3px);
}


/* ============================================================
   CARD BODY
   ============================================================ */

.sc-action-body {
    position: relative;
    z-index: 2;
    margin-top: 28px;
}


    .sc-action-body h3 {
        margin: 0 0 9px;
        color: #123d22;
        font-size: 20px;
        font-weight: 800;
        letter-spacing: -0.2px;
    }


    .sc-action-body p {
        margin: 0;
        color: #718277;
        font-size: 13.5px;
        line-height: 1.65;
    }


/* ============================================================
   CARD FOOTER
   ============================================================ */

.sc-action-footer {
    position: relative;
    z-index: 2;
    margin-top: auto;
    padding-top: 24px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    color: #155c2d;
    font-size: 13px;
    font-weight: 800;
}


    .sc-action-footer i {
        width: 34px;
        height: 34px;
        display: flex;
        align-items: center;
        justify-content: center;
        border-radius: 50%;
        background: #efffce;
        font-size: 17px;
        transition: background 0.25s ease, transform 0.25s ease;
    }


.sc-action-card:hover .sc-action-footer i {
    background: #b6ff2c;
    transform: translateX(4px);
}


/* ============================================================
   FOCUS / ACCESSIBILITY
   ============================================================ */

.sc-action-card:focus-visible {
    outline: 3px solid rgba(182, 255, 44, 0.7);
    outline-offset: 4px;
}


/* ============================================================
   LARGE SCREENS
   ============================================================ */

@media (min-width: 1500px) {

    .sc-action-grid {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }

    .sc-action-card {
        min-height: 300px;
    }
}


/* ============================================================
   TABLET
   ============================================================ */

@media (max-width: 1100px) {

    .sc-action-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .sc-date-card {
        min-width: 220px;
    }
}


/* ============================================================
   SMALL TABLET
   ============================================================ */

@media (max-width: 850px) {

    .sc-dashboard-header {
        padding: 27px;
    }

    .sc-header-content {
        align-items: flex-start;
        flex-direction: column;
    }

    .sc-date-card {
        width: 100%;
        min-width: 0;
    }

    .sc-section-header {
        align-items: flex-start;
        flex-direction: column;
    }
}


/* ============================================================
   MOBILE
   ============================================================ */

@media (max-width: 650px) {

    .sc-dashboard {
        padding: 0 0 30px;
    }

    .sc-dashboard-header {
        padding: 24px 20px;
        border-radius: 20px;
        margin-bottom: 25px;
    }

    .sc-dashboard-title {
        font-size: 29px;
    }

    .sc-dashboard-description {
        font-size: 13.5px;
    }

    .sc-section-title {
        font-size: 25px;
    }

    .sc-action-grid {
        grid-template-columns: 1fr;
        gap: 16px;
    }

    .sc-action-card {
        min-height: 245px;
        padding: 22px;
    }

    .sc-action-icon {
        width: 58px;
        height: 58px;
        font-size: 26px;
        border-radius: 16px;
    }

    .sc-section-status {
        width: 100%;
        justify-content: center;
    }
}


/* ============================================================
   VERY SMALL DEVICES
   ============================================================ */

@media (max-width: 400px) {

    .sc-dashboard-header {
        padding: 20px 16px;
    }

    .sc-action-card {
        padding: 19px;
    }

    .sc-date-value {
        white-space: normal;
    }
}

/* ============================================================
           SWIFTCARE EQUIPMENT ORDERS
           FOREST GREEN + LIME GREEN THEME
           ============================================================ */

.sc-orders-page {
    min-height: 100%;
    padding: 0 0 45px;
    color: #1f2937;
}


/* ============================================================
           HEADER
           ============================================================ */

.sc-orders-header {
    position: relative;
    overflow: hidden;
    margin-bottom: 30px;
    padding: 30px;
    border-radius: 0 0 24px 24px;
    background: linear-gradient( 135deg, #123d24 0%, #1f6b3b 55%, #14532d 100% );
    box-shadow: 0 10px 30px rgba(20, 83, 45, 0.18);
}

    .sc-orders-header::before {
        content: "";
        position: absolute;
        width: 280px;
        height: 280px;
        border-radius: 50%;
        top: -160px;
        right: -80px;
        background: rgba(190, 242, 100, 0.12);
        pointer-events: none;
    }

    .sc-orders-header::after {
        content: "";
        position: absolute;
        width: 180px;
        height: 180px;
        border-radius: 50%;
        bottom: -130px;
        right: 180px;
        background: rgba(163, 230, 53, 0.08);
        pointer-events: none;
    }

.sc-orders-header-inner {
    position: relative;
    z-index: 1;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 25px;
}

.sc-orders-title-section {
    display: flex;
    align-items: center;
    gap: 18px;
}

.sc-orders-back-button {
    width: 48px;
    height: 48px;
    flex-shrink: 0;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 14px;
    color: #ffffff;
    text-decoration: none;
    font-size: 1.25rem;
    background: rgba(255, 255, 255, 0.12);
    border: 1px solid rgba(255, 255, 255, 0.18);
    transition: all 0.25s ease;
}

    .sc-orders-back-button:hover {
        color: #123d24;
        background: #bef264;
        border-color: #bef264;
        transform: translateX(-3px);
    }

.sc-orders-heading {
    margin: 0;
    color: #ffffff;
    font-size: 1.85rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.sc-orders-subheading {
    margin: 6px 0 0;
    color: rgba(255, 255, 255, 0.78);
    font-size: 0.95rem;
}


/* ============================================================
           FILTERS
           ============================================================ */

.sc-orders-filter-group {
    display: flex;
    align-items: center;
    gap: 10px;
    flex-wrap: wrap;
}

.sc-orders-filter-button {
    border: 1px solid rgba(255, 255, 255, 0.16);
    padding: 10px 16px;
    border-radius: 12px;
    background: rgba(255, 255, 255, 0.1);
    color: #ffffff;
    font-size: 0.88rem;
    font-weight: 700;
    cursor: pointer;
    transition: all 0.25s ease;
}

    .sc-orders-filter-button:hover {
        background: rgba(190, 242, 100, 0.18);
        border-color: #bef264;
        transform: translateY(-2px);
    }

    .sc-orders-filter-button.sc-orders-filter-active {
        background: #bef264;
        color: #123d24;
        border-color: #bef264;
        box-shadow: 0 6px 18px rgba(0, 0, 0, 0.15);
    }


/* ============================================================
           TEMP MESSAGE
           ============================================================ */

#scOrdersTempMessage {
    margin: 0 20px 25px;
    border-radius: 14px;
    border: none;
    font-weight: 600;
    box-shadow: 0 5px 16px rgba(0, 0, 0, 0.06);
}


/* ============================================================
           ORDERS GRID
           ============================================================ */

.sc-orders-grid {
    padding-bottom: 20px;
}


/* ============================================================
           ORDER CARD
           ============================================================ */

.sc-orders-card {
    height: 100%;
    overflow: hidden;
    display: flex;
    flex-direction: column;
    background: #ffffff;
    border: 1px solid #e2e8e0;
    border-radius: 20px;
    box-shadow: 0 5px 20px rgba(20, 83, 45, 0.07);
    transition: transform 0.28s ease, box-shadow 0.28s ease, border-color 0.28s ease;
}

    .sc-orders-card:hover {
        transform: translateY(-6px);
        border-color: rgba(132, 204, 22, 0.55);
        box-shadow: 0 18px 38px rgba(20, 83, 45, 0.15);
    }


/* ============================================================
           CARD HEADER
           ============================================================ */

.sc-orders-card-header {
    position: relative;
    overflow: hidden;
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 22px;
    color: #ffffff;
    background: linear-gradient( 135deg, #14532d, #1f6b3b );
}

    .sc-orders-card-header::after {
        content: "";
        position: absolute;
        width: 110px;
        height: 110px;
        border-radius: 50%;
        top: -55px;
        right: -30px;
        background: rgba(190, 242, 100, 0.1);
    }

.sc-orders-card-header-content {
    position: relative;
    z-index: 1;
}

.sc-orders-card-label {
    margin-bottom: 5px;
    color: rgba(255, 255, 255, 0.68);
    font-size: 0.72rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 1px;
}

.sc-orders-card-number {
    font-size: 1.12rem;
    font-weight: 800;
    word-break: break-word;
}

.sc-orders-card-header-icon {
    position: relative;
    z-index: 1;
    width: 50px;
    height: 50px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 15px;
    color: #bef264;
    font-size: 1.4rem;
    background: rgba(255, 255, 255, 0.12);
    border: 1px solid rgba(255, 255, 255, 0.12);
}


/* ============================================================
           CARD BODY
           ============================================================ */

.sc-orders-card-body {
    flex: 1;
    padding: 10px 22px 20px;
}

.sc-orders-info-row {
    display: flex;
    align-items: center;
    gap: 14px;
    padding: 15px 0;
    border-bottom: 1px solid #edf1eb;
}

    .sc-orders-info-row:last-child {
        border-bottom: none;
    }

.sc-orders-info-icon {
    width: 42px;
    height: 42px;
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 13px;
    color: #1f6b3b;
    background: #f0f8eb;
    font-size: 1.05rem;
    transition: all 0.25s ease;
}

.sc-orders-card:hover .sc-orders-info-icon {
    color: #14532d;
    background: #ecfccb;
}

.sc-orders-info-content {
    min-width: 0;
    display: flex;
    flex-direction: column;
}

.sc-orders-info-label {
    margin-bottom: 3px;
    color: #7b8790;
    font-size: 0.73rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.4px;
}

.sc-orders-info-value {
    color: #243027;
    font-size: 0.92rem;
    font-weight: 700;
}


/* ============================================================
           STATUS BADGES
           ============================================================ */

.sc-orders-status-badge {
    width: fit-content;
    display: inline-flex;
    align-items: center;
    padding: 6px 12px;
    border-radius: 999px;
    font-size: 0.78rem;
    font-weight: 800;
}

.sc-orders-status-pending {
    color: #8a5a00;
    background: #fff4cc;
    border: 1px solid #fde68a;
}

.sc-orders-status-ontheway {
    color: #14532d;
    background: #ecfccb;
    border: 1px solid #bef264;
}

.sc-orders-status-collected {
    color: #ffffff;
    background: #1f6b3b;
    border: 1px solid #14532d;
}


/* ============================================================
           CARD ACTIONS
           ============================================================ */

.sc-orders-card-actions {
    padding: 0 22px 22px;
}

.sc-orders-details-button {
    width: 100%;
    min-height: 48px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    padding: 12px 18px;
    border-radius: 13px;
    color: #ffffff;
    text-decoration: none;
    font-size: 0.9rem;
    font-weight: 750;
    background: #14532d;
    border: 1px solid #14532d;
    box-shadow: 0 5px 14px rgba(20, 83, 45, 0.14);
    transition: all 0.25s ease;
}

    .sc-orders-details-button:hover {
        color: #123d24;
        background: #bef264;
        border-color: #bef264;
        box-shadow: 0 8px 20px rgba(132, 204, 22, 0.22);
        transform: translateY(-2px);
    }

    .sc-orders-details-button i:last-child {
        transition: transform 0.25s ease;
    }

    .sc-orders-details-button:hover i:last-child {
        transform: translateX(4px);
    }


/* ============================================================
           EMPTY STATE
           ============================================================ */

.sc-orders-empty-state,
.sc-orders-no-results {
    max-width: 720px;
    margin: 25px auto;
    padding: 60px 30px;
    text-align: center;
    background: #ffffff;
    border: 1px solid #e2e8e0;
    border-radius: 22px;
    box-shadow: 0 10px 30px rgba(20, 83, 45, 0.07);
}

.sc-orders-no-results {
    display: none;
}

.sc-orders-empty-icon {
    width: 82px;
    height: 82px;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 auto 20px;
    border-radius: 24px;
    color: #14532d;
    background: #ecfccb;
    font-size: 2rem;
    border: 1px solid #d9f99d;
}

.sc-orders-empty-state h4,
.sc-orders-no-results h5 {
    margin-bottom: 10px;
    color: #173b25;
    font-weight: 800;
}

.sc-orders-empty-state p,
.sc-orders-no-results p {
    max-width: 500px;
    margin: 0 auto 25px;
    color: #718078;
}

.sc-orders-empty-button {
    width: auto;
    min-width: 210px;
}


/* ============================================================
           RESPONSIVE
           ============================================================ */

@media (max-width: 992px) {

    .sc-orders-header-inner {
        align-items: flex-start;
        flex-direction: column;
    }

    .sc-orders-filter-group {
        width: 100%;
    }
}

@media (max-width: 768px) {

    .sc-orders-page {
        padding-bottom: 25px;
    }

    .sc-orders-header {
        padding: 22px 18px;
        border-radius: 0 0 20px 20px;
    }

    .sc-orders-title-section {
        align-items: flex-start;
    }

    .sc-orders-back-button {
        width: 44px;
        height: 44px;
    }

    .sc-orders-heading {
        font-size: 1.45rem;
    }

    .sc-orders-subheading {
        font-size: 0.87rem;
    }

    .sc-orders-filter-group {
        gap: 8px;
    }

    .sc-orders-filter-button {
        flex: 1;
        min-width: 105px;
        padding: 10px 8px;
        font-size: 0.8rem;
    }

    .sc-orders-card-header,
    .sc-orders-card-body,
    .sc-orders-card-actions {
        padding-left: 17px;
        padding-right: 17px;
    }

    .sc-orders-empty-state,
    .sc-orders-no-results {
        margin: 20px 15px;
        padding: 45px 20px;
    }
}

@media (max-width: 480px) {

    .sc-orders-title-section {
        gap: 12px;
    }

    .sc-orders-heading {
        font-size: 1.3rem;
    }

    .sc-orders-filter-button {
        min-width: calc(50% - 5px);
    }

    .sc-orders-card-header-icon {
        width: 45px;
        height: 45px;
    }
}
/* ============================================================
           SWIFTCARE RECEIVE ORDER
           FOREST GREEN + LIME GREEN
           ============================================================ */

:root {
    --sc-receive-forest: #14532d;
    --sc-receive-forest-dark: #0b3b20;
    --sc-receive-forest-light: #eaf7ee;
    --sc-receive-lime: #a3e635;
    --sc-receive-lime-dark: #65a30d;
    --sc-receive-white: #ffffff;
    --sc-receive-text: #1f2937;
    --sc-receive-muted: #6b7280;
    --sc-receive-border: #dce8df;
}

.sc-receive-page {
    padding-bottom: 110px;
    color: var(--sc-receive-text);
}

/* ============================================================
           HEADER
           ============================================================ */

.sc-receive-header {
    background: linear-gradient( 135deg, var(--sc-receive-forest-dark), var(--sc-receive-forest) );
    padding: 28px 32px;
    border-radius: 0 0 24px 24px;
    margin-bottom: 30px;
    box-shadow: 0 10px 30px rgba(20, 83, 45, 0.15);
}

.sc-receive-header-inner {
    display: flex;
    align-items: center;
    gap: 20px;
}

.sc-receive-back {
    width: 46px;
    height: 46px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    text-decoration: none;
    color: white;
    background: rgba(255,255,255,0.12);
    border: 1px solid rgba(255,255,255,0.16);
    border-radius: 14px;
    transition: all 0.25s ease;
}

    .sc-receive-back:hover {
        color: var(--sc-receive-lime);
        background: rgba(255,255,255,0.18);
        transform: translateX(-3px);
    }

.sc-receive-title {
    margin: 0;
    color: white;
    font-size: 1.75rem;
    font-weight: 750;
}

.sc-receive-subtitle {
    margin: 5px 0 0;
    color: rgba(255,255,255,0.75);
    font-size: 0.95rem;
}

/* ============================================================
           ORDER SUMMARY
           ============================================================ */

.sc-receive-summary-card {
    background: white;
    border: 1px solid var(--sc-receive-border);
    border-radius: 20px;
    padding: 22px;
    margin-bottom: 28px;
    box-shadow: 0 8px 25px rgba(0,0,0,0.05);
}

.sc-receive-summary-item {
    padding: 8px 14px;
}

.sc-receive-summary-label {
    display: block;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.8px;
    color: var(--sc-receive-muted);
    margin-bottom: 5px;
}

.sc-receive-summary-value {
    font-size: 1rem;
    font-weight: 700;
    color: var(--sc-receive-forest-dark);
}

/* ============================================================
           INFORMATION MESSAGE
           ============================================================ */

.sc-receive-info-banner {
    display: flex;
    align-items: flex-start;
    gap: 14px;
    background: var(--sc-receive-forest-light);
    border: 1px solid #c8e6d0;
    border-radius: 18px;
    padding: 18px 20px;
    margin-bottom: 25px;
}

.sc-receive-info-icon {
    width: 42px;
    height: 42px;
    flex-shrink: 0;
    border-radius: 12px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: var(--sc-receive-forest);
    color: var(--sc-receive-lime);
    font-size: 1.2rem;
}

.sc-receive-info-title {
    font-weight: 700;
    color: var(--sc-receive-forest-dark);
    margin-bottom: 4px;
}

.sc-receive-info-text {
    color: #4b6352;
    font-size: 0.9rem;
    margin: 0;
}

/* ============================================================
           EQUIPMENT SECTION
           ============================================================ */

.sc-receive-section-title {
    display: flex;
    align-items: center;
    gap: 10px;
    font-weight: 750;
    color: var(--sc-receive-forest-dark);
    margin-bottom: 18px;
}

    .sc-receive-section-title i {
        color: var(--sc-receive-lime-dark);
    }

/* ============================================================
           EQUIPMENT CARD
           ============================================================ */

.sc-receive-equipment-card {
    position: relative;
    background: white;
    border: 1px solid var(--sc-receive-border);
    border-radius: 20px;
    padding: 22px;
    margin-bottom: 18px;
    box-shadow: 0 7px 22px rgba(0,0,0,0.045);
    transition: all 0.25s ease;
}

    .sc-receive-equipment-card:hover {
        border-color: var(--sc-receive-lime-dark);
        transform: translateY(-2px);
        box-shadow: 0 12px 30px rgba(20,83,45,0.09);
    }

.sc-receive-equipment-icon {
    width: 52px;
    height: 52px;
    border-radius: 16px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: var(--sc-receive-forest-light);
    color: var(--sc-receive-forest);
    font-size: 1.4rem;
    flex-shrink: 0;
}

.sc-receive-equipment-name {
    font-size: 1.05rem;
    font-weight: 750;
    margin-bottom: 5px;
    color: var(--sc-receive-forest-dark);
}

.sc-receive-equipment-id {
    font-size: 0.78rem;
    color: var(--sc-receive-muted);
}

/* ============================================================
           QUANTITY DISPLAY
           ============================================================ */

.sc-receive-quantity-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 15px;
    margin-top: 20px;
}

.sc-receive-quantity-box {
    background: #f8fbf8;
    border: 1px solid var(--sc-receive-border);
    border-radius: 15px;
    padding: 15px;
}

.sc-receive-quantity-label {
    display: block;
    font-size: 0.72rem;
    color: var(--sc-receive-muted);
    text-transform: uppercase;
    letter-spacing: 0.6px;
    margin-bottom: 6px;
}

.sc-receive-quantity-value {
    font-size: 1.35rem;
    font-weight: 800;
    color: var(--sc-receive-forest-dark);
}

.sc-receive-input {
    width: 100%;
    border: 1px solid var(--sc-receive-border);
    border-radius: 14px;
    padding: 12px 14px;
    font-size: 1rem;
    font-weight: 700;
    color: var(--sc-receive-forest-dark);
    outline: none;
    transition: all 0.2s ease;
    background: white;
}

    .sc-receive-input:focus {
        border-color: var(--sc-receive-lime-dark);
        box-shadow: 0 0 0 4px rgba(163,230,53,0.18);
    }

.sc-receive-difference {
    margin-top: 16px;
    padding: 10px 14px;
    border-radius: 12px;
    background: #f6f8f6;
    color: var(--sc-receive-muted);
    font-size: 0.85rem;
}

    .sc-receive-difference strong {
        color: var(--sc-receive-forest-dark);
    }

/* ============================================================
           EMPTY STATE
           ============================================================ */

.sc-receive-empty {
    text-align: center;
    padding: 70px 25px;
    background: white;
    border-radius: 22px;
    border: 1px solid var(--sc-receive-border);
    box-shadow: 0 8px 25px rgba(0,0,0,0.05);
}

.sc-receive-empty-icon {
    width: 78px;
    height: 78px;
    border-radius: 50%;
    background: var(--sc-receive-forest-light);
    color: var(--sc-receive-forest);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 2rem;
    margin: 0 auto 18px;
}

/* ============================================================
           FOOTER
           ============================================================ */

.sc-receive-footer {
    position: fixed;
    bottom: 0;
    left: 0;
    right: 0;
    background: rgba(255,255,255,0.96);
    backdrop-filter: blur(12px);
    border-top: 1px solid var(--sc-receive-border);
    padding: 16px 25px;
    z-index: 100;
}

.sc-receive-footer-inner {
    display: flex;
    justify-content: flex-end;
}

.sc-receive-submit-button {
    border: none;
    background: var(--sc-receive-forest);
    color: white;
    border-radius: 14px;
    padding: 13px 24px;
    font-weight: 700;
    display: inline-flex;
    align-items: center;
    gap: 9px;
    transition: all 0.25s ease;
}

    .sc-receive-submit-button:hover {
        background: var(--sc-receive-forest-dark);
        color: white;
        transform: translateY(-2px);
        box-shadow: 0 8px 20px rgba(20,83,45,0.2);
    }

    .sc-receive-submit-button i {
        color: var(--sc-receive-lime);
    }

@media (max-width: 768px) {

    .sc-receive-header {
        padding: 22px 18px;
    }

    .sc-receive-title {
        font-size: 1.35rem;
    }

    .sc-receive-summary-card {
        padding: 15px;
    }

    .sc-receive-quantity-grid {
        grid-template-columns: 1fr;
    }

    .sc-receive-footer-inner {
        justify-content: stretch;
    }

    .sc-receive-submit-button {
        width: 100%;
        justify-content: center;
    }
}
/* ============================================================
   SWIFTCARE RECEIVE ORDER - QR / BARCODE SCANNER
   FOREST GREEN + LIME GREEN
   ============================================================ */

.sc-receive-scanner-card {
    background: #ffffff;
    border: 1px solid rgba(24, 88, 52, 0.12);
    border-radius: 22px;
    padding: 22px;
    box-shadow: 0 10px 35px rgba(18, 72, 42, 0.08);
    height: 100%;
    overflow: hidden;
}

.sc-receive-scanner-heading {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 8px;
}

.sc-receive-scanner-heading-icon {
    width: 45px;
    height: 45px;
    border-radius: 14px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: rgba(109, 179, 63, 0.14);
    color: #2f7d32;
    font-size: 1.25rem;
}

.sc-receive-scanner-title {
    margin: 0;
    color: #174d2c;
    font-size: 1.05rem;
    font-weight: 700;
}

.sc-receive-scanner-description {
    margin: 0 0 20px;
    color: #718096;
    font-size: 0.9rem;
    line-height: 1.6;
}

/* ============================================================
   SCANNER AREA
   ============================================================ */

.sc-receive-scanner-area {
    position: relative;
    padding: 8px;
    background: linear-gradient( 135deg, rgba(24, 88, 52, 0.06), rgba(109, 179, 63, 0.12) );
    border: 1px solid rgba(109, 179, 63, 0.2);
    border-radius: 20px;
    overflow: hidden;
}

/* The html5-qrcode scanner */

#scReceiveScanner {
    width: 100%;
    overflow: hidden;
    border-radius: 15px;
    background: #f7faf8;
}

    /* Remove ugly default borders */

    #scReceiveScanner video {
        width: 100% !important;
        height: auto !important;
        border-radius: 14px;
        display: block;
    }

    #scReceiveScanner img {
        border-radius: 14px;
    }

/* html5-qrcode internal elements */

#scReceiveScanner__dashboard {
    padding: 12px !important;
}

#scReceiveScanner__dashboard_section {
    padding: 0 !important;
}

#scReceiveScanner__dashboard_section_csr {
    display: flex !important;
    justify-content: center;
    align-items: center;
    flex-wrap: wrap;
    gap: 10px;
}

#scReceiveScanner button {
    border: none !important;
    background: #1f6b3b !important;
    color: #ffffff !important;
    border-radius: 10px !important;
    padding: 9px 14px !important;
    font-size: 0.85rem !important;
    font-weight: 600 !important;
    cursor: pointer !important;
    transition: all 0.2s ease !important;
}

    #scReceiveScanner button:hover {
        background: #174d2c !important;
        transform: translateY(-1px);
    }

#scReceiveScanner select {
    border: 1px solid rgba(24, 88, 52, 0.2) !important;
    border-radius: 9px !important;
    padding: 8px 10px !important;
    background: #ffffff !important;
    color: #174d2c !important;
    outline: none !important;
}

/* ============================================================
   SCANNER STATUS
   ============================================================ */

.sc-receive-scanner-status {
    display: flex;
    align-items: center;
    gap: 9px;
    margin-top: 16px;
    padding: 12px 14px;
    border-radius: 12px;
    background: rgba(24, 88, 52, 0.07);
    color: #1f6b3b;
    font-size: 0.86rem;
    font-weight: 600;
    transition: all 0.25s ease;
}

    .sc-receive-scanner-status i {
        font-size: 1rem;
        color: #6db33f;
    }

    /* ============================================================
   SUCCESS STATUS
   ============================================================ */

    .sc-receive-scanner-status.sc-receive-scan-success {
        background: rgba(109, 179, 63, 0.16);
        color: #276738;
        border: 1px solid rgba(109, 179, 63, 0.3);
    }

        .sc-receive-scanner-status.sc-receive-scan-success i {
            color: #4d9c2b;
        }

    /* ============================================================
   WARNING / UNKNOWN BOX
   ============================================================ */

    .sc-receive-scanner-status.sc-receive-scan-warning {
        background: #fff8e7;
        color: #9a6b12;
        border: 1px solid rgba(212, 162, 40, 0.3);
    }

        .sc-receive-scanner-status.sc-receive-scan-warning i {
            color: #c58a17;
        }

    /* ============================================================
   ERROR
   ============================================================ */

    .sc-receive-scanner-status.sc-receive-scan-error {
        background: #fff0f0;
        color: #a83232;
        border: 1px solid rgba(190, 60, 60, 0.2);
    }

        .sc-receive-scanner-status.sc-receive-scan-error i {
            color: #c0392b;
        }

/* ============================================================
   LAST SCANNED BOX
   ============================================================ */

.sc-receive-last-scan {
    margin-top: 16px;
    padding: 14px;
    border-radius: 14px;
    background: linear-gradient( 135deg, #174d2c, #1f6b3b );
    color: white;
    display: none;
}

.sc-receive-last-scan-label {
    display: block;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.8px;
    opacity: 0.7;
    margin-bottom: 4px;
}

.sc-receive-last-scan-value {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    word-break: break-word;
}

/* ============================================================
   SCANNER SCAN FRAME EFFECT
   ============================================================ */

.sc-receive-scanner-area::before,
.sc-receive-scanner-area::after {
    content: "";
    position: absolute;
    width: 28px;
    height: 28px;
    border-color: #6db33f;
    pointer-events: none;
    z-index: 2;
}

.sc-receive-scanner-area::before {
    top: 16px;
    left: 16px;
    border-top: 3px solid;
    border-left: 3px solid;
    border-radius: 8px 0 0 0;
}

.sc-receive-scanner-area::after {
    right: 16px;
    bottom: 16px;
    border-right: 3px solid;
    border-bottom: 3px solid;
    border-radius: 0 0 8px 0;
}

/* ============================================================
   SCAN SUCCESS ANIMATION
   ============================================================ */

.sc-receive-scanner-card.sc-receive-scan-flash {
    animation: scReceiveScanFlash 0.45s ease;
}

@keyframes scReceiveScanFlash {

    0% {
        transform: scale(1);
    }

    50% {
        transform: scale(1.015);
        box-shadow: 0 0 0 5px rgba(109, 179, 63, 0.18);
    }

    100% {
        transform: scale(1);
    }
}

/* ============================================================
   MOBILE
   ============================================================ */

@media (max-width: 991px) {

    .sc-receive-scanner-card {
        margin-bottom: 24px;
    }
}

@media (max-width: 576px) {

    .sc-receive-scanner-card {
        padding: 17px;
        border-radius: 18px;
    }

    .sc-receive-scanner-heading-icon {
        width: 40px;
        height: 40px;
        border-radius: 12px;
    }

    .sc-receive-scanner-area {
        border-radius: 16px;
        padding: 6px;
    }

    .sc-receive-scanner-status {
        font-size: 0.8rem;
        padding: 10px 12px;
    }
}
/* ============================================================
   SWIFTCARE – EQUIPMENT ORDERS
   FOREST GREEN + LIME THEME
   Unique classes: sc-orders-*
   ============================================================ */

:root {
    --sc-forest: #1f5c3a;
    --sc-forest-dark: #16442b;
    --sc-forest-light: #2f7a4f;
    --sc-lime: #a8d94b;
    --sc-lime-light: #dff3b8;
    --sc-lime-soft: #f1f9df;
    --sc-page-bg: #f4f8f3;
    --sc-white: #ffffff;
    --sc-text: #1d2b22;
    --sc-muted: #708078;
    --sc-border: #dfe8df;
    --sc-shadow: 0 10px 35px rgba(25, 75, 45, 0.08);
}


/* ============================================================
   PAGE
   ============================================================ */

.sc-orders-page {
    min-height: 100vh;
    padding: 24px;
    background: radial-gradient( circle at top right, rgba(168, 217, 75, 0.12), transparent 30% ), var(--sc-page-bg);
}


/* ============================================================
   HEADER
   ============================================================ */

.sc-orders-header {
    position: relative;
    overflow: hidden;
    margin-bottom: 28px;
    padding: 28px 32px;
    border-radius: 22px;
    background: linear-gradient( 135deg, var(--sc-forest-dark), var(--sc-forest) );
    box-shadow: var(--sc-shadow);
}

    .sc-orders-header::after {
        content: "";
        position: absolute;
        width: 260px;
        height: 260px;
        top: -150px;
        right: -60px;
        border-radius: 50%;
        background: rgba(168, 217, 75, 0.14);
    }

.sc-orders-header-inner {
    position: relative;
    z-index: 2;
    display: flex;
    align-items: center;
    gap: 18px;
}

.sc-orders-back {
    width: 46px;
    height: 46px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    border-radius: 14px;
    background: rgba(255, 255, 255, 0.12);
    color: var(--sc-white);
    text-decoration: none;
    font-size: 1.35rem;
    transition: all 0.25s ease;
}

    .sc-orders-back:hover {
        background: var(--sc-lime);
        color: var(--sc-forest-dark);
        transform: translateX(-3px);
    }

.sc-orders-header-title {
    margin: 0;
    color: var(--sc-white);
    font-size: 1.8rem;
    font-weight: 750;
    letter-spacing: -0.5px;
}

.sc-orders-header-subtitle {
    margin: 5px 0 0;
    color: rgba(255, 255, 255, 0.72);
    font-size: 0.92rem;
}


/* ============================================================
   TOOLBAR
   ============================================================ */

.sc-orders-toolbar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 20px;
    margin-bottom: 24px;
}

.sc-orders-search {
    position: relative;
    width: 100%;
    max-width: 480px;
}

    .sc-orders-search i {
        position: absolute;
        top: 50%;
        left: 17px;
        transform: translateY(-50%);
        color: var(--sc-muted);
        pointer-events: none;
    }

.sc-orders-search-input {
    width: 100%;
    height: 50px;
    padding: 0 18px 0 46px;
    border: 1px solid var(--sc-border);
    border-radius: 14px;
    outline: none;
    background: var(--sc-white);
    color: var(--sc-text);
    box-shadow: 0 4px 18px rgba(20, 60, 35, 0.04);
    transition: all 0.25s ease;
}

    .sc-orders-search-input::placeholder {
        color: #9aa69e;
    }

    .sc-orders-search-input:focus {
        border-color: var(--sc-lime);
        box-shadow: 0 0 0 4px rgba(168, 217, 75, 0.18), 0 5px 20px rgba(20, 70, 40, 0.08);
    }


/* ============================================================
   BUTTONS
   ============================================================ */

.sc-orders-primary-button,
.sc-orders-package-button,
.sc-orders-action-button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    border: none;
    border-radius: 12px;
    font-weight: 650;
    text-decoration: none;
    cursor: pointer;
    transition: all 0.25s ease;
}

.sc-orders-primary-button {
    min-height: 48px;
    padding: 0 20px;
    background: var(--sc-forest);
    color: var(--sc-white);
    box-shadow: 0 8px 18px rgba(31, 92, 58, 0.18);
}

    .sc-orders-primary-button:hover {
        background: var(--sc-forest-dark);
        color: var(--sc-white);
        transform: translateY(-2px);
    }

.sc-orders-package-button {
    min-height: 38px;
    padding: 0 14px;
    background: var(--sc-lime-light);
    color: var(--sc-forest-dark);
    font-size: 0.82rem;
}

    .sc-orders-package-button:hover {
        background: var(--sc-lime);
        color: var(--sc-forest-dark);
        transform: translateY(-1px);
    }

.sc-orders-action-button {
    min-height: 38px;
    padding: 0 14px;
    background: var(--sc-forest);
    color: var(--sc-white);
    font-size: 0.82rem;
}

    .sc-orders-action-button:hover {
        background: var(--sc-forest-dark);
        color: var(--sc-white);
    }


/* ============================================================
   ALERTS
   ============================================================ */

.sc-orders-alert {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    margin-bottom: 20px;
    padding: 16px 18px;
    border: 1px solid;
    border-radius: 15px;
}

.sc-orders-alert-success {
    background: #edf8ef;
    border-color: #cde8d1;
    color: #23623a;
}

.sc-orders-alert-error {
    background: #fff1f1;
    border-color: #f1d0d0;
    color: #9d3131;
}

.sc-orders-alert-close {
    border: none;
    background: transparent;
    color: inherit;
    font-size: 1.25rem;
    cursor: pointer;
}


/* ============================================================
   TABLE CARD
   ============================================================ */

.sc-orders-table-card {
    overflow: hidden;
    border: 1px solid var(--sc-border);
    border-radius: 20px;
    background: var(--sc-white);
    box-shadow: var(--sc-shadow);
}

.sc-orders-table {
    width: 100%;
    margin: 0;
    border-collapse: separate;
    border-spacing: 0;
}

    .sc-orders-table thead {
        background: linear-gradient( 135deg, var(--sc-forest-dark), var(--sc-forest) );
    }

        .sc-orders-table thead th {
            padding: 17px 20px;
            border: none;
            color: rgba(255, 255, 255, 0.9);
            font-size: 0.74rem;
            font-weight: 700;
            text-transform: uppercase;
            letter-spacing: 0.7px;
            white-space: nowrap;
        }

    .sc-orders-table tbody tr {
        border-bottom: 1px solid #edf1ed;
        transition: background 0.2s ease;
    }

        .sc-orders-table tbody tr:last-child {
            border-bottom: none;
        }

        .sc-orders-table tbody tr:hover {
            background: #f8fbf6;
        }

    .sc-orders-table tbody td {
        padding: 18px 20px;
        vertical-align: middle;
        border-top: none;
        color: var(--sc-text);
    }


/* ============================================================
   ORDER NUMBER
   ============================================================ */

.sc-orders-number {
    display: inline-flex;
    align-items: center;
    gap: 9px;
    font-weight: 750;
    color: var(--sc-forest-dark);
}

.sc-orders-number-icon {
    width: 34px;
    height: 34px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 10px;
    background: var(--sc-lime-soft);
    color: var(--sc-forest);
}


/* ============================================================
   EQUIPMENT / QUANTITY
   ============================================================ */

.sc-orders-equipment {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    color: var(--sc-muted);
}

.sc-orders-count-badge {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 29px;
    height: 29px;
    padding: 0 8px;
    border-radius: 9px;
    background: var(--sc-lime-soft);
    color: var(--sc-forest-dark);
    font-size: 0.78rem;
    font-weight: 750;
}

.sc-orders-quantity {
    font-weight: 750;
    color: var(--sc-forest-dark);
}


/* ============================================================
   DATE
   ============================================================ */

.sc-orders-date {
    color: var(--sc-muted);
    font-size: 0.88rem;
    white-space: nowrap;
}


/* ============================================================
   STATUS
   ============================================================ */

.sc-orders-status {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    padding: 7px 11px;
    border-radius: 999px;
    font-size: 0.76rem;
    font-weight: 700;
    white-space: nowrap;
}

.sc-orders-status-pending {
    background: #fff5d9;
    color: #9a6900;
}

.sc-orders-status-packaged {
    background: var(--sc-lime-soft);
    color: #527b14;
}

.sc-orders-status-way {
    background: #eaf4ff;
    color: #27659c;
}

.sc-orders-status-collected {
    background: #e8f7ed;
    color: #287141;
}

.sc-orders-status-cancelled {
    background: #fff0f0;
    color: #a33b3b;
}


/* ============================================================
   EMPTY STATE
   ============================================================ */

.sc-orders-empty {
    padding: 70px 25px;
    border: 1px dashed #cbd9cb;
    border-radius: 20px;
    background: var(--sc-white);
    text-align: center;
    box-shadow: var(--sc-shadow);
}

.sc-orders-empty-icon {
    width: 72px;
    height: 72px;
    margin: 0 auto 18px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 22px;
    background: var(--sc-lime-soft);
    color: var(--sc-forest);
    font-size: 2rem;
}

.sc-orders-empty h4 {
    margin-bottom: 8px;
    color: var(--sc-forest-dark);
    font-weight: 750;
}

.sc-orders-empty p {
    margin: 0;
    color: var(--sc-muted);
}


/* ============================================================
   FLOATING ACTION MENU
   ============================================================ */

.sc-orders-floating-menu {
    display: none;
    position: fixed;
    z-index: 9999;
    width: 225px;
    overflow: hidden;
    border: 1px solid var(--sc-border);
    border-radius: 16px;
    background: rgba(255, 255, 255, 0.98);
    box-shadow: 0 18px 45px rgba(15, 55, 30, 0.18);
