/* ============================================================
   SUMMARY CARD
   ============================================================ */

.sc-order-details-summary {
    margin-bottom: 25px;
    padding: 24px;
    background: #ffffff;
    border: 1px solid #e4ece5;
    border-radius: 20px;
    box-shadow: 0 5px 20px rgba(18, 61, 42, 0.06);
}

.sc-order-details-summary-item {
    position: relative;
    height: 100%;
    padding: 18px;
    overflow: hidden;
    background: #f8fbf7;
    border: 1px solid #e5eee5;
    border-radius: 15px;
    transition: all 0.25s ease;
}

    .sc-order-details-summary-item:hover {
        border-color: #a8d83f;
        box-shadow: 0 7px 18px rgba(31, 92, 61, 0.08);
