    background: #fff4cc;
}

.sc-order-details-status-packaged {
    color: #315d00;
    background: #e6f6c9;
}

.sc-order-details-status-way {
    color: #125a4b;
    background: #d8f4ec;
}

.sc-order-details-status-collected {
    color: #17633b;
    background: #ddf5e6;
}

.sc-order-details-status-cancelled {
    color: #a12626;
    background: #fde5e5;
}


/* ============================================================
   INFORMATION SECTION
   ============================================================ */

.sc-order-details-info-card {
    margin-bottom: 25px;
    padding: 25px;
    background: #ffffff;
    border: 1px solid #e4ece5;
    border-radius: 20px;
    box-shadow: 0 5px 20px rgba(18, 61, 42, 0.06);
}

.sc-order-details-section-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 15px;
    margin-bottom: 22px;
}

.sc-order-details-section-title {
    display: flex;
    align-items: center;
    gap: 10px;
    margin: 0;
    color: #173c2b;
    font-size: 1.15rem;
    font-weight: 700;
}

    .sc-order-details-section-title i {
        color: #5e9f1c;
        font-size: 1.25rem;
    }


/* ============================================================
   ORDER ITEMS
   ============================================================ */

.sc-order-details-items {
    display: flex;
    flex-direction: column;
    gap: 15px;
}

.sc-order-details-item {
    display: flex;
    align-items: center;
