    font-size: 0.68rem;
    font-weight: 700;
    text-transform: uppercase;
}

.sc-order-details-quantity-value {
    display: block;
    color: #315d00;
    font-size: 1.15rem;
    font-weight: 800;
}


/* ============================================================
   PACKAGE BUTTON
   ============================================================ */

.sc-order-details-package-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    min-width: 145px;
    padding: 11px 18px;
    color: #173c2b;
    font-size: 0.88rem;
    font-weight: 700;
    background: #a8d83f;
    border: 1px solid #a8d83f;
    border-radius: 12px;
    cursor: pointer;
    transition: all 0.25s ease;
}

    .sc-order-details-package-btn:hover {
        color: #ffffff;
        background: #1f5c3d;
        border-color: #1f5c3d;
        box-shadow: 0 7px 18px rgba(31, 92, 61, 0.2);
        transform: translateY(-2px);
    }

    .sc-order-details-package-btn:active {
        transform: translateY(0);
    }

    .sc-order-details-package-btn:disabled {
        color: #7c8a7e;
        background: #e8eee7;
        border-color: #e8eee7;
        cursor: not-allowed;
        box-shadow: none;
        transform: none;
    }


/* ============================================================
   PACKAGE ACTION / TOP BUTTON
   ============================================================ */

.sc-order-details-package-order-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 9px;
    padding: 13px 22px;
    color: #ffffff;
    font-size: 0.9rem;
    font-weight: 700;
    background: #1f5c3d;
    border: 1px solid #1f5c3d;
    border-radius: 13px;
    cursor: pointer;
    transition: all 0.25s ease;
}

    .sc-order-details-package-order-btn:hover {
        color: #173c2b;
        background: #a8d83f;
        border-color: #a8d83f;
        box-shadow: 0 8px 20px rgba(168, 216, 63, 0.25);
        transform: translateY(-2px);
    }

    .sc-order-details-package-order-btn:disabled {
        color: rgba(255, 255, 255, 0.8);
        background: #6f8d7b;
        border-color: #6f8d7b;
        cursor: not-allowed;
        transform: none;
    }


/* ============================================================
   EMPTY STATE
   ============================================================ */

.sc-order-details-empty {
    padding: 60px 25px;
    text-align: center;
    background: #ffffff;
    border: 1px solid #e4ece5;
    border-radius: 20px;
}

.sc-order-details-empty-icon {
    width: 70px;
    height: 70px;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 auto 18px;
    color: #5e9f1c;
    font-size: 2rem;
    background: #eef8df;
    border-radius: 50%;
}

.sc-order-details-empty h5 {
    margin-bottom: 7px;
    color: #173c2b;
    font-weight: 700;
}

.sc-order-details-empty p {
    margin: 0;
    color: #7a887c;
}


/* ============================================================
   ALERT / AJAX MESSAGE
   ============================================================ */

.sc-order-details-message {
    display: none;
    align-items: center;
    gap: 12px;
    margin-bottom: 22px;
    padding: 15px 18px;
    border-radius: 14px;
    font-size: 0.9rem;
    font-weight: 600;
}

.sc-order-details-message-success {
    color: #17633b;
    background: #e4f7e9;
    border: 1px solid #bde8c9;
}

.sc-order-details-message-error {
    color: #a12626;
    background: #fde8e8;
    border: 1px solid #f5c2c2;
}


/* ============================================================
   ORDER META / TOTALS
   ============================================================ */

.sc-order-details-total {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 10px 14px;
    color: #315d00;
    font-size: 0.85rem;
    font-weight: 700;
    background: #eef8df;
    border: 1px solid #d7eeb4;
    border-radius: 12px;
}

    .sc-order-details-total i {
        color: #5e9f1c;
    }


/* ============================================================
   LOADING STATE
   ============================================================ */

.sc-order-details-loading {
    display: inline-flex;
    align-items: center;
    gap: 8px;
}

.sc-order-details-spinner {
    width: 17px;
    height: 17px;
    border: 2px solid rgba(255, 255, 255, 0.35);
    border-top-color: #ffffff;
    border-radius: 50%;
    animation: sc-order-details-spin 0.7s linear infinite;
}

@keyframes sc-order-details-spin {
    to {
        transform: rotate(360deg);
    }
}


/* ============================================================
   RESPONSIVE
   ============================================================ */

@media (max-width: 991.98px) {

    .sc-order-details-header {
        padding: 25px 22px;
    }

    .sc-order-details-summary {
        padding: 18px;
