    }

    .sc-order-details-section-header {
        align-items: flex-start;
        flex-direction: column;
    }

    .sc-order-details-package-order-btn {
        width: 100%;
    }

    .sc-order-details-item {
        gap: 13px;
        padding: 15px;
        border-radius: 14px;
    }

    .sc-order-details-item-icon {
        width: 46px;
        height: 46px;
        font-size: 1.15rem;
        border-radius: 13px;
    }

    .sc-order-details-item-content {
        min-width: calc(100% - 60px);
    }

    .sc-order-details-item-name {
        font-size: 0.93rem;
    }

    .sc-order-details-quantity {
        width: 100%;
