/* ============================================================
SWIFTCARE
PACKAGED ORDERS PAGE
FOREST GREEN + LIME ACCENTS
============================================================ */

.sc-packaged-page {
    min-height: 100vh;
    background: linear-gradient( 135deg, #f4f8f5 0%, #edf5ef 45%, #f8fbf8 100% );
    padding-bottom: 45px;
}


/* ============================================================
HEADER
============================================================ */

.sc-packaged-header {
    position: relative;
    overflow: hidden;
    padding: 34px 40px;
    background: linear-gradient( 135deg, #0b3d2e, #145c42 );
    box-shadow: 0 10px 30px rgba(9, 62, 43, 0.18);
}

    .sc-packaged-header::before {
        content: "";
        position: absolute;
        width: 330px;
        height: 330px;
        border-radius: 50%;
        right: -120px;
        top: -180px;
        background: rgba(181, 230, 29, 0.12);
    }

    .sc-packaged-header::after {
        content: "";
        position: absolute;
        width: 220px;
        height: 220px;
        border-radius: 50%;
        left: 20%;
        bottom: -170px;
        background: rgba(181, 230, 29, 0.06);
    }

.sc-packaged-header-inner {
    position: relative;
    z-index: 2;
    max-width: 1450px;
    margin: 0 auto;
    display: flex;
    align-items: center;
    gap: 24px;
}

.sc-packaged-back {
    width: 48px;
    height: 48px;
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    text-decoration: none;
    color: #ffffff;
    font-size: 1.5rem;
    border-radius: 15px;
    background: rgba(255, 255, 255, 0.10);
    border: 1px solid rgba(255, 255, 255, 0.16);
    transition: all 0.2s ease;
}

    .sc-packaged-back:hover {
        color: #b5e61d;
        transform: translateX(-3px);
        background: rgba(255, 255, 255, 0.16);
    }

.sc-packaged-title-area {
    display: flex;
    align-items: center;
    gap: 18px;
}

.sc-packaged-title-icon {
    width: 62px;
    height: 62px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 19px;
    color: #173d24;
    font-size: 1.8rem;
    background: linear-gradient( 135deg, #d4ff52, #a9db14 );
    box-shadow: 0 10px 25px rgba(0, 0, 0, 0.16);
}

.sc-packaged-kicker {
    display: block;
    margin-bottom: 4px;
    color: #b5e61d;
    font-size: 0.68rem;
    font-weight: 800;
    letter-spacing: 1.6px;
}

.sc-packaged-title-area h1 {
    margin: 0;
    color: #ffffff;
    font-size: 1.75rem;
    font-weight: 750;
}

.sc-packaged-title-area p {
    margin: 5px 0 0;
    color: rgba(255, 255, 255, 0.72);
    font-size: 0.92rem;
}

.sc-packaged-header-stat {
    margin-left: auto;
    min-width: 155px;
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 12px 17px;
    border-radius: 18px;
    background: rgba(255, 255, 255, 0.10);
    border: 1px solid rgba(255, 255, 255, 0.14);
    backdrop-filter: blur(10px);
}

.sc-packaged-header-stat-icon {
    width: 42px;
    height: 42px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 13px;
    color: #183e27;
    background: #b5e61d;
}

.sc-packaged-header-stat strong {
    display: block;
    color: #ffffff;
    font-size: 1.35rem;
    line-height: 1.1;
}

.sc-packaged-header-stat span {
    display: block;
    margin-top: 2px;
    color: rgba(255, 255, 255, 0.68);
    font-size: 0.7rem;
}


/* ============================================================
CONTENT
============================================================ */

.sc-packaged-content {
    max-width: 1450px;
    margin: 0 auto;
    padding: 30px 40px;
}


/* ============================================================
MESSAGE
============================================================ */

.sc-packaged-message {
    display: none;
    align-items: center;
    gap: 11px;
    margin-bottom: 22px;
    padding: 15px 18px;
    border-radius: 15px;
    font-size: 0.9rem;
    font-weight: 600;
    animation: scPackagedMessageIn 0.25s ease;
}

.sc-packaged-message-success {
    color: #155c34;
    background: #e8f8ea;
    border: 1px solid #bde8c4;
}

.sc-packaged-message-error {
    color: #a02b2b;
    background: #fff0f0;
    border: 1px solid #f3c3c3;
}

@keyframes scPackagedMessageIn {
    from {
        opacity: 0;
        transform: translateY(-8px);
    }

    to {
        opacity: 1;
        transform: translateY(0);
    }
}


/* ============================================================
SUMMARY
============================================================ */

.sc-packaged-summary {
    margin-bottom: 25px;
}

.sc-packaged-summary-card {
    height: 100%;
