/* ============================================================
TOOLBAR
============================================================ */

.sc-packaged-toolbar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 18px;
    margin-bottom: 24px;
}

.sc-packaged-search {
    width: 100%;
    max-width: 460px;
    position: relative;
}

    .sc-packaged-search i {
        position: absolute;
        top: 50%;
        left: 17px;
        transform: translateY(-50%);
        color: #5e806c;
        font-size: 1rem;
    }

    .sc-packaged-search input {
        width: 100%;
        height: 48px;
        padding: 0 18px 0 47px;
        outline: none;
        color: #173d2a;
        border-radius: 15px;
        border: 1px solid #d8e7dc;
        background: rgba(255, 255, 255, 0.82);
        box-shadow: 0 5px 15px rgba(25, 75, 47, 0.04);
        transition: border-color 0.2s ease, box-shadow 0.2s ease;
    }

        .sc-packaged-search input:focus {
            border-color: #9dcc16;
