        padding: 19px 20px;
        vertical-align: middle;
        color: #294534;
        border-bottom: 1px solid #edf2ee;
    }

    .sc-packaged-table tbody tr {
        transition: background 0.2s ease, transform 0.2s ease, opacity 0.3s ease;
    }

        .sc-packaged-table tbody tr:hover {
            background: rgba(232, 247, 223, 0.45);
        }

        .sc-packaged-table tbody tr:last-child td {
            border-bottom: none;
        }


/* ============================================================
ORDER
============================================================ */

.sc-packaged-order-number {
    display: flex;
    align-items: center;
    gap: 12px;
}

.sc-packaged-order-icon {
    width: 42px;
    height: 42px;
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 13px;
    color: #2d653f;
    background: #eaf6d3;
}

.sc-packaged-order-number strong {
    display: block;
    color: #183e2a;
    font-size: 0.9rem;
    font-weight: 750;
}

.sc-packaged-order-number small {
    display: block;
    margin-top: 3px;
    color: #849188;
    font-size: 0.72rem;
}


/* ============================================================
EQUIPMENT
============================================================ */

.sc-packaged-equipment {
    display: flex;
    align-items: center;
    gap: 8px;
    color: #526b5b;
    font-size: 0.82rem;
    font-weight: 600;
}

.sc-packaged-equipment-count {
    min-width: 28px;
    height: 28px;
    padding: 0 7px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 9px;
    color: #1d5c39;
    font-size: 0.75rem;
    font-weight: 800;
    background: #e8f4d0;
}


/* ============================================================
QUANTITY
============================================================ */

.sc-packaged-quantity {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    color: #315640;
    font-size: 0.82rem;
    font-weight: 650;
}

    .sc-packaged-quantity i {
        color: #76a414;
    }


/* ============================================================
DATE
============================================================ */

.sc-packaged-date {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    color: #66796d;
    font-size: 0.8rem;
}

    .sc-packaged-date i {
        color: #5f876e;
    }


/* ============================================================
STATUS
============================================================ */

.sc-packaged-status {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    padding: 7px 11px;
    border-radius: 50px;
    color: #3d6810;
    background: #eef8d7;
    font-size: 0.73rem;
    font-weight: 750;
}

.sc-packaged-status-dot {
    width: 7px;
    height: 7px;
    border-radius: 50%;
    background: #91bf13;
}


/* ============================================================
DELIVER BUTTON
============================================================ */

.sc-packaged-deliver-btn {
    min-width: 116px;
    height: 42px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    padding: 0 17px;
    cursor: pointer;
    color: #ffffff;
    border: none;
    border-radius: 13px;
    background: linear-gradient( 135deg, #175b3b, #0e412a );
    box-shadow: 0 7px 16px rgba(18, 76, 46, 0.18);
    font-size: 0.8rem;
    font-weight: 750;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}

    .sc-packaged-deliver-btn:hover:not(:disabled) {
        transform: translateY(-2px);
        box-shadow: 0 11px 22px rgba(18, 76, 46, 0.26);
    }

    .sc-packaged-deliver-btn:disabled {
        cursor: not-allowed;
        opacity: 0.7;
    }


/* ============================================================
LOADING
============================================================ */

.sc-packaged-btn-loading {
    display: inline-flex;
    align-items: center;
    gap: 7px;
}

.sc-packaged-spinner {
    width: 15px;
    height: 15px;
    display: inline-block;
    border-radius: 50%;
    border: 2px solid rgba(255, 255, 255, 0.35);
    border-top-color: #ffffff;
    animation: scPackagedSpin 0.7s linear infinite;
}

@keyframes scPackagedSpin {

    to {
        transform: rotate(360deg);
    }
}


/* ============================================================
DELIVERED ROW
============================================================ */

.sc-packaged-row-delivered {
    opacity: 0;
    transform: translateX(20px);
    background: #e8f7dc !important;
}


/* ============================================================
EMPTY STATE
============================================================ */

.sc-packaged-empty {
    padding: 75px 30px;
    text-align: center;
    border-radius: 23px;
    background: rgba(255, 255, 255, 0.75);
    border: 1px dashed #cadacc;
}

.sc-packaged-empty-icon {
    width: 82px;
    height: 82px;
    margin: 0 auto 20px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 24px;
    color: #4e7613;
    font-size: 2.2rem;
    background: linear-gradient( 135deg, #eef8d6, #d8ef91 );
}

.sc-packaged-empty h3 {
    margin-bottom: 8px;
    color: #163d29;
    font-size: 1.25rem;
    font-weight: 750;
}

.sc-packaged-empty p {
    margin: 0;
    color: #748279;
}


/* ============================================================
RESPONSIVE
============================================================ */

@media (max-width: 991px) {

    .sc-packaged-header {
        padding: 28px 25px;
    }

    .sc-packaged-content {
        padding: 25px;
    }

    .sc-packaged-header-stat {
        display: none;
    }
}


@media (max-width: 767px) {

    .sc-packaged-header-inner {
        align-items: flex-start;
    }

    .sc-packaged-title-icon {
        display: none;
    }

    .sc-packaged-title-area h1 {
        font-size: 1.4rem;
    }

    .sc-packaged-toolbar {
        flex-direction: column;
        align-items: stretch;
    }

    .sc-packaged-ready-info {
        white-space: normal;
    }

    .sc-packaged-table-header {
        align-items: flex-start;
    }
}


@media (max-width: 575px) {

    .sc-packaged-header {
        padding: 22px 16px;
    }

    .sc-packaged-content {
        padding: 20px 14px;
    }

    .sc-packaged-back {
        width: 42px;
        height: 42px;
    }

    .sc-packaged-table-header {
        padding: 20px;
    }

    .sc-packaged-summary-card {
        padding: 18px;
    }
}
