.sc-maintenance-meta-icon {
    width: 38px;
    height: 38px;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    border-radius: 12px;
    color: #286342;
    background: rgba(182, 255, 44, 0.2);
}


.sc-maintenance-meta-item span {
    display: block;
    color: #83938a;
    font-size: 9px;
}


.sc-maintenance-meta-item strong {
    display: block;
    margin-top: 3px;
    color: #214532;
    font-size: 11px;
    word-break: break-word;
}


/* ============================================================
   ASSIGNMENT NOTES
============================================================ */

.sc-maintenance-assignment-notes {
    display: flex;
    align-items: flex-start;
    gap: 12px;
    margin-top: 18px;
    padding: 16px;
    border-radius: 16px;
    background: rgba(182, 255, 44, 0.08);
    border: 1px solid rgba(182, 255, 44, 0.18);
}


.sc-maintenance-notes-icon {
    width: 38px;
    height: 38px;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    border-radius: 12px;
    color: #245f3d;
    background: #b6ff2c;
}


.sc-maintenance-assignment-notes span {
    display: block;
    margin-bottom: 5px;
    color: #65933e;
    font-size: 10px;
    font-weight: 800;
}


.sc-maintenance-assignment-notes p {
    margin: 0;
    color: #50685a;
    font-size: 12px;
    line-height: 1.6;
}


/* ============================================================
   VALIDATION
============================================================ */

.sc-maintenance-validation {
    margin-bottom: 18px;
    padding: 14px;
    border-radius: 14px;
    background: #fff7f7;
    border: 1px solid rgba(185, 50, 50, 0.15);
}


/* ============================================================
   FORM
============================================================ */

.sc-maintenance-form {
    margin-top: 10px;
}


.sc-maintenance-field {
    margin-bottom: 27px;
}


    .sc-maintenance-field > label {
        display: flex;
        align-items: center;
        gap: 8px;
        margin-bottom: 12px;
        color: #28503a;
        font-size: 13px;
        font-weight: 800;
    }


        .sc-maintenance-field > label > i {
            color: #579d38;
            font-size: 16px;
        }


/* ============================================================
   PRIORITY OPTIONS
============================================================ */

.sc-priority-options {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 12px;
}


.sc-priority-option {
    position: relative;
    margin: 0;
    cursor: pointer;
}


    .sc-priority-option input {
        position: absolute;
        opacity: 0;
        pointer-events: none;
    }


.sc-priority-option-content {
    display: flex;
    align-items: center;
    gap: 12px;
    min-height: 78px;
    padding: 14px;
    border-radius: 16px;
    background: rgba(20, 75, 50, 0.035);
    border: 1px solid rgba(20, 75, 50, 0.1);
    transition: all 0.25s ease;
}


.sc-priority-option:hover
.sc-priority-option-content {
    transform: translateY(-2px);
    border-color: rgba(182, 255, 44, 0.55);
    box-shadow: 0 10px 20px rgba(18, 74, 48, 0.07);
}


.sc-priority-option input:checked + .sc-priority-option-content {
    background: rgba(182, 255, 44, 0.14);
    border-color: #9dde2b;
    box-shadow: 0 8px 20px rgba(110, 180, 45, 0.1);
}


.sc-priority-radio-icon {
    width: 43px;
    height: 43px;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    border-radius: 13px;
    font-size: 18px;
}


.sc-priority-low {
    color: #477e34;
    background: rgba(182, 255, 44, 0.2);
}


.sc-priority-medium {
    color: #2d6947;
    background: rgba(48, 133, 87, 0.12);
}


.sc-priority-high {
    color: #b47b20;
    background: rgba(255, 194, 73, 0.18);
}


.sc-priority-critical {
    color: #b44949;
    background: rgba(220, 80, 80, 0.13);
}


.sc-priority-option strong {
    display: block;
    color: #244632;
    font-size: 12px;
}


.sc-priority-option small {
    display: block;
    margin-top: 3px;
    color: #84938b;
    font-size: 10px;
}


/* ============================================================
   TEXTAREA
============================================================ */

.sc-maintenance-textarea {
    min-height: 160px;
    padding: 16px;
    resize: vertical;
    border-radius: 16px;
    color: #294937;
    background: rgba(255, 255, 255, 0.75);
    border: 1px solid rgba(20, 75, 50, 0.14);
    box-shadow: none;
}


    .sc-maintenance-textarea:focus {
        border-color: #91d92d;
        box-shadow: 0 0 0 4px rgba(182, 255, 44, 0.14);
    }


.sc-maintenance-field-help {
    display: flex;
    align-items: flex-start;
    gap: 7px;
    margin-top: 9px;
    color: #84958a;
    font-size: 11px;
    line-height: 1.5;
}


    .sc-maintenance-field-help i {
        color: #62a63b;
    }


/* ============================================================
   OPTIONAL LABEL
============================================================ */

.sc-maintenance-optional {
    margin-left: 4px;
    padding: 3px 8px;
    border-radius: 20px;
    color: #718178;
    font-size: 8px;
    font-weight: 800;
    background: rgba(20, 75, 50, 0.07);
}


/* ============================================================
   FILE UPLOAD
============================================================ */

.sc-maintenance-file-input {
    display: none;
}


.sc-maintenance-upload-area {
    display: flex;
    align-items: center;
    gap: 15px;
    min-height: 85px;
    padding: 17px;
    cursor: pointer;
    border-radius: 18px;
    background: rgba(20, 75, 50, 0.035);
    border: 1.5px dashed rgba(38, 100, 65, 0.25);
    transition: all 0.25s ease;
}


    .sc-maintenance-upload-area:hover {
        background: rgba(182, 255, 44, 0.08);
        border-color: #9dde2b;
    }


.sc-maintenance-upload-icon {
    width: 48px;
    height: 48px;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    border-radius: 15px;
    color: #234e35;
    font-size: 22px;
    background: #b6ff2c;
}


.sc-maintenance-upload-area strong {
    display: block;
    color: #244833;
    font-size: 12px;
}


.sc-maintenance-upload-area span {
    display: block;
    margin-top: 4px;
    color: #829188;
    font-size: 10px;
}


/* ============================================================
   IMAGE PREVIEW
============================================================ */

.sc-maintenance-image-preview {
    position: relative;
    display: none;
    width: 100%;
    max-width: 250px;
    margin-top: 15px;
    overflow: hidden;
    border-radius: 17px;
    border: 1px solid rgba(20, 75, 50, 0.12);
}


    .sc-maintenance-image-preview.show {
        display: block;
    }


    .sc-maintenance-image-preview img {
        display: block;
        width: 100%;
        height: 180px;
        object-fit: cover;
    }


    .sc-maintenance-image-preview button {
        position: absolute;
        top: 8px;
        right: 8px;
        width: 32px;
        height: 32px;
        border: none;
        border-radius: 50%;
        color: #ffffff;
        background: rgba(150, 45, 45, 0.85);
        cursor: pointer;
    }


/* ============================================================
   REQUEST SUMMARY
============================================================ */

.sc-maintenance-summary {
    display: flex;
    align-items: center;
    gap: 15px;
    margin-top: 10px;
    padding: 18px;
    border-radius: 18px;
    background: linear-gradient( 135deg, rgba(20, 75, 50, 0.06), rgba(182, 255, 44, 0.11) );
    border: 1px solid rgba(20, 75, 50, 0.08);
}


.sc-maintenance-summary-icon {
    width: 46px;
    height: 46px;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    border-radius: 15px;
    color: #173f2b;
    background: #b6ff2c;
    font-size: 20px;
}


.sc-maintenance-summary span {
    display: block;
    color: #779087;
    font-size: 9px;
    font-weight: 800;
    letter-spacing: 0.8px;
}


.sc-maintenance-summary strong {
    display: block;
    margin-top: 4px;
    color: #214532;
    font-size: 13px;
}


.sc-maintenance-summary-arrow {
    margin-left: auto;
    color: #5c9c39;
    font-size: 20px;
}


.sc-maintenance-summary-status {
    display: flex;
    align-items: center;
    gap: 7px;
    color: #4b8432;
    font-size: 10px;
    font-weight: 700;
}


    .sc-maintenance-summary-status span {
        width: 7px;
        height: 7px;
        border-radius: 50%;
        background: #75bd3f;
    }


/* ============================================================
   ACTIONS
============================================================ */

.sc-maintenance-actions {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: 12px;
    margin-top: 28px;
}


.sc-maintenance-cancel-btn,
.sc-maintenance-submit-btn {
    min-height: 50px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 9px;
    padding: 0 22px;
    border-radius: 14px;
    font-size: 13px;
    font-weight: 800;
    text-decoration: none;
    transition: all 0.25s ease;
}


/* CANCEL */

.sc-maintenance-cancel-btn {
    color: #496453;
    background: #ffffff;
    border: 1px solid rgba(20, 75, 50, 0.14);
}


    .sc-maintenance-cancel-btn:hover {
        color: #244832;
        background: #f4f8f3;
    }


/* SUBMIT */

.sc-maintenance-submit-btn {
    border: none;
    color: #173f2b;
    background: linear-gradient( 135deg, #c4ff4d, #a8e92c );
    box-shadow: 0 10px 24px rgba(102, 174, 53, 0.2);
}


    .sc-maintenance-submit-btn:hover {
        transform: translateY(-2px);
        box-shadow: 0 15px 30px rgba(102, 174, 53, 0.3);
    }


    .sc-maintenance-submit-btn i {
        font-size: 16px;
    }


/* ============================================================
   SWIFTCARE
   MAINTENANCE PERSON DASHBOARD
   FOREST GREEN + LIME DESIGN
============================================================ */


/* ============================================================
   ROOT COLORS
============================================================ */

:root {
    --sc-forest: #0b3d2e;
    --sc-forest-dark: #062b20;
    --sc-forest-light: #145c45;
    --sc-lime: #b6ff2c;
    --sc-lime-soft: #d4ff7a;
    --sc-white: #ffffff;
    --sc-text: #17362b;
    --sc-muted: #6d8178;
    --sc-border: rgba(11, 61, 46, 0.10);
    --sc-shadow: 0 15px 45px rgba(6, 43, 32, 0.10);
}


/* ============================================================
   PAGE
============================================================ */

.maintenance-dashboard {
    width: 100%;
    min-height: 100vh;
    padding: 30px;
    background: radial-gradient( circle at top right, rgba(182, 255, 44, 0.10), transparent 30% ), #f4f8f5;
}


.maintenance-dashboard-container {
    width: 100%;
    max-width: 1450px;
    margin: 0 auto;
}


/* ============================================================
   WELCOME HERO
============================================================ */

.maintenance-welcome {
    position: relative;
    overflow: hidden;
    padding: 45px;
    margin-bottom: 30px;
    border-radius: 28px;
    background: linear-gradient( 135deg, var(--sc-forest-dark), var(--sc-forest), var(--sc-forest-light) );
    box-shadow: 0 25px 60px rgba(6, 43, 32, 0.20);
}


    /* Decorative glow */

    .maintenance-welcome::before {
        content: "";
        position: absolute;
        width: 320px;
        height: 320px;
        right: -100px;
        top: -150px;
        border-radius: 50%;
        background: rgba(182, 255, 44, 0.12);
        filter: blur(20px);
    }


    .maintenance-welcome::after {
        content: "";
        position: absolute;
        width: 180px;
        height: 180px;
        left: 50%;
        bottom: -120px;
        border-radius: 50%;
        background: rgba(255, 255, 255, 0.04);
    }


.maintenance-welcome-content {
    position: relative;
    z-index: 2;
}


.maintenance-welcome h1 {
    margin: 0;
    color: var(--sc-white);
    font-size: clamp(2rem, 4vw, 3rem);
    font-weight: 800;
    letter-spacing: -1px;
}


.maintenance-welcome p {
    max-width: 650px;
    margin: 12px 0 22px;
    color: rgba(255, 255, 255, 0.75);
    font-size: 1rem;
    line-height: 1.7;
}


/* ============================================================
   DUTY STATUS
============================================================ */

.maintenance-status {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    padding: 10px 16px;
    border-radius: 100px;
    color: var(--sc-lime);
    font-size: 0.9rem;
    font-weight: 700;
    background: rgba(255, 255, 255, 0.08);
    border: 1px solid rgba(182, 255, 44, 0.25);
    backdrop-filter: blur(10px);
}


.maintenance-status-dot {
    width: 9px;
    height: 9px;
    border-radius: 50%;
    background: var(--sc-lime);
    box-shadow: 0 0 0 5px rgba(182, 255, 44, 0.12);
}


/* ============================================================
   MAIN ACTIONS
============================================================ */

.maintenance-actions {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 20px;
    margin-bottom: 30px;
}


/* ============================================================
   ACTION CARD
============================================================ */

.maintenance-action-card {
    display: flex;
    align-items: center;
    gap: 20px;
    position: relative;
    padding: 25px;
    min-height: 135px;
    border-radius: 22px;
    text-decoration: none;
    background: rgba(255, 255, 255, 0.92);
    border: 1px solid var(--sc-border);
    box-shadow: var(--sc-shadow);
    transition: transform 0.25s ease, box-shadow 0.25s ease, border-color 0.25s ease, background 0.25s ease;
}


    .maintenance-action-card:hover {
        transform: translateY(-5px);
        background: var(--sc-white);
        border-color: rgba(182, 255, 44, 0.75);
        box-shadow: 0 25px 55px rgba(6, 43, 32, 0.15);
    }


/* ============================================================
   ACTION ICON
============================================================ */

.maintenance-action-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    width: 60px;
    height: 60px;
    border-radius: 18px;
    color: var(--sc-forest);
    font-size: 1.6rem;
    background: linear-gradient( 135deg, rgba(182, 255, 44, 0.90), rgba(212, 255, 122, 0.65) );
    transition: transform 0.25s ease;
}


.maintenance-action-card:hover
.maintenance-action-icon {
    transform: rotate(-5deg) scale(1.08);
}


/* ============================================================
   ACTION CONTENT
============================================================ */

.maintenance-action-content {
    flex: 1;
    min-width: 0;
}


.maintenance-action-title {
    margin-bottom: 7px;
    color: var(--sc-forest-dark);
    font-size: 1.1rem;
    font-weight: 800;
}


.maintenance-action-description {
    color: var(--sc-muted);
    font-size: 0.9rem;
    line-height: 1.6;
}


/* ============================================================
   ACTION ARROW
============================================================ */

.maintenance-action-arrow {
    color: var(--sc-forest);
    font-size: 1.2rem;
    transition: transform 0.25s ease;
}


.maintenance-action-card:hover
.maintenance-action-arrow {
    transform: translateX(5px);
}


/* ============================================================
   MAIN SECTION
============================================================ */

.maintenance-section {
    overflow: hidden;
    padding: 30px;
    border-radius: 25px;
    background: rgba(255, 255, 255, 0.92);
    border: 1px solid var(--sc-border);
    box-shadow: var(--sc-shadow);
}


/* ============================================================
   SECTION HEADER
============================================================ */

.maintenance-section-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 20px;
    margin-bottom: 30px;
    padding-bottom: 20px;
    border-bottom: 1px solid rgba(11, 61, 46, 0.08);
}


.maintenance-section-title {
    display: flex;
    align-items: center;
    gap: 12px;
    color: var(--sc-forest-dark);
    font-size: 1.25rem;
    font-weight: 800;
}


    .maintenance-section-title i {
        display: flex;
        align-items: center;
        justify-content: center;
        width: 42px;
        height: 42px;
        border-radius: 13px;
        color: var(--sc-forest);
        background: rgba(182, 255, 44, 0.40);
    }


/* ============================================================
   DATE
============================================================ */

.maintenance-date {
    padding: 9px 15px;
    border-radius: 10px;
    color: var(--sc-forest);
    font-size: 0.85rem;
    font-weight: 700;
    background: rgba(11, 61, 46, 0.06);
}


/* ============================================================
   EMPTY STATE
============================================================ */

.maintenance-empty-state {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    text-align: center;
    padding: 50px 20px;
}


.maintenance-empty-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 85px;
    height: 85px;
    margin-bottom: 20px;
    border-radius: 25px;
    color: var(--sc-forest);
    font-size: 2.2rem;
    background: linear-gradient( 135deg, rgba(182, 255, 44, 0.55), rgba(212, 255, 122, 0.25) );
    box-shadow: 0 15px 35px rgba(6, 43, 32, 0.08);
}


.maintenance-empty-state h3 {
    margin-bottom: 10px;
    color: var(--sc-forest-dark);
    font-size: 1.2rem;
    font-weight: 800;
}


.maintenance-empty-state p {
    max-width: 500px;
    margin: 0;
    color: var(--sc-muted);
    line-height: 1.7;
}


/* ============================================================
   QUICK INFORMATION
============================================================ */

.maintenance-info {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    margin-top: 20px;
    border-top: 1px solid rgba(11, 61, 46, 0.08);
}


.maintenance-info-item {
    position: relative;
    padding: 25px 20px;
    text-align: center;
}


    .maintenance-info-item:not(:last-child)::after {
        content: "";
        position: absolute;
        right: 0;
        top: 25%;
        width: 1px;
        height: 50%;
        background: rgba(11, 61, 46, 0.10);
    }


.maintenance-info-label {
    margin-bottom: 8px;
    color: var(--sc-muted);
    font-size: 0.8rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.8px;
}


.maintenance-info-value {
    color: var(--sc-forest-dark);
    font-size: 1.05rem;
    font-weight: 800;
}


/* ============================================================
   OPTIONAL STATUS VALUE
============================================================ */

.maintenance-info-item:last-child
.maintenance-info-value {
    color: var(--sc-forest);
}


/* ============================================================
   RESPONSIVE - TABLET
============================================================ */

@media (max-width: 992px) {

    .maintenance-dashboard {
        padding: 22px;
    }


    .maintenance-welcome {
        padding: 35px;
    }


    .maintenance-actions {
        grid-template-columns: 1fr;
    }
}


/* ============================================================
   RESPONSIVE - MOBILE
============================================================ */

@media (max-width: 768px) {

    .maintenance-dashboard {
        padding: 15px;
    }


    .maintenance-welcome {
        padding: 28px 22px;
        border-radius: 22px;
    }


        .maintenance-welcome h1 {
            font-size: 2rem;
        }


    .maintenance-section {
        padding: 22px 18px;
        border-radius: 20px;
    }


    .maintenance-section-header {
        align-items: flex-start;
        flex-direction: column;
    }


    .maintenance-action-card {
        align-items: flex-start;
        padding: 20px;
        min-height: auto;
    }


    .maintenance-action-icon {
        width: 54px;
        height: 54px;
        font-size: 1.4rem;
        border-radius: 16px;
    }


    .maintenance-action-arrow {
        align-self: center;
    }


    .maintenance-info {
        grid-template-columns: 1fr;
    }


    .maintenance-info-item:not(:last-child)::after {
        top: auto;
        bottom: 0;
        right: 10%;
        width: 80%;
        height: 1px;
    }
}


/* ============================================================
   RESPONSIVE - SMALL MOBILE
============================================================ */

@media (max-width: 480px) {

    .maintenance-dashboard {
        padding: 10px;
    }


    .maintenance-welcome {
        padding: 25px 18px;
    }


        .maintenance-welcome p {
            font-size: 0.9rem;
        }


    .maintenance-status {
        width: 100%;
        justify-content: center;
    }


    .maintenance-action-card {
        gap: 15px;
    }


    .maintenance-action-title {
        font-size: 1rem;
    }


    .maintenance-action-description {
        font-size: 0.82rem;
    }


    .maintenance-empty-state {
        padding: 35px 10px;
    }


    .maintenance-date {
        width: 100%;
        text-align: center;
    }
}

/* ============================================================
   SWIFTCARE
   MAINTENANCE REQUESTS
   FOREST GREEN + LIME
============================================================ */

:root {
    --sc-forest: #0b3d2e;
    --sc-forest-dark: #062b20;
    --sc-forest-light: #145c45;
    --sc-lime: #b6ff2c;
    --sc-lime-soft: #d4ff7a;
    --sc-white: #ffffff;
    --sc-page: #f4f8f5;
    --sc-text: #17362b;
    --sc-muted: #708178;
    --sc-border: rgba(11, 61, 46, 0.10);
    --sc-shadow: 0 15px 45px rgba(6, 43, 32, 0.10);
}


/* ============================================================
   PAGE
============================================================ */

.maintenance-requests-page {
    min-height: 100vh;
    padding: 30px;
    background: radial-gradient( circle at top right, rgba(182, 255, 44, 0.10), transparent 30% ), var(--sc-page);
}


.maintenance-requests-container {
    width: 100%;
    max-width: 1500px;
    margin: 0 auto;
}


/* ============================================================
   HERO
============================================================ */

.maintenance-requests-hero {
    position: relative;
    overflow: hidden;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 30px;
    padding: 42px;
    margin-bottom: 28px;
    border-radius: 28px;
    background: linear-gradient( 135deg, var(--sc-forest-dark), var(--sc-forest), var(--sc-forest-light) );
    box-shadow: 0 25px 60px rgba(6, 43, 32, 0.20);
}


    .maintenance-requests-hero::before {
        content: "";
        position: absolute;
        width: 330px;
        height: 330px;
        right: -100px;
        top: -170px;
        border-radius: 50%;
        background: rgba(182, 255, 44, 0.10);
        filter: blur(15px);
