    color: var(--sc-forest);
    font-size: 0.85rem;
    font-weight: 800;
    background: rgba(182, 255, 44, 0.22);
}


/* ============================================================
   REQUEST LIST
============================================================ */

.maintenance-request-list {
    display: flex;
    flex-direction: column;
    gap: 18px;
}


/* ============================================================
   REQUEST CARD
============================================================ */

.maintenance-request-card {
    display: flex;
    align-items: stretch;
    gap: 22px;
    padding: 20px;
    border-radius: 22px;
    background: #ffffff;
    border: 1px solid rgba(11, 61, 46, 0.10);
