    border-radius: 18px;
    background: rgba(11, 61, 46, 0.05);
}


    .maintenance-request-image img {
        width: 100%;
        height: 100%;
        object-fit: cover;
    }


/* ============================================================
   REQUEST MAIN
============================================================ */

.maintenance-request-main {
    flex: 1;
    min-width: 0;
}


/* ============================================================
   REQUEST TOP
============================================================ */

.maintenance-request-top {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 20px;
    margin-bottom: 12px;
}


.maintenance-request-label {
