}


/* ============================================================
   REFERENCE
============================================================ */

.maintenance-reference {
    display: flex;
    align-items: center;
    gap: 6px;
    margin-bottom: 16px;
    color: var(--sc-muted);
    font-size: 0.8rem;
}


