        color: var(--sc-forest);
    }


/* ============================================================
   PROBLEM BOX
============================================================ */

.maintenance-problem-box {
    display: flex;
    align-items: flex-start;
    gap: 13px;
    padding: 15px;
    margin-bottom: 18px;
    border-radius: 15px;
    background: rgba(11, 61, 46, 0.035);
    border-left: 3px solid var(--sc-lime);
}


.maintenance-problem-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 35px;
    height: 35px;
    flex-shrink: 0;
    border-radius: 10px;
    color: var(--sc-forest);
    background: rgba(182, 255, 44, 0.35);
}


.maintenance-problem-box span {
    display: block;
    margin-bottom: 4px;
    color: var(--sc-forest);
    font-size: 0.72rem;
    font-weight: 800;
    text-transform: uppercase;
}


.maintenance-problem-box p {
    margin: 0;
    color: var(--sc-text);
    font-size: 0.9rem;
    line-height: 1.6;
}


/* ============================================================
   META INFORMATION
============================================================ */

.maintenance-request-meta {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 12px;
}


.maintenance-meta-item {
    display: flex;
    align-items: center;
    gap: 9px;
    padding: 10px;
    border-radius: 12px;
    background: rgba(11, 61, 46, 0.035);
}


    .maintenance-meta-item > i {
        color: var(--sc-forest);
        font-size: 1rem;
    }


    .maintenance-meta-item span {
        display: block;
        margin-bottom: 2px;
        color: var(--sc-muted);
        font-size: 0.68rem;
    }


    .maintenance-meta-item strong {
        display: block;
        color: var(--sc-text);
        font-size: 0.78rem;
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
    }


/* ============================================================
   SIDE ACTION
============================================================ */

.maintenance-request-side {
    display: flex;
    align-items: center;
    padding-left: 20px;
    border-left: 1px solid rgba(11, 61, 46, 0.08);
}


.maintenance-request-action {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    min-width: 145px;
    padding: 12px 16px;
    border-radius: 13px;
    color: var(--sc-forest);
    font-size: 0.85rem;
    font-weight: 800;
    text-decoration: none;
    background: var(--sc-lime);
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}


    .maintenance-request-action:hover {
        color: #ffffff;
        background: var(--sc-forest);
        transform: translateY(-2px);
        box-shadow: 0 12px 25px rgba(6, 43, 32, 0.18);
    }


/* ============================================================
   EMPTY STATE
============================================================ */

.maintenance-requests-empty {
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    padding: 65px 20px;
}


.maintenance-requests-empty-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 90px;
    height: 90px;
    margin-bottom: 20px;
    border-radius: 28px;
    color: var(--sc-forest);
    font-size: 2.4rem;
    background: rgba(182, 255, 44, 0.30);
}


.maintenance-requests-empty h3 {
    margin-bottom: 10px;
    color: var(--sc-forest-dark);
    font-weight: 800;
}


.maintenance-requests-empty p {
    max-width: 500px;
    color: var(--sc-muted);
    line-height: 1.7;
}


/* ============================================================
   BACK BUTTON
============================================================ */

.maintenance-empty-back-btn {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    margin-top: 20px;
    padding: 12px 18px;
    border-radius: 12px;
    color: var(--sc-lime);
    font-weight: 800;
    text-decoration: none;
    background: var(--sc-forest);
    transition: all 0.25s ease;
}


    .maintenance-empty-back-btn:hover {
        color: var(--sc-forest);
        background: var(--sc-lime);
        transform: translateX(-3px);
    }


/* ============================================================
   RESPONSIVE
============================================================ */

@media (max-width: 1200px) {

    .maintenance-request-stats {
        grid-template-columns: repeat(2, 1fr);
    }


    .maintenance-request-meta {
        grid-template-columns: repeat(2, 1fr);
    }
}


@media (max-width: 992px) {

    .maintenance-request-card {
        flex-wrap: wrap;
    }


    .maintenance-request-main {
        width: calc(100% - 150px);
    }


    .maintenance-request-side {
        width: 100%;
        padding: 15px 0 0;
        border-left: none;
        border-top: 1px solid rgba(11, 61, 46, 0.08);
    }


    .maintenance-request-action {
        width: 100%;
    }
}


@media (max-width: 768px) {

    .maintenance-requests-page {
        padding: 15px;
    }


    .maintenance-requests-hero {
        padding: 28px;
        align-items: flex-start;
    }


    .maintenance-hero-icon {
        width: 70px;
        height: 70px;
        font-size: 2rem;
    }


    .maintenance-requests-section {
        padding: 20px;
    }


    .maintenance-requests-section-header {
        align-items: flex-start;
        flex-direction: column;
    }


    .maintenance-request-card {
        flex-direction: column;
    }


    .maintenance-request-image {
        width: 100%;
        height: 200px;
    }


    .maintenance-request-main {
        width: 100%;
    }


    .maintenance-request-top {
        flex-direction: column;
    }


    .maintenance-request-badges {
        justify-content: flex-start;
    }
}


@media (max-width: 576px) {

    .maintenance-request-stats {
        grid-template-columns: 1fr;
    }


    .maintenance-request-meta {
        grid-template-columns: 1fr;
    }


    .maintenance-requests-hero {
        flex-direction: column;
    }


    .maintenance-hero-icon {
        display: none;
    }


    .maintenance-request-count {
        width: 100%;
        justify-content: center;
    }
}

