    color: #1976d2;
}


.sc-trip-status-completed {
    background: #e7f8ee;
    color: #168343;
}


.sc-trip-status-rejected {
    background: #fdeaea;
    color: #c62828;
}


/* ============================================================
   ROUTE
============================================================ */

.sc-scheduled-trip-route {
    display: grid;
    grid-template-columns: 1fr 50px 1fr;
    align-items: center;
    gap: 12px;
    padding: 18px;
    margin-top: 20px;
    border-radius: 17px;
    background: #f7f9f8;
}


.sc-trip-location {
    display: flex;
    align-items: center;
    gap: 12px;
    min-width: 0;
}


.sc-trip-location-icon {
    width: 42px;
    height: 42px;
    min-width: 42px;
    border-radius: 13px;
    display: flex;
    align-items: center;
    justify-content: center;
}


.sc-trip-pickup-icon {
    background: #e8f5ee;
    color: #1f7a4d;
}


.sc-trip-destination-icon {
    background: #fff0e8;
    color: #d35c2f;
}


.sc-trip-location span {
    display: block;
    font-size: 11px;
    color: #888;
}


.sc-trip-location strong {
    display: block;
    margin-top: 3px;
    font-size: 13px;
    color: #333;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}


.sc-trip-route-line {
    text-align: center;
    color: #839189;
}


/* ============================================================
   META
============================================================ */

.sc-scheduled-trip-meta {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 15px;
    margin-top: 20px;
}


.sc-trip-meta-item {
    display: flex;
    align-items: center;
    gap: 10px;
}


.sc-trip-meta-icon {
    width: 38px;
    height: 38px;
    min-width: 38px;
    border-radius: 12px;
    background: #f1f4f2;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #527060;
}


.sc-trip-meta-item span {
    display: block;
    font-size: 10px;
    color: #888;
}


.sc-trip-meta-item strong {
    display: block;
    margin-top: 2px;
    font-size: 12px;
    color: #333;
}


/* ============================================================
   ACTION
============================================================ */

.sc-scheduled-trip-action {
    display: flex;
    align-items: center;
}


.sc-scheduled-trip-view-btn {
    white-space: nowrap;
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 11px 16px;
    border-radius: 13px;
    text-decoration: none;
    background: #173f2b;
    color: white;
    font-size: 12px;
    font-weight: 700;
    transition: 0.2s ease;
}


    .sc-scheduled-trip-view-btn:hover {
        background: #0d2c1d;
        color: white;
        transform: translateX(2px);
    }


/* ============================================================
   EMPTY STATE
============================================================ */

.sc-scheduled-trips-empty {
    padding: 70px 20px;
    text-align: center;
}


.sc-scheduled-trips-empty-icon {
    width: 90px;
    height: 90px;
    margin: 0 auto 20px;
    border-radius: 28px;
    background: #f1f5f3;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 38px;
    color: #577064;
}


.sc-scheduled-trips-empty h3 {
    font-size: 22px;
    font-weight: 800;
}


.sc-scheduled-trips-empty p {
    max-width: 480px;
    margin: 10px auto 25px;
    color: #777;
}


.sc-scheduled-empty-btn {
    display: inline-flex;
    align-items: center;
    gap: 9px;
    padding: 12px 18px;
    border-radius: 13px;
    background: #173f2b;
    color: white;
    text-decoration: none;
    font-size: 13px;
    font-weight: 700;
}


    .sc-scheduled-empty-btn:hover {
        color: white;
        background: #0d2c1d;
    }


/* ============================================================
   RESPONSIVE
============================================================ */

@media (max-width: 1200px) {

    .sc-scheduled-trip-stats {
        grid-template-columns: repeat(2, 1fr);
    }


    .sc-scheduled-trip-meta {
        grid-template-columns: repeat(2, 1fr);
    }
}


@media (max-width: 768px) {

    .sc-scheduled-trips-page {
        padding: 15px;
    }


    .sc-scheduled-trips-hero {
        padding: 28px;
    }


    .sc-scheduled-trips-hero-icon {
        display: none;
    }


    .sc-scheduled-trips-hero h1 {
        font-size: 27px;
    }


    .sc-scheduled-trips-hero-stats {
        flex-direction: column;
    }


    .sc-scheduled-trips-content {
        padding: 20px;
    }


    .sc-scheduled-trips-section-header {
        align-items: flex-start;
        flex-direction: column;
        gap: 16px;
    }


    .sc-scheduled-trip-card {
        flex-direction: column;
    }


    .sc-scheduled-trip-date {
        width: 100%;
        height: auto;
        padding: 12px;
        flex-direction: row;
        gap: 10px;
    }


    .sc-trip-year {
        margin-left: 5px;
    }


    .sc-scheduled-trip-top {
        flex-direction: column;
    }


    .sc-scheduled-trip-route {
        grid-template-columns: 1fr;
    }


    .sc-trip-route-line {
        transform: rotate(90deg);
    }


    .sc-scheduled-trip-meta {
        grid-template-columns: 1fr;
    }


    .sc-scheduled-trip-action {
        width: 100%;
    }


    .sc-scheduled-trip-view-btn {
        width: 100%;
        justify-content: center;
    }
}


@media (max-width: 500px) {

    .sc-scheduled-trip-stats {
        grid-template-columns: 1fr;
    }
}

/* ============================================================
   SWIFTCARE TRANSPORT REQUEST DETAILS
   UNIQUE PAGE STYLES
   Prefix: sc-transport-details-
============================================================ */


/* ============================================================
   PAGE
============================================================ */

.sc-transport-details-page {
    width: 100%;
    padding: 28px;
    min-height: 100%;
    box-sizing: border-box;
}


/* ============================================================
   ERROR STATE
============================================================ */

.sc-transport-error-card {
    max-width: 650px;
    margin: 70px auto;
    padding: 45px;
    text-align: center;
    border-radius: 24px;
    background: rgba(255, 255, 255, 0.82);
    border: 1px solid rgba(255, 255, 255, 0.7);
    box-shadow: 0 20px 50px rgba(0, 0, 0, 0.08);
    backdrop-filter: blur(18px);
    -webkit-backdrop-filter: blur(18px);
}

.sc-transport-error-icon {
    width: 75px;
    height: 75px;
    margin: 0 auto 22px;
    border-radius: 22px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 32px;
    background: rgba(220, 53, 69, 0.12);
    color: #dc3545;
}

.sc-transport-error-card h2 {
    font-size: 25px;
    font-weight: 700;
    margin-bottom: 12px;
    color: #1f2937;
}

.sc-transport-error-card p {
    color: #6b7280;
    margin-bottom: 25px;
}

.sc-transport-debug-box {
    margin-bottom: 25px;
    padding: 15px;
    border-radius: 14px;
    font-size: 13px;
    background: #f8f9fa;
    color: #6b7280;
    word-break: break-word;
}


/* ============================================================
   HERO
============================================================ */

.sc-transport-details-hero {
    position: relative;
    width: 100%;
    min-height: 230px;
    padding: 38px 42px;
    margin-bottom: 28px;
    border-radius: 28px;
    overflow: hidden;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 25px;
    background: linear-gradient( 135deg, #153d2d, #1f5b42 );
    box-shadow: 0 18px 45px rgba(21, 61, 45, 0.18);
}

    .sc-transport-details-hero::before {
        content: "";
        position: absolute;
        width: 280px;
        height: 280px;
        border-radius: 50%;
        right: -90px;
        top: -100px;
        background: rgba(255, 255, 255, 0.06);
    }

    .sc-transport-details-hero::after {
        content: "";
        position: absolute;
        width: 190px;
        height: 190px;
        border-radius: 50%;
        right: 180px;
        bottom: -120px;
        background: rgba(255, 255, 255, 0.04);
    }

.sc-transport-hero-content {
    position: relative;
    z-index: 2;
}

.sc-transport-back-btn {
    display: inline-flex;
    align-items: center;
    gap: 9px;
    padding: 9px 15px;
    margin-bottom: 28px;
    border-radius: 12px;
    text-decoration: none;
    color: rgba(255, 255, 255, 0.92);
    font-size: 14px;
    font-weight: 600;
    background: rgba(255, 255, 255, 0.1);
    border: 1px solid rgba(255, 255, 255, 0.12);
    transition: transform 0.2s ease, background 0.2s ease;
}

    .sc-transport-back-btn:hover {
        transform: translateX(-3px);
        color: #ffffff;
        background: rgba(255, 255, 255, 0.17);
    }

.sc-transport-hero-heading {
    display: flex;
    align-items: center;
    gap: 18px;
}

.sc-transport-hero-icon {
    width: 72px;
    height: 72px;
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 22px;
    font-size: 30px;
    color: #ffffff;
    background: rgba(255, 255, 255, 0.14);
    border: 1px solid rgba(255, 255, 255, 0.15);
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.1);
}

.sc-transport-eyebrow {
    display: block;
    margin-bottom: 7px;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 1.6px;
    color: rgba(255, 255, 255, 0.58);
}

.sc-transport-hero-heading h1 {
    margin: 0;
    color: #ffffff;
    font-size: 30px;
    font-weight: 700;
}

.sc-transport-hero-heading p {
    margin: 8px 0 0;
    font-size: 14px;
    color: rgba(255, 255, 255, 0.7);
}

.sc-transport-header-dot {
    margin: 0 8px;
}


/* ============================================================
   STATUS
============================================================ */

.sc-transport-status {
    position: relative;
    z-index: 2;
    display: inline-flex;
    align-items: center;
    gap: 9px;
    padding: 12px 18px;
    border-radius: 50px;
    font-size: 13px;
    font-weight: 700;
    white-space: nowrap;
    background: rgba(255, 255, 255, 0.14);
    border: 1px solid rgba(255, 255, 255, 0.16);
    color: #ffffff;
}

.sc-transport-status-pending {
    background: rgba(255, 193, 7, 0.18);
    color: #fff3cd;
    border-color: rgba(255, 193, 7, 0.28);
}

.sc-transport-status-assigned {
    background: rgba(13, 110, 253, 0.22);
    color: #dbeafe;
    border-color: rgba(13, 110, 253, 0.3);
}

.sc-transport-status-completed {
    background: rgba(25, 135, 84, 0.24);
    color: #d1fae5;
    border-color: rgba(25, 135, 84, 0.3);
}

.sc-transport-status-rejected {
    background: rgba(220, 53, 69, 0.2);
    color: #fee2e2;
    border-color: rgba(220, 53, 69, 0.3);
}


/* ============================================================
   ALERTS
============================================================ */

.sc-transport-alert-success,
.sc-transport-alert-error {
    width: 100%;
    padding: 15px 18px;
    margin-bottom: 24px;
    border-radius: 16px;
    display: flex;
    align-items: center;
    gap: 12px;
    font-size: 14px;
    font-weight: 600;
}

.sc-transport-alert-success {
    color: #146c43;
    background: rgba(25, 135, 84, 0.1);
    border: 1px solid rgba(25, 135, 84, 0.16);
}

.sc-transport-alert-error {
    color: #b42318;
    background: rgba(220, 53, 69, 0.08);
    border: 1px solid rgba(220, 53, 69, 0.15);
}


/* ============================================================
   OVERVIEW GRID
============================================================ */

.sc-transport-overview-grid {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 18px;
    margin-bottom: 28px;
}

.sc-transport-overview-card {
    min-height: 115px;
    padding: 20px;
    display: flex;
    align-items: center;
    gap: 15px;
    border-radius: 22px;
    background: rgba(255, 255, 255, 0.78);
    border: 1px solid rgba(255, 255, 255, 0.85);
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.05);
    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}

    .sc-transport-overview-card:hover {
        transform: translateY(-3px);
        box-shadow: 0 16px 35px rgba(0, 0, 0, 0.08);
    }

.sc-overview-icon {
    width: 48px;
    height: 48px;
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 15px;
    font-size: 20px;
    color: #1f5b42;
    background: rgba(31, 91, 66, 0.1);
}

.sc-transport-overview-card span {
    display: block;
    margin-bottom: 5px;
    font-size: 12px;
    color: #8a94a6;
}

.sc-transport-overview-card strong {
    display: block;
    font-size: 15px;
    font-weight: 700;
    color: #1f2937;
}


/* ============================================================
   MAIN GRID
============================================================ */

.sc-transport-main-grid {
    display: grid;
    grid-template-columns: minmax(0, 1.65fr) minmax(330px, 0.9fr);
    gap: 25px;
    align-items: start;
}

.sc-transport-left-column,
.sc-transport-right-column {
    display: flex;
    flex-direction: column;
    gap: 24px;
}


/* ============================================================
   GENERAL CARD
============================================================ */

.sc-transport-card {
    width: 100%;
    overflow: hidden;
    border-radius: 24px;
    background: rgba(255, 255, 255, 0.82);
    border: 1px solid rgba(255, 255, 255, 0.9);
    box-shadow: 0 12px 35px rgba(0, 0, 0, 0.055);
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
}

.sc-transport-card-header {
    padding: 24px 26px 20px;
    border-bottom: 1px solid rgba(0, 0, 0, 0.05);
}

.sc-transport-section-eyebrow {
    display: block;
    margin-bottom: 6px;
    font-size: 10px;
    font-weight: 800;
    letter-spacing: 1.5px;
    color: #829087;
}

.sc-transport-card-header h2 {
    margin: 0;
    display: flex;
    align-items: center;
    gap: 10px;
    font-size: 18px;
    font-weight: 700;
    color: #202936;
}

    .sc-transport-card-header h2 i {
        color: #1f5b42;
    }

.sc-transport-card-body {
    padding: 26px;
}


/* ============================================================
   RESIDENT PROFILE
============================================================ */

.sc-resident-profile {
    display: flex;
    align-items: center;
    gap: 18px;
    padding-bottom: 24px;
    margin-bottom: 24px;
    border-bottom: 1px solid rgba(0, 0, 0, 0.06);
}

.sc-resident-image-wrapper {
    position: relative;
    width: 78px;
    height: 78px;
    flex-shrink: 0;
}

.sc-resident-profile-image,
.sc-resident-profile-fallback {
    width: 78px;
    height: 78px;
    border-radius: 22px;
}

.sc-resident-profile-image {
    display: block;
    object-fit: cover;
    border: 3px solid rgba(31, 91, 66, 0.12);
}

.sc-resident-profile-fallback {
    align-items: center;
    justify-content: center;
    font-size: 28px;
    font-weight: 700;
    color: #ffffff;
    background: linear-gradient( 135deg, #1f5b42, #2f7a59 );
}

.sc-resident-profile-content h3 {
    margin: 0 0 8px;
    font-size: 21px;
    font-weight: 700;
    color: #1f2937;
}

.sc-resident-profile-content span {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    font-size: 13px;
    color: #7b8494;
}

    .sc-resident-profile-content span i {
        color: #1f5b42;
    }


/* ============================================================
   DETAIL GRID
============================================================ */

.sc-detail-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 16px;
}

.sc-detail-box {
    min-height: 82px;
    padding: 16px;
    border-radius: 17px;
    background: rgba(248, 250, 249, 0.85);
    border: 1px solid rgba(31, 91, 66, 0.06);
}

    .sc-detail-box span {
        display: flex;
        align-items: center;
        gap: 7px;
        margin-bottom: 9px;
        font-size: 11px;
        font-weight: 700;
        color: #8a94a6;
        text-transform: uppercase;
        letter-spacing: 0.4px;
    }

        .sc-detail-box span i {
            color: #1f5b42;
        }

    .sc-detail-box strong {
        display: block;
        font-size: 14px;
        font-weight: 700;
        color: #27303d;
        word-break: break-word;
    }


/* ============================================================
   TRANSPORT REASON
============================================================ */

.sc-transport-reason {
    padding: 19px;
    margin-bottom: 20px;
    border-radius: 18px;
    background: rgba(31, 91, 66, 0.045);
    border-left: 4px solid #1f5b42;
}

    .sc-transport-reason span {
        display: flex;
        align-items: center;
        gap: 8px;
        margin-bottom: 10px;
        font-size: 12px;
        font-weight: 700;
        color: #667085;
    }

        .sc-transport-reason span i {
            color: #1f5b42;
        }

    .sc-transport-reason p {
        margin: 0;
        font-size: 14px;
        line-height: 1.7;
        color: #384252;
    }


/* ============================================================
   ROUTE
============================================================ */

.sc-route-container {
    padding: 4px 0;
}

.sc-route-location {
    display: flex;
    align-items: flex-start;
    gap: 15px;
}

.sc-route-location-icon {
    width: 45px;
    height: 45px;
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 15px;
    font-size: 18px;
}

.sc-route-pickup {
    color: #1f5b42;
    background: rgba(31, 91, 66, 0.1);
}

.sc-route-destination {
    color: #b54708;
    background: rgba(245, 158, 11, 0.12);
}

.sc-route-location span {
    display: block;
    margin-bottom: 5px;
    font-size: 10px;
    font-weight: 800;
    letter-spacing: 1px;
    color: #98a1af;
}

.sc-route-location strong {
    display: block;
    font-size: 14px;
    line-height: 1.55;
    color: #27303d;
}

.sc-route-connector {
    height: 44px;
    margin-left: 21px;
    display: flex;
    flex-direction: column;
    align-items: center;
}

    .sc-route-connector span {
        flex: 1;
        width: 2px;
        background: repeating-linear-gradient( to bottom, #d7e2dc 0, #d7e2dc 5px, transparent 5px, transparent 10px );
    }

    .sc-route-connector i {
        margin-top: 2px;
        font-size: 14px;
        color: #9aaca2;
    }

.sc-route-details {
    margin-top: 25px;
}


/* ============================================================
   ASSIGNED RESOURCE
============================================================ */

.sc-assigned-resource {
    display: flex;
    align-items: center;
    gap: 15px;
    padding: 18px;
    margin-bottom: 22px;
    border-radius: 18px;
    background: rgba(31, 91, 66, 0.055);
    border: 1px solid rgba(31, 91, 66, 0.08);
}

.sc-assigned-resource-icon {
    width: 52px;
    height: 52px;
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 16px;
    color: #ffffff;
    font-size: 20px;
    background: linear-gradient( 135deg, #1f5b42, #2f7a59 );
}

.sc-assigned-resource span {
    display: block;
    margin-bottom: 5px;
    font-size: 10px;
    font-weight: 800;
    letter-spacing: 1px;
    color: #87938d;
}

.sc-assigned-resource strong {
    display: block;
    font-size: 15px;
    color: #27303d;
}


/* ============================================================
   UNASSIGNED RESOURCE
============================================================ */

.sc-unassigned-resource {
    padding: 20px;
    display: flex;
    align-items: flex-start;
    gap: 14px;
    border-radius: 18px;
    background: rgba(248, 249, 250, 0.9);
    border: 1px dashed rgba(0, 0, 0, 0.12);
}

    .sc-unassigned-resource > i {
        width: 42px;
        height: 42px;
        flex-shrink: 0;
        display: flex;
        align-items: center;
        justify-content: center;
        border-radius: 14px;
        font-size: 18px;
        color: #8a94a6;
        background: #eef1f3;
    }

    .sc-unassigned-resource strong {
        display: block;
        margin-bottom: 5px;
        font-size: 14px;
        color: #374151;
    }

    .sc-unassigned-resource p {
        margin: 0;
        font-size: 13px;
        line-height: 1.55;
        color: #8a94a6;
    }


/* ============================================================
   DRIVER ASSIGNMENT FORM
============================================================ */

.sc-driver-assignment-form {
    margin-top: 22px;
    padding-top: 22px;
    border-top: 1px solid rgba(0, 0, 0, 0.06);
}

    .sc-driver-assignment-form label {
        display: flex;
        align-items: center;
        gap: 8px;
        margin-bottom: 9px;
        font-size: 12px;
        font-weight: 700;
        color: #596273;
    }

        .sc-driver-assignment-form label i {
            color: #1f5b42;
        }

    .sc-driver-assignment-form select {
        width: 100%;
        height: 48px;
        padding: 0 14px;
        margin-bottom: 13px;
        border-radius: 13px;
        outline: none;
        font-size: 14px;
        color: #27303d;
        background: #ffffff;
        border: 1px solid #dde3df;
        transition: border 0.2s ease, box-shadow 0.2s ease;
    }

        .sc-driver-assignment-form select:focus {
            border-color: rgba(31, 91, 66, 0.65);
            box-shadow: 0 0 0 4px rgba(31, 91, 66, 0.08);
        }


/* ============================================================
   ASSIGN DRIVER BUTTON
============================================================ */

.sc-assign-driver-btn {
    width: 100%;
    min-height: 48px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 9px;
    border: none;
