/* =========================================================
   VOLUNTEER MANAGEMENT
   ========================================================= */

.volunteer-dashboard {
    position: relative;
    padding: 20px;
    box-sizing: border-box;
}


/* =========================================================
   HEADER
   ========================================================= */

.volunteer-header {
    margin-bottom: 15px;
}

    .volunteer-header .sc-header-badge {
        display: inline-flex;
        align-items: center;
        gap: 9px;
    }

        .volunteer-header .sc-header-badge i {
            font-size: 16px;
        }


/* =========================================================
   SECTION
   ========================================================= */

.volunteer-actions-section {
    padding-top: 5px;
}


/* =========================================================
   GRID - 3 CARDS PER ROW
   ========================================================= */

.volunteer-action-grid {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 18px;
}


/* =========================================================
   VOLUNTEER CARD
   ========================================================= */

.volunteer-card {
    position: relative;
    min-height: 220px;
    padding: 22px;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    border-radius: 18px;
    background: linear-gradient( 145deg, rgba(255, 255, 255, 0.095), rgba(255, 255, 255, 0.035) );
    border: 1px solid rgba(255, 255, 255, 0.11);
    border-top: 3px solid transparent;
    box-shadow: 0 12px 35px rgba(0, 0, 0, 0.10);
    backdrop-filter: blur(18px);
    -webkit-backdrop-filter: blur(18px);
    transition: transform 0.35s ease, box-shadow 0.35s ease, border-color 0.35s ease;
    text-decoration: none;
    color: inherit;
}


    /* =========================================================
   CARD DECORATIVE GLOW
   ========================================================= */

    .volunteer-card::before {
        content: "";
        position: absolute;
        width: 150px;
        height: 150px;
        top: -75px;
        right: -75px;
        border-radius: 50%;
        background: rgba(255, 255, 255, 0.035);
        transition: transform 0.45s ease, opacity 0.45s ease;
    }


    /* =========================================================
   CARD HOVER
   ========================================================= */

    .volunteer-card:hover {
        transform: translateY(-7px);
        border-top-color: #b8ff00;
        border-left-color: rgba(255, 255, 255, 0.18);
        border-right-color: rgba(255, 255, 255, 0.18);
        border-bottom-color: rgba(255, 255, 255, 0.18);
        box-shadow: 0 22px 45px rgba(0, 0, 0, 0.30), 0 10px 22px rgba(0, 0, 0, 0.18), 0 -3px 15px rgba(184, 255, 0, 0.14);
        text-decoration: none;
        color: inherit;
    }


        .volunteer-card:hover::before {
            transform: scale(2.2);
            opacity: 0.5;
        }


    /* =========================================================
   CARD TOP
   ========================================================= */

    .volunteer-card .sc-action-top {
        position: relative;
        z-index: 2;
        display: flex;
        align-items: center;
        justify-content: space-between;
        margin-bottom: 18px;
    }


    /* =========================================================
   ICON
   ========================================================= */

    .volunteer-card .volunteer-icon {
        width: 52px;
        height: 52px;
        display: flex;
        align-items: center;
        justify-content: center;
        border-radius: 15px;
        background: rgba(255, 255, 255, 0.09);
        border: 1px solid rgba(255, 255, 255, 0.10);
        font-size: 22px;
        transition: transform 0.35s ease, background 0.35s ease;
    }


    .volunteer-card:hover .volunteer-icon {
        transform: scale(1.08) rotate(-3deg);
        background: rgba(255, 255, 255, 0.14);
    }


/* =========================================================
   TOP RIGHT ARROW
   ========================================================= */

.volunteer-card-arrow {
    width: 36px;
    height: 36px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.055);
    border: 1px solid rgba(255, 255, 255, 0.08);
    font-size: 16px;
    opacity: 0.65;
    transition: transform 0.35s ease, opacity 0.35s ease, background 0.35s ease;
}


.volunteer-card:hover .volunteer-card-arrow {
    transform: translate(4px, -4px);
    opacity: 1;
    background: rgba(255, 255, 255, 0.12);
}


/* =========================================================
   CARD BODY
   ========================================================= */

.volunteer-card .sc-action-body {
    position: relative;
    z-index: 2;
    flex: 1;
}


/* =========================================================
   SMALL LABEL
   ========================================================= */

.volunteer-card-label {
    display: block;
    margin-bottom: 6px;
    font-size: 9px;
    font-weight: 700;
    letter-spacing: 1.5px;
    opacity: 0.48;
}


/* =========================================================
   CARD TITLE
   ========================================================= */

.volunteer-card .sc-action-body h3 {
    margin: 0 0 7px;
    font-size: 20px;
    font-weight: 700;
    letter-spacing: -0.3px;
}


/* =========================================================
   CARD DESCRIPTION
   ========================================================= */

.volunteer-card .sc-action-body p {
    max-width: 520px;
    margin: 0;
    font-size: 13px;
    line-height: 1.5;
    opacity: 0.66;
}


/* =========================================================
   CARD FOOTER
   ========================================================= */

.volunteer-card .sc-action-footer {
    position: relative;
    z-index: 2;
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-top: 18px;
    padding-top: 13px;
    border-top: 1px solid rgba(255, 255, 255, 0.08);
    font-size: 12px;
    font-weight: 650;
    opacity: 0.82;
}


    .volunteer-card .sc-action-footer i {
        font-size: 16px;
        transition: transform 0.3s ease;
    }


.volunteer-card:hover .sc-action-footer i {
    transform: translateX(6px);
}


/* =========================================================
   TABLET
   ========================================================= */

@media (max-width: 1100px) {

    .volunteer-action-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}


/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width: 700px) {

    .volunteer-dashboard {
        padding: 15px;
    }

    .volunteer-action-grid {
        grid-template-columns: 1fr;
        gap: 15px;
    }

    .volunteer-card {
        min-height: 210px;
        padding: 20px;
        border-radius: 17px;
    }

        .volunteer-card .sc-action-body h3 {
            font-size: 19px;
        }

