/* =========================================================
   SWIFTCARE - NEW OPPORTUNITY
   WHITE / FOREST GREEN / LIME
   READABLE DEEP TEXT
   ========================================================= */

.sc-new-opportunity {
    --sc-forest: #176b3a;
    --sc-forest-dark: #0f542c;
    --sc-forest-deep: #0b3f22;
    --sc-lime: #b8ff00;
    --sc-lime-dark: #8fce00;
    /* Deep readable text */
    --sc-text: #173329;
    --sc-muted: #53665d;
    --sc-border: #e5ece7;
    --sc-soft: #f6faf7;
    width: 100%;
    box-sizing: border-box;
    padding: 28px 30px 45px;
    color: var(--sc-text);
    background: #ffffff;
}


    /* =========================================================
   HEADER
   ========================================================= */

