        justify-content: center;
        color: var(--sc-forest);
        background: rgba(184, 255, 0, .15);
        border: 1px solid rgba(143, 206, 0, .28);
        border-radius: 13px;
        font-size: 18px;
    }

    .sc-new-opportunity .op-card-header h2 {
        margin: 0;
        color: var(--sc-forest-deep);
        font-size: 17px;
        line-height: 1.2;
        font-weight: 800;
    }

    .sc-new-opportunity .op-card-header span {
        display: block;
        margin-top: 4px;
        color: #53665d;
        font-size: 11px;
        line-height: 1.4;
    }


    /* =========================================================
   FORM GRID
   ========================================================= */

    .sc-new-opportunity .op-form-grid {
        position: relative;
        z-index: 2;
        display: grid;
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 18px;
    }

    .sc-new-opportunity .op-form-group {
        min-width: 0;
        display: flex;
        flex-direction: column;
        gap: 7px;
    }

        .sc-new-opportunity .op-form-group.full {
            grid-column: 1 / -1;
        }


    /* =========================================================
   LABELS
   ========================================================= */

    .sc-new-opportunity .op-label {
        color: #304b3f;
        font-size: 11px;
        line-height: 1.3;
        font-weight: 750;
        letter-spacing: .15px;
    }

    .sc-new-opportunity .op-required {
        color: #75aa00;
        font-weight: 900;
    }


    /* =========================================================
   INPUTS
   ========================================================= */

    .sc-new-opportunity .op-input,
    .sc-new-opportunity .op-select,
    .sc-new-opportunity .op-textarea {
        width: 100%;
        box-sizing: border-box;
        color: #173329;
        background: #fbfdfb;
        border: 1px solid #dce7df;
        border-radius: 11px;
        outline: none;
        font-family: inherit;
        transition: border-color .25s ease, box-shadow .25s ease, background .25s ease;
    }

    .sc-new-opportunity .op-input,
    .sc-new-opportunity .op-select {
        height: 46px;
        padding: 0 13px;
        font-size: 13px;
    }

    .sc-new-opportunity .op-textarea {
        min-height: 125px;
        padding: 13px;
        resize: vertical;
        font-size: 13px;
        line-height: 1.55;
    }

        .sc-new-opportunity .op-input::placeholder,
        .sc-new-opportunity .op-textarea::placeholder {
            color: #7d8c84;
        }

        .sc-new-opportunity .op-input:hover,
        .sc-new-opportunity .op-select:hover,
        .sc-new-opportunity .op-textarea:hover {
            border-color: #bfd2c4;
            background: #ffffff;
        }

        .sc-new-opportunity .op-input:focus,
        .sc-new-opportunity .op-select:focus,
        .sc-new-opportunity .op-textarea:focus {
            border-color: var(--sc-forest);
            background: #ffffff;
            box-shadow: 0 0 0 3px rgba(23, 107, 58, .08);
        }

    .sc-new-opportunity .op-select {
        cursor: pointer;
    }

        .sc-new-opportunity .op-select option {
            color: #173329;
            background: #ffffff;
        }

    .sc-new-opportunity .field-validation-error {
        color: #c73b3b;
        font-size: 10px;
        line-height: 1.3;
    }


    /* =========================================================
   POSTER CARD
   ========================================================= */

    .sc-new-opportunity .poster-card {
        padding: 20px;
    }

        .sc-new-opportunity .poster-card .op-card-header {
            margin-bottom: 17px;
        }


    /* =========================================================
   DOTTED UPLOAD AREA
   ========================================================= */

    .sc-new-opportunity .poster-upload {
        position: relative;
        width: 100%;
        min-height: 310px;
        display: flex;
        align-items: center;
        justify-content: center;
        box-sizing: border-box;
        padding: 25px;
        overflow: hidden;
        text-align: center;
        background: linear-gradient( 145deg, #fbfefb, #f6faf7 );
        border: 2px dashed rgba(23, 107, 58, .28);
        border-radius: 17px;
        cursor: pointer;
        transition: border-color .3s ease, background .3s ease, transform .3s ease, box-shadow .3s ease;
    }

        .sc-new-opportunity .poster-upload::after {
            content: "";
            position: absolute;
            inset: 7px;
            border: 1px dashed rgba(184, 255, 0, .35);
            border-radius: 12px;
            pointer-events: none;
        }

        .sc-new-opportunity .poster-upload:hover {
            border-color: var(--sc-forest);
            background: linear-gradient( 145deg, #f8fdf8, #f1f9f3 );
            transform: translateY(-2px);
            box-shadow: 0 10px 28px rgba(23, 107, 58, .08);
        }

        .sc-new-opportunity .poster-upload.dragover {
            border-color: var(--sc-lime-dark);
            background: rgba(184, 255, 0, .08);
            box-shadow: 0 0 0 4px rgba(184, 255, 0, .08);
        }

    .sc-new-opportunity .poster-upload-content {
        position: relative;
        z-index: 3;
        pointer-events: none;
    }

    .sc-new-opportunity .poster-upload-icon {
        width: 68px;
        height: 68px;
        display: flex;
        align-items: center;
        justify-content: center;
        margin: 0 auto 16px;
        color: var(--sc-forest);
        background: rgba(184, 255, 0, .17);
        border: 1px solid rgba(143, 206, 0, .32);
        border-radius: 19px;
        font-size: 27px;
    }

    .sc-new-opportunity .poster-upload h3 {
        margin: 0 0 7px;
        color: var(--sc-forest-deep);
        font-size: 15px;
        font-weight: 800;
    }

    .sc-new-opportunity .poster-upload p {
        margin: 0;
        color: #53665d;
        font-size: 11px;
        line-height: 1.65;
    }

    .sc-new-opportunity .poster-upload strong {
        color: var(--sc-forest);
        font-weight: 800;
    }

    .sc-new-opportunity .poster-formats {
        margin-top: 9px !important;
        color: #718078 !important;
        font-size: 10px !important;
    }

    .sc-new-opportunity .poster-input {
        position: absolute;
        inset: 0;
        width: 100%;
        height: 100%;
        opacity: 0;
        cursor: pointer;
        z-index: 10;
    }


    /* =========================================================
   POSTER LIVE PREVIEW
   ========================================================= */

    .sc-new-opportunity .poster-preview {
        position: absolute;
        inset: 0;
        z-index: 8;
        display: none;
        background: #102d1d;
    }

        .sc-new-opportunity .poster-preview.active {
            display: block;
        }

        .sc-new-opportunity .poster-preview img {
            width: 100%;
            height: 100%;
            display: block;
            object-fit: cover;
        }

    .sc-new-opportunity .poster-preview-overlay {
        position: absolute;
        inset: 0;
        display: flex;
        align-items: flex-end;
        justify-content: space-between;
        gap: 10px;
        padding: 15px;
        background: linear-gradient( to top, rgba(7, 27, 17, .88), rgba(7, 27, 17, 0) 65% );
        pointer-events: none;
    }

    .sc-new-opportunity .poster-file-name {
        max-width: 65%;
        overflow: hidden;
        color: #ffffff;
        white-space: nowrap;
        text-overflow: ellipsis;
        font-size: 11px;
        font-weight: 700;
    }

    .sc-new-opportunity .poster-change {
        display: inline-flex;
        align-items: center;
        gap: 6px;
        padding: 8px 10px;
        color: #ffffff;
        background: rgba(23, 107, 58, .9);
        border: 1px solid rgba(184, 255, 0, .45);
        border-radius: 8px;
        font-size: 10px;
        font-weight: 750;
    }

    .sc-new-opportunity .poster-help {
        display: flex;
        gap: 7px;
        margin-top: 11px;
        color: #61736a;
        font-size: 10px;
        line-height: 1.55;
    }

        .sc-new-opportunity .poster-help i {
            flex-shrink: 0;
            margin-top: 1px;
            color: var(--sc-forest);
        }


    /* =========================================================
   DYNAMIC LISTS
   ========================================================= */

    .sc-new-opportunity .dynamic-list {
        position: relative;
        z-index: 2;
        display: flex;
        flex-direction: column;
        gap: 10px;
    }

    .sc-new-opportunity .dynamic-row {
        display: flex;
        align-items: center;
        gap: 9px;
    }

        .sc-new-opportunity .dynamic-row .op-input {
            flex: 1;
        }

    .sc-new-opportunity .remove-item {
        width: 43px;
        height: 43px;
        flex-shrink: 0;
        display: flex;
        align-items: center;
        justify-content: center;
        color: #65756d;
        background: #f8faf8;
        border: 1px solid #e0e7e2;
        border-radius: 10px;
        cursor: pointer;
        transition: all .25s ease;
    }

        .sc-new-opportunity .remove-item:hover {
            color: #c53d3d;
            background: #fff5f5;
            border-color: #f0caca;
        }


    /* =========================================================
   ADD BUTTON
   ========================================================= */

    .sc-new-opportunity .add-item {
        position: relative;
        z-index: 2;
        width: fit-content;
        display: inline-flex;
        align-items: center;
        gap: 7px;
        margin-top: 11px;
        padding: 9px 13px;
        color: var(--sc-forest);
        background: rgba(184, 255, 0, .10);
        border: 1px solid rgba(143, 206, 0, .27);
        border-radius: 9px;
        font-size: 11px;
        font-weight: 750;
        cursor: pointer;
        transition: all .25s ease;
    }

        .sc-new-opportunity .add-item:hover {
            color: var(--sc-forest-dark);
            background: rgba(184, 255, 0, .18);
            border-color: rgba(143, 206, 0, .45);
            transform: translateY(-1px);
        }


    /* =========================================================
   INFORMATION BOX
   ========================================================= */

    .sc-new-opportunity .op-info {
        position: relative;
        z-index: 2;
        padding: 17px;
        background: #f7faf8;
        border: 1px solid #e2ebe5;
        border-radius: 14px;
    }

    .sc-new-opportunity .op-info-title {
        display: flex;
        align-items: center;
        gap: 8px;
        margin-bottom: 13px;
        color: var(--sc-forest-deep);
        font-size: 12px;
        font-weight: 800;
    }

        .sc-new-opportunity .op-info-title i {
            color: var(--sc-lime-dark);
            font-size: 15px;
        }

    .sc-new-opportunity .op-info ul {
        padding: 0;
        margin: 0;
        list-style: none;
    }

    .sc-new-opportunity .op-info li {
        position: relative;
        padding-left: 16px;
        margin-bottom: 9px;
        color: #53665d;
        font-size: 10px;
        line-height: 1.55;
    }

        .sc-new-opportunity .op-info li:last-child {
            margin-bottom: 0;
        }

        .sc-new-opportunity .op-info li::before {
            content: "";
            position: absolute;
            left: 0;
            top: 6px;
            width: 5px;
            height: 5px;
            border-radius: 50%;
            background: var(--sc-lime-dark);
        }


    /* =========================================================
   FORM ACTIONS
   ========================================================= */

    .sc-new-opportunity .op-actions {
        display: flex;
        align-items: center;
        justify-content: flex-end;
        gap: 10px;
        padding-top: 2px;
    }

    .sc-new-opportunity .op-btn {
        min-height: 45px;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        gap: 8px;
        padding: 0 18px;
        border-radius: 10px;
        font-size: 11px;
        font-weight: 800;
        text-decoration: none;
        cursor: pointer;
        transition: all .25s ease;
    }

    .sc-new-opportunity .op-btn-cancel {
        color: #53665d;
        background: #f5f7f5;
        border: 1px solid #dfe6e1;
    }

        .sc-new-opportunity .op-btn-cancel:hover {
            color: var(--sc-forest);
            background: #eef5f0;
            border-color: #cadbce;
        }

    .sc-new-opportunity .op-btn-submit {
        color: #12351f;
        background: var(--sc-lime);
        border: 1px solid var(--sc-lime);
        box-shadow: 0 7px 18px rgba(143, 206, 0, .18);
    }

        .sc-new-opportunity .op-btn-submit:hover {
            background: #c7ff32;
            border-color: #c7ff32;
            transform: translateY(-2px);
            box-shadow: 0 10px 24px rgba(143, 206, 0, .25);
        }


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 1100px) {

    .sc-new-opportunity .op-layout {
        grid-template-columns: 1fr;
    }

    .sc-new-opportunity .op-sidebar {
        position: static;
        display: grid;
        grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
        align-items: start;
    }
}


@media (max-width: 760px) {

    .sc-new-opportunity {
        padding: 20px 15px 35px;
    }

        .sc-new-opportunity .op-header {
            margin-bottom: 20px;
        }

            .sc-new-opportunity .op-header h1 {
                font-size: 24px;
            }

        .sc-new-opportunity .op-header-description {
            font-size: 12px;
        }

        .sc-new-opportunity .op-layout {
            gap: 15px;
        }

        .sc-new-opportunity .op-form-grid {
            grid-template-columns: 1fr;
        }

        .sc-new-opportunity .op-form-group.full {
            grid-column: auto;
        }

        .sc-new-opportunity .op-sidebar {
            grid-template-columns: 1fr;
        }

        .sc-new-opportunity .op-card {
            padding: 18px;
            border-radius: 16px;
        }

        .sc-new-opportunity .poster-upload {
            min-height: 275px;
        }

        .sc-new-opportunity .op-actions {
            flex-direction: column-reverse;
        }

        .sc-new-opportunity .op-btn {
            width: 100%;
        }
}


@media (max-width: 480px) {

    .sc-new-opportunity .op-header-left {
        gap: 10px;
    }

    .sc-new-opportunity .op-back {
        width: 38px;
        height: 38px;
    }

    .sc-new-opportunity .op-header h1 {
        font-size: 21px;
    }

    .sc-new-opportunity .op-badge {
        font-size: 8px;
    }

    .sc-new-opportunity .dynamic-row {
        align-items: stretch;
    }

    .sc-new-opportunity .remove-item {
        width: 40px;
        height: 46px;
    }
}


/* =========================================================
   SOUTH AFRICAN CITY SEARCH
   ========================================================= */

.sc-new-opportunity .city-search-wrapper {
    position: relative;
    width: 100%;
}

.sc-new-opportunity .city-search-input-wrapper {
    position: relative;
}

.sc-new-opportunity .city-search-input {
    padding-left: 42px;
    padding-right: 42px;
}

.sc-new-opportunity .city-search-icon {
    position: absolute;
    left: 15px;
    top: 50%;
    z-index: 3;
    color: var(--sc-forest);
    transform: translateY(-50%);
    pointer-events: none;
}

.sc-new-opportunity .city-loading {
    position: absolute;
    right: 14px;
    top: 50%;
    display: none;
    color: var(--sc-forest);
    transform: translateY(-50%);
}

    .sc-new-opportunity .city-loading i {
        display: block;
        animation: citySpin .8s linear infinite;
    }

@keyframes citySpin {
    from {
        transform: rotate(0deg);
    }

    to {
        transform: rotate(360deg);
    }
}


/* =========================================================
   CITY SEARCH CONTAINER
   ========================================================= */

.city-search-wrapper {
    position: relative;
    width: 100%;
    z-index: 1000;
}


/* =========================================================
   CITY INPUT
   ========================================================= */

.city-search-input-wrapper {
    position: relative;
    width: 100%;
    z-index: 1002;
}

.city-search-input {
    width: 100%;
    padding-left: 44px !important;
    padding-right: 48px !important;
}


/* =========================================================
   SEARCH ICON
   ========================================================= */

.city-search-icon {
    position: absolute;
    left: 16px;
    top: 50%;
    transform: translateY(-50%);
    color: #53665d;
    font-size: 17px;
    pointer-events: none;
    z-index: 1003;
}


/* =========================================================
   LOADING ICON
   ========================================================= */

.city-loading {
    position: absolute;
    right: 16px;
    top: 50%;
    transform: translateY(-50%);
    display: none;
    color: var(--sc-forest);
    z-index: 1003;
}

    .city-loading i {
        display: inline-block;
        animation: citySpinner 0.8s linear infinite;
    }

@keyframes citySpinner {

    from {
        transform: rotate(0deg);
    }

    to {
        transform: rotate(360deg);
    }
}


/* =========================================================
   CITY DROPDOWN
   ========================================================= */

.city-results {
    position: absolute;
    top: calc(100% + 8px);
    left: 0;
    right: 0;
    width: 100%;
    background: #ffffff;
    border: 1px solid #dce7df;
    border-radius: 14px;
    box-shadow: 0 20px 45px rgba(15, 23, 42, 0.18), 0 6px 15px rgba(15, 23, 42, 0.08);
    display: none;
    z-index: 999999;
    max-height: 330px;
    overflow-y: auto;
    box-sizing: border-box;
    animation: cityDropdownIn 0.15s ease-out;
}

    .city-results.active {
        display: block;
    }

@keyframes cityDropdownIn {

    from {
        opacity: 0;
        transform: translateY(-5px);
    }

    to {
        opacity: 1;
        transform: translateY(0);
    }
}


/* =========================================================
   CITY RESULT
   ========================================================= */

.city-result {
    width: 100%;
    min-height: 64px;
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 12px 15px;
    margin: 0;
    border: none;
    border-bottom: 1px solid #edf1ee;
    background: #ffffff;
    color: #263b32;
    text-align: left;
    cursor: pointer;
    box-sizing: border-box;
    transition: background 0.15s ease, padding-left 0.15s ease;
}

    .city-result:last-child {
        border-bottom: none;
    }

    .city-result:hover {
        background: #f3f8f5;
        padding-left: 18px;
    }

    .city-result:focus {
        outline: none;
        background: #f3f8f5;
    }

    .city-result:active {
        background: #e8f2eb;
    }


/* =========================================================
   CITY RESULT ICON
   ========================================================= */

.city-result-icon {
    width: 38px;
    height: 38px;
    min-width: 38px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    background: #edf7f0;
    color: #1f5135;
    font-size: 16px;
    flex-shrink: 0;
}


/* =========================================================
   RESULT CONTENT
   ========================================================= */

.city-result-content {
    flex: 1;
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 3px;
}

.city-result-name {
    display: block;
    font-size: 15px;
    font-weight: 700;
    color: #263b32;
    line-height: 1.3;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.city-result-province {
    display: block;
    font-size: 13px;
    color: #5f7068;
    line-height: 1.3;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}


/* =========================================================
   RIGHT ARROW
   ========================================================= */

.city-result-arrow {
    color: #718078;
    font-size: 14px;
    flex-shrink: 0;
    transition: color 0.15s ease, transform 0.15s ease;
}

.city-result:hover .city-result-arrow {
    color: #1f5135;
    transform: translateX(3px);
}


/* =========================================================
   NO RESULTS
   ========================================================= */

.city-no-results {
    padding: 20px;
    display: flex;
    align-items: center;
    justify-content: center;
    text-align: center;
    color: #5f7068;
    background: #ffffff;
    font-size: 14px;
    min-height: 60px;
}

    .city-no-results i {
        color: #1f5135;
    }


/* =========================================================
   SELECTED CITY
   ========================================================= */

.selected-city {
    display: none;
    align-items: center;
    gap: 12px;
    width: 100%;
    margin-top: 10px;
    padding: 12px 14px;
    background: #f1f8f3;
    border: 1px solid #cfe3d4;
    border-radius: 12px;
    box-sizing: border-box;
}

    .selected-city.active {
        display: flex;
    }


/* =========================================================
   SELECTED CITY ICON
   ========================================================= */

.selected-city-icon {
    width: 38px;
    height: 38px;
    min-width: 38px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    background: #1f5135;
    color: #ffffff;
    font-size: 17px;
    flex-shrink: 0;
}


/* =========================================================
   SELECTED CITY TEXT
   ========================================================= */

.selected-city-content {
    flex: 1;
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 3px;
}

    .selected-city-content strong {
        display: block;
        font-size: 15px;
        font-weight: 700;
        color: #1f5135;
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
    }

    .selected-city-content span {
        display: block;
        font-size: 13px;
        color: #5f7068;
    }


/* =========================================================
   CLEAR CITY
   ========================================================= */

.clear-city {
    width: 34px;
    height: 34px;
    min-width: 34px;
    display: flex;
    align-items: center;
    justify-content: center;
    border: none;
    border-radius: 8px;
    background: transparent;
    color: #65756d;
    cursor: pointer;
    font-size: 18px;
    transition: background 0.15s ease, color 0.15s ease;
}

    .clear-city:hover {
        background: #ffffff;
        color: #dc2626;
    }

    .clear-city:focus {
        outline: none;
        box-shadow: 0 0 0 3px rgba(31, 81, 53, 0.12);
    }


/* =========================================================
   DROPDOWN SCROLLBAR
   ========================================================= */

.city-results::-webkit-scrollbar {
    width: 7px;
}

.city-results::-webkit-scrollbar-track {
    background: #f5f7f5;
}

.city-results::-webkit-scrollbar-thumb {
    background: #c8d5cb;
    border-radius: 10px;
}

    .city-results::-webkit-scrollbar-thumb:hover {
        background: #aab9ae;
    }


/* =========================================================
   VERY IMPORTANT
   ALLOW DROPDOWN TO ESCAPE CARD
   ========================================================= */

.sc-new-opportunity,
.op-layout,
.op-main,
.op-card,
.op-form-grid,
.op-form-group,
.city-search-wrapper {
    overflow: visible !important;
}


    /* =========================================================
   KEEP CITY SECTION ABOVE FOLLOWING SECTIONS
   ========================================================= */

