   LIGHT FOREST GREEN
   ========================================================= */

.sc-op-hero {
    position: relative;
    min-height: 330px;
    margin-bottom: 22px;
    overflow: hidden;
    border: 1px solid rgba(23, 69, 44, 0.16);
    border-radius: 24px;
    /*
       LIGHT FOREST GREEN ONLY.
       No dark green hero anymore.
    */
    background: linear-gradient( 135deg, #e5f2e8 0%, #dceee1 42%, #d3e9d9 72%, #c9e3d0 100% );
    box-shadow: 0 20px 50px rgba(31, 81, 53, 0.10), inset 0 1px 0 rgba(255, 255, 255, 0.85);
}

.sc-op-hero-pattern {
    position: absolute;
    inset: 0;
    pointer-events: none;
    opacity: 0.45;
    background-image: linear-gradient( 135deg, rgba(255,255,255,0.38) 25%, transparent 25% ), linear-gradient( 315deg, rgba(23,69,44,0.035) 25%, transparent 25% );
    background-size: 80px 80px;
}

.sc-op-hero-glow {
    position: absolute;
    border-radius: 50%;
    filter: blur(3px);
    pointer-events: none;
}

.sc-op-hero-glow-one {
    width: 330px;
    height: 330px;
    right: -130px;
    top: -180px;
    background: rgba(183, 227, 63, 0.10);
}

.sc-op-hero-glow-two {
    width: 250px;
    height: 250px;
    left: -140px;
    bottom: -170px;
    background: rgba(255, 255, 255, 0.40);
}

.sc-op-hero-content {
    position: relative;
    z-index: 2;
    padding: 34px 37px;
}


/* =========================================================
   HERO TOP
   ========================================================= */

.sc-op-hero-top {
    display: flex;
    align-items: center;
    gap: 14px;
    margin-bottom: 19px;
}

.sc-op-hero-icon {
    width: 49px;
    height: 49px;
    flex: 0 0 49px;
    display: flex;
    align-items: center;
    justify-content: center;
    border: 1px solid rgba(23, 69, 44, 0.14);
    border-radius: 14px;
    background: rgba(255, 255, 255, 0.58);
    color: var(--sc-forest);
    font-size: 22px;
    box-shadow: 0 8px 25px rgba(31, 81, 53, 0.08), inset 0 1px 0 rgba(255,255,255,0.80);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
}

.sc-op-hero-badges {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 8px;
}

.sc-op-category-badge,
.sc-op-status-badge {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 8px 12px;
    border-radius: 30px;
    font-size: 11px;
    font-weight: 750;
}

.sc-op-category-badge {
    border: 1px solid rgba(23, 69, 44, 0.13);
    background: rgba(255, 255, 255, 0.64);
    color: #315f42;
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
}

.sc-op-status-badge {
    border: 1px solid rgba(23, 69, 44, 0.12);
    background: rgba(255,255,255,0.58);
    color: #355b43;
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
}


/* =========================================================
   STATUS COLOURS
   ========================================================= */

.sc-op-status-published {
    background: rgba(183, 227, 63, 0.18);
    border-color: rgba(130, 169, 37, 0.20);
    color: #4e6d22;
}

.sc-op-status-draft {
    background: rgba(255,255,255,0.58);
    color: #52665a;
}

.sc-op-status-closed {
    background: rgba(200,210,205,0.24);
    color: #5c6961;
}

.sc-op-status-cancelled {
    background: rgba(255, 100, 110, 0.10);
    color: #963e46;
}


/* =========================================================
   HERO TITLE
   ========================================================= */

.sc-op-hero h1 {
    max-width: 1000px;
    margin: 0 0 13px;
    /*
       Dark forest text on the light hero.
    */
    color: #173d28;
    font-size: clamp(30px, 3.5vw, 47px);
    font-weight: 800;
    line-height: 1.1;
    letter-spacing: -1px;
}

.sc-op-hero-description {
    max-width: 950px;
    margin: 0;
    color: #496253;
    font-size: 14px;
    line-height: 1.72;
    white-space: pre-line;
}


/* =========================================================
   HERO META
   ========================================================= */

.sc-op-hero-meta {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 12px;
    margin-top: 26px;
}

.sc-op-meta-item {
    display: flex;
    align-items: center;
    gap: 10px;
    min-width: 0;
    padding: 13px;
    border: 1px solid rgba(23,69,44,0.10);
    border-radius: 13px;
    background: rgba(255,255,255,0.54);
    backdrop-filter: blur(13px);
    -webkit-backdrop-filter: blur(13px);
}

.sc-op-meta-icon {
    width: 35px;
    height: 35px;
    flex: 0 0 35px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 9px;
    background: rgba(23,69,44,0.08);
    color: var(--sc-forest);
    font-size: 14px;
}

.sc-op-meta-item div:last-child {
    min-width: 0;
}

.sc-op-meta-item small {
    display: block;
    margin-bottom: 4px;
    color: #708076;
    font-size: 10px;
    font-weight: 650;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.sc-op-meta-item strong {
    display: block;
    overflow: hidden;
    color: #294635;
    font-size: 13px;
    font-weight: 700;
    text-overflow: ellipsis;
    white-space: nowrap;
}


/* =========================================================
   POSTER CARD
   ========================================================= */

.sc-op-poster-card {
    position: relative;
    margin-bottom: 22px;
    overflow: hidden;
    border: 1px solid var(--sc-border);
    border-radius: 20px;
    background: linear-gradient( 145deg, rgba(255,255,255,0.94), rgba(246,250,247,0.80) );
    box-shadow: 0 14px 40px rgba(25, 55, 38, 0.08), inset 0 1px 0 rgba(255,255,255,0.9);
    backdrop-filter: blur(18px);
    -webkit-backdrop-filter: blur(18px);
}

.sc-op-poster-header {
    padding: 18px 21px;
    border-bottom: 1px solid rgba(31,81,53,0.08);
}

.sc-op-poster-container {
    position: relative;
    display: flex;
    justify-content: center;
    padding: 23px;
    background: linear-gradient( 135deg, rgba(183,227,63,0.035), rgba(23,69,44,0.035) );
}

.sc-op-poster-image {
    display: block;
    width: auto;
    max-width: 100%;
    max-height: 520px;
    object-fit: contain;
    border-radius: 14px;
    box-shadow: 0 15px 40px rgba(16,53,31,0.16);
    border: 1px solid rgba(31,81,53,0.10);
}


/* =========================================================
   CONTENT GRID
   SAME ORIGINAL LAYOUT
   ========================================================= */

.sc-op-content-grid {
    display: grid;
    grid-template-columns: minmax(0, 1fr) 340px;
    align-items: start;
    gap: 22px;
}

.sc-op-main-column {
    min-width: 0;
}

.sc-op-sidebar {
    min-width: 0;
    position: sticky;
    top: 18px;
}


/* =========================================================
   GLASS CARDS
   ========================================================= */

.sc-op-glass-card {
    position: relative;
    margin-bottom: 20px;
    overflow: hidden;
    border: 1px solid rgba(31,81,53,0.11);
    border-radius: 18px;
    background: linear-gradient( 145deg, rgba(255,255,255,0.91), rgba(249,252,250,0.76) );
    box-shadow: 0 12px 32px rgba(24,67,43,0.07), inset 0 1px 0 rgba(255,255,255,0.95);
    backdrop-filter: blur(18px);
    -webkit-backdrop-filter: blur(18px);
}

    .sc-op-glass-card::before {
        content: "";
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 2px;
        background: linear-gradient( 90deg, transparent, rgba(183,227,63,0.30), transparent );
    }


/* =========================================================
   CARD HEADER
   ========================================================= */

.sc-op-card-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 15px;
    padding: 18px 20px;
    border-bottom: 1px solid rgba(31,81,53,0.08);
    background: linear-gradient( 90deg, rgba(248,252,249,0.82), rgba(255,255,255,0.48) );
}

.sc-op-section-heading {
    display: flex;
    align-items: center;
    gap: 11px;
    min-width: 0;
}

.sc-op-section-icon {
    width: 38px;
    height: 38px;
    flex: 0 0 38px;
    display: flex;
    align-items: center;
    justify-content: center;
    border: 1px solid rgba(23,69,44,0.12);
    border-radius: 10px;
    background: linear-gradient( 135deg, #edf5ef, #e3eee6 );
    color: var(--sc-forest);
    font-size: 15px;
    box-shadow: inset 0 1px 0 rgba(255,255,255,0.8);
}

.sc-op-section-heading h2 {
    margin: 0 0 3px;
    color: #234532;
    font-size: 15px;
    font-weight: 750;
}

.sc-op-section-heading p {
    margin: 0;
    color: #849087;
    font-size: 11px;
    line-height: 1.4;
}


/* =========================================================
   OVERVIEW
   ========================================================= */

.sc-op-overview-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 12px;
    padding: 20px;
}

.sc-op-info-box {
    display: flex;
    align-items: center;
    gap: 12px;
    min-width: 0;
    padding: 15px;
    border: 1px solid rgba(31,81,53,0.08);
    border-radius: 13px;
    background: rgba(255,255,255,0.65);
    box-shadow: 0 5px 15px rgba(24,67,43,0.035);
    transition: transform 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease;
}

    .sc-op-info-box:hover {
        transform: translateY(-2px);
        border-color: rgba(23,69,44,0.22);
        box-shadow: 0 9px 22px rgba(24,67,43,0.07);
    }

.sc-op-info-icon {
    width: 40px;
    height: 40px;
    flex: 0 0 40px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 10px;
    background: var(--sc-forest-soft);
    color: var(--sc-forest);
    font-size: 15px;
}

.sc-op-info-box div:last-child {
    min-width: 0;
}

.sc-op-info-box span {
    display: block;
    margin-bottom: 4px;
    color: #849087;
    font-size: 10px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.sc-op-info-box strong {
    display: block;
    color: #30483a;
    font-size: 13px;
    font-weight: 750;
}

.sc-op-info-box small {
    display: block;
    margin-top: 3px;
    color: #849087;
    font-size: 10px;
}


/* =========================================================
   SCHEDULE
   ========================================================= */

.sc-op-schedule-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 12px;
    padding: 20px;
}

.sc-op-schedule-box {
    display: flex;
    align-items: center;
    gap: 11px;
    padding: 15px;
    border: 1px solid rgba(31,81,53,0.08);
    border-radius: 13px;
    background: rgba(255,255,255,0.63);
}

.sc-op-schedule-icon {
    width: 39px;
    height: 39px;
    flex: 0 0 39px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 10px;
    background: linear-gradient( 135deg, #edf5ef, #e3eee6 );
    color: var(--sc-forest);
    font-size: 14px;
}

.sc-op-schedule-box span {
    display: block;
    margin-bottom: 4px;
    color: #829087;
    font-size: 10px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.sc-op-schedule-box strong {
    display: block;
    color: #30483a;
    font-size: 13px;
    font-weight: 750;
}


/* =========================================================
   COUNT BADGE
   ========================================================= */

.sc-op-count {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 28px;
    height: 28px;
    padding: 0 9px;
    border-radius: 30px;
    background: var(--sc-forest-soft);
    color: var(--sc-forest);
    font-size: 11px;
    font-weight: 800;
}


/* =========================================================
   LISTS
   ========================================================= */

.sc-op-list {
    display: flex;
    flex-direction: column;
    gap: 8px;
    padding: 19px 20px 21px;
}

.sc-op-list-item {
    display: flex;
    align-items: flex-start;
    gap: 10px;
    padding: 13px 14px;
    border: 1px solid rgba(31,81,53,0.075);
    border-radius: 11px;
    background: rgba(255,255,255,0.58);
    color: #536259;
    font-size: 12px;
    line-height: 1.58;
    transition: background 0.2s ease, transform 0.2s ease;
}

    .sc-op-list-item:hover {
        background: rgba(243,250,223,0.45);
        transform: translateX(2px);
    }

.sc-op-list-check {
    width: 26px;
    height: 26px;
    flex: 0 0 26px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 7px;
    background: var(--sc-forest-soft);
    color: var(--sc-forest);
    font-size: 11px;
}


/* =========================================================
   SKILLS
   ========================================================= */

.sc-op-skills {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    padding: 20px 20px 22px;
}

.sc-op-skill {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    padding: 9px 12px;
    border: 1px solid rgba(23,69,44,0.14);
    border-radius: 30px;
    background: linear-gradient( 135deg, #eef5ef, #e6f0e8 );
    color: #31573e;
    font-size: 11px;
    font-weight: 700;
    box-shadow: inset 0 1px 0 rgba(255,255,255,0.8);
}

    .sc-op-skill i {
        color: var(--sc-forest-light);
        font-size: 10px;
    }


/* =========================================================
   CAPACITY
   ========================================================= */

.sc-op-capacity-body {
    padding: 20px;
}

.sc-op-capacity-number {
    display: flex;
    align-items: flex-end;
    justify-content: space-between;
    margin-bottom: 13px;
}

    .sc-op-capacity-number strong {
        display: block;
        color: var(--sc-forest);
        font-size: 31px;
        font-weight: 800;
        line-height: 1;
    }

    .sc-op-capacity-number span {
        display: block;
        margin-top: 5px;
        color: #7d8b82;
        font-size: 10px;
        font-weight: 650;
    }

.sc-op-capacity-total {
    color: #708078;
    font-size: 14px;
    font-weight: 750;
}

.sc-op-progress {
    width: 100%;
    height: 9px;
    overflow: hidden;
    border-radius: 30px;
    background: #e8eee9;
    box-shadow: inset 0 1px 3px rgba(0,0,0,0.05);
}

.sc-op-progress-bar {
    height: 100%;
    min-width: 2px;
    border-radius: inherit;
    background: linear-gradient( 90deg, #4f812c, #b7e33f );
    box-shadow: 0 0 10px rgba(183,227,63,0.28);
    transition: width 0.3s ease;
}

.sc-op-capacity-footer {
    display: flex;
    justify-content: space-between;
    gap: 8px;
    margin-top: 10px;
    color: #7a877f;
    font-size: 10px;
    font-weight: 650;
}

    .sc-op-capacity-footer span:first-child {
        color: #50705b;
    }

    .sc-op-capacity-footer i {
        color: #5d8630;
    }


/* =========================================================
   DEADLINE
   ========================================================= */

.sc-op-deadline-card {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 17px;
}

.sc-op-deadline-icon {
    width: 43px;
    height: 43px;
    flex: 0 0 43px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 11px;
    background: var(--sc-forest-soft);
    color: var(--sc-forest);
    font-size: 17px;
}

.sc-op-deadline-content {
    min-width: 0;
}

    .sc-op-deadline-content > span {
        display: block;
        margin-bottom: 4px;
        color: #849087;
        font-size: 10px;
        font-weight: 700;
        text-transform: uppercase;
        letter-spacing: 0.45px;
    }

    .sc-op-deadline-content > strong {
        display: block;
        color: #30483a;
        font-size: 14px;
        font-weight: 800;
    }

    .sc-op-deadline-content small {
        display: flex;
        align-items: center;
        gap: 5px;
        margin-top: 5px;
        font-size: 10px;
        font-weight: 650;
    }

.sc-op-deadline-open {
    color: #4c7823;
}

.sc-op-deadline-expired {
    color: #9b3e45;
}


/* =========================================================
   LOCATION
   ========================================================= */

.sc-op-location {
    display: flex;
    align-items: flex-start;
    gap: 12px;
    padding: 20px;
}

.sc-op-location-icon {
    width: 41px;
    height: 41px;
    flex: 0 0 41px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 10px;
    background: var(--sc-forest-soft);
    color: var(--sc-forest);
    font-size: 16px;
}

.sc-op-location strong {
    display: block;
    margin-bottom: 4px;
    color: #30483a;
    font-size: 14px;
    font-weight: 800;
}

.sc-op-location span,
.sc-op-location small {
    display: block;
    margin-top: 3px;
    color: #7d8982;
    font-size: 11px;
}

.sc-op-location small {
    color: #a0aaa4;
}


/* =========================================================
   DETAIL LIST
   ========================================================= */

.sc-op-detail-list {
    padding: 8px 20px 15px;
}

.sc-op-detail-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    padding: 12px 0;
    border-bottom: 1px solid rgba(31,81,53,0.075);
}

    .sc-op-detail-row:last-child {
        border-bottom: 0;
    }

    .sc-op-detail-row span {
        display: inline-flex;
        align-items: center;
        gap: 7px;
        color: #7c8981;
        font-size: 11px;
        font-weight: 650;
    }

        .sc-op-detail-row span i {
            color: #5d8630;
            font-size: 12px;
        }

    .sc-op-detail-row strong {
        color: #30483a;
        font-size: 11px;
        font-weight: 750;
        text-align: right;
    }


/* =========================================================
   ACTIONS
   ========================================================= */

.sc-op-actions-card {
    display: flex;
    flex-direction: column;
    gap: 9px;
    padding: 16px;
    border: 1px solid rgba(31,81,53,0.11);
    border-radius: 18px;
    background: linear-gradient( 145deg, rgba(255,255,255,0.92), rgba(246,250,247,0.80) );
    box-shadow: 0 12px 30px rgba(24,67,43,0.07);
    backdrop-filter: blur(18px);
    -webkit-backdrop-filter: blur(18px);
}

.sc-op-action-primary,
.sc-op-action-secondary {
    width: 100%;
    min-height: 44px;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    padding: 10px 14px;
    border-radius: 10px;
    font-size: 12px;
    font-weight: 750;
    text-decoration: none;
    transition: transform 0.2s ease, box-shadow 0.2s ease, background 0.2s ease;
}


/* =========================================================
   PRIMARY ACTION
   ========================================================= */

.sc-op-action-primary {
    border: 1px solid #17452c;
    background: linear-gradient( 135deg, #17452c, #28633f );
    color: #ffffff;
    box-shadow: 0 7px 18px rgba(23,69,44,0.20);
}

    .sc-op-action-primary:hover {
        color: #ffffff;
        transform: translateY(-2px);
        background: linear-gradient( 135deg, #123a25, #215a38 );
        box-shadow: 0 11px 25px rgba(23,69,44,0.27);
    }


/* =========================================================
   SECONDARY ACTION
   ========================================================= */

.sc-op-action-secondary {
    border: 1px solid rgba(31,81,53,0.13);
    background: rgba(255,255,255,0.68);
    color: var(--sc-forest);
}

    .sc-op-action-secondary:hover {
        color: var(--sc-forest);
        background: #ffffff;
        transform: translateY(-1px);
        box-shadow: 0 7px 17px rgba(24,67,43,0.08);
    }


/* =========================================================
   RESPONSIVE - 1100
   ========================================================= */

@media (max-width: 1100px) {

    .sc-op-content-grid {
        grid-template-columns: minmax(0, 1fr) 300px;
    }

    .sc-op-hero h1 {
        font-size: 36px;
    }
}


/* =========================================================
   RESPONSIVE - 900
   ========================================================= */

@media (max-width: 900px) {

    .sc-opportunity-details-page {
        padding: 20px 17px 35px;
    }

    .sc-op-content-grid {
        grid-template-columns: 1fr;
    }

    .sc-op-sidebar {
        position: static;
        display: grid;
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 15px;
    }

        .sc-op-sidebar .sc-op-glass-card {
            margin-bottom: 0;
        }

        .sc-op-sidebar .sc-op-actions-card {
            grid-column: 1 / -1;
        }
}


/* =========================================================
   RESPONSIVE - 700
   ========================================================= */

@media (max-width: 700px) {

    .sc-opportunity-details-page {
        padding: 15px 11px 30px;
    }

    .sc-op-page-header-label {
        display: none;
    }

    .sc-op-hero {
        min-height: auto;
        border-radius: 18px;
    }

    .sc-op-hero-content {
        padding: 26px 20px;
    }

    .sc-op-hero h1 {
        font-size: 30px;
        letter-spacing: -0.5px;
    }

    .sc-op-hero-description {
        font-size: 13px;
    }

    .sc-op-hero-meta {
        grid-template-columns: 1fr;
    }

    .sc-op-overview-grid,
    .sc-op-schedule-grid {
        grid-template-columns: 1fr;
    }

