/* =========================================================
   TEMPDATA MESSAGE
   ========================================================= */

.sc-tempdata-message {
    width: 100%;
    display: flex;
    align-items: center;
    gap: 13px;
    padding: 13px 15px;
    margin-bottom: 18px;
    border-radius: 14px;
    border: 1px solid transparent;
    box-sizing: border-box;
    box-shadow: 0 8px 25px rgba(32, 53, 42, 0.08);
    animation: scTempDataSlideIn 0.35s ease forwards;
}

.sc-tempdata-success {
    background: rgba(239, 248, 242, 0.96);
    border-color: #cfe4d5;
    color: #28583b;
}

.sc-tempdata-error {
    background: rgba(255, 244, 244, 0.96);
    border-color: #edcccc;
    color: #8a3030;
}

.sc-tempdata-icon {
    width: 36px;
    height: 36px;
    flex: 0 0 36px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 10px;
    font-size: 17px;
}

.sc-tempdata-success .sc-tempdata-icon {
    background: #dcefe2;
    color: #2f6b46;
}

.sc-tempdata-error .sc-tempdata-icon {
    background: #f9dddd;
    color: #9b3535;
}

.sc-tempdata-content {
    min-width: 0;
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 2px;
}

    .sc-tempdata-content strong {
        font-size: 13px;
        font-weight: 700;
    }

    .sc-tempdata-content span {
        font-size: 12px;
        line-height: 1.45;
        color: #53645a;
    }

.sc-tempdata-close {
    width: 30px;
    height: 30px;
    flex: 0 0 30px;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 0;
    border: 0;
    border-radius: 8px;
    background: transparent;
    color: #718077;
    font-size: 18px;
    cursor: pointer;
    transition: all 0.2s ease;
}

    .sc-tempdata-close:hover {
        background: rgba(32, 53, 42, 0.07);
        color: #20352a;
    }

.sc-tempdata-message.sc-tempdata-hiding {
    animation: scTempDataFadeOut 0.35s ease forwards;
}

@keyframes scTempDataSlideIn {
    from {
        opacity: 0;
        transform: translateY(-8px);
    }

    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@keyframes scTempDataFadeOut {
    from {
        opacity: 1;
        transform: translateY(0);
        max-height: 100px;
        margin-bottom: 18px;
    }

    to {
        opacity: 0;
        transform: translateY(-8px);
        max-height: 0;
        margin-bottom: 0;
        padding-top: 0;
        padding-bottom: 0;
        overflow: hidden;
    }
}


/* =========================================================
   SWIFTCARE - VOLUNTEER OPPORTUNITIES
   SOFT GREEN + STRONG LIME + GLASS
   MATCHES THE ACTUAL RAZOR MARKUP
   ========================================================= */

.swiftcare-volunteer-section {
