/* =========================================================
   OPPORTUNITIES GRID
   ========================================================= */

.swiftcare-opportunities-grid {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 20px;
}


/* =========================================================
   OPPORTUNITY CARD
   ========================================================= */

.swiftcare-opportunity-card {
    position: relative;
    display: flex;
    flex-direction: column;
    min-height: 300px;
    padding: 23px;
    background: linear-gradient( 145deg, rgba(255, 255, 255, 0.84), rgba(255, 255, 255, 0.68) );
    border: 1px solid rgba(23, 77, 43, 0.13);
    border-radius: 20px;
    backdrop-filter: blur(22px);
    -webkit-backdrop-filter: blur(22px);
    box-shadow: 0 18px 40px rgba(23, 77, 43, 0.09), inset 0 1px 0 rgba(255, 255, 255, 0.88);
    overflow: hidden;
    transition: transform 0.25s ease, border-color 0.25s ease, box-shadow 0.25s ease;
}


    /* =========================================================
   LIME TOP ACCENT
   ========================================================= */

    .swiftcare-opportunity-card::before {
        content: "";
        position: absolute;
        top: 0;
        left: 7%;
        right: 7%;
        height: 3px;
        background: linear-gradient( 90deg, transparent, #9bea20, transparent );
    }


    .swiftcare-opportunity-card:hover {
        transform: translateY(-5px);
        border-color: rgba(111, 174, 15, 0.34);
        box-shadow: 0 22px 45px rgba(23, 77, 43, 0.12), 0 0 25px rgba(155, 234, 32, 0.09), inset 0 1px 0 rgba(255, 255, 255, 0.92);
    }


/* =========================================================
   CARD TOP
   IMPORTANT: MATCHES .swiftcare-opportunity-top
   ========================================================= */

.swiftcare-opportunity-top {
    position: relative;
    z-index: 2;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    margin-bottom: 21px;
}


/* =========================================================
   OPPORTUNITY ICON
   ========================================================= */

.swiftcare-opportunity-icon {
    width: 45px;
    height: 45px;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    border-radius: 14px;
    background: linear-gradient( 145deg, rgba(200, 255, 105, 0.55), rgba(155, 234, 32, 0.22) );
    border: 1px solid rgba(111, 174, 15, 0.28);
    color: #174d2b !important;
    font-size: 1rem;
    box-shadow: 0 8px 18px rgba(23, 77, 43, 0.06);
}


    .swiftcare-opportunity-icon i {
        color: #174d2b !important;
    }


/* =========================================================
   OPEN STATUS
   ALWAYS LIME
   ========================================================= */

.swiftcare-opportunity-status {
    display: inline-flex !important;
    align-items: center;
    justify-content: center;
    gap: 6px;
    padding: 7px 11px;
    border: 0 !important;
    border-radius: 50px;
    background: #b8e64c !important;
    background-color: #b8e64c !important;
    color: #10351f !important;
    font-size: 0.7rem;
    font-weight: 850;
    line-height: 1;
    white-space: nowrap;
    box-shadow: 0 5px 14px rgba(111, 174, 15, 0.15);
}


    .swiftcare-opportunity-status * {
        color: #10351f !important;
    }


    /*
   Your Razor currently has:

   <span class="swiftcare-opportunity-status">
       <span></span>
       Open
   </span>

   So target the inner span directly.
*/

    .swiftcare-opportunity-status > span {
        width: 6px;
        height: 6px;
        display: inline-block;
        flex-shrink: 0;
        border-radius: 50%;
        background: #17452c !important;
    }


/* =========================================================
   TITLE
   IMPORTANT: MATCHES .swiftcare-opportunity-title
   ========================================================= */

.swiftcare-opportunity-title {
