    backdrop-filter: blur(25px);
    -webkit-backdrop-filter: blur(25px);
    box-shadow: 0 22px 50px rgba(23, 77, 43, 0.10), inset 0 1px 0 rgba(255, 255, 255, 0.90);
    overflow: hidden;
}


    /* =========================================================
   EMPTY STATE LIME TOP LINE
   ========================================================= */

    .swiftcare-volunteer-empty::before {
        content: "";
        position: absolute;
        top: 0;
        left: 15%;
        right: 15%;
        height: 3px;
        background: linear-gradient( 90deg, transparent, #9bea20, transparent );
    }


