}


.sc-applicant-poster-image {
    width: 100%;
    height: 100%;
    display: block;
    object-fit: cover;
}


.sc-applicant-poster-placeholder {
    width: 100%;
    height: 100%;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 12px;
    text-align: center;
    color: #174d2b;
    background: linear-gradient( 145deg, rgba(200, 255, 105, 0.45), rgba(155, 234, 32, 0.12) );
}


    .sc-applicant-poster-placeholder i {
        font-size: 3rem;
    }


    .sc-applicant-poster-placeholder span {
        font-size: 0.85rem;
        font-weight: 800;
    }


/* =========================================================
           INTRODUCTION
           ========================================================= */

.sc-applicant-introduction {
    flex: 1;
    min-width: 0;
    padding: 12px 5px;
}


.sc-applicant-status {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    padding: 8px 12px;
    border-radius: 999px;
    background: rgba(155, 234, 32, 0.20);
    border: 1px solid rgba(111, 174, 15, 0.28);
    color: #174d2b;
    font-size: 0.72rem;
    font-weight: 850;
}


    .sc-applicant-status span {
        width: 7px;
        height: 7px;
        border-radius: 50%;
        background: #6fae0f;
    }


.sc-applicant-title {
    margin: 22px 0 18px;
    color: #174d2b;
    font-size: clamp(2rem, 4vw, 3rem);
    font-weight: 850;
    line-height: 1.08;
    letter-spacing: -1px;
}


.sc-applicant-description {
    margin: 0;
    color: #344f3d;
    font-size: 0.94rem;
    line-height: 1.8;
}


/* =========================================================
           INFORMATION
           TWO COLUMNS
           ========================================================= */

.sc-applicant-information {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    column-gap: 35px;
    margin-top: 28px;
}


.sc-applicant-information-item {
    display: flex;
    align-items: center;
    gap: 15px;
    width: 100%;
    padding: 17px 4px;
    border-bottom: 1px solid rgba(23, 77, 43, 0.09);
}


.sc-applicant-information-icon {
    width: 42px;
    min-width: 42px;
    height: 42px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 12px;
    background: rgba(155, 234, 32, 0.17);
    border: 1px solid rgba(111, 174, 15, 0.22);
    color: #174d2b;
    font-size: 0.95rem;
}


.sc-applicant-information-content {
    display: flex;
    flex-direction: column;
    gap: 3px;
    min-width: 0;
}


    .sc-applicant-information-content span {
        color: #6b7f71;
        font-size: 0.72rem;
        font-weight: 750;
        text-transform: uppercase;
        letter-spacing: 0.6px;
    }


    .sc-applicant-information-content strong {
        color: #20352a;
        font-size: 0.92rem;
        font-weight: 800;
        line-height: 1.4;
    }


/* =========================================================
           LIST SECTIONS
           ========================================================= */

.sc-applicant-list-section {
    margin-top: 30px;
    padding-top: 28px;
    border-top: 1px solid rgba(23, 77, 43, 0.10);
}


.sc-applicant-section-heading {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 17px;
}


    .sc-applicant-section-heading i {
        color: #6fae0f;
        font-size: 1rem;
    }


    .sc-applicant-section-heading h2 {
        margin: 0;
        color: #174d2b;
        font-size: 1.15rem;
        font-weight: 850;
    }


.sc-applicant-list {
    display: flex;
    flex-direction: column;
    gap: 11px;
    margin: 0;
    padding: 0;
    list-style: none;
}


    .sc-applicant-list li {
        display: flex;
        align-items: flex-start;
        gap: 10px;
        color: #344f3d;
        font-size: 0.88rem;
        line-height: 1.65;
    }


        .sc-applicant-list li i {
            flex-shrink: 0;
            margin-top: 4px;
            color: #6fae0f;
            font-size: 0.82rem;
        }


/* =========================================================
           APPLY BUTTON
           ========================================================= */

.sc-applicant-footer {
    display: flex;
    justify-content: flex-end;
    align-items: center;
    margin-top: 35px;
    padding-top: 25px;
    border-top: 1px solid rgba(23, 77, 43, 0.10);
}


.sc-applicant-apply-button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 9px;
    padding: 13px 24px;
    border-radius: 12px;
    background: #174d2b;
    border: 1px solid #174d2b;
    color: #ffffff !important;
    text-decoration: none;
    font-size: 0.78rem;
    font-weight: 850;
    letter-spacing: 0.5px;
    box-shadow: 0 9px 20px rgba(23, 77, 43, 0.18);
    transition: transform 0.2s ease, background 0.2s ease, box-shadow 0.2s ease;
}


    .sc-applicant-apply-button:hover {
        transform: translateY(-2px);
        background: #28633f;
        border-color: #28633f;
        color: #ffffff !important;
        box-shadow: 0 12px 25px rgba(23, 77, 43, 0.22);
    }


    .sc-applicant-apply-button i {
        transition: transform 0.2s ease;
    }


    .sc-applicant-apply-button:hover i {
        transform: translateX(4px);
    }


/* =========================================================
           RESPONSIVE
           ========================================================= */

@media (max-width: 760px) {

    .sc-applicant-opportunity-page {
        padding: 25px 14px 45px;
    }


    .sc-applicant-opportunity-card {
        padding: 22px;
        border-radius: 19px;
    }


    .sc-applicant-top {
        flex-direction: column;
        gap: 24px;
    }


    .sc-applicant-poster {
        width: 100%;
        min-width: 0;
        height: 350px;
    }


    .sc-applicant-introduction {
        padding: 0;
    }


    .sc-applicant-title {
        margin-top: 18px;
        font-size: 2rem;
    }


    .sc-applicant-information {
        grid-template-columns: 1fr;
        column-gap: 0;
    }
}


@media (max-width: 480px) {

    .sc-applicant-opportunity-card {
        padding: 18px;
    }


    .sc-applicant-poster {
        height: 300px;
    }


    .sc-applicant-title {
        font-size: 1.7rem;
    }


    .sc-applicant-description {
        font-size: 0.88rem;
    }


    .sc-applicant-information-item {
        padding: 15px 2px;
    }


    .sc-applicant-information-icon {
        width: 39px;
        min-width: 39px;
        height: 39px;
    }


    .sc-applicant-footer {
        justify-content: stretch;
    }


    .sc-applicant-apply-button {
        width: 100%;
    }
}

/* =========================================================
   SWIFTCARE
   VOLUNTEER APPLICATION
   CV UPLOAD
   GLASS + FOREST GREEN + LIME
   ========================================================= */

.sc-application-page {
    width: 100%;
    min-height: 100vh;

    padding: 50px 20px 70px;

    background:
        radial-gradient(
            circle at 10% 10%,
            rgba(155, 234, 32, 0.10),
            transparent 28%
        ),
        radial-gradient(
            circle at 90% 85%,
            rgba(23, 77, 43, 0.08),
            transparent 30%
        );
}


/* =========================================================
   MAIN CARD
   ========================================================= */

.sc-application-card {
    width: min(850px, 100%);

    margin: 0 auto;

    padding: 38px;

    background: rgba(255, 255, 255, 0.97);

    border: 1px solid rgba(23, 77, 43, 0.12);

    border-radius: 24px;

    box-shadow:
        0 20px 50px rgba(20, 35, 27, 0.15),
        0 5px 15px rgba(20, 35, 27, 0.07);
}


/* =========================================================
   HEADER
   ========================================================= */

.sc-application-header {
    display: flex;

    align-items: flex-start;

    gap: 18px;

    padding-bottom: 28px;

    border-bottom: 1px solid rgba(23, 77, 43, 0.10);
}

.sc-application-header-icon {
    width: 52px;
    min-width: 52px;
    height: 52px;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 15px;

    background: rgba(155, 234, 32, 0.18);

    border: 1px solid rgba(111, 174, 15, 0.22);

    color: #174d2b;

    font-size: 1.15rem;
}

.sc-application-eyebrow {
    display: block;

    margin-bottom: 6px;

    color: #6fae0f;

    font-size: 0.68rem;

    font-weight: 850;

    letter-spacing: 1.2px;
}

.sc-application-header h1 {
    margin: 0;

    color: #174d2b;

    font-size: clamp(1.8rem, 4vw, 2.5rem);

    font-weight: 850;

    line-height: 1.1;
}

.sc-application-header p {
    max-width: 650px;

    margin: 10px 0 0;

    color: #4b6253;

    font-size: 0.9rem;

    line-height: 1.7;
}


/* =========================================================
   OPPORTUNITY
   ========================================================= */

.sc-application-opportunity {
    display: flex;

    align-items: center;

    gap: 15px;

    margin-top: 28px;

    padding: 18px;

    background:
        linear-gradient(
            135deg,
            rgba(155, 234, 32, 0.13),
            rgba(155, 234, 32, 0.04)
        );

    border: 1px solid rgba(111, 174, 15, 0.18);

    border-radius: 16px;
}

.sc-application-opportunity-icon {
    width: 45px;
    min-width: 45px;
    height: 45px;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 12px;

    background: rgba(155, 234, 32, 0.20);

    color: #174d2b;

    font-size: 1rem;
}

.sc-application-opportunity-content {
    min-width: 0;
}

.sc-application-opportunity-content span {
    display: block;

    margin-bottom: 4px;

    color: #6b7f71;

    font-size: 0.65rem;

    font-weight: 850;

    letter-spacing: 0.8px;
}

.sc-application-opportunity-content h2 {
    margin: 0;

    color: #174d2b;

    font-size: 1.05rem;

    font-weight: 850;

    line-height: 1.4;
}


/* =========================================================
   SECTION
   ========================================================= */

.sc-application-section {
    margin-top: 32px;
}

.sc-application-section-heading {
    display: flex;

    align-items: flex-start;

    gap: 13px;

    margin-bottom: 20px;
}

.sc-application-section-icon {
    width: 40px;
    min-width: 40px;
    height: 40px;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 11px;

    background: rgba(155, 234, 32, 0.16);

    color: #174d2b;

    font-size: 0.9rem;
}

.sc-application-section-heading h2 {
    margin: 0;

    color: #174d2b;

    font-size: 1.05rem;

    font-weight: 850;
}

.sc-application-section-heading p {
    margin: 4px 0 0;

    color: #627568;

    font-size: 0.8rem;

    line-height: 1.6;
}


/* =========================================================
   CV UPLOAD WRAPPER
   ========================================================= */

.sc-cv-upload-wrapper {
    width: 100%;
}


/* =========================================================
   HIDDEN FILE INPUT
   ========================================================= */

.sc-cv-file-input {
    position: absolute;

    width: 1px;
    height: 1px;

    opacity: 0;

    pointer-events: none;
}


/* =========================================================
   UPLOAD AREA
   ========================================================= */

.sc-cv-upload-area {
    width: 100%;

    min-height: 230px;

    display: flex;

    flex-direction: column;

    align-items: center;

    justify-content: center;

    gap: 16px;

    padding: 35px 25px;

    box-sizing: border-box;

    cursor: pointer;

    text-align: center;

    background:
        linear-gradient(
            145deg,
            rgba(248, 251, 248, 0.95),
            rgba(241, 247, 242, 0.90)
        );

    border: 2px dashed rgba(23, 77, 43, 0.20);

    border-radius: 18px;

    transition:
        border-color 0.25s ease,
        background 0.25s ease,
        transform 0.25s ease,
        box-shadow 0.25s ease;
}

.sc-cv-upload-area:hover {
    border-color: #6fae0f;

    background:
        linear-gradient(
            145deg,
            rgba(155, 234, 32, 0.08),
            rgba(248, 251, 248, 0.98)
        );

    transform: translateY(-2px);

    box-shadow:
        0 12px 30px rgba(23, 77, 43, 0.08);
}


/* =========================================================
   DRAG OVER
   ========================================================= */

.sc-cv-upload-dragover {
    border-color: #6fae0f !important;

    background:
        linear-gradient(
            145deg,
            rgba(155, 234, 32, 0.18),
            rgba(155, 234, 32, 0.06)
        ) !important;

    transform: scale(1.01);
}


/* =========================================================
   UPLOAD ICON
   ========================================================= */

.sc-cv-upload-icon {
    width: 68px;
    height: 68px;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 20px;

    background:
        linear-gradient(
            145deg,
            rgba(155, 234, 32, 0.24),
            rgba(155, 234, 32, 0.10)
        );

    border: 1px solid rgba(111, 174, 15, 0.20);

    color: #174d2b;

    font-size: 1.65rem;

    transition:
        transform 0.25s ease,
        background 0.25s ease;
}

.sc-cv-upload-area:hover .sc-cv-upload-icon {
    transform: translateY(-4px);
}


/* =========================================================
   UPLOAD TEXT
   ========================================================= */

.sc-cv-upload-content {
    display: flex;

    flex-direction: column;

    align-items: center;

    gap: 5px;
}

.sc-cv-upload-content strong {
    color: #20352a;

    font-size: 0.98rem;

    font-weight: 850;
}

.sc-cv-upload-content span {
    color: #64776a;

    font-size: 0.78rem;
}

.sc-cv-upload-content small {
    margin-top: 5px;

    color: #89988e;

    font-size: 0.67rem;

    font-weight: 650;
}


/* =========================================================
   SELECTED
   ========================================================= */

.sc-cv-upload-selected {
    border-color: #6fae0f;

    background:
        linear-gradient(
            145deg,
            rgba(155, 234, 32, 0.10),
            rgba(248, 251, 248, 0.98)
        );
}

.sc-cv-upload-selected
.sc-cv-upload-icon {
    background: rgba(155, 234, 32, 0.22);

    color: #174d2b;
}


/* =========================================================
   FILE PREVIEW
   ========================================================= */

.sc-cv-file-preview {
    display: none;

    align-items: center;

    gap: 13px;

    margin-top: 12px;

    padding: 14px 15px;

    background: #f7faf7;

    border: 1px solid rgba(23, 77, 43, 0.12);

    border-radius: 14px;

    animation: scCvPreviewIn 0.25s ease;
}

.sc-cv-file-preview-visible {
    display: flex;
}

@keyframes scCvPreviewIn {

    from {
        opacity: 0;

        transform: translateY(-5px);
    }

    to {
        opacity: 1;

        transform: translateY(0);
    }

}


/* =========================================================
   FILE ICON
   ========================================================= */

.sc-cv-file-preview-icon {
    width: 43px;
    min-width: 43px;
    height: 43px;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 11px;

    background: rgba(155, 234, 32, 0.16);

    color: #174d2b;

    font-size: 1rem;
}


/* =========================================================
   FILE DETAILS
   ========================================================= */

.sc-cv-file-details {
    min-width: 0;

    flex: 1;

    display: flex;

    flex-direction: column;

    gap: 3px;
}

.sc-cv-file-details strong {
    overflow: hidden;

    color: #20352a;

    font-size: 0.78rem;

    font-weight: 800;

    text-overflow: ellipsis;

    white-space: nowrap;
}

.sc-cv-file-details span {
    color: #7a8b80;

    font-size: 0.67rem;

    font-weight: 650;
}


/* =========================================================
   REMOVE BUTTON
   ========================================================= */

.sc-cv-remove-button {
    width: 37px;
    height: 37px;

    display: flex;

    align-items: center;
    justify-content: center;

    flex-shrink: 0;

    border: 1px solid rgba(180, 35, 24, 0.13);

    border-radius: 10px;

    background: rgba(180, 35, 24, 0.05);

    color: #b42318;

    cursor: pointer;

    transition:
        background 0.2s ease,
        transform 0.2s ease;
}

.sc-cv-remove-button:hover {
    background: rgba(180, 35, 24, 0.10);

    transform: scale(1.04);
}


/* =========================================================
   TEXTAREA
   ========================================================= */

.sc-application-field {
    width: 100%;
}

.sc-application-label {
    display: block;

    margin-bottom: 9px;

    color: #20352a;

    font-size: 0.78rem;

    font-weight: 800;
}

.sc-application-textarea {
    width: 100%;

    min-height: 200px;

    padding: 16px 17px;

    resize: vertical;

    box-sizing: border-box;

    background: rgba(247, 250, 247, 0.95);

    border: 1px solid rgba(23, 77, 43, 0.16);

    border-radius: 14px;

    outline: none;

    color: #20352a;

    font-family: inherit;

    font-size: 0.88rem;

    line-height: 1.7;

    transition:
        border-color 0.2s ease,
        box-shadow 0.2s ease,
        background 0.2s ease;
}

.sc-application-textarea::placeholder {
    color: #9aa99f;
}

.sc-application-textarea:focus {
    background: #ffffff;

    border-color: #6fae0f;

    box-shadow:
        0 0 0 3px rgba(155, 234, 32, 0.13);
}


/* =========================================================
   FIELD FOOTER
   ========================================================= */

.sc-application-field-footer {
    display: flex;

    justify-content: space-between;

    margin-top: 7px;

    color: #7b8d81;

    font-size: 0.68rem;

    font-weight: 650;
}


/* =========================================================
   VALIDATION
   ========================================================= */

.sc-application-validation {
    display: block;

    margin-top: 7px;

    color: #b42318;

    font-size: 0.72rem;

    font-weight: 700;
}


/* =========================================================
   NOTICE
   ========================================================= */

.sc-application-notice {
    display: flex;

    align-items: flex-start;

    gap: 13px;

    margin-top: 28px;

    padding: 16px 17px;

    background: rgba(23, 77, 43, 0.045);

    border: 1px solid rgba(23, 77, 43, 0.10);

    border-radius: 14px;
}

.sc-application-notice-icon {
    color: #6fae0f;

    font-size: 1rem;
}

.sc-application-notice strong {
    display: block;

    margin-bottom: 4px;

    color: #174d2b;

    font-size: 0.78rem;

    font-weight: 850;
}

.sc-application-notice p {
    margin: 0;

    color: #52675a;

    font-size: 0.75rem;

    line-height: 1.65;
}


/* =========================================================
   FOOTER
   ========================================================= */

.sc-application-footer {
    display: flex;

    align-items: center;

    justify-content: space-between;

    gap: 15px;

    margin-top: 30px;

    padding-top: 25px;

    border-top: 1px solid rgba(23, 77, 43, 0.10);
}


/* =========================================================
   BACK BUTTON
   ========================================================= */

.sc-application-cancel-button {
    display: inline-flex;

    align-items: center;
    justify-content: center;

    gap: 8px;

    padding: 12px 18px;

    border-radius: 11px;

    background: rgba(23, 77, 43, 0.05);

    border: 1px solid rgba(23, 77, 43, 0.12);

    color: #355442 !important;

    text-decoration: none;

    font-size: 0.74rem;

    font-weight: 800;

    letter-spacing: 0.4px;

    transition:
        background 0.2s ease,
        transform 0.2s ease;
}

.sc-application-cancel-button:hover {
    background: rgba(23, 77, 43, 0.09);

    color: #174d2b !important;

    transform: translateY(-1px);
}


/* =========================================================
   SUBMIT
   ========================================================= */

.sc-application-submit-button {
    display: inline-flex;

    align-items: center;
    justify-content: center;

    gap: 9px;

    padding: 13px 22px;

    border-radius: 11px;

    background: #174d2b;

    border: 1px solid #174d2b;

    color: #ffffff !important;

    cursor: pointer;

    font-family: inherit;

    font-size: 0.74rem;

    font-weight: 850;

    letter-spacing: 0.5px;

    box-shadow:
        0 9px 20px rgba(23, 77, 43, 0.18);

    transition:
        transform 0.2s ease,
        background 0.2s ease,
        box-shadow 0.2s ease;
}

.sc-application-submit-button:hover {
    transform: translateY(-2px);

    background: #28633f;

    border-color: #28633f;

    box-shadow:
        0 12px 25px rgba(23, 77, 43, 0.22);
}


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 700px) {

    .sc-application-page {
        padding: 30px 14px 45px;
    }

    .sc-application-card {
        padding: 25px;

        border-radius: 20px;
    }

    .sc-application-header {
        gap: 13px;
    }

    .sc-application-header-icon {
        width: 45px;
        min-width: 45px;
        height: 45px;
    }

    .sc-application-header h1 {
        font-size: 1.8rem;
    }

    .sc-application-footer {
        flex-direction: column-reverse;

        align-items: stretch;
    }

    .sc-application-cancel-button,
    .sc-application-submit-button {
        width: 100%;
    }
}


@media (max-width: 480px) {

    .sc-application-page {
        padding: 20px 10px 35px;
    }

    .sc-application-card {
        padding: 19px;

        border-radius: 18px;
    }

    .sc-application-opportunity {
        padding: 14px;
    }

    .sc-application-opportunity-content h2 {
        font-size: 0.92rem;
    }

    .sc-cv-upload-area {
        min-height: 210px;

        padding: 28px 18px;
    }

    .sc-cv-upload-icon {
        width: 60px;
        height: 60px;
    }

    .sc-cv-upload-content strong {
        font-size: 0.9rem;
    }

    .sc-cv-upload-content span {
        font-size: 0.73rem;
    }

    .sc-application-textarea {
        min-height: 180px;
    }

    .sc-application-field-footer {
        flex-direction: column;

        gap: 2px;
    }
}


/* =========================================================
   SWIFTCARE
   PERSONAL DETAILS
   MATCHES EXISTING APPLICATION STYLING
   ========================================================= */

.sc-application-section-number {
    display: block;
    margin-bottom: 3px;
    color: #6fae0f;
    font-size: 0.65rem;
    font-weight: 850;
    letter-spacing: 1px;
}


/* =========================================================
   PERSONAL DETAILS GRID
   ========================================================= */

.sc-personal-details-card {
    width: 100%;
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 20px 22px;
}


/* =========================================================
   APPLICATION FIELD
   ========================================================= */

.sc-application-field {
    width: 100%;
}


/* =========================================================
   INPUT WRAPPER
   ========================================================= */

.sc-application-input-wrapper {
    position: relative;
    width: 100%;
}


    /* =========================================================
   INPUT ICON
   ========================================================= */

    .sc-application-input-wrapper > i {
        position: absolute;
        top: 50%;
        left: 15px;
        z-index: 2;
        transform: translateY(-50%);
        color: #6fae0f;
        font-size: 0.9rem;
        pointer-events: none;
    }


/* =========================================================
   INPUT
   ========================================================= */

.sc-application-input {
    width: 100%;
    height: 48px;
    padding: 0 15px 0 42px;
    box-sizing: border-box;
    background: rgba(247, 250, 247, 0.95);
    border: 1px solid rgba(23, 77, 43, 0.16);
    border-radius: 14px;
    outline: none;
    color: #20352a;
    font-family: inherit;
    font-size: 0.86rem;
    line-height: 1.4;
    transition: border-color 0.2s ease, box-shadow 0.2s ease, background 0.2s ease;
}


    /* =========================================================
   PLACEHOLDER
   ========================================================= */

    .sc-application-input::placeholder {
        color: #9aa99f;
    }


    /* =========================================================
   INPUT FOCUS
   ========================================================= */

    .sc-application-input:focus {
        background: #ffffff;
        border-color: #6fae0f;
        box-shadow: 0 0 0 3px rgba(155, 234, 32, 0.13);
    }


/* =========================================================
   LABEL
   ========================================================= */

.sc-application-label {
    display: block;
    margin-bottom: 9px;
    color: #20352a;
    font-size: 0.78rem;
    font-weight: 800;
}


/* =========================================================
   DATE OF BIRTH
   ========================================================= */

.sc-personal-date-field {
    grid-column: span 2;
    width: calc(50% - 11px);
}


/* =========================================================
   DATE INPUT
   ========================================================= */

.sc-application-input[type="date"] {
    color: #20352a;
    cursor: pointer;
}


/* =========================================================
   VALIDATION
   ========================================================= */

.sc-application-validation {
    display: block;
    margin-top: 7px;
    color: #b42318;
    font-size: 0.72rem;
    font-weight: 700;
}


/* =========================================================
   COVER MESSAGE WRAPPER
   ========================================================= */

.sc-application-textarea-wrapper {
    position: relative;
    width: 100%;
}


    /* =========================================================
   COVER MESSAGE ICON
   ========================================================= */

    .sc-application-textarea-wrapper > i {
        position: absolute;
        top: 17px;
        left: 16px;
        z-index: 2;
        color: #6fae0f;
        font-size: 0.9rem;
        pointer-events: none;
    }


    /* =========================================================
   COVER MESSAGE TEXTAREA
   ========================================================= */

    .sc-application-textarea-wrapper .sc-application-textarea {
        padding-left: 43px;
    }


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 700px) {

    .sc-personal-details-card {
        grid-template-columns: 1fr;
        gap: 18px;
    }

    .sc-personal-date-field {
        grid-column: span 1;
        width: 100%;
    }
}


@media (max-width: 480px) {

    .sc-personal-details-card {
        gap: 16px;
    }

    .sc-application-input {
        height: 46px;
        font-size: 0.82rem;
    }
}

/* =========================================================
   SWIFTCARE
   APPLICATION QUESTIONS
   ========================================================= */
.sc-question-card {
    position: relative;
    overflow: hidden;
}


/* =========================================================
   HEADER
   ========================================================= */

.sc-question-section-icon {
    background: rgba(111, 174, 15, 0.12);
    color: #6fae0f;
}


.sc-question-header-content {
    flex: 1;
}


.sc-question-count-badge {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 8px 13px;
    border-radius: 999px;
    background: rgba(111, 174, 15, 0.10);
    border: 1px solid rgba(111, 174, 15, 0.20);
    color: #527d0b;
    font-size: 0.72rem;
    font-weight: 800;
    white-space: nowrap;
}

    .sc-question-count-badge i {
        font-size: 0.78rem;
    }


/* =========================================================
   INFORMATION PANEL
   ========================================================= */

.sc-question-info {
    display: flex;
    align-items: flex-start;
    gap: 14px;
    margin-top: 22px;
    padding: 16px 18px;
    border-radius: 16px;
    background: rgba(111, 174, 15, 0.07);
    border: 1px solid rgba(111, 174, 15, 0.15);
}


.sc-question-info-icon {
    flex: 0 0 38px;
    width: 38px;
    height: 38px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 12px;
    background: rgba(111, 174, 15, 0.14);
    color: #6fae0f;
}


    .sc-question-info-icon i {
        font-size: 1rem;
    }


.sc-question-info strong {
    display: block;
    margin-bottom: 4px;
    color: #20352a;
    font-size: 0.82rem;
    font-weight: 850;
}


.sc-question-info p {
    margin: 0;
    color: #66776d;
    font-size: 0.76rem;
    line-height: 1.6;
}


/* =========================================================
   TOOLBAR
   ========================================================= */

.sc-question-toolbar {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
    gap: 16px;
    margin-top: 20px;
}


.sc-question-filter-group,
.sc-question-search-group {
    min-width: 0;
}


.sc-question-toolbar label {
    display: block;
    margin-bottom: 8px;
    color: #20352a;
    font-size: 0.72rem;
    font-weight: 800;
}


.sc-question-select-wrapper,
.sc-question-search-wrapper {
    position: relative;
}


    .sc-question-select-wrapper > i,
    .sc-question-search-wrapper > i {
        position: absolute;
        top: 50%;
        left: 14px;
        z-index: 2;
        transform: translateY(-50%);
        color: #6fae0f;
        font-size: 0.82rem;
        pointer-events: none;
    }


    .sc-question-filter,
    .sc-question-search-wrapper input {
        width: 100%;
        height: 46px;
        box-sizing: border-box;
        border: 1px solid rgba(23, 77, 43, 0.14);
        border-radius: 13px;
        background: rgba(247, 250, 247, 0.96);
        color: #20352a;
        outline: none;
        font-family: inherit;
        font-size: 0.76rem;
        transition: border-color 0.2s ease, box-shadow 0.2s ease, background 0.2s ease;
    }


.sc-question-filter {
    padding: 0 13px 0 39px;
    cursor: pointer;
}


.sc-question-search-wrapper input {
    padding: 0 14px 0 39px;
}


    .sc-question-filter:focus,
    .sc-question-search-wrapper input:focus {
        background: #ffffff;
        border-color: #6fae0f;
        box-shadow: 0 0 0 3px rgba(155, 234, 32, 0.12);
    }


/* =========================================================
   SELECTED SUMMARY
   ========================================================= */

.sc-selected-question-summary {
    display: flex;
    align-items: center;
    gap: 13px;
    margin-top: 18px;
    padding: 14px 16px;
    border-radius: 15px;
    background: rgba(32, 53, 42, 0.035);
    border: 1px solid rgba(32, 53, 42, 0.08);
}


.sc-selected-question-summary-icon {
    flex: 0 0 35px;
    width: 35px;
    height: 35px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 11px;
    background: rgba(32, 53, 42, 0.08);
    color: #829188;
}


    .sc-selected-question-summary-icon.active {
        background: rgba(111, 174, 15, 0.14);
        color: #6fae0f;
    }


.sc-selected-question-summary strong {
    display: block;
    color: #20352a;
    font-size: 0.76rem;
    font-weight: 850;
}


.sc-selected-question-summary span {
    display: block;
    margin-top: 3px;
    color: #77857d;
    font-size: 0.7rem;
}


/* =========================================================
   QUESTION LIST
   ========================================================= */

.sc-question-list {
    display: flex;
    flex-direction: column;
    gap: 10px;
    margin-top: 18px;
}


/* =========================================================
   QUESTION ITEM
   ========================================================= */

.sc-question-item {
    position: relative;
    display: flex;
    align-items: flex-start;
    gap: 13px;
    width: 100%;
    box-sizing: border-box;
    padding: 15px 48px 15px 15px;
    border: 1px solid rgba(23, 77, 43, 0.10);
    border-radius: 15px;
    background: #ffffff;
    cursor: pointer;
    transition: border-color 0.2s ease, background 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
}


    .sc-question-item:hover {
        border-color: rgba(111, 174, 15, 0.35);
        background: rgba(250, 252, 249, 0.98);
        box-shadow: 0 7px 20px rgba(23, 77, 43, 0.06);
        transform: translateY(-1px);
    }


    .sc-question-item.selected {
        border-color: rgba(111, 174, 15, 0.55);
        background: rgba(111, 174, 15, 0.055);
        box-shadow: 0 7px 22px rgba(111, 174, 15, 0.08);
    }


    /* =========================================================
   PERFECT CATEGORY + AREA MATCH
   ========================================================= */

    .sc-question-item.sc-question-perfect-match {
        border-left: 4px solid #6fae0f;
    }


        .sc-question-item.sc-question-perfect-match::after {
            content: "BEST MATCH";
            position: absolute;
            top: 10px;
            right: 43px;
            padding: 4px 7px;
            border-radius: 999px;
            background: rgba(111, 174, 15, 0.10);
            color: #5b8a0b;
            font-size: 0.55rem;
            font-weight: 900;
            letter-spacing: 0.5px;
        }


/* =========================================================
   CHECKBOX
   ========================================================= */

.sc-question-checkbox {
    position: absolute;
    opacity: 0;
    pointer-events: none;
}


.sc-question-checkmark {
    flex: 0 0 24px;
    width: 24px;
    height: 24px;
    margin-top: 1px;
    display: flex;
    align-items: center;
    justify-content: center;
    border: 1.5px solid rgba(23, 77, 43, 0.20);
    border-radius: 8px;
    background: #ffffff;
    color: transparent;
    transition: background 0.2s ease, border-color 0.2s ease, color 0.2s ease, transform 0.2s ease;
}


.sc-question-checkbox:checked ~ .sc-question-checkmark {
    background: #6fae0f;
    border-color: #6fae0f;
    color: #ffffff;
    transform: scale(1.04);
}


.sc-question-checkmark i {
    font-size: 0.75rem;
    font-weight: 900;
}


/* =========================================================
   QUESTION CONTENT
   ========================================================= */

.sc-question-content {
    min-width: 0;
    flex: 1;
}


.sc-question-text {
    display: block;
    color: #20352a;
    font-size: 0.79rem;
    font-weight: 750;
    line-height: 1.55;
}


.sc-question-meta {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 7px;
    margin-top: 9px;
}


.sc-question-type,
.sc-question-required,
.sc-question-optional,
.sc-question-source {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    padding: 4px 7px;
    border-radius: 999px;
    font-size: 0.59rem;
    font-weight: 800;
}


.sc-question-type {
    background: rgba(32, 53, 42, 0.055);
    color: #637169;
}


.sc-question-required {
    background: rgba(180, 35, 24, 0.07);
    color: #a52a21;
}


.sc-question-optional {
    background: rgba(32, 53, 42, 0.055);
    color: #758179;
}


.sc-question-source-general {
    background: rgba(94, 112, 101, 0.08);
    color: #65756b;
}


.sc-question-source-category {
    background: rgba(111, 174, 15, 0.09);
    color: #648d18;
}


.sc-question-source-area {
    background: rgba(34, 115, 140, 0.08);
    color: #39798c;
}


.sc-question-source-specific {
    background: rgba(111, 174, 15, 0.16);
    color: #527d0b;
}


.sc-question-meta i {
    font-size: 0.59rem;
}


/* =========================================================
   RIGHT SELECTION INDICATOR
   ========================================================= */

.sc-question-selection-indicator {
    position: absolute;
    top: 50%;
    right: 15px;
    width: 27px;
    height: 27px;
    display: flex;
    align-items: center;
    justify-content: center;
    transform: translateY(-50%);
    border-radius: 50%;
    background: rgba(32, 53, 42, 0.055);
    color: #849088;
    transition: background 0.2s ease, color 0.2s ease, transform 0.2s ease;
}


    .sc-question-selection-indicator i {
        font-size: 0.7rem;
    }


.sc-question-item.selected
.sc-question-selection-indicator {
    background: #6fae0f;
    color: #ffffff;
    transform: translateY(-50%) rotate(45deg);
}


/* =========================================================
   EMPTY STATE
   ========================================================= */

.sc-question-empty {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 42px 20px;
    text-align: center;
    border: 1px dashed rgba(23, 77, 43, 0.16);
    border-radius: 16px;
    background: rgba(32, 53, 42, 0.025);
}


.sc-question-empty-filtered {
    margin-top: 18px;
}


.sc-question-empty-icon {
    width: 48px;
    height: 48px;
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 12px;
    border-radius: 15px;
    background: rgba(111, 174, 15, 0.10);
    color: #6fae0f;
}


    .sc-question-empty-icon i {
        font-size: 1.1rem;
    }


.sc-question-empty h3 {
    margin: 0;
    color: #20352a;
    font-size: 0.84rem;
    font-weight: 850;
}


.sc-question-empty p {
    max-width: 430px;
    margin: 7px 0 0;
    color: #77857d;
    font-size: 0.72rem;
    line-height: 1.5;
}


/* =========================================================
   FOOTER
   ========================================================= */

.sc-question-footer {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 15px;
    margin-top: 18px;
    padding-top: 16px;
    border-top: 1px solid rgba(23, 77, 43, 0.09);
}


.sc-question-footer-left {
    display: flex;
    align-items: center;
    gap: 8px;
    color: #77857d;
    font-size: 0.68rem;
}


    .sc-question-footer-left i {
        color: #6fae0f;
        font-size: 0.8rem;
    }


.sc-question-clear-button {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    border: 0;
    padding: 7px 10px;
    border-radius: 9px;
    background: transparent;
    color: #77857d;
    font-family: inherit;
    font-size: 0.66rem;
    font-weight: 800;
    cursor: pointer;
    transition: background 0.2s ease, color 0.2s ease;
}


    .sc-question-clear-button:hover {
        background: rgba(180, 35, 24, 0.06);
        color: #a52a21;
    }


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 700px) {

    .sc-question-toolbar {
        grid-template-columns: 1fr;
        gap: 13px;
    }


    .sc-question-count-badge {
        margin-left: auto;
    }


    .sc-question-info {
        padding: 14px;
    }


    .sc-question-item {
        padding: 14px 43px 14px 13px;
    }


    .sc-question-meta {
        gap: 5px;
    }


    .sc-question-perfect-match::after {
        display: none;
    }


    .sc-question-footer {
        align-items: flex-start;
        flex-direction: column;
    }


    .sc-question-clear-button {
        padding-left: 0;
    }
}


@media (max-width: 480px) {

    .sc-question-card .op-card-header {
        align-items: flex-start;
    }


    .sc-question-count-badge {
        padding: 6px 9px;
        font-size: 0.62rem;
    }


    .sc-question-info p {
        font-size: 0.7rem;
    }


    .sc-question-text {
        font-size: 0.75rem;
    }


    .sc-question-type,
    .sc-question-required,
    .sc-question-optional,
    .sc-question-source {
        font-size: 0.55rem;
    }


    .sc-question-selection-indicator {
        right: 11px;
        width: 24px;
        height: 24px;
    }
}

