}
/* =========================================================
       SWIFTCARE APPLICATION - TWO STEP ADDITIONS
       ========================================================= */


/* =========================================================
       PROGRESS
       ========================================================= */

.sc-application-progress {
    display: flex;
    align-items: center;
    width: 100%;
    padding: 22px 28px;
    margin: 0 0 30px;
    background: #f7faf8;
    border: 1px solid #e4ebe7;
    border-radius: 18px;
    box-sizing: border-box;
}

.sc-application-progress-step {
    display: flex;
    align-items: center;
    gap: 12px;
    min-width: 220px;
}

.sc-progress-number {
    width: 44px;
    height: 44px;
    min-width: 44px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #e8efeb;
    color: #53665d;
    font-size: 13px;
    font-weight: 800;
    transition: all .25s ease;
}

.sc-progress-text {
    display: flex;
    flex-direction: column;
    gap: 3px;
}

    .sc-progress-text strong {
        color: #173329;
        font-size: 14px;
        font-weight: 800;
    }

    .sc-progress-text span {
        color: #64766e;
        font-size: 12px;
    }

.sc-application-progress-step.active .sc-progress-number {
    background: #176b3a;
    color: #ffffff;
    box-shadow: 0 8px 20px rgba(23, 107, 58, .20);
}

.sc-application-progress-step.completed .sc-progress-number {
    background: #b8ff00;
    color: #173329;
}

.sc-application-progress-step.active .sc-progress-text strong {
    color: #176b3a;
}

.sc-application-progress-step.completed .sc-progress-text strong {
    color: #176b3a;
}

.sc-progress-line {
    height: 2px;
    flex: 1;
    margin: 0 20px;
    background: #dce5e0;
}


/* =========================================================
       STEP CONTAINER
       ========================================================= */

.sc-application-step {
    display: none;
}

.sc-application-step-active {
    display: block;
    animation: scApplicationStepIn .35s ease;
}

.sc-application-step-hidden {
    display: none;
}

@keyframes scApplicationStepIn {

    from {
        opacity: 0;
        transform: translateX(12px);
    }

    to {
        opacity: 1;
        transform: translateX(0);
    }
}


/* =========================================================
       NEXT BUTTON
       ========================================================= */

.sc-application-next-button {
    min-height: 54px;
    padding: 0 28px;
    border: 0;
    border-radius: 14px;
    background: #176b3a;
    color: #ffffff;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 12px;
    font-size: 13px;
    font-weight: 800;
    letter-spacing: .6px;
    cursor: pointer;
    transition: transform .2s ease, background .2s ease, box-shadow .2s ease;
}

    .sc-application-next-button:hover {
        background: #0f542c;
        transform: translateY(-2px);
        box-shadow: 0 10px 22px rgba(23, 107, 58, .18);
    }

    .sc-application-next-button i {
        font-size: 16px;
    }


/* =========================================================
       STEP 2 INTRO
       ========================================================= */

.sc-questions-intro-card {
    display: flex;
    align-items: flex-start;
    gap: 18px;
    padding: 26px;
    margin-bottom: 24px;
    background: linear-gradient( 135deg, #f4faf6, #ffffff );
    border: 1px solid #dfeae3;
    border-radius: 20px;
}

.sc-questions-intro-icon {
    width: 56px;
    height: 56px;
    min-width: 56px;
    border-radius: 16px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #176b3a;
    color: #ffffff;
    font-size: 23px;
    box-shadow: 0 10px 22px rgba(23, 107, 58, .15);
}

.sc-questions-intro-card > div:last-child {
    flex: 1;
}

    .sc-questions-intro-card > div:last-child > span {
        display: block;
        margin-bottom: 5px;
        color: #176b3a;
        font-size: 11px;
        font-weight: 900;
        letter-spacing: 1.4px;
    }

.sc-questions-intro-card h2 {
    margin: 0 0 7px;
    color: #173329;
    font-size: 24px;
    font-weight: 850;
}

.sc-questions-intro-card p {
    margin: 0;
    color: #53665d;
    font-size: 14px;
    line-height: 1.7;
}


/* =========================================================
       QUESTIONS CONTAINER
       ========================================================= */

.sc-application-questions-container {
    display: flex;
    flex-direction: column;
    gap: 18px;
}


/* =========================================================
       QUESTION CARD
       ========================================================= */

.sc-application-question-card {
    display: flex;
    gap: 20px;
    padding: 25px;
    background: #ffffff;
    border: 1px solid #e1e9e4;
    border-radius: 20px;
    box-shadow: 0 7px 24px rgba(21, 58, 40, .055);
    transition: border-color .2s ease, box-shadow .2s ease, transform .2s ease;
}

    .sc-application-question-card:hover {
        border-color: #c9d9cf;
        box-shadow: 0 12px 30px rgba(21, 58, 40, .08);
        transform: translateY(-1px);
    }


/* =========================================================
       QUESTION NUMBER
       ========================================================= */

.sc-application-question-number {
    width: 46px;
    height: 46px;
    min-width: 46px;
    border-radius: 14px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #edf6f0;
    color: #176b3a;
    font-size: 13px;
    font-weight: 900;
}


/* =========================================================
       QUESTION BODY
       ========================================================= */

.sc-application-question-body {
    flex: 1;
    min-width: 0;
}

.sc-application-question-header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 20px;
    margin-bottom: 20px;
}

.sc-application-question-label {
    display: block;
    margin-bottom: 6px;
    color: #176b3a;
    font-size: 10px;
    font-weight: 900;
    letter-spacing: 1.3px;
}

.sc-application-question-header h3 {
    margin: 0;
    color: #173329;
    font-size: 17px;
    line-height: 1.55;
    font-weight: 750;
}

.sc-application-question-badges {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    flex-wrap: wrap;
    gap: 7px;
}

.sc-question-required-badge,
.sc-question-optional-badge,
.sc-question-type-badge {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 7px 10px;
    border-radius: 999px;
    font-size: 10px;
    font-weight: 800;
    white-space: nowrap;
}

.sc-question-required-badge {
    background: #eff8df;
    color: #4c6900;
    border: 1px solid #d9edaf;
}

.sc-question-optional-badge {
    background: #f3f5f4;
    color: #596a63;
    border: 1px solid #e2e7e4;
}

.sc-question-type-badge {
    background: #edf5f0;
    color: #176b3a;
    border: 1px solid #dce9e1;
}


/* =========================================================
       QUESTION ANSWER INPUT
       ========================================================= */

.sc-question-answer-wrapper {
    position: relative;
    display: flex;
    align-items: center;
    width: 100%;
}

    .sc-question-answer-wrapper > i {
        position: absolute;
        left: 17px;
        top: 50%;
        transform: translateY(-50%);
        color: #176b3a;
        font-size: 17px;
        z-index: 2;
    }

.sc-question-answer-input {
    width: 100%;
    min-height: 54px;
    padding: 0 17px 0 48px;
    border: 1px solid #dce6e0;
    border-radius: 13px;
    background: #fbfdfc;
    color: #173329;
    font-size: 14px;
    outline: none;
    transition: border-color .2s ease, box-shadow .2s ease, background .2s ease;
    box-sizing: border-box;
}

    .sc-question-answer-input::placeholder {
        color: #82918a;
    }

    .sc-question-answer-input:focus {
        background: #ffffff;
        border-color: #176b3a;
        box-shadow: 0 0 0 4px rgba(23, 107, 58, .08);
    }


/* =========================================================
       LONG ANSWER
       ========================================================= */

.sc-question-answer-textarea-wrapper {
    display: block;
}

    .sc-question-answer-textarea-wrapper > i {
        top: 22px;
        transform: none;
    }

.sc-question-answer-textarea {
    width: 100%;
    min-height: 150px;
    padding: 17px 17px 42px 48px;
    border: 1px solid #dce6e0;
    border-radius: 13px;
    background: #fbfdfc;
    color: #173329;
    font-family: inherit;
    font-size: 14px;
    line-height: 1.7;
    resize: vertical;
    outline: none;
    box-sizing: border-box;
    transition: border-color .2s ease, box-shadow .2s ease, background .2s ease;
}

    .sc-question-answer-textarea::placeholder {
        color: #82918a;
    }

    .sc-question-answer-textarea:focus {
        background: #ffffff;
        border-color: #176b3a;
        box-shadow: 0 0 0 4px rgba(23, 107, 58, .08);
    }

.sc-question-answer-footer {
    position: absolute;
    left: 48px;
    right: 15px;
    bottom: 12px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    color: #718079;
    font-size: 11px;
}


/* =========================================================
       YES / NO
       ========================================================= */

.sc-question-yes-no {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 12px;
}

.sc-question-choice {
    position: relative;
    display: block;
    cursor: pointer;
}

    .sc-question-choice input {
        position: absolute;
        opacity: 0;
        pointer-events: none;
    }

.sc-question-choice-box {
    min-height: 64px;
    padding: 0 18px;
    display: flex;
    align-items: center;
    gap: 12px;
    border: 1px solid #dce6e0;
    border-radius: 14px;
    background: #fbfdfc;
    color: #304b3f;
    font-size: 14px;
    font-weight: 750;
    transition: border-color .2s ease, background .2s ease, box-shadow .2s ease, transform .2s ease;
    box-sizing: border-box;
}

    .sc-question-choice-box:hover {
        border-color: #aac4b4;
        background: #f7fbf8;
    }

.sc-question-choice-icon {
    width: 35px;
    height: 35px;
    border-radius: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #edf5f0;
    color: #176b3a;
    font-size: 16px;
}

.sc-question-choice input:checked + .sc-question-choice-box {
    background: #f1f9e4;
    border-color: #9ecb36;
    color: #173329;
    box-shadow: 0 6px 18px rgba(23, 107, 58, .08);
}

    .sc-question-choice input:checked + .sc-question-choice-box
    .sc-question-choice-icon {
        background: #b8ff00;
        color: #173329;
    }


/* =========================================================
       NO QUESTIONS
       ========================================================= */

.sc-no-application-questions {
    display: flex;
    align-items: center;
    gap: 18px;
    padding: 26px;
    border: 1px dashed #cad8d0;
    border-radius: 18px;
    background: #f9fbfa;
}

.sc-no-questions-icon {
    width: 52px;
    height: 52px;
    min-width: 52px;
    border-radius: 15px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #edf5f0;
    color: #176b3a;
    font-size: 22px;
}

.sc-no-application-questions h3 {
    margin: 0 0 5px;
    color: #173329;
    font-size: 16px;
}

.sc-no-application-questions p {
    margin: 0;
    color: #64766e;
    font-size: 13px;
}


/* =========================================================
       FINAL NOTICE
       ========================================================= */

.sc-final-application-notice {
    display: flex;
    align-items: flex-start;
    gap: 15px;
    margin-top: 24px;
    padding: 20px;
    border: 1px solid #dce9e1;
    border-radius: 16px;
    background: #f4faf6;
}

.sc-final-application-notice-icon {
    width: 40px;
    height: 40px;
    min-width: 40px;
    border-radius: 11px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #b8ff00;
    color: #173329;
    font-size: 18px;
}

.sc-final-application-notice strong {
    display: block;
    margin-bottom: 4px;
    color: #173329;
    font-size: 14px;
    font-weight: 850;
}

.sc-final-application-notice p {
    margin: 0;
    color: #53665d;
    font-size: 13px;
    line-height: 1.65;
}


/* =========================================================
       STEP TWO FOOTER
       ========================================================= */

.sc-step-two-footer {
    margin-top: 30px;
}


/* =========================================================
       RESPONSIVE
       ========================================================= */

@media (max-width: 768px) {

    .sc-application-progress {
        padding: 18px;
    }

    .sc-application-progress-step {
        min-width: 0;
    }

    .sc-progress-text span {
        display: none;
    }

    .sc-progress-line {
        margin: 0 10px;
    }

    .sc-application-question-card {
        padding: 20px;
        gap: 14px;
    }

    .sc-application-question-header {
        flex-direction: column;
        gap: 12px;
    }

    .sc-application-question-badges {
        justify-content: flex-start;
    }

    .sc-question-yes-no {
        grid-template-columns: 1fr;
    }
}


@media (max-width: 560px) {

    .sc-application-progress {
        padding: 15px;
    }

    .sc-progress-number {
        width: 38px;
        height: 38px;
        min-width: 38px;
        font-size: 11px;
    }

    .sc-progress-text strong {
        font-size: 12px;
    }

    .sc-progress-line {
        margin: 0 7px;
    }

    .sc-questions-intro-card {
        padding: 20px;
        gap: 13px;
    }

    .sc-questions-intro-icon {
        width: 45px;
        height: 45px;
        min-width: 45px;
        border-radius: 13px;
        font-size: 18px;
    }

    .sc-questions-intro-card h2 {
        font-size: 20px;
    }

    .sc-application-question-card {
        flex-direction: column;
    }

    .sc-application-question-number {
        width: 40px;
        height: 40px;
        min-width: 40px;
    }

    .sc-application-question-header h3 {
        font-size: 15px;
    }

    .sc-question-type-badge,
    .sc-question-required-badge,
    .sc-question-optional-badge {
        font-size: 9px;
        padding: 6px 8px;
    }
}


/* =========================================================
       ACCESSIBILITY / VALIDATION
       ========================================================= */

.sc-question-answer-input:invalid:focus,
.sc-question-answer-textarea:invalid:focus {
    border-color: #c66;
    box-shadow: 0 0 0 4px rgba(180, 60, 60, .08);
}


/* =========================================================
   APPLY PAGE — VISIBLE FULL PAGE BACKGROUND
   ========================================================= */
.sc-application-background {
    position: fixed;
    inset: 0;
    z-index: -1;
    pointer-events: none;
    overflow: hidden;
    background: linear-gradient( 135deg, #edf7f0 0%, #f8fbf8 45%, #e8f4eb 100% );
}


/* CLEAR GEOMETRIC PATTERN */

.sc-application-hero-pattern {
    position: absolute;
    inset: 0;
    pointer-events: none;
    opacity: 0.75;
    background-image: linear-gradient( 135deg, rgba(255, 255, 255, 0.65) 25%, transparent 25% ), linear-gradient( 315deg, rgba(23, 69, 44, 0.075) 25%, transparent 25% );
    background-size: 80px 80px;
}


/* GLOW 1 */

.sc-application-hero-glow {
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
    filter: blur(5px);
}

.sc-application-hero-glow-one {
    width: 420px;
    height: 420px;
    right: -150px;
    top: -180px;
    background: rgba(183, 227, 63, 0.28);
}


/* GLOW 2 */

.sc-application-hero-glow-two {
    width: 350px;
    height: 350px;
    left: -150px;
    bottom: -180px;
    background: rgba(255, 255, 255, 0.75);
}


/* =========================================================
   OPPORTUNITY DETAILS — VISIBLE FULL PAGE BACKGROUND
   ========================================================= */

.sc-op-details-background {
    position: fixed;
    inset: 0;
    z-index: -1;
    pointer-events: none;
    overflow: hidden;
    background: linear-gradient( 135deg, #edf7f0 0%, #f9fcf9 48%, #e7f3ea 100% );
}


/* CLEAR GEOMETRIC PATTERN */

.sc-op-details-hero-pattern {
    position: absolute;
    inset: 0;
    pointer-events: none;
    opacity: 0.75;
    background-image: linear-gradient( 135deg, rgba(255, 255, 255, 0.65) 25%, transparent 25% ), linear-gradient( 315deg, rgba(23, 69, 44, 0.075) 25%, transparent 25% );
    background-size: 80px 80px;
}


/* TOP RIGHT LIME GLOW */

.sc-op-details-hero-glow {
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
    filter: blur(5px);
}

.sc-op-details-hero-glow-one {
    width: 420px;
    height: 420px;
    right: -150px;
    top: -180px;
    background: rgba(183, 227, 63, 0.28);
}


/* BOTTOM LEFT WHITE GLOW */

.sc-op-details-hero-glow-two {
    width: 350px;
    height: 350px;
    left: -150px;
    bottom: -180px;
    background: rgba(255, 255, 255, 0.75);
}


/* =========================================================
   KEEP CARDS ABOVE BACKGROUND
   ========================================================= */

.sc-application-page,
.sc-opportunity-details-page {
    position: relative;
    isolation: isolate;
}

    .sc-application-page > *:not(.sc-application-background),
    .sc-opportunity-details-page > *:not(.sc-op-details-background) {
        position: relative;
        z-index: 1;
    }

/* =========================================================
   SWIFTCARE - APPLICATION SUBMITTED PAGE
   ========================================================= */

.sc-application-submitted-page {
    position: relative;
    isolation: isolate;
    min-height: calc(100vh - 80px);
    padding: 55px 20px 70px;
    display: flex;
    align-items: center;
    justify-content: center;
}


/* =========================================================
   BACKGROUND
   ========================================================= */

.sc-application-submitted-background {
    position: fixed;
    inset: 0;
    z-index: -1;
    pointer-events: none;
    overflow: hidden;
    background: linear-gradient( 135deg, #edf7f0 0%, #f9fcf9 48%, #e7f3ea 100% );
}

.sc-application-submitted-pattern {
    position: absolute;
    inset: 0;
    opacity: .7;
    background-image: linear-gradient( 135deg, rgba(255,255,255,.7) 25%, transparent 25% ), linear-gradient( 315deg, rgba(23,69,44,.06) 25%, transparent 25% );
    background-size: 80px 80px;
}

.sc-application-submitted-glow {
    position: absolute;
    border-radius: 50%;
    filter: blur(8px);
}

.sc-application-submitted-glow-one {
    width: 450px;
    height: 450px;
    right: -170px;
    top: -190px;
    background: rgba(183,227,63,.25);
}

.sc-application-submitted-glow-two {
    width: 400px;
    height: 400px;
    left: -190px;
    bottom: -210px;
    background: rgba(255,255,255,.8);
}


/* =========================================================
   CONTAINER
   ========================================================= */

.sc-application-submitted-container {
    width: 100%;
    max-width: 900px;
    position: relative;
    z-index: 1;
}


/* =========================================================
   MAIN CARD
   ========================================================= */

.sc-application-submitted-card {
    background: rgba(255,255,255,.96);
    border: 1px solid rgba(23,107,58,.12);
    border-radius: 28px;
    padding: 55px 60px 35px;
    box-shadow: 0 25px 70px rgba(23,69,44,.12), 0 5px 20px rgba(23,69,44,.06);
    text-align: center;
}


/* =========================================================
   SUCCESS ICON
   ========================================================= */

.sc-application-submitted-icon-wrapper {
    display: flex;
    justify-content: center;
    margin-bottom: 25px;
}

.sc-application-submitted-icon {
    width: 90px;
    height: 90px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    background: linear-gradient( 135deg, #176b3a, #24934f );
    color: white;
    font-size: 45px;
    box-shadow: 0 12px 30px rgba(23,107,58,.25);
}

    .sc-application-submitted-icon::after {
        content: "";
        position: absolute;
        width: 112px;
        height: 112px;
        border-radius: 50%;
        border: 1px solid rgba(23,107,58,.12);
    }


/* =========================================================
   HEADING
   ========================================================= */

.sc-application-submitted-heading {
    max-width: 680px;
    margin: 0 auto 32px;
}

.sc-application-submitted-eyebrow {
    display: inline-block;
    margin-bottom: 10px;
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 2px;
    color: #176b3a;
}

.sc-application-submitted-heading h1 {
    margin: 0 0 14px;
    color: #123d28;
    font-size: clamp(30px, 4vw, 42px);
    line-height: 1.15;
    font-weight: 800;
}

.sc-application-submitted-heading p {
    margin: 0;
    color: #4d6255;
    font-size: 16px;
    line-height: 1.7;
}


/* =========================================================
   REFERENCE
   ========================================================= */

.sc-application-submitted-reference {
    display: flex;
    align-items: center;
    gap: 16px;
    padding: 17px 20px;
    margin-bottom: 25px;
    border-radius: 16px;
    background: #f1f8f3;
    border: 1px solid #dcecdf;
    text-align: left;
}

.sc-application-submitted-reference-icon {
    width: 48px;
    height: 48px;
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 12px;
    background: #176b3a;
    color: white;
    font-size: 21px;
}

.sc-application-submitted-reference-content {
    display: flex;
    flex-direction: column;
    gap: 3px;
}

    .sc-application-submitted-reference-content span {
        color: #668071;
        font-size: 11px;
        font-weight: 800;
        letter-spacing: 1.2px;
    }

    .sc-application-submitted-reference-content strong {
        color: #123d28;
        font-size: 18px;
        letter-spacing: .5px;
    }


/* =========================================================
   DETAILS
   ========================================================= */

.sc-application-submitted-details {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 14px;
    margin-bottom: 25px;
}

.sc-application-submitted-detail {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 17px;
    border-radius: 15px;
    background: #fafcfb;
    border: 1px solid #e5eee8;
    text-align: left;
}

.sc-application-submitted-detail-icon {
    width: 40px;
    height: 40px;
    flex-shrink: 0;
    display: flex;
