.sc-track-application-card {
    position: relative;
    overflow: hidden;
    padding: 22px 23px;
    background: rgba(255, 255, 255, 0.96);
    border: 1px solid #dce9df;
    border-radius: 17px;
    box-shadow: 0 8px 26px rgba(23, 69, 44, 0.065);
    transition: transform 0.22s ease, box-shadow 0.22s ease, border-color 0.22s ease;
}

    .sc-track-application-card::before {
        content: "";
        position: absolute;
        top: 0;
        left: 0;
        bottom: 0;
        width: 4px;
        background: #176b3a;
        opacity: 0;
        transition: opacity 0.2s ease;
    }

    .sc-track-application-card:hover {
        transform: translateY(-2px);
        border-color: #cbded1;
        box-shadow: 0 14px 32px rgba(23, 69, 44, 0.1);
    }

        .sc-track-application-card:hover::before {
            opacity: 1;
        }


/* ============================================================
   CARD TOP
   ============================================================ */

.sc-track-card-top {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 25px;
}


/* ============================================================
   APPLICATION MAIN
   ============================================================ */

.sc-track-application-main {
    display: flex;
    align-items: center;
    min-width: 0;
    gap: 15px;
}

.sc-track-application-icon {
    width: 53px;
    height: 53px;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    background: linear-gradient( 145deg, #edf8f0, #e2f2e7 );
    border: 1px solid #d7e9dc;
    color: #176b3a;
    border-radius: 14px;
    font-size: 21px;
}

.sc-track-application-info {
    min-width: 0;
}

.sc-track-application-label {
    display: block;
    margin-bottom: 5px;
    color: #7a8982;
    font-size: 9px;
    font-weight: 850;
    letter-spacing: 1.3px;
}

.sc-track-application-info h3 {
    margin: 0;
    overflow: hidden;
    color: #173329;
    font-size: 18px;
    line-height: 1.35;
    font-weight: 800;
    text-overflow: ellipsis;
    white-space: nowrap;
}


/* ============================================================
   STATUS
   ============================================================ */

.sc-track-status {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 7px;
    flex-shrink: 0;
    padding: 9px 13px;
    border-radius: 9px;
    font-size: 11px;
    font-weight: 850;
    white-space: nowrap;
}

    .sc-track-status i {
        font-size: 13px;
    }

.sc-track-status-pending {
    background: #fff5d8;
    border: 1px solid #f2df9e;
    color: #7c5d00;
}

.sc-track-status-approved {
    background: #e7f6eb;
    border: 1px solid #c9e6d1;
    color: #176b3a;
}

.sc-track-status-rejected {
    background: #fbeaea;
    border: 1px solid #efcccc;
    color: #a33131;
}

.sc-track-status-default {
    background: #edf1ef;
    border: 1px solid #dce3df;
    color: #53665d;
}


/* ============================================================
   DIVIDER
   ============================================================ */

.sc-track-divider {
    height: 1px;
    margin: 18px 0;
    background: #e8eee9;
}


/* ============================================================
   CARD BOTTOM
   ============================================================ */

.sc-track-card-bottom {
    display: flex;
    align-items: center;
}

.sc-track-application-details {
    display: flex;
    align-items: center;
    gap: 32px;
}

.sc-track-detail-item {
    display: flex;
    align-items: center;
    gap: 9px;
}

.sc-track-detail-icon {
    width: 32px;
    height: 32px;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    background: #f0f6f2;
    border-radius: 8px;
    color: #176b3a;
    font-size: 13px;
}

.sc-track-detail-item div:last-child {
    display: flex;
    flex-direction: column;
    gap: 2px;
}

.sc-track-detail-item span {
    color: #85918b;
    font-size: 8px;
    font-weight: 850;
    letter-spacing: 1px;
}

.sc-track-detail-item strong {
    color: #34483f;
    font-size: 12px;
    font-weight: 750;
}


/* ============================================================
   EMPTY STATE
   ============================================================ */

.sc-track-empty {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 28px;
    padding: 55px 45px;
    background: rgba(255, 255, 255, 0.96);
    border: 1px solid #dce9df;
    border-radius: 20px;
    box-shadow: 0 10px 30px rgba(23, 69, 44, 0.07);
    text-align: left;
}

.sc-track-empty-icon {
    width: 78px;
    height: 78px;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    background: linear-gradient( 145deg, #edf8f0, #e2f2e7 );
    border: 1px solid #d6e8dc;
    border-radius: 20px;
    color: #176b3a;
    font-size: 31px;
}

.sc-track-empty-content {
    max-width: 620px;
}

.sc-track-empty-label {
    display: block;
    margin-bottom: 5px;
    color: #176b3a;
    font-size: 9px;
    font-weight: 900;
    letter-spacing: 1.5px;
}

.sc-track-empty h2 {
    margin: 0;
    color: #173329;
    font-size: 25px;
    font-weight: 800;
}

.sc-track-empty p {
    margin: 8px 0 20px;
    color: #61736a;
    font-size: 14px;
    line-height: 1.6;
}

.sc-track-primary-button {
    display: inline-flex;
    align-items: center;
    gap: 9px;
    padding: 12px 17px;
    background: linear-gradient( 135deg, #176b3a, #0f542c );
    border-radius: 10px;
    color: #ffffff;
    font-size: 12px;
    font-weight: 750;
    text-decoration: none;
    box-shadow: 0 7px 18px rgba(23, 107, 58, 0.16);
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}

    .sc-track-primary-button:hover {
        color: #ffffff;
        transform: translateY(-2px);
        box-shadow: 0 10px 23px rgba(23, 107, 58, 0.22);
    }

    .sc-track-primary-button i:last-child {
        color: #b8ff00;
    }


/* ============================================================
   RESPONSIVE - 950PX
   ============================================================ */

@media (max-width: 950px) {

    .sc-track-card-top {
        align-items: flex-start;
    }

    .sc-track-application-details {
        gap: 22px;
    }
}


/* ============================================================
   RESPONSIVE - 750PX
   ============================================================ */

@media (max-width: 750px) {

    .sc-track-page {
        padding: 35px 18px 55px;
    }

    .sc-track-header {
        align-items: flex-start;
        flex-direction: column;
    }

    .sc-track-browse-button {
        width: 100%;
    }

    .sc-track-card-top {
        flex-direction: column;
        align-items: flex-start;
        gap: 15px;
    }

    .sc-track-status {
        align-self: flex-start;
    }

    .sc-track-application-details {
        flex-wrap: wrap;
        gap: 18px 28px;
    }

    .sc-track-empty {
        flex-direction: column;
        padding: 45px 25px;
        text-align: center;
    }

    .sc-track-empty-content {
        max-width: 100%;
    }
}


/* ============================================================
   RESPONSIVE - 520PX
   ============================================================ */

@media (max-width: 520px) {

    .sc-track-page {
        padding: 28px 13px 45px;
    }

    .sc-track-header-left {
        align-items: flex-start;
        gap: 12px;
    }

    .sc-track-header-icon {
        width: 52px;
        height: 52px;
        border-radius: 14px;
        font-size: 22px;
    }

    .sc-track-header h1 {
        font-size: 27px;
    }

    .sc-track-header p {
        font-size: 13px;
    }

    .sc-track-section-header {
        align-items: flex-start;
        flex-direction: column;
        gap: 8px;
    }

        .sc-track-section-header h2 {
            font-size: 19px;
        }

    .sc-track-application-card {
        padding: 19px 17px;
    }

    .sc-track-application-main {
        align-items: flex-start;
    }

    .sc-track-application-icon {
        width: 47px;
        height: 47px;
        border-radius: 12px;
        font-size: 19px;
    }

    .sc-track-application-info h3 {
        font-size: 16px;
        white-space: normal;
    }

    .sc-track-application-details {
        width: 100%;
        flex-direction: column;
        align-items: flex-start;
        gap: 13px;
    }

    .sc-track-detail-item {
        width: 100%;
    }

    .sc-track-status {
        width: 100%;
    }

    .sc-track-empty {
        padding: 40px 20px;
    }

    .sc-track-empty-icon {
        width: 68px;
        height: 68px;
        font-size: 27px;
    }

    .sc-track-empty h2 {
        font-size: 22px;
    }

    .sc-track-empty p {
        font-size: 13px;
    }

    .sc-track-primary-button {
        width: 100%;
        justify-content: center;
    }
}


/* =========================================================
   SWIFTCARE - APPLICANT DASHBOARD
   SIMPLE OPPORTUNITY CARDS
   WHITE / FOREST GREEN / LIME
   ========================================================= */

.sc-applicant-dashboard {
    --sc-forest: #176b3a;
    --sc-forest-dark: #0f542c;
    --sc-forest-deep: #0b3f22;
    --sc-lime: #b7e33f;
    --sc-lime-light: #e8f8bf;
    --sc-text: #173b29;
    --sc-text-soft: #557263;
    --sc-border: #dbe9dd;
    position: relative;
    min-height: calc(100vh - 80px);
    padding: 48px 30px 70px;
    overflow: hidden;
}


/* =========================================================
   BACKGROUND
   ========================================================= */

.sc-applicant-dashboard-background {
    position: fixed;
    inset: 0;
    z-index: -1;
    pointer-events: none;
    overflow: hidden;
    background: linear-gradient( 135deg, #edf8ef 0%, #f9fcf9 48%, #e5f3e8 100% );
}


.sc-applicant-dashboard-pattern {
    position: absolute;
    inset: 0;
    opacity: .55;
    background-image: linear-gradient( 135deg, rgba(255,255,255,.65) 25%, transparent 25% ), linear-gradient( 315deg, rgba(23,69,44,.055) 25%, transparent 25% );
    background-size: 80px 80px;
}


.sc-applicant-dashboard-glow {
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
    filter: blur(5px);
}


.sc-applicant-dashboard-glow-one {
    width: 430px;
    height: 430px;
    top: -210px;
    right: -130px;
    background: rgba(183,227,63,.20);
}


.sc-applicant-dashboard-glow-two {
    width: 390px;
    height: 390px;
    bottom: -210px;
    left: -170px;
    background: rgba(255,255,255,.70);
}


/* =========================================================
   CONTAINER
   ========================================================= */

.sc-applicant-dashboard-container {
    width: 100%;
    max-width: 1380px;
    margin: 0 auto;
    position: relative;
    z-index: 1;
}


/* =========================================================
   HEADER
   ========================================================= */

.sc-applicant-dashboard-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 35px;
    margin-bottom: 42px;
}


.sc-applicant-dashboard-header-content {
    max-width: 760px;
}


.sc-applicant-dashboard-eyebrow {
    display: inline-block;
    margin-bottom: 8px;
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 2px;
    color: var(--sc-forest);
}


.sc-applicant-dashboard-header-content h1 {
    margin: 0 0 12px;
    font-size: clamp(34px, 4vw, 52px);
    line-height: 1.08;
    font-weight: 850;
    letter-spacing: -1.5px;
    color: var(--sc-forest-deep);
}


.sc-applicant-dashboard-header-content p {
    max-width: 720px;
    margin: 0;
    font-size: 16px;
    line-height: 1.7;
    color: var(--sc-text-soft);
}


/* =========================================================
   TRACK APPLICATION BUTTON
   ========================================================= */

.sc-applicant-track-button {
    flex-shrink: 0;
    display: flex;
    align-items: center;
    gap: 13px;
    min-width: 270px;
    padding: 14px 17px;
    border: 1px solid #d1e4b0;
    border-radius: 15px;
    background: rgba(255,255,255,.90);
    color: var(--sc-forest-dark);
    text-decoration: none;
    box-shadow: 0 8px 25px rgba(16,65,35,.07);
    transition: transform .2s ease, box-shadow .2s ease, border-color .2s ease;
}


    .sc-applicant-track-button:hover {
        transform: translateY(-3px);
        color: var(--sc-forest-dark);
        border-color: #b7e33f;
        box-shadow: 0 14px 32px rgba(16,65,35,.12);
    }


.sc-applicant-track-button-icon {
    width: 42px;
    height: 42px;
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 12px;
    background: var(--sc-lime-light);
    color: var(--sc-forest);
    font-size: 18px;
}


.sc-applicant-track-button-content {
    display: flex;
    flex-direction: column;
    gap: 2px;
}


    .sc-applicant-track-button-content small {
        font-size: 9px;
        font-weight: 800;
        letter-spacing: 1px;
        color: #729080;
    }


    .sc-applicant-track-button-content strong {
        font-size: 13px;
        font-weight: 800;
        color: var(--sc-forest-deep);
    }


.sc-applicant-track-arrow {
    margin-left: auto;
    font-size: 16px;
    color: var(--sc-forest);
}


/* =========================================================
   SECTION HEADER
   ========================================================= */

.sc-applicant-opportunities-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 20px;
    margin-bottom: 22px;
}


.sc-applicant-section-eyebrow {
    display: block;
    margin-bottom: 5px;
    font-size: 10px;
    font-weight: 850;
    letter-spacing: 1.6px;
    color: var(--sc-forest);
}


.sc-applicant-opportunities-header h2 {
    margin: 0;
    font-size: 25px;
    font-weight: 850;
    color: var(--sc-forest-deep);
}


.sc-applicant-opportunity-count {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 9px 14px;
    border-radius: 20px;
    background: rgba(255,255,255,.72);
    border: 1px solid var(--sc-border);
    color: var(--sc-forest-dark);
    font-size: 12px;
    font-weight: 750;
}


    .sc-applicant-opportunity-count i {
        color: #78ad16;
    }


/* =========================================================
   CARD GRID
   ========================================================= */

.sc-applicant-opportunity-grid {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 22px;
    align-items: stretch;
}


/* =========================================================
   SIMPLE OPPORTUNITY CARD
   ========================================================= */

.sc-applicant-opportunity-card {
    min-width: 0;
    overflow: hidden;
    display: flex;
    flex-direction: column;
    border-radius: 20px;
    background: rgba(255,255,255,.94);
    border: 1px solid rgba(207,225,211,.90);
    box-shadow: 0 10px 30px rgba(25,71,43,.08);
    transition: transform .22s ease, box-shadow .22s ease, border-color .22s ease;
}


    .sc-applicant-opportunity-card:hover {
        transform: translateY(-6px);
        border-color: rgba(183,227,63,.75);
        box-shadow: 0 18px 38px rgba(25,71,43,.14);
    }


/* =========================================================
   IMAGE
   ========================================================= */

.sc-applicant-opportunity-poster {
    position: relative;
    height: 170px;
    overflow: hidden;
    background: linear-gradient( 135deg, #dff1d9, #f5faef );
}


    .sc-applicant-opportunity-poster img {
        width: 100%;
        height: 100%;
        display: block;
        object-fit: cover;
        transition: transform .35s ease;
    }


.sc-applicant-opportunity-card:hover
.sc-applicant-opportunity-poster img {
    transform: scale(1.045);
}


/* =========================================================
   FALLBACK IMAGE
   ========================================================= */

.sc-applicant-no-poster {
    width: 100%;
    height: 100%;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 7px;
    color: var(--sc-forest);
}


    .sc-applicant-no-poster i {
        font-size: 38px;
    }


    .sc-applicant-no-poster span {
        font-size: 11px;
        font-weight: 850;
        letter-spacing: 2px;
    }


/* =========================================================
   OPEN BADGE
   ========================================================= */

.sc-applicant-open-badge {
    position: absolute;
    top: 13px;
    right: 13px;
    display: inline-flex;
    align-items: center;
    gap: 7px;
    padding: 7px 11px;
    border-radius: 20px;
    background: var(--sc-lime);
    color: var(--sc-forest-deep);
    font-size: 11px;
    font-weight: 850;
    box-shadow: 0 5px 15px rgba(52,91,19,.16);
}


.sc-applicant-open-dot {
    width: 7px;
    height: 7px;
    border-radius: 50%;
    background: var(--sc-forest);
}


/* =========================================================
   CATEGORY BADGE
   ========================================================= */

.sc-applicant-category-badge {
    position: absolute;
    left: 13px;
    bottom: 13px;
    display: inline-flex;
    align-items: center;
    gap: 7px;
    max-width: calc(100% - 26px);
    padding: 7px 11px;
    border-radius: 20px;
    background: rgba(255,255,255,.94);
    color: var(--sc-forest-dark);
    font-size: 10px;
    font-weight: 800;
    box-shadow: 0 5px 18px rgba(0,0,0,.10);
}


    .sc-applicant-category-badge i {
        color: #6ca80d;
    }


/* =========================================================
   CARD BODY
   ========================================================= */

.sc-applicant-opportunity-body {
    display: flex;
    flex-direction: column;
    flex: 1;
    padding: 20px 20px 18px;
}


    .sc-applicant-opportunity-body h3 {
        margin: 0 0 9px;
        min-height: 44px;
        font-size: 18px;
        line-height: 1.3;
        font-weight: 850;
        color: var(--sc-forest-deep);
    }


.sc-applicant-opportunity-description {
    margin: 0;
    min-height: 63px;
    font-size: 13px;
    line-height: 1.6;
    color: var(--sc-text-soft);
}


/* =========================================================
   DIVIDER
   ========================================================= */

.sc-applicant-card-divider {
    width: 100%;
    height: 1px;
    margin: 15px 0 13px;
    background: #e0ebe2;
}


/* =========================================================
   SIMPLE DETAILS
   ========================================================= */

.sc-applicant-simple-details {
    display: flex;
    flex-direction: column;
    gap: 9px;
    margin-bottom: 18px;
}


.sc-applicant-simple-detail {
    display: flex;
    align-items: center;
    gap: 9px;
    min-width: 0;
    color: var(--sc-text);
}


    .sc-applicant-simple-detail i {
        flex-shrink: 0;
        width: 18px;
        text-align: center;
        font-size: 13px;
        color: #6fae0e;
    }


    .sc-applicant-simple-detail span {
        overflow: hidden;
        text-overflow: ellipsis;
        white-space: nowrap;
        font-size: 11px;
        font-weight: 700;
        color: #385c48;
    }


/* =========================================================
   VIEW BUTTON
   ========================================================= */

.sc-applicant-view-button {
    display: flex;
    align-items: center;
    justify-content: space-between;
    width: 100%;
    margin-top: auto;
    padding-top: 5px;
    color: var(--sc-forest-dark);
    text-decoration: none;
    font-size: 12px;
    font-weight: 850;
    transition: color .2s ease;
}


    .sc-applicant-view-button i {
        margin-left: 8px;
        font-size: 15px;
        color: #75ad12;
        transition: transform .2s ease;
    }


    .sc-applicant-view-button:hover {
        color: #0b3f22;
    }


        .sc-applicant-view-button:hover i {
            transform: translateX(5px);
        }


/* =========================================================
   EMPTY STATE
   ========================================================= */

.sc-applicant-empty {
    display: flex;
    align-items: center;
    gap: 25px;
    padding: 40px;
    border-radius: 20px;
    background: rgba(255,255,255,.90);
    border: 1px solid var(--sc-border);
    box-shadow: 0 10px 30px rgba(25,71,43,.07);
}


.sc-applicant-empty-icon {
    width: 70px;
    height: 70px;
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 18px;
    background: var(--sc-lime-light);
    color: var(--sc-forest);
    font-size: 27px;
}


.sc-applicant-empty-content span {
    font-size: 10px;
    font-weight: 850;
    letter-spacing: 1.5px;
    color: var(--sc-forest);
}


.sc-applicant-empty-content h2 {
    margin: 5px 0 7px;
    font-size: 22px;
    color: var(--sc-forest-deep);
}


.sc-applicant-empty-content p {
    max-width: 650px;
    margin: 0;
    font-size: 13px;
    line-height: 1.6;
    color: var(--sc-text-soft);
}


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 1100px) {

    .sc-applicant-opportunity-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}


@media (max-width: 850px) {

    .sc-applicant-dashboard-header {
        align-items: stretch;
        flex-direction: column;
    }

    .sc-applicant-track-button {
        width: 100%;
    }
}


@media (max-width: 650px) {

    .sc-applicant-dashboard {
        padding: 32px 17px 55px;
    }

    .sc-applicant-opportunity-grid {
        grid-template-columns: 1fr;
    }

    .sc-applicant-opportunities-header {
        align-items: flex-start;
        flex-direction: column;
    }

    .sc-applicant-opportunity-count {
        align-self: flex-start;
    }
}


@media (max-width: 480px) {

    .sc-applicant-dashboard-header-content h1 {
        font-size: 32px;
    }

    .sc-applicant-dashboard-header-content p {
        font-size: 14px;
    }

    .sc-applicant-opportunity-poster {
        height: 155px;
    }

    .sc-applicant-opportunity-body {
        padding: 18px;
    }

    .sc-applicant-empty {
        align-items: flex-start;
        flex-direction: column;
        padding: 25px;
    }
}

/* =========================================================
   SWIFTCARE ADMIN
   VOLUNTEER APPLICATIONS
   SIMPLE ADMIN TABLE
   ========================================================= */

.sc-admin-applications-page {
    --sc-admin-forest: #176b3a;
    --sc-admin-forest-dark: #0f542c;
    --sc-admin-forest-deep: #0b3f22;
    --sc-admin-lime: #b7e33f;
    --sc-admin-lime-light: #e8f8bf;
    --sc-admin-text: #173b29;
    --sc-admin-text-soft: #587364;
    --sc-admin-border: #dce9de;
    position: relative;
    min-height: calc(100vh - 80px);
    padding: 42px 30px 65px;
    overflow: hidden;
}


/* =========================================================
   BACKGROUND
   ========================================================= */

.sc-admin-applications-background {
    position: fixed;
    inset: 0;
    z-index: -1;
    pointer-events: none;
    overflow: hidden;
    background: linear-gradient( 135deg, #edf8ef 0%, #f9fcf9 48%, #e6f3e9 100% );
}


.sc-admin-applications-pattern {
    position: absolute;
    inset: 0;
    opacity: .55;
    background-image: linear-gradient( 135deg, rgba(255,255,255,.65) 25%, transparent 25% ), linear-gradient( 315deg, rgba(23,69,44,.055) 25%, transparent 25% );
    background-size: 80px 80px;
}


.sc-admin-applications-glow {
    position: absolute;
    border-radius: 50%;
    filter: blur(5px);
    pointer-events: none;
}


.sc-admin-applications-glow-one {
    width: 420px;
    height: 420px;
    top: -200px;
    right: -130px;
    background: rgba(183,227,63,.20);
}


.sc-admin-applications-glow-two {
    width: 370px;
    height: 370px;
    bottom: -200px;
    left: -150px;
    background: rgba(255,255,255,.75);
}


/* =========================================================
   CONTAINER
   ========================================================= */

.sc-admin-applications-container {
    width: 100%;
    max-width: 1450px;
    margin: 0 auto;
    position: relative;
    z-index: 1;
}


/* =========================================================
   HEADER
   ========================================================= */

.sc-admin-applications-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 25px;
    margin-bottom: 30px;
}


.sc-admin-applications-header-left {
    display: flex;
    align-items: center;
    gap: 16px;
}


.sc-admin-applications-header-icon {
    width: 58px;
    height: 58px;
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 16px;
    background: var(--sc-admin-lime-light);
    border: 1px solid #cfe8a2;
    color: var(--sc-admin-forest);
    font-size: 23px;
}


.sc-admin-applications-eyebrow {
    display: block;
    margin-bottom: 4px;
    font-size: 9px;
    font-weight: 850;
    letter-spacing: 1.8px;
    color: var(--sc-admin-forest);
}


.sc-admin-applications-header h1 {
    margin: 0 0 5px;
    font-size: 31px;
    line-height: 1.15;
    font-weight: 850;
    color: var(--sc-admin-forest-deep);
}


.sc-admin-applications-header p {
    margin: 0;
    font-size: 13px;
    line-height: 1.5;
    color: var(--sc-admin-text-soft);
}


/* =========================================================
   BACK BUTTON
   ========================================================= */

.sc-admin-applications-back-button {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 11px 16px;
    flex-shrink: 0;
    border-radius: 10px;
    border: 1px solid #d2e3d4;
    background: rgba(255,255,255,.90);
    color: var(--sc-admin-forest-dark);
    text-decoration: none;
    font-size: 11px;
    font-weight: 800;
    box-shadow: 0 6px 18px rgba(25,71,43,.06);
    transition: transform .2s ease, border-color .2s ease, box-shadow .2s ease;
}


    .sc-admin-applications-back-button:hover {
        color: var(--sc-admin-forest-dark);
        transform: translateY(-2px);
        border-color: var(--sc-admin-lime);
        box-shadow: 0 10px 24px rgba(25,71,43,.10);
    }


    .sc-admin-applications-back-button i {
        color: #6da90e;
        font-size: 13px;
    }


/* =========================================================
   MAIN CARD
   ========================================================= */

.sc-admin-applications-card {
    overflow: hidden;
    border-radius: 18px;
    background: rgba(255,255,255,.95);
    border: 1px solid var(--sc-admin-border);
    box-shadow: 0 12px 35px rgba(25,71,43,.08);
}


/* =========================================================
   CARD HEADER
   ========================================================= */

.sc-admin-applications-card-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 20px;
    padding: 21px 23px;
    border-bottom: 1px solid #e3ece4;
}


.sc-admin-applications-section-label {
    display: block;
    margin-bottom: 4px;
    font-size: 9px;
    font-weight: 850;
    letter-spacing: 1.6px;
    color: var(--sc-admin-forest);
}


.sc-admin-applications-card-header h2 {
    margin: 0;
    font-size: 20px;
    font-weight: 850;
    color: var(--sc-admin-forest-deep);
}


.sc-admin-applications-count {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    padding: 8px 12px;
    border-radius: 20px;
    background: #f3f8f1;
    border: 1px solid #dfebdd;
    color: var(--sc-admin-forest-dark);
    font-size: 11px;
    font-weight: 800;
}


    .sc-admin-applications-count i {
        color: #6da90e;
    }


/* =========================================================
   TABLE WRAPPER
   ========================================================= */

.sc-admin-applications-table-wrapper {
    width: 100%;
    overflow-x: auto;
}


/* =========================================================
   TABLE
   ========================================================= */

.sc-admin-applications-table {
    width: 100%;
    min-width: 1050px;
    border-collapse: collapse;
}


    .sc-admin-applications-table thead {
        background: #f7faf7;
    }


    .sc-admin-applications-table th {
        padding: 13px 17px;
        text-align: left;
        white-space: nowrap;
        border-bottom: 1px solid #dfe9e0;
        color: #6c8275;
        font-size: 9px;
        font-weight: 850;
        letter-spacing: 1px;
        text-transform: uppercase;
    }


    .sc-admin-applications-table td {
        padding: 15px 17px;
        vertical-align: middle;
        border-bottom: 1px solid #edf2ed;
        color: var(--sc-admin-text);
        font-size: 11px;
    }


    .sc-admin-applications-table tbody tr {
        transition: background .18s ease;
    }


        .sc-admin-applications-table tbody tr:hover {
            background: #fbfdfb;
        }


        .sc-admin-applications-table tbody tr:last-child td {
            border-bottom: none;
        }


/* =========================================================
   REFERENCE
   ========================================================= */

.sc-admin-application-reference {
    display: flex;
    align-items: center;
    gap: 8px;
    white-space: nowrap;
}


.sc-admin-reference-icon {
    width: 30px;
    height: 30px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 8px;
    background: var(--sc-admin-lime-light);
    color: var(--sc-admin-forest);
    font-size: 13px;
}


.sc-admin-application-reference strong {
    color: var(--sc-admin-forest-deep);
    font-size: 11px;
    font-weight: 850;
    letter-spacing: .4px;
}


/* =========================================================
   APPLICANT
   ========================================================= */

.sc-admin-application-applicant {
    display: flex;
    align-items: center;
    gap: 10px;
    min-width: 180px;
}


.sc-admin-applicant-avatar {
    width: 35px;
    height: 35px;
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 10px;
    background: #edf7e6;
    color: var(--sc-admin-forest);
    font-size: 15px;
}


.sc-admin-application-applicant div:last-child {
    display: flex;
    flex-direction: column;
    gap: 2px;
    min-width: 0;
}


.sc-admin-application-applicant strong {
    max-width: 190px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    color: var(--sc-admin-forest-deep);
    font-size: 11px;
    font-weight: 800;
}


.sc-admin-application-applicant small {
    font-size: 9px;
    color: #819388;
}


/* =========================================================
   OPPORTUNITY
   ========================================================= */

.sc-admin-application-opportunity {
    display: flex;
    align-items: center;
    gap: 8px;
    min-width: 190px;
}


    .sc-admin-application-opportunity i {
        width: 28px;
        height: 28px;
        flex-shrink: 0;
        display: flex;
        align-items: center;
        justify-content: center;
        border-radius: 8px;
        background: #edf7e6;
        color: var(--sc-admin-forest);
        font-size: 12px;
    }


    .sc-admin-application-opportunity span {
        max-width: 220px;
        overflow: hidden;
        text-overflow: ellipsis;
        white-space: nowrap;
        color: #365b47;
        font-size: 11px;
        font-weight: 700;
    }


/* =========================================================
   EMAIL
   ========================================================= */

.sc-admin-application-email {
    display: flex;
    align-items: center;
    gap: 7px;
    white-space: nowrap;
}


    .sc-admin-application-email i {
        color: #6da90e;
        font-size: 12px;
    }


    .sc-admin-application-email span {
        color: #527063;
        font-size: 10px;
        font-weight: 650;
    }


/* =========================================================
   DATE
   ========================================================= */

.sc-admin-application-date {
    display: flex;
    align-items: center;
    gap: 7px;
    white-space: nowrap;
}


    .sc-admin-application-date i {
        color: #6da90e;
        font-size: 12px;
    }


    .sc-admin-application-date span {
        color: #527063;
        font-size: 10px;
        font-weight: 700;
    }


/* =========================================================
   STATUS
   ========================================================= */

.sc-admin-application-status {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    min-width: 82px;
    padding: 7px 10px;
    border-radius: 20px;
    font-size: 9px;
    font-weight: 850;
    white-space: nowrap;
}


    .sc-admin-application-status i {
        font-size: 10px;
    }


.sc-admin-application-status-pending {
    background: #fff5d5;
    color: #87670f;
}


.sc-admin-application-status-approved {
    background: #e3f5e7;
    color: #176b3a;
}


.sc-admin-application-status-rejected {
    background: #fde8e8;
    color: #a03b3b;
}


.sc-admin-application-status-default {
    background: #edf1ee;
    color: #586b60;
}


/* =========================================================
   VIEW BUTTON
   ========================================================= */

.sc-admin-application-view-button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    padding: 8px 12px;
    border-radius: 9px;
    background: #f0f8df;
    color: var(--sc-admin-forest-dark);
    text-decoration: none;
    font-size: 10px;
    font-weight: 850;
    white-space: nowrap;
    transition: background .18s ease, transform .18s ease;
}


    .sc-admin-application-view-button:hover {
        background: var(--sc-admin-lime);
        color: var(--sc-admin-forest-deep);
        transform: translateX(2px);
    }


    .sc-admin-application-view-button i {
        font-size: 11px;
    }


/* =========================================================
   EMPTY STATE
   ========================================================= */

.sc-admin-applications-empty {
    display: flex;
    align-items: center;
    gap: 22px;
    padding: 42px 30px;
}


.sc-admin-applications-empty-icon {
    width: 65px;
    height: 65px;
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 17px;
    background: var(--sc-admin-lime-light);
    color: var(--sc-admin-forest);
    font-size: 25px;
}


.sc-admin-applications-empty span {
    font-size: 9px;
    font-weight: 850;
    letter-spacing: 1.5px;
    color: var(--sc-admin-forest);
}


.sc-admin-applications-empty h3 {
    margin: 5px 0 6px;
    font-size: 19px;
    font-weight: 850;
    color: var(--sc-admin-forest-deep);
}


.sc-admin-applications-empty p {
    margin: 0;
    font-size: 12px;
    color: var(--sc-admin-text-soft);
}


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 800px) {

    .sc-admin-applications-page {
        padding: 32px 18px 55px;
    }


    .sc-admin-applications-header {
        align-items: flex-start;
        flex-direction: column;
    }


    .sc-admin-applications-back-button {
        align-self: flex-start;
    }
}


@media (max-width: 600px) {

    .sc-admin-applications-header-left {
        align-items: flex-start;
    }


    .sc-admin-applications-header-icon {
        width: 48px;
        height: 48px;
        border-radius: 13px;
        font-size: 19px;
    }


    .sc-admin-applications-header h1 {
        font-size: 27px;
    }


    .sc-admin-applications-card-header {
        align-items: flex-start;
        flex-direction: column;
    }


    .sc-admin-applications-empty {
        align-items: flex-start;
        flex-direction: column;
        padding: 30px 22px;
    }
}


/* =========================================================
   ACCESSIBILITY
   ========================================================= */

@media (prefers-reduced-motion: reduce) {

    .sc-admin-application-view-button,
    .sc-admin-applications-back-button,
    .sc-admin-applications-table tbody tr {
        transition: none;
    }
}

/* =========================================================
   SWIFTCARE - AI SHORTLISTING MODAL
   FIXED / ABOVE NAVBAR / PROPER VIEWPORT FIT
   ========================================================= */

.sc-shortlisting-modal {
    position: fixed;
    inset: 0;
    width: 100%;
    height: 100dvh;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 24px;
    box-sizing: border-box;
    opacity: 0;
    visibility: hidden;
    pointer-events: none;
    /* MUST be higher than the SwiftCare navbar/sidebar */
    z-index: 99999;
    transition: opacity 0.2s ease, visibility 0.2s ease;
}

    .sc-shortlisting-modal.sc-shortlisting-modal-visible {
        opacity: 1;
        visibility: visible;
        pointer-events: auto;
    }


/* =========================================================
   BACKGROUND OVERLAY
   ========================================================= */

.sc-shortlisting-modal-overlay {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    background: rgba(5, 35, 20, 0.68);
    backdrop-filter: blur(7px);
    -webkit-backdrop-filter: blur(7px);
    z-index: 1;
}


/* =========================================================
   MODAL DIALOG
   ========================================================= */

.sc-shortlisting-modal-dialog {
    position: relative;
    width: min(720px, 100%);
    /*
       Prevent the modal from going underneath the browser
       viewport or fixed application header.
    */
    max-height: calc(100dvh - 48px);
    margin: 0;
    display: flex;
    flex-direction: column;
    background: #ffffff;
    border: 1px solid rgba(23, 107, 58, 0.16);
    border-radius: 22px;
    box-shadow: 0 30px 80px rgba(0, 0, 0, 0.24), 0 10px 30px rgba(23, 107, 58, 0.14);
    overflow: hidden;
    z-index: 2;
    transform: translateY(12px) scale(0.98);
    transition: transform 0.22s ease, opacity 0.22s ease;
}

.sc-shortlisting-modal.sc-shortlisting-modal-visible
.sc-shortlisting-modal-dialog {
    transform: translateY(0) scale(1);
}


/* =========================================================
   MODAL HEADER
   ========================================================= */

.sc-shortlisting-modal-header {
    position: relative;
    flex: 0 0 auto;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 20px;
    padding: 20px 24px;
    background: #ffffff;
    border-bottom: 1px solid #e6eee8;
    z-index: 3;
}

.sc-shortlisting-modal-title-area {
    display: flex;
    align-items: center;
    gap: 14px;
    min-width: 0;
}

.sc-shortlisting-modal-icon {
    width: 44px;
    height: 44px;
    flex: 0 0 44px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 13px;
    background: #e8f8bf;
    color: #176b3a;
    font-size: 20px;
}

.sc-shortlisting-modal-eyebrow {
    display: block;
    margin-bottom: 3px;
    color: #176b3a;
    font-size: 10px;
    font-weight: 800;
    letter-spacing: 1.2px;
    text-transform: uppercase;
}

.sc-shortlisting-modal-header h2 {
    margin: 0;
    color: #0b3f22;
    font-size: 21px;
    font-weight: 800;
    line-height: 1.2;
}

.sc-shortlisting-modal-close {
    width: 38px;
    height: 38px;
    flex: 0 0 38px;
    display: flex;
    align-items: center;
    justify-content: center;
    border: 1px solid #dce8df;
    border-radius: 10px;
    background: #ffffff;
    color: #527061;
    cursor: pointer;
    font-size: 14px;
    transition: background 0.18s ease, color 0.18s ease, border-color 0.18s ease;
}

    .sc-shortlisting-modal-close:hover {
        background: #f0f8f2;
        border-color: #b8d7c1;
        color: #176b3a;
    }


/* =========================================================
   MODAL BODY
   ========================================================= */

.sc-shortlisting-modal-body {
    flex: 1 1 auto;
    min-height: 0;
    overflow-y: auto;
    padding: 22px 24px 20px;
    background: #ffffff;
    scrollbar-width: thin;
    scrollbar-color: #b8d7c1 transparent;
}

    .sc-shortlisting-modal-body::-webkit-scrollbar {
        width: 7px;
    }

    .sc-shortlisting-modal-body::-webkit-scrollbar-track {
        background: transparent;
    }

    .sc-shortlisting-modal-body::-webkit-scrollbar-thumb {
        background: #b8d7c1;
        border-radius: 20px;
    }


/* =========================================================
   CONFIRMATION AREA
   ========================================================= */

.sc-shortlisting-confirmation {
    display: flex;
    align-items: flex-start;
    gap: 14px;
    padding: 15px;
    margin-bottom: 22px;
    border: 1px solid #d8e8dc;
    border-radius: 14px;
    background: #f5faf6;
}

.sc-shortlisting-confirmation-icon {
    width: 38px;
    height: 38px;
    flex: 0 0 38px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 11px;
    background: #e8f8bf;
    color: #176b3a;
    font-size: 16px;
}

.sc-shortlisting-confirmation h3 {
    margin: 1px 0 5px;
    color: #123c25;
    font-size: 14px;
    font-weight: 800;
}

.sc-shortlisting-confirmation p {
    margin: 0;
    color: #5c7566;
    font-size: 11px;
    line-height: 1.55;
}


/* =========================================================
   PIPELINE HEADER
   ========================================================= */

.sc-shortlisting-steps-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 15px;
    margin-bottom: 10px;
}

    .sc-shortlisting-steps-header span {
        color: #176b3a;
        font-size: 10px;
        font-weight: 900;
        letter-spacing: 1.2px;
    }

    .sc-shortlisting-steps-header small {
        color: #819489;
        font-size: 9px;
    }


/* =========================================================
   PIPELINE STEPS
   ========================================================= */

.sc-shortlisting-steps {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.sc-shortlisting-step {
    display: grid;
    grid-template-columns: 34px 38px minmax(0, 1fr);
    align-items: center;
    gap: 10px;
    min-height: 62px;
    padding: 9px 12px;
    border: 1px solid #dfe9e2;
    border-radius: 12px;
    background: #ffffff;
    transition: border-color 0.18s ease, background 0.18s ease, transform 0.18s ease;
}

    .sc-shortlisting-step:hover {
        background: #f8fbf9;
        border-color: #bfdac6;
        transform: translateX(2px);
    }

.sc-shortlisting-step-number {
    color: #8a9d91;
    font-size: 10px;
    font-weight: 800;
    text-align: center;
}

.sc-shortlisting-step-icon {
    width: 38px;
    height: 38px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 10px;
    background: #eef7e9;
    color: #176b3a;
    font-size: 15px;
}

.sc-shortlisting-step-content {
    min-width: 0;
}

    .sc-shortlisting-step-content h4 {
        margin: 0 0 3px;
        color: #123c25;
        font-size: 11px;
        font-weight: 800;
    }

    .sc-shortlisting-step-content p {
        margin: 0;
        color: #718277;
        font-size: 9px;
        line-height: 1.45;
    }


/* =========================================================
   NOTICE
   ========================================================= */

.sc-shortlisting-notice {
    display: flex;
    align-items: flex-start;
    gap: 12px;
    margin-top: 16px;
    padding: 13px 14px;
    border: 1px solid #e0e9e3;
    border-radius: 12px;
    background: #fafcfb;
}

.sc-shortlisting-notice-icon {
    width: 30px;
    height: 30px;
    flex: 0 0 30px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 9px;
    background: #eef7e9;
    color: #176b3a;
    font-size: 13px;
}

.sc-shortlisting-notice strong {
    display: block;
    margin-bottom: 3px;
    color: #234d34;
    font-size: 10px;
    font-weight: 800;
}

.sc-shortlisting-notice p {
    margin: 0;
    color: #718277;
    font-size: 9px;
    line-height: 1.45;
}


/* =========================================================
   MODAL FOOTER
   ========================================================= */

.sc-shortlisting-modal-footer {
    flex: 0 0 auto;
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: 9px;
    padding: 14px 24px;
    background: #fbfdfb;
    border-top: 1px solid #e4ece6;
    z-index: 3;
}

.sc-shortlisting-cancel-button,
.sc-shortlisting-confirm-button {
    min-height: 38px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    padding: 0 16px;
    border-radius: 10px;
    font-size: 10px;
    font-weight: 800;
    cursor: pointer;
    transition: transform 0.18s ease, box-shadow 0.18s ease, background 0.18s ease;
}

.sc-shortlisting-cancel-button {
    border: 1px solid #d7e4db;
    background: #ffffff;
    color: #65786d;
}

    .sc-shortlisting-cancel-button:hover {
        background: #f4f8f5;
        color: #176b3a;
    }

.sc-shortlisting-confirm-button {
    border: 1px solid #176b3a;
    background: #176b3a;
    color: #ffffff;
    box-shadow: 0 5px 14px rgba(23, 107, 58, 0.18);
}

    .sc-shortlisting-confirm-button:hover {
        background: #0f542c;
        border-color: #0f542c;
        transform: translateY(-1px);
        box-shadow: 0 8px 18px rgba(23, 107, 58, 0.24);
    }


/* =========================================================
   PREVENT PAGE SCROLL WHILE MODAL IS OPEN
   ========================================================= */

body.sc-shortlisting-modal-open {
    overflow: hidden;
}


/* =========================================================
   TABLET
   ========================================================= */

@media (max-width: 700px) {

    .sc-shortlisting-modal {
        padding: 14px;
    }

    .sc-shortlisting-modal-dialog {
        width: 100%;
        max-height: calc(100dvh - 28px);
        border-radius: 18px;
    }

    .sc-shortlisting-modal-header {
        padding: 17px 18px;
    }

    .sc-shortlisting-modal-body {
        padding: 18px;
    }

    .sc-shortlisting-modal-footer {
        padding: 13px 18px;
    }
}


/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width: 520px) {

    .sc-shortlisting-modal {
        padding: 8px;
    }

    .sc-shortlisting-modal-dialog {
        max-height: calc(100dvh - 16px);
        border-radius: 16px;
    }

    .sc-shortlisting-modal-header {
        padding: 14px;
    }

        .sc-shortlisting-modal-header h2 {
            font-size: 17px;
        }

    .sc-shortlisting-modal-icon {
        width: 38px;
        height: 38px;
        flex-basis: 38px;
        border-radius: 10px;
    }

    .sc-shortlisting-modal-body {
        padding: 15px 14px;
    }

    .sc-shortlisting-confirmation {
        padding: 12px;
        margin-bottom: 17px;
    }

    .sc-shortlisting-step {
        grid-template-columns: 28px 34px minmax(0, 1fr);
        gap: 7px;
        padding: 8px 9px;
    }

    .sc-shortlisting-step-icon {
        width: 34px;
        height: 34px;
    }

    .sc-shortlisting-modal-footer {
        flex-direction: column;
        align-items: stretch;
        padding: 12px 14px;
    }

    .sc-shortlisting-cancel-button,
    .sc-shortlisting-confirm-button {
        width: 100%;
    }
}


/* =========================================================
   REDUCED MOTION
   ========================================================= */

@media (prefers-reduced-motion: reduce) {

    .sc-shortlisting-modal,
    .sc-shortlisting-modal-dialog,
    .sc-shortlisting-step,
    .sc-shortlisting-cancel-button,
    .sc-shortlisting-confirm-button {
        transition: none;
    }
}
/* =========================================================
   SWIFTCARE ADMIN APPLICATIONS
   ATS SUMMARY CARDS
   ========================================================= */

.sc-admin-applications-summary-grid {
    display: grid;
    grid-template-columns: repeat(5, minmax(0, 1fr));
