}

.sc-shortlisting-opportunity-selector-icon {
    flex: 0 0 40px;
    width: 40px;
    height: 40px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 11px;
    background: rgba(22, 101, 52, 0.1);
    color: #166534;
