}


/* =========================================================
   PIPELINE RESULT STATISTICS
   ========================================================= */

.sc-shortlisting-result-grid {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 12px;
    margin-bottom: 22px;
}

.sc-shortlisting-result-card {
    padding: 15px;
    border: 1px solid #e2e8f0;
    border-radius: 13px;
    background: #ffffff;
    text-align: center;
}

    .sc-shortlisting-result-card span {
        display: block;
        margin-bottom: 7px;
        color: #64748b;
        font-size: 9px;
        font-weight: 850;
        letter-spacing: 0.08em;
    }

    .sc-shortlisting-result-card strong {
        display: block;
        color: #172033;
        font-size: 23px;
        font-weight: 850;
        line-height: 1;
    }


/* =========================================================
   DISABLED PIPELINE BUTTON
   ========================================================= */

.sc-shortlisting-confirm-button:disabled {
    opacity: 0.65;
    cursor: not-allowed;
    transform: none !important;
    box-shadow: none !important;
}


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 1200px) {

    .sc-admin-applications-summary-grid {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }
}


@media (max-width: 900px) {

    .sc-admin-applications-summary-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .sc-shortlisting-result-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}


@media (max-width: 650px) {

    .sc-admin-applications-summary-grid {
        grid-template-columns: 1fr;
        gap: 12px;
    }

    .sc-admin-applications-summary-card {
        min-height: 78px;
    }

    .sc-admin-applications-summary-icon {
        width: 42px;
        height: 42px;
        flex-basis: 42px;
    }

    .sc-admin-applications-summary-card strong {
        font-size: 22px;
    }

    .sc-shortlisting-result-grid {
        grid-template-columns: 1fr;
    }

    .sc-shortlisting-opportunity-selector {
        padding: 14px;
    }

    .sc-shortlisting-opportunity-selector-header h3 {
        font-size: 14px;
    }
}
/* ============================================================
   LIVE PIPELINE CONTAINER
   ============================================================ */

.sc-live-pipeline {
    position: relative;
}


/* ============================================================
   LIVE STATUS
   ============================================================ */

.sc-pipeline-live-status {
    margin-left: auto;
    min-width: 105px;
    display: inline-flex;
    align-items: center;
    justify-content: flex-end;
    gap: 7px;
    font-size: 12px;
    font-weight: 700;
    color: #94a3b8;
    white-space: nowrap;
}

    .sc-pipeline-live-status i {
        font-size: 13px;
    }


/* ============================================================
   ACTIVE STEP
   ============================================================ */

.sc-shortlisting-step.sc-pipeline-step-active {
    transform: translateX(4px);
}

    .sc-shortlisting-step.sc-pipeline-step-active
    .sc-shortlisting-step-icon {
        box-shadow: 0 0 0 5px rgba(34, 197, 94, 0.10), 0 8px 25px rgba(34, 197, 94, 0.16);
    }

    .sc-shortlisting-step.sc-pipeline-step-active
    .sc-pipeline-live-status {
        color: #16a34a;
    }


/* ============================================================
   ROTATING GEAR
   ============================================================ */

.sc-pipeline-gear {
    animation: scPipelineGearRotation 1s linear infinite;
}

@keyframes scPipelineGearRotation {
    from {
        transform: rotate(0deg);
    }

    to {
        transform: rotate(360deg);
    }
}


/* ============================================================
   COMPLETED STEP
   ============================================================ */

.sc-shortlisting-step.sc-pipeline-step-completed
.sc-pipeline-live-status {
    color: #16a34a;
}

    .sc-shortlisting-step.sc-pipeline-step-completed
    .sc-pipeline-live-status i {
        animation: scPipelineComplete 0.35s ease-out;
    }

@keyframes scPipelineComplete {
    0% {
        transform: scale(0.5);
        opacity: 0;
    }

    70% {
        transform: scale(1.15);
    }

    100% {
        transform: scale(1);
        opacity: 1;
    }
}


/* ============================================================
   LIVE MESSAGE
   ============================================================ */

.sc-pipeline-live-message {
    margin-top: 18px;
    padding: 15px 18px;
    display: flex;
    align-items: center;
    gap: 13px;
    border: 1px solid rgba(148, 163, 184, 0.18);
    border-radius: 14px;
    background: rgba(248, 250, 252, 0.75);
    transition: transform 0.25s ease, border-color 0.25s ease, box-shadow 0.25s ease;
}

.sc-pipeline-live-message-active {
    border-color: rgba(34, 197, 94, 0.25);
    box-shadow: 0 8px 25px rgba(34, 197, 94, 0.08);
}

.sc-pipeline-live-message-icon {
    width: 38px;
    height: 38px;
    flex-shrink: 0;
    border-radius: 11px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: rgba(34, 197, 94, 0.10);
    color: #16a34a;
}

    .sc-pipeline-live-message-icon i {
        font-size: 18px;
    }

.sc-pipeline-live-message-active
.sc-pipeline-live-message-icon i {
    animation: scPipelineMessagePulse 1.4s ease-in-out infinite;
}

@keyframes scPipelineMessagePulse {
    0%, 100% {
        transform: scale(1);
    }

    50% {
        transform: scale(1.12);
    }
}

.sc-pipeline-live-message strong {
    display: block;
    margin-bottom: 2px;
    color: #0f172a;
    font-size: 13px;
}

.sc-pipeline-live-message p {
    margin: 0;
    color: #64748b;
    font-size: 12px;
    line-height: 1.5;
}


/* ============================================================
   PIPELINE RUNNING BUTTON
   ============================================================ */

.sc-pipeline-button-gear {
    animation: scPipelineGearRotation 1s linear infinite;
}


