.sc-shortlist-card-header h2 {
    margin: 0;
    font-size: 20px;
    color: #173225;
}

.sc-shortlist-card-header p {
    margin: 5px 0 0;
    color: #65746b;
    font-size: 13px;
}

.sc-shortlist-count {
    white-space: nowrap;
    padding: 8px 13px;
    border-radius: 999px;
    background: #edf7f1;
    color: #176b3a;
    font-size: 12px;
    font-weight: 800;
}


/* =========================================================
   FILTERS
   ========================================================= */

.sc-shortlist-filters {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 17px 24px;
    background: #fbfcfb;
    border-bottom: 1px solid #edf1ee;
}

.sc-shortlist-search {
    flex: 1;
    min-width: 220px;
    height: 42px;
    display: flex;
    align-items: center;
    gap: 9px;
    padding: 0 13px;
    border-radius: 11px;
    background: #ffffff;
    border: 1px solid #dfe7e2;
}

    .sc-shortlist-search i {
        color: #718078;
    }

    .sc-shortlist-search input {
        width: 100%;
        border: 0;
        outline: 0;
        background: transparent;
        color: #24352b;
        font-size: 13px;
    }

.sc-shortlist-filter select {
    height: 42px;
    min-width: 190px;
    padding: 0 34px 0 12px;
    border-radius: 11px;
    border: 1px solid #dfe7e2;
    background: #ffffff;
    color: #293a30;
    font-size: 13px;
    outline: 0;
}


/* =========================================================
   TABLE
   ========================================================= */

.sc-shortlist-table-wrapper {
    width: 100%;
    overflow-x: auto;
}

.sc-shortlist-table {
    width: 100%;
    border-collapse: collapse;
    min-width: 1150px;
}

    .sc-shortlist-table th {
        padding: 13px 15px;
        text-align: left;
        background: #fafcfb;
        color: #738078;
        font-size: 10px;
        font-weight: 800;
        letter-spacing: .07em;
        white-space: nowrap;
        border-bottom: 1px solid #e8eeea;
    }

    .sc-shortlist-table td {
        padding: 16px 15px;
        border-bottom: 1px solid #edf1ee;
        vertical-align: middle;
    }

    .sc-shortlist-table tbody tr {
        transition: background .15s ease;
    }

        .sc-shortlist-table tbody tr:hover {
            background: #fbfdfb;
        }


/* =========================================================
   RANK
   ========================================================= */

.sc-shortlist-rank-number {
    width: 40px;
    height: 32px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 9px;
    background: #f0f5f1;
    color: #176b3a;
    font-size: 12px;
    font-weight: 800;
}


/* =========================================================
   APPLICANT
   ========================================================= */

.sc-shortlist-applicant {
    display: flex;
    align-items: center;
    gap: 11px;
    min-width: 190px;
}

.sc-shortlist-avatar {
    width: 42px;
    height: 42px;
    flex-shrink: 0;
    overflow: hidden;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #176b3a;
    color: #ffffff;
    font-size: 14px;
    font-weight: 800;
}

    .sc-shortlist-avatar img {
        width: 100%;
        height: 100%;
        object-fit: cover;
    }

.sc-shortlist-applicant-info strong {
    display: block;
    color: #26382d;
    font-size: 13px;
    font-weight: 800;
}

.sc-shortlist-applicant-info span {
    display: block;
    margin-top: 3px;
    color: #7a877f;
    font-size: 11px;
}


/* =========================================================
   OPPORTUNITY
   ========================================================= */

.sc-shortlist-opportunity {
    display: flex;
    align-items: center;
    gap: 8px;
    max-width: 190px;
    color: #42534a;
    font-size: 12px;
    font-weight: 600;
}

    .sc-shortlist-opportunity i {
        color: #176b3a;
    }


/* =========================================================
   ELIGIBILITY / RECOMMENDATION / STAGE
   ========================================================= */

.sc-shortlist-eligibility,
.sc-shortlist-recommendation,
.sc-shortlist-stage {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    white-space: nowrap;
    border-radius: 999px;
    padding: 7px 10px;
    font-size: 10px;
    font-weight: 800;
}

.sc-shortlist-eligibility-eligible {
    background: #eaf7ef;
    color: #176b3a;
}

.sc-shortlist-eligibility-review {
    background: #fff7df;
    color: #9b6c00;
}

.sc-shortlist-eligibility-not {
    background: #fceeee;
    color: #a43b3b;
}

.sc-shortlist-eligibility-default {
    background: #f1f3f2;
    color: #69766f;
}


/* =========================================================
   SCORE
   ========================================================= */

.sc-shortlist-score {
    display: flex;
    align-items: baseline;
    gap: 3px;
}

    .sc-shortlist-score strong {
        color: #176b3a;
        font-size: 20px;
        font-weight: 850;
    }

    .sc-shortlist-score span {
        color: #89948e;
        font-size: 10px;
    }


/* =========================================================
   RECOMMENDATIONS
   ============================================================ */

.sc-shortlist-recommendation-strong {
    background: #eaf7ef;
    color: #176b3a;
}

.sc-shortlist-recommendation-review {
    background: #fff7df;
    color: #956900;
}

.sc-shortlist-recommendation-not {
    background: #f1f3f2;
    color: #68766e;
}


/* =========================================================
   STAGE
   ========================================================= */

.sc-shortlist-stage {
    background: #edf5f0;
    color: #176b3a;
}


/* =========================================================
   ACTIONS
   ========================================================= */

.sc-shortlist-actions {
    display: flex;
    align-items: center;
    gap: 7px;
}

.sc-shortlist-view-button,
.sc-shortlist-interview-button {
    height: 34px;
    padding: 0 11px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    border-radius: 9px;
    font-size: 11px;
    font-weight: 800;
    cursor: pointer;
    text-decoration: none;
    transition: .2s ease;
}

.sc-shortlist-view-button {
    background: #176b3a;
    color: #ffffff;
}

    .sc-shortlist-view-button:hover {
        color: #ffffff;
        background: #0f542c;
        transform: translateY(-1px);
    }

.sc-shortlist-interview-button {
    border: 1px solid #dce6df;
    background: #ffffff;
    color: #31513e;
}

    .sc-shortlist-interview-button:hover {
        background: #f5f9f6;
    }


/* =========================================================
   EMPTY STATES
   ========================================================= */

.sc-shortlist-empty,
.sc-shortlist-no-results {
    text-align: center;
    padding: 70px 25px;
}

.sc-shortlist-empty-icon,
.sc-shortlist-no-results-icon {
    width: 62px;
    height: 62px;
    margin: 0 auto 15px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 18px;
    background: #edf6f0;
    color: #176b3a;
    font-size: 25px;
}

.sc-shortlist-empty h3,
.sc-shortlist-no-results h3 {
    margin: 0;
    color: #26382d;
    font-size: 18px;
}

.sc-shortlist-empty p,
.sc-shortlist-no-results p {
    max-width: 480px;
    margin: 8px auto 20px;
    color: #718078;
    font-size: 13px;
    line-height: 1.6;
}

.sc-shortlist-empty-button {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    padding: 10px 15px;
    border-radius: 10px;
    background: #176b3a;
    color: #ffffff;
    text-decoration: none;
    font-size: 12px;
    font-weight: 800;
}

    .sc-shortlist-empty-button:hover {
        color: #ffffff;
        background: #0f542c;
    }


/* =========================================================
   SHORTLIST MODAL
   ========================================================= */

.sc-shortlist-modal {
    position: fixed;
    inset: 0;
    width: 100%;
    height: 100dvh;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 20px;
    box-sizing: border-box;
    opacity: 0;
    visibility: hidden;
    pointer-events: none;
    z-index: 99999;
}

    .sc-shortlist-modal.visible {
        opacity: 1;
        visibility: visible;
        pointer-events: auto;
    }

.sc-shortlist-modal-overlay {
    position: absolute;
    inset: 0;
    background: rgba(8, 24, 15, .48);
}

.sc-shortlist-modal-dialog {
    position: relative;
    z-index: 2;
    width: min(520px, 100%);
    overflow: hidden;
    border-radius: 18px;
    background: #ffffff;
    box-shadow: 0 25px 70px rgba(0, 0, 0, .22);
}

.sc-shortlist-modal-header {
    padding: 20px;
    display: flex;
    align-items: center;
    gap: 12px;
    border-bottom: 1px solid #edf1ee;
}

.sc-shortlist-modal-icon {
    width: 43px;
    height: 43px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 12px;
    background: #edf6f0;
    color: #176b3a;
}

.sc-shortlist-modal-eyebrow {
    font-size: 9px;
    font-weight: 800;
    letter-spacing: .1em;
    color: #176b3a;
}

.sc-shortlist-modal-header h3 {
    margin: 2px 0 0;
    color: #24362b;
    font-size: 17px;
}

.sc-shortlist-modal-close {
    margin-left: auto;
    width: 35px;
    height: 35px;
    border: 0;
    border-radius: 9px;
    background: #f3f5f4;
    color: #526158;
    cursor: pointer;
}

.sc-shortlist-modal-body {
    padding: 22px;
}

.sc-shortlist-modal-message {
    display: flex;
    gap: 13px;
    padding: 15px;
    border-radius: 13px;
    background: #f7faf8;
    border: 1px solid #e8efea;
}

.sc-shortlist-modal-message-icon {
    color: #176b3a;
    font-size: 18px;
}

.sc-shortlist-modal-message strong {
    color: #26382d;
    font-size: 14px;
}

.sc-shortlist-modal-message p {
    margin: 4px 0 0;
    color: #6b7971;
    font-size: 12px;
    line-height: 1.55;
}

.sc-shortlist-modal-footer {
    padding: 15px 20px;
    border-top: 1px solid #edf1ee;
    display: flex;
    justify-content: flex-end;
}

.sc-shortlist-modal-cancel {
    padding: 9px 15px;
    border: 1px solid #dce5df;
    border-radius: 9px;
    background: #ffffff;
    color: #34463b;
    font-size: 12px;
    font-weight: 800;
    cursor: pointer;
}


/* ============================================================
   SHORTLISTING PIPELINE MODAL
   ============================================================ */

.sc-shortlisting-modal-overlay {
    position: fixed;
    inset: 0;
    z-index: 99999;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 24px;
    background: rgba(7, 25, 16, 0.72);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
}


/* ============================================================
   LARGE ENTERPRISE DIALOG
   ============================================================ */

.sc-shortlisting-modal-dialog {
    position: relative;
    width: min(1240px, calc(100vw - 40px));
    max-height: calc(100vh - 48px);
    display: flex;
    flex-direction: column;
    background: #ffffff;
    border: 1px solid #dfe8e2;
    border-radius: 20px;
    overflow: hidden;
    box-shadow: 0 30px 90px rgba(0, 0, 0, .25), 0 8px 30px rgba(23, 107, 58, .08);
    animation: scPipelineModalIn .28s ease-out;
}

@keyframes scPipelineModalIn {
    from {
        opacity: 0;
        transform: translateY(14px) scale(.985);
    }

    to {
        opacity: 1;
        transform: translateY(0) scale(1);
    }
}


/* ============================================================
   HEADER
   ============================================================ */

.sc-shortlisting-modal-header {
    min-height: 82px;
    padding: 18px 28px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    border-bottom: 1px solid #e5ebe7;
    background: #ffffff;
}

.sc-shortlisting-modal-title-area {
    display: flex;
    align-items: center;
    gap: 13px;
}

.sc-shortlisting-modal-icon {
    width: 45px;
    height: 45px;
    flex: 0 0 45px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 12px;
    background: #edf6f0;
    color: #176b3a;
    font-size: 19px;
}

.sc-shortlisting-modal-eyebrow {
    margin-bottom: 3px;
    color: #176b3a;
    font-size: 9px;
    font-weight: 900;
    letter-spacing: .13em;
    text-transform: uppercase;
}

.sc-shortlisting-modal-title-area h2 {
    margin: 0;
    color: #17261d;
    font-size: 20px;
    font-weight: 850;
}

.sc-shortlisting-modal-close {
    width: 36px;
    height: 36px;
    border: 1px solid #e1e8e3;
    border-radius: 9px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #f8faf9;
    color: #536159;
    cursor: pointer;
    transition: .2s ease;
}

    .sc-shortlisting-modal-close:hover {
        background: #eef4ef;
        color: #176b3a;
        border-color: #d4e2d8;
    }


/* ============================================================
   BODY
   ============================================================ */

.sc-shortlisting-modal-body {
    padding: 26px 34px 24px;
    max-height: calc(100vh - 160px);
    overflow-y: auto;
}


/* ============================================================
   OPPORTUNITY SELECTOR
   ============================================================ */

.sc-shortlisting-opportunity-selector {
    padding: 16px 18px;
    border: 1px solid #e0e8e3;
    border-radius: 13px;
    background: #fafcfb;
}

.sc-shortlisting-opportunity-selector-header {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 10px;
}

.sc-shortlisting-opportunity-selector-icon {
    width: 35px;
    height: 35px;
    flex: 0 0 35px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 9px;
    background: #e9f4ed;
    color: #176b3a;
    font-size: 14px;
}

.sc-shortlisting-opportunity-selector-header strong {
    display: block;
    color: #26372d;
    font-size: 12px;
    font-weight: 850;
}

.sc-shortlisting-opportunity-selector-header span {
    display: block;
    margin-top: 2px;
    color: #718078;
    font-size: 10px;
}

.sc-shortlisting-opportunity-select {
    width: 100%;
    height: 42px;
    padding: 0 12px;
    border: 1px solid #d8e2db;
    border-radius: 9px;
    outline: none;
    background: #ffffff;
    color: #25362c;
    font-size: 12px;
    font-weight: 600;
}

    .sc-shortlisting-opportunity-select:focus {
        border-color: #176b3a;
        box-shadow: 0 0 0 3px rgba(23, 107, 58, .07);
    }


/* ============================================================
   CONFIRMATION
   ============================================================ */

.sc-shortlisting-confirmation {
    margin-top: 13px;
    padding: 12px 15px;
    display: flex;
    align-items: center;
    gap: 10px;
    border: 1px solid #e0e8e3;
    border-radius: 11px;
    background: #f9fbfa;
}

.sc-shortlisting-confirmation-icon {
    width: 33px;
    height: 33px;
    flex: 0 0 33px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 9px;
    background: #e7f3ea;
    color: #176b3a;
    font-size: 13px;
}

.sc-shortlisting-confirmation strong {
    display: block;
    color: #25362c;
    font-size: 11px;
}

.sc-shortlisting-confirmation span {
    display: block;
    margin-top: 2px;
    color: #718078;
    font-size: 10px;
}


/* ============================================================
   PIPELINE HEADER
   ============================================================ */

.sc-shortlisting-steps {
    margin-top: 22px;
}

.sc-shortlisting-steps-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 3px;
}

    .sc-shortlisting-steps-header h3 {
        margin: 0;
        color: #18291f;
        font-size: 15px;
        font-weight: 850;
    }

    .sc-shortlisting-steps-header p {
        margin: 3px 0 0;
        color: #6d7b73;
        font-size: 10px;
    }

.sc-pipeline-live-badge {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    padding: 6px 10px;
    border: 1px solid #d9e6dd;
    border-radius: 999px;
    background: #f7faf8;
    color: #176b3a;
    font-size: 8px;
    font-weight: 900;
    letter-spacing: .07em;
    text-transform: uppercase;
}

.sc-pipeline-live-dot {
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: #176b3a;
    box-shadow: 0 0 0 3px rgba(23, 107, 58, .08);
    animation: scLiveDot 1.25s ease-in-out infinite;
}

@keyframes scLiveDot {
    0%, 100% {
        opacity: 1;
        transform: scale(1);
    }

    50% {
        opacity: .4;
        transform: scale(.72);
    }
}


/* ============================================================
   REALISTIC ATS PIPELINE
   - NO VERTICAL PROGRESS BAR
   - NO HORIZONTAL TRACK
   - NODES SIT AT CONNECTOR ENDS
   - CLEAN ZIG-ZAG FLOW
   ============================================================ */

.sc-pipeline-track {
    position: relative;
    width: 100%;
    min-width: 1080px;
    height: 285px;
    margin: 2px auto 0;
    padding: 0 15px;
    display: grid;
    grid-template-columns: 58px 1fr 58px 1fr 58px 1fr 58px 1fr 58px 1fr 58px;
    align-items: center;
    background: transparent !important;
    background-image: none !important;
    border: none !important;
    box-shadow: none !important;
}


    /* ============================================================
   REMOVE ANY TRACK / FILL / PROGRESS ELEMENT
   ============================================================ */

    .sc-pipeline-track::before,
    .sc-pipeline-track::after,
    .sc-live-pipeline::before,
    .sc-live-pipeline::after,
    .sc-shortlisting-steps::before,
    .sc-shortlisting-steps::after {
        content: none !important;
        display: none !important;
        width: 0 !important;
        height: 0 !important;
        background: transparent !important;
        border: none !important;
        box-shadow: none !important;
    }


/* Kill old progress elements */

.sc-pipeline-line,
.sc-pipeline-horizontal-line,
.sc-pipeline-progress,
.sc-pipeline-progress-line,
.sc-pipeline-track-line,
.sc-pipeline-fill,
.sc-pipeline-vertical-line,
.sc-pipeline-vertical-progress {
    display: none !important;
}


/* ============================================================
   PROCESS NODE
   ============================================================ */

.sc-shortlisting-step {
    position: relative;
    z-index: 50;
    width: 56px;
    height: 56px;
    justify-self: center;
    display: flex;
    align-items: center;
    justify-content: center;
    border: 2px solid #d5ded8;
    border-radius: 50%;
    background: #ffffff;
    box-shadow: 0 4px 12px rgba(23, 45, 31, .08), 0 1px 2px rgba(23, 45, 31, .04);
    transition: border-color .3s ease, background .3s ease, box-shadow .3s ease, transform .3s ease;
}


/* ============================================================
   TOP / BOTTOM POSITIONING
   ============================================================ */

.sc-pipeline-step-top {
    transform: translateY(-62px);
}

.sc-pipeline-step-bottom {
    transform: translateY(62px);
}


/* ============================================================
   STEP NUMBER
   ============================================================ */

.sc-shortlisting-step-number {
    position: absolute;
    width: 19px;
    height: 19px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    background: #edf1ee;
    color: #637068;
    border: 2px solid #ffffff;
    font-size: 8px;
    font-weight: 900;
    box-shadow: 0 2px 5px rgba(0, 0, 0, .08);
    z-index: 60;
}


.sc-pipeline-step-top
.sc-shortlisting-step-number {
    right: -7px;
    top: -7px;
}


.sc-pipeline-step-bottom
.sc-shortlisting-step-number {
    right: -7px;
    bottom: -7px;
}


/* ============================================================
   NODE ICON
   ============================================================ */

.sc-shortlisting-step-icon {
    width: 29px;
    height: 29px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    background: #f1f4f2;
    color: #607068;
    font-size: 12px;
    transition: background .3s ease, color .3s ease, box-shadow .3s ease;
}


/* ============================================================
   LABEL OUTSIDE NODE
   ============================================================ */

.sc-shortlisting-step-content {
    position: absolute;
    left: 50%;
    width: 130px;
    transform: translateX(-50%);
    text-align: center;
    pointer-events: none;
}


    .sc-shortlisting-step-content h4 {
        margin: 0;
        color: #35443b;
        font-size: 10px;
        line-height: 1.3;
        font-weight: 800;
    }


.sc-pipeline-step-top
.sc-shortlisting-step-content {
    top: 69px;
}


.sc-pipeline-step-bottom
.sc-shortlisting-step-content {
    bottom: 69px;
}


/* ============================================================
   CONNECTOR CONTAINER
   ============================================================ */

.sc-pipeline-connection {
    position: relative;
    z-index: 15;
    width: calc(100% + 56px);
    height: 125px;
    margin-left: -28px;
    pointer-events: none;
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
}


    /* ============================================================
   REMOVE OLD CONNECTOR BACKGROUNDS
   ============================================================ */

    .sc-pipeline-connection::before,
    .sc-pipeline-connection::after {
        content: none !important;
        display: none !important;
        background: transparent !important;
        border: none !important;
        box-shadow: none !important;
    }


/* ============================================================
   CONNECTOR LINE AREA
   ============================================================ */

.sc-pipeline-connection-line {
    position: absolute;
    left: 0;
    right: 0;
    top: 0;
    bottom: 0;
    overflow: visible;
    background: transparent !important;
}


/* ============================================================
   ZIG-ZAG SEGMENTS
   ============================================================ */

.sc-pipeline-connector-segment {
    position: absolute;
    display: block;
    height: 2px;
    border-radius: 999px;
    background: #d4ddd7;
    transform-origin: center;
    transition: background .3s ease, box-shadow .3s ease;
    z-index: 20;
}


/* ============================================================
   TOP → BOTTOM
   ============================================================ */

.sc-pipeline-connection:not(.sc-pipeline-connection-down)
.sc-pipeline-connector-segment-one {
    left: 0;
    top: 50%;
    width: 50%;
    transform-origin: left center;
    transform: rotate(31deg);
}


.sc-pipeline-connection:not(.sc-pipeline-connection-down)
.sc-pipeline-connector-segment-two {
    right: 0;
    top: 50%;
    width: 50%;
    transform-origin: right center;
    transform: rotate(-31deg);
}


/* ============================================================
   BOTTOM → TOP
   ============================================================ */

.sc-pipeline-connection-down
.sc-pipeline-connector-segment-one {
    left: 0;
    top: 50%;
    width: 50%;
    transform-origin: left center;
    transform: rotate(-31deg);
}


.sc-pipeline-connection-down
.sc-pipeline-connector-segment-two {
    right: 0;
    top: 50%;
    width: 50%;
    transform-origin: right center;
    transform: rotate(31deg);
}


/* ============================================================
   ACTIVE CONNECTOR
   ============================================================ */

.sc-pipeline-connection-active
.sc-pipeline-connector-segment-one,
.sc-pipeline-connection-active
.sc-pipeline-connector-segment-two {
    background: #176b3a;
    box-shadow: 0 0 0 1px rgba(23, 107, 58, .04), 0 0 6px rgba(23, 107, 58, .14);
}


/* ============================================================
   COMPLETED CONNECTOR
   ============================================================ */

.sc-pipeline-connection-completed
.sc-pipeline-connector-segment-one,
.sc-pipeline-connection-completed
.sc-pipeline-connector-segment-two {
    background: #176b3a;
    box-shadow: 0 0 3px rgba(23, 107, 58, .10);
}


/* ============================================================
   REMOVE OLD FAKE HORIZONTAL FLOW
   ============================================================ */

.sc-pipeline-connector-flow {
    display: none !important;
}


/* ============================================================
   ACTIVE NODE
   ============================================================ */

.sc-shortlisting-step.sc-pipeline-step-active {
    border-color: #176b3a;
    background: #ffffff;
    box-shadow: 0 0 0 5px rgba(23, 107, 58, .055), 0 8px 20px rgba(23, 107, 58, .14);
    animation: scPipelineNodePulse 1.8s ease-in-out infinite;
}


    .sc-shortlisting-step.sc-pipeline-step-active
    .sc-shortlisting-step-icon {
        background: #e7f3eb;
        color: #176b3a;
    }


    .sc-shortlisting-step.sc-pipeline-step-active
    .sc-shortlisting-step-number {
        background: #176b3a;
        color: #ffffff;
    }


    .sc-shortlisting-step.sc-pipeline-step-active
    .sc-shortlisting-step-content h4 {
        color: #176b3a;
    }


/* ============================================================
   COMPLETED NODE
   ============================================================ */

.sc-shortlisting-step.sc-pipeline-step-completed {
    border-color: #176b3a;
    background: #176b3a;
    box-shadow: 0 7px 18px rgba(23, 107, 58, .18);
}


    .sc-shortlisting-step.sc-pipeline-step-completed
    .sc-shortlisting-step-icon {
        background: transparent;
        color: #ffffff;
    }


    .sc-shortlisting-step.sc-pipeline-step-completed
    .sc-shortlisting-step-number {
        background: #ffffff;
        color: #176b3a;
    }


    .sc-shortlisting-step.sc-pipeline-step-completed
    .sc-shortlisting-step-content h4 {
        color: #176b3a;
    }


/* ============================================================
   NODE PULSE
   ============================================================ */

@keyframes scPipelineNodePulse {

    0%, 100% {
        box-shadow: 0 0 0 5px rgba(23, 107, 58, .055), 0 7px 18px rgba(23, 107, 58, .13);
    }

    50% {
        box-shadow: 0 0 0 8px rgba(23, 107, 58, .035), 0 9px 24px rgba(23, 107, 58, .17);
    }
}


/* ============================================================
   MAKE CONNECTOR ENTER NODE EDGE
   ============================================================ */

.sc-pipeline-connection {
    transform: translateZ(0);
}


/*
   Nodes remain above connectors so the connector visually
   disappears underneath the circular edge instead of floating
   beside it.
*/

.sc-shortlisting-step {
