/* ============================================================
   REDUCED MOTION
   ============================================================ */

@media (prefers-reduced-motion: reduce) {

    .sc-shortlisting-step.sc-pipeline-step-active {
        animation: none !important;
    }

    .sc-pipeline-gear,
    .sc-pipeline-live-dot,
    .sc-pipeline-live-message-active
    .sc-pipeline-live-message-icon i {
        animation: none !important;
    }
}

/* ============================================================
   SWIFTCARE ATS PIPELINE
   SVG CONNECTOR VERSION
   ============================================================ */

.sc-pipeline-track {
    position: relative;
    width: 100%;
    min-width: 1080px;
    height: 285px;
    margin: 2px auto 0;
    display: grid;
    grid-template-columns: 58px 1fr 58px 1fr 58px 1fr 58px 1fr 58px 1fr 58px;
    align-items: center;
    padding: 0;
    background: transparent !important;
    background-image: none !important;
    border: 0 !important;
    box-shadow: none !important;
    overflow: visible;
}


    /* ============================================================
   KILL OLD TRACK / PROGRESS / FILL ELEMENTS
   ============================================================ */

    .sc-pipeline-track::before,
    .sc-pipeline-track::after,
    .sc-pipeline-connection::before,
    .sc-pipeline-connection::after {
        content: none !important;
        display: none !important;
    }

.sc-pipeline-line,
.sc-pipeline-horizontal-line,
.sc-pipeline-progress,
.sc-pipeline-progress-line,
.sc-pipeline-vertical-line,
.sc-pipeline-connector-line,
.sc-pipeline-track-line,
.sc-pipeline-track-progress {
    display: none !important;
}

.sc-pipeline-connector-flow,
.sc-pipeline-flow,
.sc-pipeline-flow-line,
.sc-pipeline-segment,
.sc-pipeline-connector,
.sc-pipeline-segment-horizontal {
    display: none !important;
}


/* ============================================================
   STEP NODE
   ============================================================ */

.sc-shortlisting-step {
    position: relative;
    z-index: 100;
    width: 56px;
    height: 56px;
    justify-self: center;
    display: flex;
    align-items: center;
    justify-content: center;
    border: 2px solid #d7e0da;
    border-radius: 50%;
    background: #ffffff;
    box-shadow: 0 5px 15px rgba(23, 45, 31, .09), 0 1px 3px rgba(23, 45, 31, .05);
    transition: border-color .3s ease, background .3s ease, box-shadow .3s ease, transform .3s ease;
    flex-shrink: 0;
}


/* ============================================================
   ALTERNATING NODE POSITIONS
   ============================================================ */

.sc-pipeline-step-top {
    transform: translateY(-62px);
}

.sc-pipeline-step-bottom {
    transform: translateY(62px);
}


/* ============================================================
   STEP NUMBER
   ============================================================ */

.sc-shortlisting-step-number {
    position: absolute;
    width: 20px;
    height: 20px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    background: #edf1ee;
    color: #637068;
    border: 2px solid #ffffff;
    font-size: 8px;
    font-weight: 900;
    box-shadow: 0 2px 5px rgba(0, 0, 0, .08);
    z-index: 5;
}

.sc-pipeline-step-top
.sc-shortlisting-step-number {
    right: -7px;
    top: -7px;
}

.sc-pipeline-step-bottom
.sc-shortlisting-step-number {
    right: -7px;
    bottom: -7px;
}


/* ============================================================
   STEP ICON
   ============================================================ */

.sc-shortlisting-step-icon {
    width: 32px;
    height: 32px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    background: #f1f4f2;
    color: #607068;
    font-size: 13px;
    transition: background .3s ease, color .3s ease, transform .3s ease;
}


/* ============================================================
   STEP CONTENT
   ============================================================ */

.sc-shortlisting-step-content {
    position: absolute;
    left: 50%;
    width: 145px;
    transform: translateX(-50%);
    text-align: center;
    pointer-events: none;
    z-index: 110;
}

    .sc-shortlisting-step-content h4 {
        margin: 0;
        color: #35443b;
        font-size: 10px;
        line-height: 1.35;
        font-weight: 800;
    }

    .sc-shortlisting-step-content p {
        margin: 5px 0 0;
        color: #87928c;
        font-size: 8px;
        line-height: 1.4;
        font-weight: 600;
    }

.sc-pipeline-step-top
.sc-shortlisting-step-content {
    top: 70px;
}

.sc-pipeline-step-bottom
.sc-shortlisting-step-content {
    bottom: 70px;
}


/* ============================================================
   SVG CONNECTOR
   ============================================================ */

.sc-pipeline-connection {
    position: relative;
    z-index: 20;
    height: 140px;
    width: calc(100% + 56px);
    margin-left: -28px;
    pointer-events: none;
    overflow: visible;
    background: transparent !important;
    border: 0 !important;
    box-shadow: none !important;
    transform: none !important;
}

.sc-pipeline-connector-svg {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    overflow: visible;
    display: block;
    pointer-events: none;
}


/* ============================================================
   BASE CONNECTOR
   ============================================================ */

.sc-pipeline-connector-base,
.sc-pipeline-connector-active-path,
.sc-pipeline-connector-completed-path {
    fill: none;
    stroke-linecap: round;
    stroke-linejoin: round;
    vector-effect: non-scaling-stroke;
}


/* ============================================================
   WAITING CONNECTOR
   ============================================================ */

.sc-pipeline-connector-base {
    stroke: #d5ded8;
    stroke-width: 2;
    opacity: 1;
}


/* ============================================================
   COMPLETED CONNECTOR
   ============================================================ */

.sc-pipeline-connector-completed-path {
    stroke: #176b3a;
    stroke-width: 2.7;
    opacity: 0;
    transition: opacity .35s ease;
}

.sc-pipeline-connection-completed
.sc-pipeline-connector-completed-path {
    opacity: 1;
}


/* ============================================================
   ACTIVE CONNECTOR
   ============================================================ */

.sc-pipeline-connector-active-path {
    stroke: #176b3a;
    stroke-width: 3;
    stroke-dasharray: 8 7;
    stroke-dashoffset: 30;
    opacity: 0;
    filter: drop-shadow( 0 0 4px rgba(23, 107, 58, .20) );
}

.sc-pipeline-connection-active
.sc-pipeline-connector-active-path {
    opacity: 1;
    animation: scPipelineSvgFlow 1s linear infinite;
}

@keyframes scPipelineSvgFlow {
    from {
        stroke-dashoffset: 30;
    }

    to {
        stroke-dashoffset: 0;
    }
}


/* ============================================================
   NODE ACTIVE
   ============================================================ */

.sc-shortlisting-step.sc-pipeline-step-active {
    border-color: #176b3a;
    background: #ffffff;
    box-shadow: 0 0 0 5px rgba(23, 107, 58, .07), 0 7px 20px rgba(23, 107, 58, .16);
    animation: scPipelineNodePulse 1.6s ease-in-out infinite;
}

    .sc-shortlisting-step.sc-pipeline-step-active
    .sc-shortlisting-step-icon {
        background: #e7f3eb;
        color: #176b3a;
        transform: scale(1.05);
    }

    .sc-shortlisting-step.sc-pipeline-step-active
    .sc-shortlisting-step-number {
        background: #176b3a;
        color: #ffffff;
    }

@keyframes scPipelineNodePulse {
    0%, 100% {
        box-shadow: 0 0 0 5px rgba(23, 107, 58, .06), 0 7px 20px rgba(23, 107, 58, .13);
    }

    50% {
        box-shadow: 0 0 0 8px rgba(23, 107, 58, .10), 0 8px 24px rgba(23, 107, 58, .19);
    }
}


/* ============================================================
   NODE COMPLETED
   ============================================================ */

.sc-shortlisting-step.sc-pipeline-step-completed {
    border-color: #176b3a;
    background: #f7fbf8;
    box-shadow: 0 5px 16px rgba(23, 107, 58, .13), 0 1px 3px rgba(23, 107, 58, .06);
}

    .sc-shortlisting-step.sc-pipeline-step-completed
    .sc-shortlisting-step-icon {
        background: #176b3a;
        color: #ffffff;
    }

    .sc-shortlisting-step.sc-pipeline-step-completed
    .sc-shortlisting-step-number {
        background: #176b3a;
        color: #ffffff;
    }


/* ============================================================
   GEAR ANIMATION
   ============================================================ */

.sc-pipeline-gear {
    animation: scPipelineGearSpin 1.15s linear infinite;
}

@keyframes scPipelineGearSpin {
    from {
        transform: rotate(0deg);
    }

    to {
        transform: rotate(360deg);
    }
}


/* ============================================================
   PIPELINE STATUS AREA
   ============================================================ */

.sc-pipeline-status {
    position: relative;
    margin-top: 4px;
    text-align: center;
}

.sc-pipeline-status-title {
    margin: 0;
    color: #26352d;
    font-size: 13px;
    font-weight: 800;
}

.sc-pipeline-status-description {
    margin: 4px 0 0;
    color: #87928c;
    font-size: 10px;
    font-weight: 600;
}


/* ============================================================
   PIPELINE RESULT
   ============================================================ */

.sc-pipeline-result {
    display: none;
    margin-top: 14px;
    padding: 14px 16px;
    border: 1px solid #dce7df;
    border-radius: 12px;
    background: #f8fbf9;
    box-shadow: 0 3px 10px rgba(23, 45, 31, .05);
}

    .sc-pipeline-result.show {
        display: block;
        animation: scPipelineResultIn .35s ease;
    }

@keyframes scPipelineResultIn {
    from {
        opacity: 0;
        transform: translateY(5px);
    }

    to {
        opacity: 1;
        transform: translateY(0);
    }
}


/* ============================================================
   PIPELINE RESULT GRID
   ============================================================ */

.sc-pipeline-result-grid {
    display: grid;
    grid-template-columns: repeat(6, minmax(0, 1fr));
    gap: 8px;
}

.sc-pipeline-result-item {
    padding: 8px;
    border-radius: 8px;
    background: #ffffff;
    border: 1px solid #e5ebe7;
    text-align: center;
}

    .sc-pipeline-result-item strong {
        display: block;
        color: #26352d;
        font-size: 14px;
        line-height: 1.2;
    }

    .sc-pipeline-result-item span {
        display: block;
        margin-top: 3px;
        color: #7d8982;
        font-size: 8px;
        font-weight: 700;
    }


/* ============================================================
   PIPELINE FOOTER
   ============================================================ */

.sc-pipeline-footer {
    margin-top: 16px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    padding-top: 12px;
    border-top: 1px solid #edf1ee;
}

.sc-pipeline-footer-left {
    display: flex;
    align-items: center;
    gap: 7px;
    color: #7a867f;
    font-size: 9px;
    font-weight: 700;
}

    .sc-pipeline-footer-left i {
        color: #176b3a;
        font-size: 11px;
    }


