/* ============================================================
       PAGE
       ============================================================ */

.sc-application-details-page {
    width: 100%;
    max-width: 1500px;
    margin: 0 auto;
    padding: 24px 28px 60px;
    color: #172033;
}


/* ============================================================
       HEADER
       ============================================================ */

.sc-application-details-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 30px;
    padding: 28px;
    margin-bottom: 18px;
    background: #ffffff;
    border: 1px solid #e7ebef;
    border-radius: 18px;
    box-shadow: 0 5px 18px rgba(15, 23, 42, 0.05);
}

.sc-application-details-header-left {
    min-width: 0;
}

.sc-application-back-button {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    margin-bottom: 20px;
    color: #198754;
    text-decoration: none;
    font-size: 13px;
    font-weight: 700;
}

    .sc-application-back-button:hover {
        color: #146c43;
    }

.sc-application-title-row {
    display: flex;
    align-items: center;
    gap: 16px;
}

.sc-application-avatar {
    width: 62px;
    height: 62px;
    flex: 0 0 62px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 16px;
    background: #eaf7f0;
    color: #198754;
    font-size: 27px;
}

.sc-application-eyebrow {
    margin-bottom: 4px;
    color: #198754;
    font-size: 11px;
    font-weight: 800;
    letter-spacing: 1.2px;
}

.sc-application-title-row h1 {
    margin: 0;
    font-size: 27px;
    font-weight: 800;
    color: #172033;
}

.sc-application-title-row p {
    margin: 5px 0 0;
    color: #6b7280;
    font-size: 14px;
}

.sc-application-header-score {
    min-width: 170px;
    padding: 18px 22px;
    text-align: center;
    border-left: 1px solid #e8ebef;
}

.sc-application-header-score-label {
    color: #7a8493;
    font-size: 10px;
    font-weight: 800;
    letter-spacing: 1px;
}

.sc-application-header-score-value {
    display: inline-block;
    margin-top: 4px;
    font-size: 38px;
    font-weight: 900;
}

.sc-application-header-score-total {
    display: inline-block;
    margin-left: 2px;
    color: #9aa2ad;
    font-size: 13px;
    font-weight: 700;
}


/* ============================================================
       META
       ============================================================ */

.sc-application-meta-grid {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 14px;
    margin-bottom: 22px;
}

.sc-application-meta-card {
    display: flex;
    align-items: center;
    gap: 13px;
    min-height: 78px;
    padding: 16px;
    background: #ffffff;
    border: 1px solid #e7ebef;
    border-radius: 14px;
}

.sc-application-meta-icon {
    width: 40px;
    height: 40px;
    flex: 0 0 40px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 11px;
    background: #f0f8f4;
    color: #198754;
}

.sc-application-meta-card span {
    display: block;
    margin-bottom: 4px;
    color: #8a93a0;
    font-size: 10px;
    font-weight: 800;
    letter-spacing: .7px;
    text-transform: uppercase;
}

.sc-application-meta-card strong {
    display: block;
    color: #273142;
    font-size: 13px;
    font-weight: 750;
}


/* ============================================================
       SECTIONS
       ============================================================ */

.sc-application-section {
    margin-bottom: 22px;
    padding: 26px;
    background: #ffffff;
    border: 1px solid #e7ebef;
    border-radius: 18px;
    box-shadow: 0 4px 15px rgba(15, 23, 42, 0.035);
}

.sc-application-section-heading {
    display: flex;
    align-items: flex-start;
    gap: 14px;
    margin-bottom: 22px;
}

.sc-application-section-heading-icon {
    width: 44px;
    height: 44px;
    flex: 0 0 44px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 12px;
    background: #eaf7f0;
    color: #198754;
    font-size: 18px;
}

.sc-application-section-heading span {
    display: block;
    margin-bottom: 3px;
    color: #198754;
    font-size: 10px;
    font-weight: 800;
    letter-spacing: 1px;
}

.sc-application-section-heading h2 {
    margin: 0;
    color: #172033;
    font-size: 20px;
    font-weight: 800;
}

.sc-application-section-heading p {
    margin: 5px 0 0;
    color: #7b8491;
    font-size: 13px;
}


/* ============================================================
       ATS SUMMARY
       ============================================================ */

.sc-ats-summary-grid {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 14px;
    margin-bottom: 18px;
}

.sc-ats-summary-card {
    padding: 18px;
    background: #f9fbfa;
    border: 1px solid #e6ece8;
    border-radius: 14px;
}

.sc-ats-summary-card-top {
    display: flex;
    align-items: center;
    justify-content: space-between;
    color: #87918c;
    font-size: 10px;
    font-weight: 800;
    letter-spacing: .8px;
}

    .sc-ats-summary-card-top i {
        color: #198754;
        font-size: 17px;
    }

.sc-ats-summary-card strong {
    display: block;
    margin-top: 7px;
    color: #1f2937;
    font-size: 27px;
    font-weight: 900;
}

.sc-ats-summary-card small {
    display: block;
    margin-top: 2px;
    color: #89918e;
    font-size: 11px;
}


/* ============================================================
       SCORE COLORS
       ============================================================ */

.sc-score-good {
    color: #198754 !important;
}

.sc-score-average {
    color: #c47b00 !important;
}

.sc-score-low {
    color: #c0392b !important;
}


/* ============================================================
       RECOMMENDATION
       ============================================================ */

.sc-ats-recommendation {
    display: flex;
    align-items: center;
    gap: 15px;
    padding: 18px;
    border: 1px solid;
    border-radius: 14px;
}

.sc-ats-recommendation-icon {
    width: 45px;
    height: 45px;
    flex: 0 0 45px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 12px;
    font-size: 19px;
}

.sc-ats-recommendation-content span {
    display: block;
    margin-bottom: 3px;
    font-size: 10px;
    font-weight: 800;
    letter-spacing: .8px;
}

.sc-ats-recommendation-content h3 {
    margin: 0;
    font-size: 17px;
    font-weight: 850;
}

.sc-ats-recommendation-content p {
    margin: 4px 0 0;
    font-size: 12px;
}

.sc-application-status-success {
    color: #198754;
    background: #effaf4;
    border-color: #ccebd9;
}

.sc-application-status-warning {
    color: #a96900;
    background: #fff9eb;
    border-color: #f0dfb4;
}

.sc-application-status-danger {
    color: #b42318;
    background: #fff2f1;
    border-color: #f1ceca;
}

.sc-application-status-neutral {
    color: #687281;
    background: #f6f7f8;
    border-color: #e0e4e8;
}


/* ============================================================
       EXPLANATION
       ============================================================ */

.sc-ats-explanation-card {
    display: flex;
    gap: 15px;
    padding: 20px;
    background: #f8faf9;
    border: 1px solid #e5ebe7;
    border-radius: 14px;
}

.sc-ats-explanation-icon {
    width: 42px;
    height: 42px;
    flex: 0 0 42px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 11px;
    background: #e4f4eb;
    color: #198754;
}

.sc-ats-explanation-card h3 {
    margin: 0 0 5px;
    color: #273142;
    font-size: 14px;
    font-weight: 800;
}

.sc-ats-explanation-card p {
    margin: 0;
    color: #606b78;
    font-size: 13px;
    line-height: 1.7;
}


/* ============================================================
       FEEDBACK
       ============================================================ */

.sc-ats-feedback-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 18px;
}

.sc-ats-feedback-card {
    overflow: hidden;
    border: 1px solid #e7ebef;
    border-radius: 14px;
}

.sc-ats-feedback-header {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 17px;
    border-bottom: 1px solid #edf0f2;
}

.sc-ats-feedback-header-icon {
    width: 39px;
    height: 39px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 10px;
}

.sc-feedback-success {
    background: #eaf7f0;
    color: #198754;
}

.sc-feedback-warning {
    background: #fff6df;
    color: #b77900;
}

.sc-ats-feedback-header span {
    display: block;
    color: #89919d;
    font-size: 9px;
    font-weight: 800;
    letter-spacing: .8px;
}

.sc-ats-feedback-header h3 {
    margin: 2px 0 0;
    color: #263142;
    font-size: 16px;
    font-weight: 800;
}

.sc-ats-feedback-content {
    padding: 16px;
}

.sc-feedback-item {
    display: flex;
    align-items: flex-start;
    gap: 10px;
    padding: 9px 0;
    color: #46515f;
    font-size: 13px;
    line-height: 1.5;
}

    .sc-feedback-item i {
        flex: 0 0 auto;
        margin-top: 2px;
        color: #198754;
    }

.sc-feedback-concern i {
    color: #c17a00;
}

.sc-feedback-empty {
    padding: 15px 0;
    color: #929aa5;
    font-size: 13px;
}


/* ============================================================
       REQUIREMENT MATCH
       ============================================================ */

.sc-requirement-match-card {
    display: flex;
    align-items: flex-start;
    gap: 14px;
    padding: 19px;
    background: #f8faf9;
    border: 1px solid #e4ebe7;
    border-radius: 14px;
}

.sc-requirement-match-icon {
    width: 43px;
    height: 43px;
    flex: 0 0 43px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 11px;
    background: #e5f5ec;
    color: #198754;
}

.sc-requirement-match-card h3 {
    margin: 0 0 5px;
    color: #273142;
    font-size: 14px;
    font-weight: 800;
}

.sc-requirement-match-card p {
    margin: 0;
    color: #5f6977;
    font-size: 13px;
    line-height: 1.65;
}


/* ============================================================
       ELIGIBILITY
       ============================================================ */

.sc-eligibility-card {
    display: grid;
    grid-template-columns: 1fr 220px;
    gap: 18px;
    align-items: center;
}

.sc-eligibility-status {
    display: flex;
    align-items: center;
    gap: 13px;
    padding: 18px;
    border: 1px solid;
    border-radius: 14px;
}

    .sc-eligibility-status > i {
        font-size: 21px;
    }

    .sc-eligibility-status span {
        display: block;
        margin-bottom: 3px;
        font-size: 9px;
        font-weight: 800;
        letter-spacing: .8px;
    }

    .sc-eligibility-status strong {
        font-size: 16px;
        font-weight: 850;
    }

.sc-eligibility-score {
    padding: 18px;
    text-align: center;
    background: #f8faf9;
    border: 1px solid #e5ebe7;
    border-radius: 14px;
}

    .sc-eligibility-score span {
        display: block;
        color: #89919a;
        font-size: 10px;
        font-weight: 750;
    }

    .sc-eligibility-score strong {
        display: block;
        margin-top: 5px;
        color: #198754;
        font-size: 27px;
        font-weight: 900;
    }

    .sc-eligibility-score small {
        color: #929aa3;
        font-size: 11px;
    }


/* ============================================================
       SCORING
       ============================================================ */

.sc-scoring-card {
    padding: 5px 0;
}

.sc-score-row {
    display: grid;
    grid-template-columns: 235px 1fr 60px;
    align-items: center;
    gap: 18px;
    padding: 13px 0;
    border-bottom: 1px solid #edf0f2;
}

.sc-score-label {
    display: flex;
    align-items: center;
    gap: 10px;
    color: #3e4856;
    font-size: 13px;
    font-weight: 700;
}

.sc-score-icon {
    width: 32px;
    height: 32px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 9px;
    background: #f0f7f3;
    color: #198754;
    font-size: 13px;
}

.sc-score-track {
    height: 8px;
    overflow: hidden;
    background: #e9edef;
    border-radius: 999px;
}

.sc-score-fill {
    height: 100%;
    min-width: 2px;
    background: #198754;
    border-radius: inherit;
}

.sc-score-row > strong {
    color: #273142;
    font-size: 13px;
    text-align: right;
}

.sc-score-overall {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-top: 16px;
    padding: 17px 18px;
    background: #edf8f2;
    border: 1px solid #d5eddf;
    border-radius: 13px;
}

    .sc-score-overall span {
        color: #37614a;
        font-size: 13px;
        font-weight: 800;
    }

    .sc-score-overall strong {
        color: #198754;
        font-size: 23px;
        font-weight: 900;
    }

    .sc-score-overall small {
        color: #769082;
        font-size: 11px;
    }


/* ============================================================
       APPLICATION INFORMATION
       ============================================================ */

.sc-application-information-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 18px;
}

.sc-application-info-card {
    border: 1px solid #e7ebef;
    border-radius: 14px;
    overflow: hidden;
}

.sc-application-info-card-header {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 16px;
    border-bottom: 1px solid #edf0f2;
}

.sc-application-info-icon {
    width: 39px;
    height: 39px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 10px;
    background: #eef7f2;
    color: #198754;
}

.sc-application-info-card-header span {
    display: block;
    color: #89919b;
    font-size: 9px;
    font-weight: 800;
    letter-spacing: .8px;
}

.sc-application-info-card-header h3 {
    margin: 2px 0 0;
    color: #283241;
    font-size: 15px;
    font-weight: 800;
}

.sc-cv-file {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 17px;
}

.sc-cv-file-icon {
    width: 42px;
    height: 42px;
    flex: 0 0 42px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 10px;
    background: #fff1f0;
    color: #c0392b;
    font-size: 18px;
}

.sc-cv-file > div:nth-child(2) {
    min-width: 0;
    flex: 1;
}

.sc-cv-file strong {
    display: block;
    overflow: hidden;
    color: #344050;
    font-size: 12px;
    font-weight: 750;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.sc-cv-file span {
    display: block;
    margin-top: 3px;
    color: #9098a2;
    font-size: 10px;
}

.sc-cv-view-button {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 8px 11px;
    color: #198754;
    background: #edf8f2;
    border: 1px solid #d5eddf;
    border-radius: 8px;
    font-size: 11px;
    font-weight: 800;
    text-decoration: none;
    white-space: nowrap;
}

    .sc-cv-view-button:hover {
        color: #ffffff;
        background: #198754;
    }

.sc-cover-message {
    min-height: 100px;
    padding: 17px;
    color: #5f6977;
    font-size: 13px;
    line-height: 1.7;
    white-space: pre-line;
}

.sc-muted {
    color: #959da7;
}

.sc-info-empty {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 25px 17px;
    color: #959da7;
    font-size: 12px;
}


/* ============================================================
       ADMIN DECISION
       ============================================================ */

.sc-admin-decision-card {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 1px;
    overflow: hidden;
    background: #e5e9ec;
    border: 1px solid #e5e9ec;
    border-radius: 13px;
}

.sc-admin-decision-item {
    padding: 17px;
    background: #ffffff;
}

    .sc-admin-decision-item span {
        display: block;
        margin-bottom: 5px;
        color: #8b939d;
        font-size: 9px;
        font-weight: 800;
        letter-spacing: .7px;
        text-transform: uppercase;
    }

    .sc-admin-decision-item strong {
        color: #303a48;
        font-size: 13px;
        font-weight: 800;
    }

.sc-admin-notes {
    display: flex;
    gap: 13px;
    margin-top: 14px;
    padding: 17px;
    background: #fffaf0;
    border: 1px solid #f0e0bd;
    border-radius: 13px;
}

.sc-admin-notes-icon {
    width: 38px;
    height: 38px;
    flex: 0 0 38px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 10px;
    background: #fff1cf;
    color: #ae7600;
}

.sc-admin-notes span {
    display: block;
    color: #9b7a36;
    font-size: 9px;
    font-weight: 800;
    letter-spacing: .8px;
}

.sc-admin-notes p {
    margin: 4px 0 0;
    color: #66563a;
    font-size: 13px;
    line-height: 1.6;
}


/* ============================================================
       AUDIT
       ============================================================ */

.sc-audit-timeline {
    position: relative;
    padding-left: 8px;
}

.sc-audit-item {
    position: relative;
    display: flex;
    gap: 15px;
    padding: 0 0 22px;
}

    .sc-audit-item:last-child {
        padding-bottom: 0;
    }

    .sc-audit-item:not(:last-child)::before {
        content: "";
        position: absolute;
        top: 36px;
        left: 15px;
        bottom: 0;
        width: 1px;
        background: #dce6e0;
    }

.sc-audit-marker {
    position: relative;
    z-index: 2;
    width: 32px;
    height: 32px;
    flex: 0 0 32px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    background: #e9f7ef;
    color: #198754;
    border: 3px solid #ffffff;
    box-shadow: 0 0 0 1px #cde8d8;
    font-size: 11px;
}

.sc-audit-content {
    flex: 1;
    min-width: 0;
    padding-top: 1px;
}

.sc-audit-top {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 15px;
}

    .sc-audit-top strong {
        color: #303a48;
        font-size: 13px;
        font-weight: 800;
    }

    .sc-audit-top time {
        color: #969da7;
        font-size: 10px;
        white-space: nowrap;
    }

.sc-audit-content p {
    margin: 5px 0;
    color: #68727f;
    font-size: 12px;
    line-height: 1.55;
}

.sc-audit-performed-by {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    color: #929aa4;
    font-size: 10px;
}


/* ============================================================
       EMPTY
       ============================================================ */

.sc-application-empty-state {
    padding: 35px 20px;
    text-align: center;
    background: #fafbfb;
    border: 1px dashed #dce2e5;
    border-radius: 14px;
}

.sc-application-empty-icon {
    width: 48px;
    height: 48px;
    margin: 0 auto 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 13px;
    background: #f0f3f4;
    color: #89929c;
    font-size: 19px;
}

.sc-application-empty-state h3 {
    margin: 0;
    color: #424c59;
    font-size: 15px;
    font-weight: 800;
}

.sc-application-empty-state p {
    margin: 5px 0 0;
    color: #9199a2;
    font-size: 12px;
}


/* ============================================================
       RESPONSIVE
       ============================================================ */

@media (max-width: 1100px) {

    .sc-application-meta-grid,
    .sc-ats-summary-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .sc-admin-decision-card {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}


@media (max-width: 800px) {

    .sc-application-details-page {
        padding: 16px 12px 40px;
    }

    .sc-application-details-header {
        flex-direction: column;
        align-items: flex-start;
    }

    .sc-application-header-score {
        width: 100%;
        border-left: 0;
        border-top: 1px solid #e8ebef;
        padding: 18px 0 0;
    }

    .sc-ats-feedback-grid,
    .sc-application-information-grid {
        grid-template-columns: 1fr;
    }

    .sc-eligibility-card {
        grid-template-columns: 1fr;
    }

    .sc-score-row {
        grid-template-columns: 1fr 65px;
        gap: 10px;
    }

    .sc-score-label {
        grid-column: 1 / -1;
    }
}


@media (max-width: 560px) {

    .sc-application-section {
        padding: 18px;
    }

    .sc-application-title-row h1 {
        font-size: 21px;
    }

    .sc-application-meta-grid,
    .sc-ats-summary-grid,
    .sc-admin-decision-card {
        grid-template-columns: 1fr;
    }

    .sc-cv-file {
        align-items: flex-start;
        flex-wrap: wrap;
    }

    .sc-cv-view-button {
        width: 100%;
        justify-content: center;
    }

    .sc-audit-top {
        align-items: flex-start;
