    border: 1px solid rgba(21,92,45,0.09);
    box-shadow: 0 10px 30px rgba(18,61,34,0.06);
}

.voice-session-progress-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 15px;
    margin-bottom: 10px;
}

.voice-session-progress-title {
    color: #123d22;
    font-size: 13px;
    font-weight: 800;
}

.voice-session-progress-count {
    color: #155c2d;
