}

.voice-session-progress-track {
    width: 100%;
    height: 7px;
    overflow: hidden;
    border-radius: 50px;
    background: #e6eee8;
}

.voice-session-progress-fill {
    width: @(
        Model.TotalQuestions > 0 ? Math.Clamp(
        (double)Model.CurrentQuestionNumber /
        Model.TotalQuestions * 100,
        0,
        100)
