                   ============================================================ */

.interview-page {
    min-height: calc(100vh - 80px);
    background: #eef8ef;
    padding: 25px;
    color: #174d32;
}

.interview-shell {
    max-width: 1050px;
    height: calc(100vh - 130px);
    min-height: 650px;
    margin: 0 auto;
    display: flex;
    flex-direction: column;
    background: #f8fff9;
    border: 1px solid #cfe5d2;
    border-radius: 24px;
    overflow: hidden;
    box-shadow: 0 12px 35px rgba(31, 91, 52, 0.12);
}

/* ============================================================
                   HEADER
                   ============================================================ */

.interview-header {
    min-height: 78px;
    padding: 16px 22px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    background: #dff2df;
    border-bottom: 1px solid #c7dfca;
}

.header-left {
    display: flex;
    align-items: center;
    gap: 13px;
}

.bot-avatar {
    width: 48px;
    height: 48px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #a8d94c;
    color: #174d32;
    font-size: 22px;
}

.interview-title {
    font-weight: 800;
    font-size: 17px;
    color: #174d32;
}

.connection-status {
    display: flex;
    align-items: center;
    gap: 7px;
    margin-top: 3px;
    font-size: 12px;
    color: #47715a;
}

.status-dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    display: inline-block;
    background: #d39b25;
}

    .status-dot.connected {
        background: #4e9b55;
    }

    .status-dot.disconnected {
        background: #c65353;
    }

.opportunity-name {
    font-size: 13px;
    font-weight: 700;
    color: #47715a;
    text-align: right;
}

/* ============================================================
                   PROGRESS
                   ============================================================ */

.interview-progress {
    padding: 13px 22px;
    background: #f3fbf4;
    border-bottom: 1px solid #dbeadd;
}

.progress-top {
    display: flex;
    justify-content: space-between;
    font-size: 12px;
    color: #52735e;
    margin-bottom: 7px;
}

    .progress-top strong {
        color: #245c39;
    }

.progress-track {
    width: 100%;
    height: 7px;
    border-radius: 20px;
    overflow: hidden;
    background: #d9e9dc;
}

.progress-fill {
    height: 100%;
    border-radius: 20px;
    background: #9dcc43;
    transition: width .35s ease;
}

/* ============================================================
                   CHAT
                   ============================================================ */

.chat-container {
    flex: 1;
    overflow-y: auto;
    padding: 28px 25px;
    background: radial-gradient( circle at top left, rgba(168, 217, 76, 0.08), transparent 30% ), #edf7ee;
}

.message-row {
    display: flex;
    width: 100%;
    margin-bottom: 17px;
}

.bot-row {
    justify-content: flex-start;
}

.applicant-row {
    justify-content: flex-end;
}

.message-avatar {
    width: 35px;
    height: 35px;
    flex: 0 0 35px;
    margin-right: 9px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #a8d94c;
    color: #174d32;
    font-size: 15px;
}

.message-bubble {
    max-width: min(72%, 680px);
    padding: 13px 16px;
    border-radius: 17px;
    box-shadow: 0 3px 10px rgba(30, 80, 42, 0.07);
}

.bot-bubble {
    background: #ffffff;
    border: 1px solid #d5e7d7;
    border-top-left-radius: 5px;
}

.applicant-bubble {
    background: #d9f0aa;
    border: 1px solid #c2df8e;
    border-top-right-radius: 5px;
}

.message-text {
    font-size: 15px;
    line-height: 1.55;
    color: #214e32;
    white-space: pre-wrap;
    word-break: break-word;
}

.message-actions {
    display: flex;
    justify-content: flex-end;
    margin-top: 8px;
}

.speak-button {
    border: 0;
    background: transparent;
    color: #4f7b4f;
    cursor: pointer;
    font-size: 14px;
    padding: 2px 5px;
}

    .speak-button:hover {
        color: #285c35;
    }

.message-meta {
    margin-top: 7px;
    font-size: 10px;
    color: #789180;
}

.applicant-meta {
    text-align: right;
}

/* ============================================================
                   CONNECTING
                   ============================================================ */

.connecting-message {
    min-height: 250px;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    gap: 14px;
    color: #52735e;
    font-size: 14px;
}

.connecting-spinner {
    width: 32px;
    height: 32px;
    border: 3px solid #d0e2d2;
    border-top-color: #77a936;
    border-radius: 50%;
    animation: spin 0.8s linear infinite;
}

@keyframes spin {
    to {
        transform: rotate(360deg);
    }
}

/* ============================================================
                   SYSTEM ERROR
                   ============================================================ */

.system-message {
    max-width: 600px;
    margin: 20px auto;
    padding: 12px 16px;
    border-radius: 12px;
    text-align: center;
    font-size: 13px;
}

.error-message {
    background: #f8dddd;
    color: #843f3f;
    border: 1px solid #e8bebe;
}

/* ============================================================
                   COMPOSER
                   ============================================================ */

.composer-area {
    padding: 13px 17px 11px;
    background: #e3f3e4;
    border-top: 1px solid #c9dfcc;
}

.composer {
    display: flex;
    align-items: flex-end;
    gap: 9px;
}

.icon-button,
.send-button {
    width: 45px;
    height: 45px;
    flex: 0 0 45px;
    border: 0;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: .2s ease;
}

.microphone-button {
    background: #cde7a2;
    color: #285a32;
}

    .microphone-button:hover {
        background: #bddd82;
    }

    .microphone-button.recording {
        background: #a8d94c;
        animation: pulse 1.2s infinite;
    }

.send-button {
    background: #86b93e;
    color: #174d32;
}

    .send-button:hover:not(:disabled) {
        transform: scale(1.05);
        background: #9dcc43;
    }

    .send-button:disabled,
    .icon-button:disabled {
        opacity: .45;
        cursor: not-allowed;
    }

.answer-input {
    flex: 1;
    min-height: 45px;
    max-height: 180px;
    resize: none;
    padding: 12px 15px;
    border: 1px solid #bfd8c2;
    border-radius: 16px;
    outline: none;
    background: #ffffff;
    color: #214e32;
    font-size: 14px;
    line-height: 1.45;
}

    .answer-input:focus {
        border-color: #89b948;
        box-shadow: 0 0 0 3px rgba(137, 185, 72, 0.12);
    }

    .answer-input::placeholder {
        color: #81988a;
    }

.composer-footer {
    display: flex;
    justify-content: space-between;
    padding: 6px 54px 0;
    font-size: 10px;
    color: #678170;
}

/* ============================================================
                   ANIMATION
                   ============================================================ */

@keyframes pulse {

    0% {
        box-shadow: 0 0 0 0 rgba(134, 185, 62, .4);
    }

    70% {
        box-shadow: 0 0 0 10px rgba(134, 185, 62, 0);
    }

    100% {
        box-shadow: 0 0 0 0 rgba(134, 185, 62, 0);
    }
}

/* ============================================================
                   MOBILE
                   ============================================================ */

@media (max-width: 700px) {

    .interview-page {
        padding: 0;
    }

    .interview-shell {
        width: 100%;
        height: 100vh;
        min-height: 100vh;
        border-radius: 0;
    }

    .interview-header {
        padding: 13px 15px;
    }

    .opportunity-name {
        display: none;
    }

    .chat-container {
        padding: 20px 13px;
    }

    .message-bubble {
        max-width: 85%;
    }

    .composer-footer {
        padding-left: 54px;
        padding-right: 5px;
    }
}

/* ============================================================
       SWIFTCARE VOICE INTERVIEW
       AUTOMATIC HUMAN-LIKE CONVERSATION
       ============================================================ */

.scv-interview-page {
    min-height: 100vh;
    padding: 24px 14px;
    background: radial-gradient(circle at 10% 5%, rgba(122,165,92,.18), transparent 30%), radial-gradient(circle at 90% 10%, rgba(84,130,53,.12), transparent 28%), #eaf4e4;
    color: #173b23;
}

.scv-shell {
    width: min(900px, 100%);
    margin: 0 auto;
    border-radius: 26px;
    overflow: hidden;
    background: rgba(255,255,255,.78);
    border: 1px solid rgba(49,96,55,.12);
    box-shadow: 0 20px 55px rgba(38,78,40,.12), 0 4px 16px rgba(38,78,40,.08);
    backdrop-filter: blur(18px);
}

/* ============================================================
       HEADER
       ============================================================ */

.scv-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 14px;
    padding: 17px 20px;
    background: rgba(243,250,239,.92);
    border-bottom: 1px solid rgba(49,96,55,.10);
}

.scv-header-left {
    display: flex;
    align-items: center;
    gap: 13px;
    min-width: 0;
}

.scv-avatar {
    width: 46px;
    height: 46px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    flex: 0 0 auto;
    background: linear-gradient(145deg, #9bcf62, #5b9c46);
    color: #173b23;
    box-shadow: 0 7px 18px rgba(67,116,48,.20);
    font-size: 19px;
}

.scv-title {
    margin: 0;
    font-size: 17px;
    font-weight: 800;
    color: #173b23;
}

.scv-subtitle {
    margin-top: 3px;
    font-size: 12px;
    color: #608064;
}

.scv-status {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    padding: 7px 11px;
    border-radius: 999px;
    background: rgba(111,169,75,.10);
    color: #42722e;
    font-size: 11px;
    font-weight: 800;
    white-space: nowrap;
}

.scv-status-dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: #70ad4e;
    box-shadow: 0 0 0 4px rgba(112,173,78,.12);
}

.scv-status.scv-error {
    color: #9a4138;
    background: rgba(196,78,64,.08);
}

    .scv-status.scv-error .scv-status-dot {
        background: #c94e42;
        box-shadow: 0 0 0 4px rgba(201,78,66,.10);
    }

/* ============================================================
       CHAT
       ============================================================ */

.scv-chat {
    position: relative;
    min-height: 570px;
    max-height: 670px;
    overflow-y: auto;
    padding: 28px 20px 110px;
    background: radial-gradient(circle at 15% 15%, rgba(123,170,92,.09), transparent 20%), radial-gradient(circle at 85% 80%, rgba(102,150,72,.07), transparent 24%), #f2f8ef;
}

    .scv-chat::-webkit-scrollbar {
        width: 6px;
    }

    .scv-chat::-webkit-scrollbar-thumb {
        background: rgba(74,119,65,.22);
        border-radius: 20px;
    }

.scv-row {
    display: flex;
    margin-bottom: 16px;
    animation: scvMessageIn .28s ease-out;
}

.scv-row-bot {
    justify-content: flex-start;
}

.scv-row-user {
    justify-content: flex-end;
}

@@keyframes scvMessageIn {
    from {
        opacity: 0;
        transform: translateY(8px);
    }

    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.scv-bubble {
    position: relative;
    max-width: min(470px, 84%);
    border-radius: 20px;
    padding: 13px 15px;
    box-shadow: 0 6px 16px rgba(43,83,43,.07);
}

.scv-bubble-bot {
    background: #ffffff;
    border-top-left-radius: 7px;
    border: 1px solid rgba(61,103,55,.08);
}

.scv-bubble-user {
    background: #dff0d5;
    border-top-right-radius: 7px;
    border: 1px solid rgba(76,124,58,.10);
}

.scv-bubble-label {
    display: flex;
    align-items: center;
    gap: 7px;
    margin-bottom: 9px;
    color: #628060;
    font-size: 10px;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: .06em;
}

    .scv-bubble-label i {
        color: #669b4c;
    }

/* ============================================================
       VOICE BUBBLE
       ============================================================ */

.scv-voice-line {
    display: flex;
    align-items: center;
    gap: 11px;
    min-width: 215px;
}

.scv-play {
    width: 35px;
    height: 35px;
    border: 0;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    flex: 0 0 auto;
    background: #76ad54;
    color: #173b23;
    cursor: pointer;
    transition: transform .15s ease, box-shadow .15s ease;
}

    .scv-play:hover {
        transform: scale(1.05);
        box-shadow: 0 5px 13px rgba(75,125,51,.18);
    }

    .scv-play:active {
        transform: scale(.96);
    }

.scv-wave {
    display: flex;
    align-items: center;
    gap: 3px;
    height: 30px;
    flex: 1;
}

    .scv-wave span {
        display: block;
        width: 3px;
        border-radius: 10px;
        background: #73a957;
        opacity: .72;
    }

        .scv-wave span:nth-child(1) {
            height: 9px;
        }

        .scv-wave span:nth-child(2) {
            height: 17px;
        }

        .scv-wave span:nth-child(3) {
            height: 24px;
        }

        .scv-wave span:nth-child(4) {
            height: 13px;
        }

        .scv-wave span:nth-child(5) {
            height: 27px;
        }

        .scv-wave span:nth-child(6) {
            height: 18px;
        }

        .scv-wave span:nth-child(7) {
            height: 10px;
        }

        .scv-wave span:nth-child(8) {
            height: 22px;
        }

        .scv-wave span:nth-child(9) {
            height: 15px;
        }

        .scv-wave span:nth-child(10) {
            height: 25px;
        }

        .scv-wave span:nth-child(11) {
            height: 11px;
        }

        .scv-wave span:nth-child(12) {
            height: 20px;
        }

    .scv-wave.scv-speaking span {
        animation: scvWave .55s ease-in-out infinite alternate;
    }

        .scv-wave.scv-speaking span:nth-child(2n) {
            animation-delay: .1s;
        }

        .scv-wave.scv-speaking span:nth-child(3n) {
            animation-delay: .2s;
        }

@keyframes scvWave {
    from {
        transform: scaleY(.55);
        opacity: .45;
    }

    to {
        transform: scaleY(1.12);
        opacity: 1;
    }
}

.scv-duration {
    color: #6d876d;
    font-size: 10px;
    white-space: nowrap;
}

/* ============================================================
       THINKING
       ============================================================ */

.scv-thinking {
    display: none;
    align-items: center;
    gap: 5px;
    padding: 11px 14px;
    width: fit-content;
    background: #ffffff;
    border-radius: 18px;
    border-top-left-radius: 7px;
    border: 1px solid rgba(61,103,55,.08);
    box-shadow: 0 5px 14px rgba(43,83,43,.06);
    margin-bottom: 16px;
}

    .scv-thinking.scv-visible {
        display: flex;
    }

    .scv-thinking span {
        width: 6px;
        height: 6px;
        border-radius: 50%;
        background: #6d9f51;
        animation: scvThinking 1.1s infinite ease-in-out;
    }

        .scv-thinking span:nth-child(2) {
            animation-delay: .16s;
        }

        .scv-thinking span:nth-child(3) {
            animation-delay: .32s;
        }

@keyframes scvThinking {
    0%, 60%, 100% {
        transform: translateY(0);
        opacity: .45;
    }

    30% {
        transform: translateY(-5px);
        opacity: 1;
    }
}

/* ============================================================
       AUTOMATIC LISTENING
       ============================================================ */

.scv-listening {
    position: absolute;
    left: 50%;
    bottom: 17px;
    transform: translateX(-50%);
    display: flex;
    align-items: center;
    gap: 10px;
    min-width: 225px;
    justify-content: center;
    padding: 10px 16px;
    border-radius: 999px;
    background: rgba(255,255,255,.94);
    border: 1px solid rgba(70,112,59,.12);
    box-shadow: 0 8px 22px rgba(48,91,48,.10);
    color: #52764e;
    font-size: 11px;
    font-weight: 800;
    opacity: 0;
    pointer-events: none;
    transition: opacity .2s ease;
    backdrop-filter: blur(12px);
}

    .scv-listening.scv-active {
        opacity: 1;
    }

.scv-mic-icon {
    width: 27px;
    height: 27px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #dcedd3;
    color: #4e873c;
}

.scv-listening-bars {
    display: flex;
    align-items: center;
    gap: 2px;
    height: 18px;
}

    .scv-listening-bars span {
        width: 2px;
        border-radius: 5px;
        background: #73a957;
        height: 6px;
    }

.scv-listening.scv-active .scv-listening-bars span {
    animation: scvListen .7s ease-in-out infinite alternate;
}

.scv-listening-bars span:nth-child(2) {
    animation-delay: .08s;
}

.scv-listening-bars span:nth-child(3) {
    animation-delay: .16s;
}

.scv-listening-bars span:nth-child(4) {
    animation-delay: .24s;
}

.scv-listening-bars span:nth-child(5) {
    animation-delay: .32s;
}

@keyframes scvListen {
    from {
        height: 5px;
    }

    to {
        height: 17px;
    }
}

/* ============================================================
       FOOTER
       ============================================================ */

.scv-footer {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    padding: 12px 16px;
    background: rgba(247,251,245,.96);
    border-top: 1px solid rgba(49,96,55,.08);
    color: #769073;
    font-size: 10px;
}

    .scv-footer i {
        color: #6fa34e;
    }

@media (max-width: 650px) {

    .scv-interview-page {
        padding: 0;
    }

    .scv-shell {
        border-radius: 0;
        min-height: 100vh;
    }

    .scv-chat {
        min-height: calc(100vh - 125px);
        max-height: none;
    }

    .scv-header {
        padding: 14px;
    }

    .scv-subtitle {
        display: none;
    }

    .scv-bubble {
        max-width: 88%;
    }

    .scv-status {
        padding: 6px 9px;
    }
}

/* ============================================================
           PAGE
           ============================================================ */

.sir-page {
    min-height: 100vh;
    padding: 30px;
    background: #f3f8f4;
    color: #123d22;
}


/* ============================================================
           HEADER
           ============================================================ */

.sir-header {
    max-width: 1500px;
    margin: 0 auto 24px;
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    gap: 30px;
}

.sir-header-left {
    flex: 1;
}

.sir-back-button {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    color: #155c2d;
    text-decoration: none;
    font-weight: 700;
    margin-bottom: 20px;
}

    .sir-back-button:hover {
        color: #0b3d1b;
    }

.sir-eyebrow,
.sir-section-eyebrow {
    color: #64806d;
    font-size: 11px;
    font-weight: 800;
    letter-spacing: 1.4px;
    text-transform: uppercase;
}

.sir-eyebrow {
    display: flex;
    align-items: center;
    gap: 7px;
    margin-bottom: 8px;
}

.sir-header h1 {
    margin: 0;
    font-size: 34px;
    font-weight: 800;
    color: #123d22;
}

.sir-header p {
    margin: 8px 0 0;
    color: #718277;
    max-width: 760px;
    line-height: 1.6;
}

.sir-header-reference {
    min-width: 220px;
    padding: 18px 20px;
    border: 1px solid #dce9df;
    border-radius: 18px;
    background: rgba(255,255,255,.85);
    text-align: right;
}

    .sir-header-reference span {
        display: block;
        color: #718277;
        font-size: 10px;
        font-weight: 800;
        letter-spacing: 1px;
    }

    .sir-header-reference strong {
        display: block;
        margin-top: 6px;
        color: #155c2d;
        font-size: 20px;
    }


/* ============================================================
           ALERT
           ============================================================ */

.sir-alert {
    max-width: 1500px;
    margin: 0 auto 20px;
    padding: 15px 18px;
    border-radius: 15px;
    display: flex;
    align-items: center;
    gap: 10px;
    font-weight: 600;
}

.sir-alert-success {
    background: #e8f7ec;
    color: #155c2d;
    border: 1px solid #bde3c6;
}

.sir-alert-error {
    background: #fff0f0;
    color: #a32929;
    border: 1px solid #f0c5c5;
}


/* ============================================================
           COMMON CARD
           ============================================================ */

.sir-card {
    background: rgba(255,255,255,.94);
    border: 1px solid #dce9df;
    border-radius: 22px;
    box-shadow: 0 12px 35px rgba(18,61,34,.055);
    padding: 24px;
}

.sir-card-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    gap: 20px;
    margin-bottom: 22px;
}

    .sir-card-header h2 {
        margin: 5px 0 0;
        color: #123d22;
        font-size: 21px;
        font-weight: 800;
    }

.sir-card-header-icon {
    width: 44px;
    height: 44px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 14px;
    background: #eaffc7;
    color: #155c2d;
    font-size: 20px;
}


/* ============================================================
           CANDIDATE
           ============================================================ */

.sir-candidate-card {
    max-width: 1500px;
    margin: 0 auto 20px;
    display: flex;
    justify-content: space-between;
    gap: 30px;
    align-items: center;
}

.sir-candidate-main {
    display: flex;
    align-items: center;
    gap: 18px;
}

.sir-avatar {
    width: 76px;
    height: 76px;
    border-radius: 22px;
    overflow: hidden;
    background: #eaffc7;
    color: #155c2d;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 32px;
    flex-shrink: 0;
}

    .sir-avatar img {
        width: 100%;
        height: 100%;
        object-fit: cover;
    }

.sir-candidate-info h2 {
    margin: 4px 0 4px;
    font-size: 26px;
    color: #123d22;
}

.sir-candidate-info p {
    margin: 0;
    color: #718277;
    font-weight: 600;
}

.sir-meta-row {
    display: flex;
    flex-wrap: wrap;
    gap: 15px;
    margin-top: 10px;
    color: #718277;
    font-size: 13px;
}

    .sir-meta-row span {
        display: inline-flex;
        align-items: center;
        gap: 6px;
    }

    .sir-meta-row i {
        color: #155c2d;
    }

.sir-candidate-statuses {
    display: flex;
    gap: 10px;
    flex-wrap: wrap;
}

.sir-status-box {
    min-width: 120px;
    padding: 13px 15px;
    border-radius: 14px;
    background: #f4f8f5;
    border: 1px solid #e1ebe4;
}

    .sir-status-box span {
        display: block;
        font-size: 9px;
        letter-spacing: 1px;
        font-weight: 800;
        color: #718277;
    }

    .sir-status-box strong {
        display: block;
        margin-top: 5px;
        color: #155c2d;
        font-size: 13px;
    }


/* ============================================================
           SCORE CARDS
           ============================================================ */

.sir-score-grid {
    max-width: 1500px;
    margin: 0 auto 20px;
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 15px;
}

.sir-score-card {
    padding: 18px;
    background: #fff;
    border: 1px solid #dce9df;
    border-radius: 18px;
    display: flex;
    align-items: center;
    gap: 13px;
}

.sir-score-icon {
    width: 44px;
    height: 44px;
    border-radius: 13px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #eaffc7;
    color: #155c2d;
    font-size: 19px;
}

.sir-score-card span {
    display: block;
    color: #718277;
    font-size: 9px;
    font-weight: 800;
    letter-spacing: 1px;
}

.sir-score-card strong {
    display: block;
    margin-top: 4px;
    font-size: 20px;
    color: #123d22;
}


/* ============================================================
           MAIN GRID
           ============================================================ */

.sir-main-grid {
    max-width: 1500px;
    margin: 0 auto;
    display: grid;
    grid-template-columns: minmax(0, 1.25fr) minmax(400px, .75fr);
    gap: 20px;
    align-items: start;
}

.sir-main-left,
.sir-main-right {
    display: flex;
    flex-direction: column;
    gap: 20px;
}


/* ============================================================
           ATS
           ============================================================ */

.sir-evaluation-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 12px;
}

.sir-evaluation-item {
    padding: 16px;
    border-radius: 15px;
    background: #f4f8f5;
    border: 1px solid #e2ebe4;
}

    .sir-evaluation-item span {
        display: block;
        color: #718277;
        font-size: 10px;
        font-weight: 800;
        letter-spacing: .8px;
    }

    .sir-evaluation-item strong {
        display: block;
        margin-top: 7px;
        color: #155c2d;
        font-size: 18px;
    }

.sir-evaluated-date {
    margin-top: 15px;
    color: #718277;
    font-size: 12px;
    display: flex;
    gap: 7px;
    align-items: center;
}


/* ============================================================
           CV
           ============================================================ */

.sir-cv-title {
    font-size: 19px;
    font-weight: 800;
    color: #155c2d;
    margin-bottom: 18px;
}

.sir-cv-summary {
    padding: 16px;
    border-radius: 15px;
    background: #f4f8f5;
    margin-bottom: 15px;
}

    .sir-cv-summary span {
        display: block;
        color: #718277;
        font-size: 10px;
        letter-spacing: 1px;
        font-weight: 800;
    }

    .sir-cv-summary p {
        margin: 8px 0 0;
        color: #314d3a;
        line-height: 1.65;
    }

.sir-cv-section {
    margin-top: 25px;
}

    .sir-cv-section h3 {
        display: flex;
        align-items: center;
        gap: 8px;
        color: #123d22;
        font-size: 16px;
        margin: 0 0 13px;
    }

        .sir-cv-section h3 i {
            color: #155c2d;
        }

.sir-skill-list {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
}

.sir-skill {
    padding: 8px 11px;
    border-radius: 10px;
    background: #eaffc7;
    color: #155c2d;
    font-size: 12px;
    font-weight: 700;
}

.sir-timeline-item {
    position: relative;
    display: flex;
    gap: 13px;
    padding-bottom: 18px;
}

.sir-timeline-dot {
    width: 10px;
    height: 10px;
    margin-top: 6px;
    border-radius: 50%;
    background: #155c2d;
    flex-shrink: 0;
}

.sir-timeline-item strong,
.sir-information-row strong {
    display: block;
    color: #123d22;
}

.sir-timeline-item span,
.sir-timeline-item small,
.sir-information-row span {
    display: block;
    color: #718277;
    margin-top: 3px;
}

.sir-timeline-item p {
    margin: 7px 0 0;
    color: #45594b;
    line-height: 1.55;
    font-size: 13px;
}

.sir-information-row {
    padding: 13px 0;
    border-bottom: 1px solid #edf2ee;
    display: flex;
    justify-content: space-between;
    gap: 15px;
}

    .sir-information-row:last-child {
        border-bottom: 0;
    }

.sir-cover-message {
    padding: 18px;
    background: #f4f8f5;
    border-radius: 15px;
    color: #314d3a;
    line-height: 1.7;
    white-space: pre-line;
}


/* ============================================================
           INTERVIEW
           ============================================================ */

.sir-interview-status {
    padding: 15px;
    background: #f4f8f5;
    border-radius: 16px;
    display: flex;
    align-items: center;
    gap: 13px;
}

.sir-interview-status-icon {
    width: 44px;
    height: 44px;
    border-radius: 13px;
    background: #eaffc7;
    color: #155c2d;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 19px;
}

.sir-interview-status strong {
    display: block;
    color: #123d22;
}

.sir-interview-status span {
    display: block;
    color: #718277;
    margin-top: 3px;
    font-size: 12px;
}

.sir-interview-counts {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 10px;
    margin-top: 12px;
}

    .sir-interview-counts > div {
        padding: 13px;
        text-align: center;
        border-radius: 14px;
        border: 1px solid #e1ebe4;
    }

    .sir-interview-counts strong {
        display: block;
        color: #155c2d;
        font-size: 20px;
    }

    .sir-interview-counts span {
        display: block;
        color: #718277;
        font-size: 10px;
        margin-top: 3px;
    }


/* ============================================================
           TRANSCRIPT
           ============================================================ */

.sir-transcript {
    display: flex;
    flex-direction: column;
    gap: 17px;
}

.sir-transcript-item {
    display: flex;
    gap: 12px;
}

.sir-question-number {
    width: 30px;
    height: 30px;
    border-radius: 10px;
    background: #eaffc7;
    color: #155c2d;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 12px;
    font-weight: 800;
    flex-shrink: 0;
}

.sir-transcript-content {
    flex: 1;
    min-width: 0;
}

.sir-question {
    padding: 13px;
    border-radius: 14px;
    background: #f4f8f5;
}

    .sir-question span {
        display: block;
        color: #718277;
        font-size: 9px;
        font-weight: 800;
        letter-spacing: 1px;
    }

    .sir-question p {
        margin: 6px 0 0;
        color: #123d22;
        line-height: 1.5;
        font-weight: 650;
    }

.sir-answer {
    margin-top: 8px;
    padding: 14px;
    border-radius: 14px;
    background: #eaffc7;
}

.sir-answer-label {
    display: flex;
    align-items: center;
    gap: 6px;
    color: #155c2d;
    font-size: 9px;
    font-weight: 800;
    letter-spacing: .8px;
}

.sir-answer p {
    margin: 8px 0 0;
    color: #244b31;
    line-height: 1.65;
    white-space: pre-line;
}


/* ============================================================
           DECISION
           ============================================================ */

.sir-decision-description {
    color: #53675a;
    line-height: 1.6;
    margin-top: 0;
}

.sir-decision-actions {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 10px;
    margin-top: 18px;
}

    .sir-decision-actions form {
        margin: 0;
    }

.sir-decision-button {
    width: 100%;
    min-height: 52px;
    border: 0;
    border-radius: 14px;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    font-weight: 800;
    transition: .2s ease;
}

.sir-approve-button {
    background: #155c2d;
    color: #eaffc7;
}

    .sir-approve-button:hover {
        background: #0b3d1b;
    }

.sir-reject-button {
    background: #fff0f0;
    color: #a32929;
    border: 1px solid #efc7c7;
}

    .sir-reject-button:hover {
        background: #ffe4e4;
    }

.sir-decision-warning {
    margin-top: 14px;
    padding: 12px;
    border-radius: 12px;
    background: #f8faf8;
    color: #718277;
    font-size: 11px;
    display: flex;
    gap: 7px;
    line-height: 1.5;
}

.sir-decision-current {
    padding: 17px;
    border-radius: 15px;
    display: flex;
    gap: 12px;
    align-items: center;
}

    .sir-decision-current i {
        font-size: 24px;
    }

    .sir-decision-current strong {
        display: block;
    }

    .sir-decision-current span {
        display: block;
        margin-top: 3px;
        font-size: 12px;
    }

.sir-decision-approved {
    background: #e8f7ec;
    color: #155c2d;
}

.sir-decision-rejected {
    background: #fff0f0;
    color: #a32929;
}


/* ============================================================
           EMPTY
           ============================================================ */

.sir-empty {
    text-align: center;
    padding: 35px 20px;
    color: #718277;
}

    .sir-empty i {
        display: block;
        font-size: 35px;
        margin-bottom: 10px;
        color: #9aad9f;
    }

    .sir-empty strong {
        display: block;
        color: #314d3a;
    }

    .sir-empty p {
        margin: 6px 0 0;
        font-size: 13px;
    }


/* ============================================================
           RESPONSIVE
           ============================================================ */

@media (max-width: 1100px) {

    .sir-main-grid {
        grid-template-columns: 1fr;
    }

    .sir-candidate-card {
        align-items: flex-start;
        flex-direction: column;
    }

    .sir-score-grid {
        grid-template-columns: repeat(2, 1fr);
    }
}


@media (max-width: 700px) {

    .sir-page {
        padding: 18px;
    }

    .sir-header {
        flex-direction: column;
        align-items: stretch;
    }

    .sir-header-reference {
        text-align: left;
    }

    .sir-score-grid,
    .sir-evaluation-grid {
        grid-template-columns: 1fr;
    }

    .sir-candidate-main {
        align-items: flex-start;
    }

    .sir-candidate-statuses {
        width: 100%;
    }

    .sir-status-box {
        flex: 1;
    }

    .sir-decision-actions {
        grid-template-columns: 1fr;
    }

    .sir-information-row {
        flex-direction: column;
    }
}
