/* ================================================================
   SWIFTCARE INTERVIEW REVIEW
   COMPLETE PAGE CSS
   ================================================================ */

:root {
    --sir-bg: #eef8f1;
    --sir-bg-soft: #f6fbf7;
    --sir-card: #ffffff;
    --sir-card-soft: #f8fcf9;
    --sir-green-950: #123d2a;
    --sir-green-900: #174d35;
    --sir-green-800: #1e6544;
    --sir-green-700: #287a50;
    --sir-green-600: #32945f;
    --sir-green-500: #4eae72;
    --sir-lime: #b9e769;
    --sir-lime-dark: #8ec944;
    --sir-text: #173a29;
    --sir-text-dark: #102d20;
    --sir-text-soft: #557061;
    --sir-text-muted: #71877a;
    --sir-border: #d8e9dc;
    --sir-border-dark: #c5ddcb;
    --sir-success: #21834d;
    --sir-success-bg: #eaf8ef;
    --sir-warning: #b87916;
    --sir-warning-bg: #fff7e6;
    --sir-danger: #b64040;
    --sir-danger-bg: #fff0f0;
    --sir-blue: #3976a8;
    --sir-blue-bg: #edf6fd;
    --sir-purple: #7651a8;
    --sir-purple-bg: #f4effb;
    --sir-shadow-sm: 0 4px 14px rgba(24, 76, 48, 0.06);
    --sir-shadow: 0 12px 35px rgba(24, 76, 48, 0.08);
    --sir-shadow-lg: 0 20px 55px rgba(24, 76, 48, 0.11);
    --sir-radius-sm: 10px;
    --sir-radius: 16px;
    --sir-radius-lg: 22px;
}


/* ================================================================
   PAGE
   ================================================================ */

.sir-page {
    width: 100%;
    max-width: 1500px;
    margin: 0 auto;
    padding: 30px 28px 70px;
    color: var(--sir-text);
    font-family: inherit;
}

    .sir-page *,
    .sir-page *::before,
    .sir-page *::after {
        box-sizing: border-box;
    }

    .sir-page button,
    .sir-page input,
    .sir-page textarea {
        font: inherit;
    }


/* ================================================================
   ALERTS
   ================================================================ */

.sir-alert {
    display: flex;
    align-items: center;
    gap: 15px;
    width: 100%;
    margin-bottom: 22px;
    padding: 15px 18px;
    border: 1px solid transparent;
    border-radius: var(--sir-radius);
    box-shadow: var(--sir-shadow-sm);
    animation: sirAlertIn 0.35s ease;
}

.sir-alert-success {
    background: var(--sir-success-bg);
    border-color: #c8e9d3;
}

.sir-alert-error {
    background: var(--sir-danger-bg);
    border-color: #f0cccc;
}

.sir-alert-icon {
    width: 40px;
    height: 40px;
    flex: 0 0 40px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 12px;
    font-size: 18px;
}

.sir-alert-success .sir-alert-icon {
    color: var(--sir-success);
    background: #d9f2e1;
}

.sir-alert-error .sir-alert-icon {
    color: var(--sir-danger);
    background: #f9dddd;
}

.sir-alert-content {
    display: flex;
    flex-direction: column;
    gap: 2px;
    min-width: 0;
    flex: 1;
}

    .sir-alert-content strong {
        color: var(--sir-text-dark);
        font-size: 14px;
        font-weight: 800;
    }

    .sir-alert-content span {
        color: var(--sir-text-soft);
        font-size: 13px;
        line-height: 1.5;
    }

.sir-alert-close {
    width: 34px;
    height: 34px;
    border: 0;
    background: transparent;
    color: var(--sir-text-muted);
    border-radius: 9px;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: 0.2s ease;
}

    .sir-alert-close:hover {
        color: var(--sir-danger);
        background: rgba(182, 64, 64, 0.08);
    }


/* ================================================================
   HEADER
   ================================================================ */

.sir-header {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 28px;
    padding: 28px 30px;
    margin-bottom: 22px;
    border: 1px solid var(--sir-border);
    border-radius: var(--sir-radius-lg);
    background: radial-gradient( circle at 88% 10%, rgba(185, 231, 105, 0.20), transparent 30% ), linear-gradient( 135deg, #ffffff 0%, #f5fbf6 100% );
    box-shadow: var(--sir-shadow);
    overflow: hidden;
}

    .sir-header::before {
        content: "";
        position: absolute;
        left: 0;
        top: 0;
        bottom: 0;
        width: 5px;
        background: linear-gradient( 180deg, var(--sir-lime), var(--sir-green-600) );
    }

.sir-header-main {
    display: flex;
    align-items: center;
    gap: 20px;
    min-width: 0;
}

.sir-avatar {
    width: 76px;
    height: 76px;
    flex: 0 0 76px;
    border-radius: 22px;
    overflow: hidden;
    display: flex;
    align-items: center;
    justify-content: center;
    background: linear-gradient( 145deg, var(--sir-green-700), var(--sir-green-900) );
    border: 4px solid #ffffff;
    box-shadow: 0 7px 20px rgba(25, 85, 49, 0.18);
}

    .sir-avatar img {
        width: 100%;
        height: 100%;
        object-fit: cover;
    }

    .sir-avatar span {
        color: var(--sir-lime);
        font-size: 28px;
        font-weight: 900;
    }

.sir-header-information {
    min-width: 0;
}

.sir-eyebrow,
.sir-section-kicker,
.sir-action-kicker {
    display: inline-flex;
    align-items: center;
    color: var(--sir-green-700);
    font-size: 11px;
    line-height: 1;
    font-weight: 900;
    letter-spacing: 0.16em;
}

.sir-header-information h1 {
    margin: 8px 0 4px;
    color: var(--sir-green-950);
    font-size: clamp(25px, 3vw, 36px);
    line-height: 1.15;
    font-weight: 900;
    letter-spacing: -0.025em;
}

.sir-header-information p {
    margin: 0;
    color: var(--sir-text-soft);
    font-size: 15px;
    line-height: 1.5;
}

.sir-reference {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    margin-top: 9px;
    padding: 6px 10px;
    border-radius: 8px;
    background: #edf7ef;
    color: var(--sir-green-800);
    font-size: 12px;
    font-weight: 800;
}

.sir-header-status {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    flex-wrap: wrap;
    gap: 9px;
}

.sir-status-badge,
.sir-stage-badge,
.sir-success-badge,
.sir-warning-badge,
.sir-decision-ready,
.sir-ai-pending-badge {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    min-height: 34px;
    padding: 8px 12px;
    border-radius: 999px;
    font-size: 11px;
    line-height: 1;
    font-weight: 900;
    white-space: nowrap;
}

.sir-status-complete {
    background: var(--sir-success-bg);
    color: var(--sir-success);
    border: 1px solid #c8e8d2;
}

.sir-status-pending {
    background: var(--sir-warning-bg);
    color: var(--sir-warning);
    border: 1px solid #f0dcaf;
}

.sir-stage-badge {
    background: #eef5f0;
    color: var(--sir-green-800);
    border: 1px solid var(--sir-border);
}


/* ================================================================
   ACTION PANEL
   ================================================================ */

.sir-action-panel {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 25px;
    margin-bottom: 20px;
    padding: 22px 24px;
    border: 1px solid #cfe4d4;
    border-radius: var(--sir-radius);
    background: linear-gradient( 135deg, #f7fcf8 0%, #edf8f0 100% );
    box-shadow: var(--sir-shadow-sm);
}

.sir-action-information {
    display: flex;
    align-items: center;
    gap: 16px;
    min-width: 0;
}

.sir-action-icon {
    width: 52px;
    height: 52px;
    flex: 0 0 52px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 16px;
    background: linear-gradient( 145deg, var(--sir-green-800), var(--sir-green-600) );
    color: var(--sir-lime);
    font-size: 23px;
    box-shadow: 0 8px 20px rgba(35, 105, 66, 0.16);
}

.sir-action-information h2 {
    margin: 6px 0 4px;
    color: var(--sir-green-950);
    font-size: 18px;
    font-weight: 850;
}

.sir-action-information p {
    max-width: 720px;
    margin: 0;
    color: var(--sir-text-soft);
    font-size: 13px;
    line-height: 1.55;
}

.sir-evaluation-form {
    flex: 0 0 auto;
}

.sir-run-evaluation-button {
    position: relative;
    min-width: 215px;
    min-height: 46px;
    padding: 0 20px;
    border: 0;
    border-radius: 12px;
    background: linear-gradient( 135deg, var(--sir-green-800), var(--sir-green-600) );
    color: #ffffff;
    cursor: pointer;
    font-size: 13px;
    font-weight: 850;
    box-shadow: 0 8px 20px rgba(30, 101, 68, 0.20);
    transition: transform 0.2s ease, box-shadow 0.2s ease, opacity 0.2s ease;
}

    .sir-run-evaluation-button:hover:not(:disabled) {
        transform: translateY(-2px);
        box-shadow: 0 12px 28px rgba(30, 101, 68, 0.25);
    }

    .sir-run-evaluation-button:disabled {
        cursor: not-allowed;
        opacity: 0.72;
    }

.sir-button-normal,
.sir-button-loading {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 9px;
}

.sir-button-loading {
    display: none;
}

.sir-evaluation-loading .sir-button-normal {
    display: none;
}

.sir-evaluation-loading .sir-button-loading {
    display: inline-flex;
}

.sir-spinner {
    width: 17px;
    height: 17px;
    border: 2px solid rgba(255, 255, 255, 0.35);
    border-top-color: #ffffff;
    border-radius: 50%;
    animation: sirSpin 0.75s linear infinite;
}


/* ================================================================
   EVALUATION META
   ================================================================ */

.sir-evaluation-meta {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 1px;
    margin-bottom: 22px;
    overflow: hidden;
    border: 1px solid var(--sir-border);
    border-radius: var(--sir-radius);
    background: var(--sir-border);
}

.sir-meta-item {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 15px;
    padding: 14px 17px;
    background: #ffffff;
}

    .sir-meta-item span {
        display: inline-flex;
        align-items: center;
        gap: 7px;
        color: var(--sir-text-muted);
        font-size: 11px;
        font-weight: 800;
        text-transform: uppercase;
        letter-spacing: 0.05em;
    }

    .sir-meta-item strong {
        color: var(--sir-green-900);
        font-size: 12px;
        font-weight: 850;
    }

.sir-meta-good {
    color: var(--sir-success) !important;
}

.sir-meta-running {
    color: var(--sir-warning) !important;
}


/* ================================================================
   SUMMARY CARDS
   ================================================================ */

.sir-summary-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 15px;
    margin-bottom: 24px;
}

.sir-summary-card {
    display: flex;
    align-items: center;
    gap: 14px;
    min-height: 108px;
    padding: 19px;
    border: 1px solid var(--sir-border);
    border-radius: var(--sir-radius);
    background: var(--sir-card);
    box-shadow: var(--sir-shadow-sm);
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}

    .sir-summary-card:hover {
        transform: translateY(-2px);
        box-shadow: var(--sir-shadow);
    }

.sir-summary-icon {
    width: 45px;
    height: 45px;
    flex: 0 0 45px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 13px;
    background: #edf7ef;
    color: var(--sir-green-700);
    font-size: 19px;
}

.sir-summary-card span {
    display: block;
    margin-bottom: 4px;
    color: var(--sir-text-muted);
    font-size: 9px;
    font-weight: 900;
    letter-spacing: 0.12em;
}

.sir-summary-card strong {
    display: block;
    color: var(--sir-green-950);
    font-size: 23px;
    line-height: 1.15;
    font-weight: 900;
}

.sir-summary-card small {
    display: block;
    margin-top: 4px;
    color: var(--sir-text-muted);
    font-size: 10px;
}

.sir-summary-ai {
    border-color: #d2e7bf;
    background: linear-gradient( 135deg, #ffffff, #f6fbe9 );
}

    .sir-summary-ai .sir-summary-icon {
        background: #edf8d9;
        color: var(--sir-green-800);
    }

.sir-evaluated-value {
    color: var(--sir-green-700) !important;
}

.sir-not-evaluated {
    color: var(--sir-text-muted) !important;
    font-size: 15px !important;
}


/* ================================================================
   GENERAL SECTIONS
   ================================================================ */

.sir-section {
    margin-bottom: 24px;
    padding: 26px;
    border: 1px solid var(--sir-border);
    border-radius: var(--sir-radius-lg);
    background: var(--sir-card);
    box-shadow: var(--sir-shadow-sm);
}

.sir-section-header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 25px;
    margin-bottom: 24px;
}

    .sir-section-header h2 {
        margin: 7px 0 6px;
        color: var(--sir-green-950);
        font-size: 22px;
        line-height: 1.2;
        font-weight: 900;
        letter-spacing: -0.015em;
    }

    .sir-section-header p {
        max-width: 850px;
        margin: 0;
        color: var(--sir-text-soft);
        font-size: 13px;
        line-height: 1.6;
    }

.sir-section-stat {
    min-width: 100px;
    padding: 11px 14px;
    border-radius: 12px;
    background: #f1f8f2;
    border: 1px solid var(--sir-border);
    text-align: center;
}

    .sir-section-stat strong {
        display: block;
        color: var(--sir-green-800);
        font-size: 22px;
        font-weight: 900;
    }

    .sir-section-stat span {
        color: var(--sir-text-muted);
        font-size: 9px;
        font-weight: 800;
        text-transform: uppercase;
    }


/* ================================================================
   SCORE OVERVIEW
   ================================================================ */

.sir-score-overview {
    display: grid;
    grid-template-columns: 245px 1fr;
    gap: 35px;
    align-items: center;
}

.sir-main-score {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
}

.sir-score-ring {
    --sir-score: 0;
    position: relative;
    width: 170px;
    height: 170px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    background: conic-gradient( var(--sir-green-600) calc(var(--sir-score) * 1%), #e2eee5 calc(var(--sir-score) * 1%) );
    box-shadow: 0 12px 28px rgba(35, 105, 66, 0.10);
}

    .sir-score-ring::before {
        content: "";
        position: absolute;
        inset: 10px;
        border-radius: 50%;
        background: #ffffff;
    }

.sir-score-ring-inner {
    position: relative;
    z-index: 1;
    display: flex;
    align-items: baseline;
    gap: 3px;
}

    .sir-score-ring-inner strong {
        color: var(--sir-green-950);
        font-size: 43px;
        line-height: 1;
        font-weight: 900;
        letter-spacing: -0.04em;
    }

    .sir-score-ring-inner span {
        color: var(--sir-text-muted);
        font-size: 12px;
        font-weight: 800;
    }

.sir-score-caption {
    margin-top: 13px;
    color: var(--sir-text-soft);
    font-size: 11px;
    font-weight: 850;
    text-transform: uppercase;
    letter-spacing: 0.08em;
}

.sir-score-details {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 14px;
}

.sir-score-detail-card {
    min-height: 110px;
    padding: 17px;
    border: 1px solid var(--sir-border);
    border-radius: 14px;
    background: var(--sir-card-soft);
}

    .sir-score-detail-card > span {
        display: block;
        margin-bottom: 8px;
        color: var(--sir-text-muted);
        font-size: 10px;
        font-weight: 850;
        text-transform: uppercase;
        letter-spacing: 0.08em;
    }

    .sir-score-detail-card > strong {
        display: block;
        color: var(--sir-green-900);
        font-size: 20px;
        font-weight: 900;
    }

    .sir-score-detail-card small {
        display: block;
        margin-top: 5px;
        color: var(--sir-text-muted);
        font-size: 10px;
    }

.sir-recommendation-value {
    color: var(--sir-green-700) !important;
}

.sir-progress {
    width: 100%;
    height: 7px;
    overflow: hidden;
    margin-top: 11px;
    border-radius: 99px;
    background: #e4eee7;
}

.sir-progress-fill {
    height: 100%;
    min-width: 0;
    border-radius: inherit;
    background: linear-gradient( 90deg, var(--sir-green-600), var(--sir-lime-dark) );
    transition: width 0.6s ease;
}

.sir-evaluation-state {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    padding: 9px 13px;
    border-radius: 999px;
    font-size: 11px;
    font-weight: 850;
}

.sir-evaluation-state-complete {
    color: var(--sir-success);
    background: var(--sir-success-bg);
    border: 1px solid #c9e8d3;
}

.sir-evaluation-state-pending {
    color: var(--sir-warning);
    background: var(--sir-warning-bg);
    border: 1px solid #f1ddb1;
}

.sir-evaluation-disclaimer {
    display: flex;
    gap: 12px;
    margin-top: 25px;
    padding: 15px 17px;
    border-radius: 13px;
    background: #f3f8f4;
    border: 1px solid var(--sir-border);
}

    .sir-evaluation-disclaimer > i {
        color: var(--sir-green-700);
        font-size: 17px;
        margin-top: 2px;
    }

    .sir-evaluation-disclaimer strong {
        display: block;
        color: var(--sir-green-900);
        font-size: 12px;
        font-weight: 900;
    }

    .sir-evaluation-disclaimer p {
        margin: 4px 0 0;
        color: var(--sir-text-soft);
        font-size: 11px;
        line-height: 1.55;
    }


/* ================================================================
   REQUIRED SKILLS SUMMARY
   ================================================================ */

.sir-skill-summary {
    display: grid;
    grid-template-columns: 120px 140px 140px 1fr;
    gap: 12px;
    margin-bottom: 20px;
    padding: 15px;
    border-radius: 14px;
    background: #f5faf6;
    border: 1px solid var(--sir-border);
}

    .sir-skill-summary > div:not(.sir-skill-summary-progress) {
        padding: 4px 13px;
        border-right: 1px solid var(--sir-border);
    }

    .sir-skill-summary span {
        display: block;
        margin-bottom: 5px;
        color: var(--sir-text-muted);
        font-size: 9px;
        font-weight: 850;
        letter-spacing: 0.08em;
    }

    .sir-skill-summary strong {
        color: var(--sir-green-800);
        font-size: 20px;
        font-weight: 900;
    }

.sir-skill-summary-progress {
    padding: 5px 12px;
}

    .sir-skill-summary-progress > span {
        margin-bottom: 8px;
    }

.sir-required-skills {
    display: flex;
    flex-direction: column;
    gap: 15px;
}

.sir-required-skill-card {
    padding: 20px;
    border: 1px solid var(--sir-border);
    border-radius: 16px;
    background: #ffffff;
}

.sir-required-skill-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 20px;
    margin-bottom: 17px;
}

.sir-required-skill-name {
    display: flex;
    align-items: center;
    gap: 12px;
    min-width: 0;
}

.sir-skill-icon {
    width: 39px;
    height: 39px;
    flex: 0 0 39px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 11px;
    color: var(--sir-green-700);
    background: #edf7ef;
}

.sir-required-skill-name strong {
    display: block;
    color: var(--sir-green-950);
    font-size: 14px;
    font-weight: 900;
}

.sir-required-skill-name span {
    display: block;
    margin-top: 3px;
    color: var(--sir-text-muted);
    font-size: 10px;
}

.sir-evaluation-badge {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 7px 10px;
    border-radius: 999px;
    font-size: 10px;
    font-weight: 850;
    white-space: nowrap;
}

.sir-evaluation-badge-complete {
    color: var(--sir-success);
    background: var(--sir-success-bg);
}

.sir-evaluation-badge-pending {
    color: var(--sir-warning);
    background: var(--sir-warning-bg);
}

.sir-skill-evidence-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 12px;
}

.sir-evidence-card {
    min-width: 0;
    padding: 16px;
    border-radius: 13px;
    background: #f8fbf9;
    border: 1px solid var(--sir-border);
}

.sir-ai-evidence-card {
    background: linear-gradient( 145deg, #f9fcf5, #f4f9eb );
    border-color: #d9e8c8;
}

.sir-evidence-heading {
    display: flex;
    align-items: center;
    gap: 8px;
    padding-bottom: 10px;
    margin-bottom: 11px;
    border-bottom: 1px solid var(--sir-border);
    color: var(--sir-green-800);
    font-size: 11px;
    font-weight: 900;
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

    .sir-evidence-heading i {
        font-size: 15px;
    }

.sir-evidence-found {
    display: flex;
    align-items: center;
    gap: 7px;
    color: var(--sir-success);
    font-size: 11px;
    font-weight: 850;
}

.sir-evidence-card p {
    margin: 9px 0 0;
    color: var(--sir-text-soft);
    font-size: 11px;
    line-height: 1.6;
}

.sir-evidence-empty {
    display: flex;
    align-items: flex-start;
    gap: 8px;
    color: var(--sir-text-muted);
    font-size: 11px;
    line-height: 1.5;
}

    .sir-evidence-empty i {
        flex: 0 0 auto;
        margin-top: 2px;
    }

.sir-ai-score-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 12px;
}

    .sir-ai-score-row > div {
        padding: 9px 10px;
        border-radius: 9px;
        background: #ffffff;
        border: 1px solid #e1ead9;
    }

.sir-mini-label {
    display: block;
    margin-bottom: 4px;
    color: var(--sir-text-muted);
    font-size: 8px;
    font-weight: 900;
    letter-spacing: 0.08em;
}

.sir-ai-score-row strong {
    color: var(--sir-green-800);
    font-size: 17px;
    font-weight: 900;
}

.sir-ai-progress {
    margin-top: 11px;
}

.sir-ai-assessment {
    display: flex;
    justify-content: space-between;
    gap: 10px;
    margin-top: 13px;
    padding-top: 11px;
    border-top: 1px solid #dce8d5;
}

    .sir-ai-assessment span,
    .sir-ai-reasoning > span {
        color: var(--sir-text-muted);
        font-size: 9px;
        font-weight: 850;
        text-transform: uppercase;
    }

    .sir-ai-assessment strong {
        color: var(--sir-green-800);
        font-size: 10px;
        font-weight: 900;
        text-align: right;
    }

.sir-ai-reasoning {
    margin-top: 11px;
}

    .sir-ai-reasoning p {
        margin-top: 5px;
    }


/* ================================================================
   EMPTY STATE
   ================================================================ */

.sir-empty-state {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    min-height: 210px;
    padding: 30px;
    text-align: center;
    border: 1px dashed var(--sir-border-dark);
    border-radius: 15px;
    background: #f9fcfa;
}

    .sir-empty-state > i {
        width: 50px;
        height: 50px;
        display: flex;
        align-items: center;
        justify-content: center;
        margin-bottom: 12px;
        border-radius: 15px;
        background: #edf7ef;
        color: var(--sir-green-600);
        font-size: 21px;
    }

    .sir-empty-state h3 {
        margin: 0 0 5px;
        color: var(--sir-green-900);
        font-size: 15px;
        font-weight: 900;
    }

    .sir-empty-state p {
        max-width: 500px;
        margin: 0;
        color: var(--sir-text-muted);
        font-size: 12px;
        line-height: 1.55;
    }


/* ================================================================
   COMPETENCY SECTION
   ================================================================ */

.sir-ai-pending-badge {
    color: var(--sir-warning);
    background: var(--sir-warning-bg);
    border: 1px solid #f0ddb5;
}

.sir-ai-complete-badge {
    color: var(--sir-success);
    background: var(--sir-success-bg);
    border-color: #c9e8d4;
}

.sir-competency-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 15px;
}

.sir-competency-card {
    padding: 19px;
    border: 1px solid var(--sir-border);
    border-radius: 16px;
    background: #ffffff;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}

    .sir-competency-card:hover {
        transform: translateY(-2px);
        box-shadow: var(--sir-shadow);
    }

.sir-competency-top {
    display: flex;
    align-items: flex-start;
    gap: 12px;
}

.sir-competency-icon {
    width: 41px;
    height: 41px;
    flex: 0 0 41px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 12px;
    color: var(--sir-green-700);
    background: #edf7ef;
    font-size: 17px;
}

.sir-competency-top h3 {
    margin: 1px 0 4px;
    color: var(--sir-green-950);
    font-size: 14px;
    font-weight: 900;
}

.sir-competency-top p {
    margin: 0;
    color: var(--sir-text-muted);
    font-size: 10px;
    line-height: 1.5;
}

.sir-competency-score {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 10px;
    margin-top: 18px;
}

    .sir-competency-score > div {
        padding: 10px;
        border-radius: 10px;
        background: #f6faf7;
        border: 1px solid #e1ede4;
    }

    .sir-competency-score span {
        display: block;
        margin-bottom: 4px;
        color: var(--sir-text-muted);
        font-size: 8px;
        font-weight: 900;
        text-transform: uppercase;
    }

    .sir-competency-score strong {
        color: var(--sir-green-800);
        font-size: 18px;
        font-weight: 900;
    }

.sir-competency-bar {
    margin-top: 13px;
}

.sir-competency-bar-track {
    width: 100%;
    height: 6px;
    overflow: hidden;
    border-radius: 99px;
    background: #e7eee9;
}

.sir-competency-bar-fill {
    height: 100%;
    border-radius: inherit;
    background: linear-gradient( 90deg, var(--sir-green-600), var(--sir-lime-dark) );
    transition: width 0.6s ease;
}

.sir-competency-status {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    margin-top: 12px;
    color: var(--sir-warning);
    font-size: 9px;
    font-weight: 900;
}

.sir-competency-status-complete {
    color: var(--sir-success);
}

.sir-competency-evidence,
.sir-competency-reasoning {
    margin-top: 15px;
    padding-top: 13px;
    border-top: 1px solid var(--sir-border);
}

    .sir-competency-evidence > span,
    .sir-competency-reasoning > span {
        color: var(--sir-text-muted);
        font-size: 9px;
        font-weight: 900;
        text-transform: uppercase;
        letter-spacing: 0.06em;
    }

    .sir-competency-evidence p,
    .sir-competency-reasoning p {
        margin: 6px 0 0;
        color: var(--sir-text-soft);
        font-size: 11px;
        line-height: 1.6;
    }


/* ================================================================
   OVERALL INTERVIEW
   ================================================================ */

.sir-interview-overall {
    display: grid;
    grid-template-columns: 1fr 180px 180px;
    gap: 20px;
    align-items: center;
    margin-top: 24px;
    padding: 20px;
    border: 1px solid #d5e5c9;
    border-radius: 16px;
    background: linear-gradient( 135deg, #f9fcf5, #f2f9e8 );
}

.sir-overall-information h3 {
    margin: 5px 0 5px;
    color: var(--sir-green-950);
    font-size: 17px;
    font-weight: 900;
}

.sir-overall-information p {
    max-width: 650px;
    margin: 0;
    color: var(--sir-text-soft);
    font-size: 11px;
    line-height: 1.55;
}

.sir-overall-score,
.sir-recommendation {
    padding: 13px 15px;
    border-radius: 12px;
    background: #ffffff;
    border: 1px solid #dce8d4;
}

    .sir-overall-score span,
    .sir-recommendation span {
        display: block;
        color: var(--sir-text-muted);
        font-size: 9px;
        font-weight: 900;
        text-transform: uppercase;
    }

    .sir-overall-score strong {
        display: block;
        margin-top: 5px;
        color: var(--sir-green-700);
        font-size: 25px;
        font-weight: 900;
    }

    .sir-overall-score small {
        display: block;
        margin-top: 3px;
        color: var(--sir-text-muted);
        font-size: 9px;
    }

    .sir-recommendation strong {
        display: block;
        margin-top: 8px;
        color: var(--sir-green-800);
        font-size: 13px;
        line-height: 1.35;
        font-weight: 900;
    }


/* ================================================================
   CV PROFILE
   ================================================================ */

.sir-success-badge {
    color: var(--sir-success);
    background: var(--sir-success-bg);
    border: 1px solid #c8e7d2;
}

.sir-warning-badge {
    color: var(--sir-warning);
    background: var(--sir-warning-bg);
    border: 1px solid #f0dcae;
}

.sir-cv-warning {
    display: flex;
    align-items: flex-start;
    gap: 10px;
    margin-bottom: 18px;
    padding: 13px 15px;
    border-radius: 12px;
    background: var(--sir-warning-bg);
    border: 1px solid #f0dcae;
    color: #8a641c;
    font-size: 11px;
    line-height: 1.5;
}

    .sir-cv-warning i {
        margin-top: 2px;
    }

.sir-profile-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 12px;
}

.sir-profile-field {
    min-width: 0;
    padding: 14px;
    border: 1px solid var(--sir-border);
    border-radius: 12px;
    background: #f9fcfa;
}

    .sir-profile-field span {
        display: block;
        margin-bottom: 6px;
        color: var(--sir-text-muted);
        font-size: 9px;
        font-weight: 900;
        text-transform: uppercase;
        letter-spacing: 0.06em;
    }

    .sir-profile-field strong {
        display: block;
        color: var(--sir-green-900);
        font-size: 12px;
        line-height: 1.45;
        font-weight: 800;
        overflow-wrap: anywhere;
    }

.sir-profile-text {
    margin-top: 14px;
    padding: 16px;
    border-radius: 13px;
    border: 1px solid var(--sir-border);
    background: #f9fcfa;
}

    .sir-profile-text span {
        display: block;
        margin-bottom: 7px;
        color: var(--sir-green-800);
        font-size: 10px;
        font-weight: 900;
        text-transform: uppercase;
        letter-spacing: 0.06em;
    }

    .sir-profile-text p {
        margin: 0;
        color: var(--sir-text-soft);
        font-size: 12px;
        line-height: 1.7;
        white-space: pre-line;
    }

.sir-cv-block {
    margin-top: 18px;
}

.sir-subheading {
    margin-bottom: 10px;
    color: var(--sir-green-900);
    font-size: 12px;
    font-weight: 900;
}

.sir-skill-tags {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
}

    .sir-skill-tags span {
        display: inline-flex;
        align-items: center;
        gap: 6px;
        padding: 7px 10px;
        border-radius: 999px;
        background: #edf7ef;
        border: 1px solid #d4e8d8;
        color: var(--sir-green-800);
        font-size: 10px;
        font-weight: 800;
    }

.sir-links-block {
    display: flex;
    flex-wrap: wrap;
    gap: 9px;
    margin-top: 18px;
    padding-top: 17px;
    border-top: 1px solid var(--sir-border);
}

    .sir-links-block a {
        display: inline-flex;
        align-items: center;
        gap: 7px;
        padding: 9px 12px;
        border-radius: 10px;
        border: 1px solid var(--sir-border);
        background: #ffffff;
        color: var(--sir-green-800);
        text-decoration: none;
        font-size: 11px;
        font-weight: 800;
        transition: 0.2s ease;
    }

        .sir-links-block a:hover {
            background: #edf7ef;
            border-color: #bfd9c6;
            transform: translateY(-1px);
        }

        .sir-links-block a i:last-child {
            font-size: 9px;
            color: var(--sir-text-muted);
        }


/* ================================================================
   EXPERIENCE TIMELINE
   ================================================================ */

.sir-timeline {
    position: relative;
    margin-left: 8px;
    padding-left: 28px;
}

    .sir-timeline::before {
        content: "";
        position: absolute;
        left: 7px;
        top: 6px;
        bottom: 6px;
        width: 2px;
        background: #d8e9dc;
    }

.sir-timeline-item {
    position: relative;
    padding-bottom: 22px;
}

    .sir-timeline-item:last-child {
        padding-bottom: 0;
    }

.sir-timeline-dot {
    position: absolute;
    left: -28px;
    top: 4px;
    width: 16px;
    height: 16px;
    border-radius: 50%;
    border: 4px solid #ffffff;
    background: var(--sir-green-600);
    box-shadow: 0 0 0 2px #cfe4d4;
}

.sir-timeline-content {
    padding: 17px;
    border: 1px solid var(--sir-border);
    border-radius: 14px;
    background: #f9fcfa;
}

.sir-timeline-date {
    margin-bottom: 6px;
    color: var(--sir-green-600);
    font-size: 9px;
    font-weight: 900;
    text-transform: uppercase;
    letter-spacing: 0.06em;
}

.sir-timeline-content h3 {
    margin: 0 0 3px;
    color: var(--sir-green-950);
    font-size: 15px;
    font-weight: 900;
}

.sir-timeline-content > strong {
    display: block;
    color: var(--sir-text-soft);
    font-size: 11px;
}

.sir-timeline-content p {
    margin: 9px 0 0;
    color: var(--sir-text-soft);
    font-size: 11px;
    line-height: 1.65;
}


/* ================================================================
   EDUCATION
   ================================================================ */

.sir-education-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 13px;
}

.sir-education-card {
    display: flex;
    gap: 13px;
    padding: 17px;
    border: 1px solid var(--sir-border);
    border-radius: 14px;
    background: #f9fcfa;
}

.sir-education-icon {
    width: 42px;
    height: 42px;
    flex: 0 0 42px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 12px;
    color: var(--sir-green-700);
    background: #edf7ef;
    font-size: 18px;
}

.sir-education-card h3 {
    margin: 1px 0 4px;
    color: var(--sir-green-950);
    font-size: 13px;
    font-weight: 900;
}

.sir-education-card strong {
    display: block;
    color: var(--sir-green-700);
    font-size: 10px;
}

.sir-education-card span {
    display: block;
    margin-top: 4px;
    color: var(--sir-text-soft);
    font-size: 11px;
}

.sir-education-card small {
    display: block;
    margin-top: 5px;
    color: var(--sir-text-muted);
    font-size: 9px;
}


/* ================================================================
   CERTIFICATIONS
   ================================================================ */

.sir-certifications-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 13px;
}

.sir-certification-card {
    display: flex;
    align-items: flex-start;
    gap: 12px;
    padding: 16px;
    border: 1px solid var(--sir-border);
    border-radius: 14px;
    background: #f9fcfa;
}

.sir-certification-icon {
    width: 40px;
    height: 40px;
    flex: 0 0 40px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 11px;
    color: var(--sir-green-700);
    background: #edf7ef;
    font-size: 17px;
}

.sir-certification-card h3 {
    margin: 1px 0 4px;
    color: var(--sir-green-950);
    font-size: 12px;
    line-height: 1.4;
    font-weight: 900;
}

.sir-certification-card span {
    display: block;
    color: var(--sir-text-soft);
    font-size: 10px;
}

.sir-certification-card small {
    display: block;
    margin-top: 5px;
    color: var(--sir-text-muted);
    font-size: 9px;
}


/* ================================================================
   LANGUAGES
   ================================================================ */

.sir-language-list {
    display: flex;
    flex-wrap: wrap;
    gap: 9px;
}

    .sir-language-list span {
        display: inline-flex;
        align-items: center;
        gap: 7px;
        padding: 9px 12px;
        border-radius: 999px;
        border: 1px solid var(--sir-border);
        background: #f7fbf8;
        color: var(--sir-green-800);
        font-size: 11px;
        font-weight: 800;
    }


/* ================================================================
   INTERVIEW TRANSCRIPT
   ================================================================ */

.sir-transcript {
    display: flex;
    flex-direction: column;
    gap: 19px;
}

.sir-transcript-item {
    display: grid;
    grid-template-columns: 36px 1fr;
    gap: 14px;
}

.sir-question-number {
    width: 36px;
    height: 36px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 11px;
    background: var(--sir-green-800);
    color: var(--sir-lime);
    font-size: 12px;
    font-weight: 900;
    box-shadow: 0 5px 12px rgba(30, 101, 68, 0.14);
}

.sir-transcript-body {
    display: flex;
    flex-direction: column;
    gap: 9px;
    min-width: 0;
}

.sir-bot-message,
.sir-applicant-message {
    padding: 14px 16px;
    border-radius: 13px;
}

.sir-bot-message {
    background: #eef7f0;
    border: 1px solid #d7e9db;
}

.sir-applicant-message {
    margin-left: 25px;
    background: #f9fbfa;
    border: 1px solid var(--sir-border);
}

.sir-message-label {
    display: flex;
    align-items: center;
    gap: 7px;
    margin-bottom: 6px;
    color: var(--sir-green-800);
    font-size: 10px;
    font-weight: 900;
}

.sir-applicant-message .sir-message-label {
    color: var(--sir-text-soft);
}

.sir-message-label i {
    font-size: 13px;
}

.sir-bot-message p,
.sir-applicant-message p {
    margin: 0;
    color: var(--sir-text);
    font-size: 12px;
    line-height: 1.7;
    white-space: pre-line;
}


/* ================================================================
   FINAL DECISION
   ================================================================ */

.sir-decision-section {
    border-color: #cfe1d4;
    background: linear-gradient( 145deg, #ffffff, #f5faf6 );
}

.sir-decision-ready {
    color: var(--sir-success);
    background: var(--sir-success-bg);
    border: 1px solid #c8e7d2;
}

.sir-decision-form {
    margin-top: 5px;
}

.sir-decision-options {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 13px;
}

.sir-decision-option {
    position: relative;
    display: block;
    cursor: pointer;
}

    .sir-decision-option input {
        position: absolute;
        opacity: 0;
        pointer-events: none;
    }

.sir-decision-option-content {
    display: flex;
    align-items: flex-start;
    gap: 12px;
    height: 100%;
    padding: 16px;
    border: 1px solid var(--sir-border);
    border-radius: 14px;
    background: #ffffff;
    transition: border-color 0.2s ease, background 0.2s ease, transform 0.2s ease, box-shadow 0.2s ease;
}

.sir-decision-option:hover .sir-decision-option-content {
    transform: translateY(-2px);
    box-shadow: var(--sir-shadow-sm);
}

.sir-decision-option-icon {
    width: 39px;
    height: 39px;
    flex: 0 0 39px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 11px;
    font-size: 17px;
}

.sir-decision-option strong {
    display: block;
    margin-bottom: 4px;
    color: var(--sir-green-950);
    font-size: 13px;
    font-weight: 900;
}

.sir-decision-option span {
    display: block;
    color: var(--sir-text-muted);
    font-size: 10px;
    line-height: 1.5;
}

.sir-decision-approve .sir-decision-option-icon {
    color: var(--sir-success);
    background: var(--sir-success-bg);
}

.sir-decision-review .sir-decision-option-icon {
    color: var(--sir-warning);
    background: var(--sir-warning-bg);
}

.sir-decision-reject .sir-decision-option-icon {
    color: var(--sir-danger);
    background: var(--sir-danger-bg);
}

.sir-decision-approve.sir-decision-selected
.sir-decision-option-content {
    border-color: #8bc8a0;
    background: #f0faf3;
    box-shadow: 0 0 0 3px rgba(33, 131, 77, 0.08);
}

.sir-decision-review.sir-decision-selected
.sir-decision-option-content {
    border-color: #e2bd69;
    background: #fffaf0;
    box-shadow: 0 0 0 3px rgba(184, 121, 22, 0.08);
}

.sir-decision-reject.sir-decision-selected
.sir-decision-option-content {
    border-color: #e1a0a0;
    background: #fff5f5;
    box-shadow: 0 0 0 3px rgba(182, 64, 64, 0.08);
}

.sir-decision-notes {
    margin-top: 18px;
}

    .sir-decision-notes label {
        display: block;
        margin-bottom: 7px;
        color: var(--sir-green-900);
        font-size: 11px;
        font-weight: 900;
    }

    .sir-decision-notes textarea {
        display: block;
        width: 100%;
        min-height: 125px;
        resize: vertical;
        padding: 13px 14px;
        border: 1px solid var(--sir-border);
        border-radius: 12px;
        outline: none;
        background: #ffffff;
        color: var(--sir-text);
        font-size: 12px;
        line-height: 1.6;
        transition: border-color 0.2s ease, box-shadow 0.2s ease;
    }

        .sir-decision-notes textarea::placeholder {
            color: #9aac9f;
        }

        .sir-decision-notes textarea:focus {
            border-color: var(--sir-green-500);
            box-shadow: 0 0 0 3px rgba(78, 174, 114, 0.10);
        }

.sir-decision-actions {
    display: flex;
    justify-content: flex-end;
    margin-top: 14px;
}

.sir-save-decision {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    min-height: 44px;
    padding: 0 19px;
    border: 0;
    border-radius: 11px;
    background: var(--sir-green-800);
    color: #ffffff;
    cursor: pointer;
    font-size: 12px;
    font-weight: 850;
    box-shadow: 0 7px 18px rgba(30, 101, 68, 0.17);
    transition: 0.2s ease;
}

    .sir-save-decision:hover {
        background: var(--sir-green-700);
        transform: translateY(-1px);
    }


/* ================================================================
   LOCKED DECISION
   ================================================================ */

.sir-decision-locked {
    display: flex;
    align-items: center;
    gap: 15px;
    margin-top: 2px;
    padding: 20px;
    border: 1px solid var(--sir-border);
    border-radius: var(--sir-radius);
    background: #f7faf8;
}

.sir-decision-locked-icon {
    width: 46px;
    height: 46px;
    flex: 0 0 46px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 13px;
    background: #edf3ee;
    color: var(--sir-text-muted);
    font-size: 18px;
}

.sir-decision-locked strong {
    display: block;
    color: var(--sir-green-900);
    font-size: 13px;
    font-weight: 900;
}

.sir-decision-locked p {
    margin: 4px 0 0;
    color: var(--sir-text-muted);
    font-size: 11px;
    line-height: 1.55;
}


/* ================================================================
   ANIMATIONS
   ================================================================ */

@keyframes sirSpin {
    to {
        transform: rotate(360deg);
    }
}

@keyframes sirAlertIn {
    from {
        opacity: 0;
        transform: translateY(-8px);
    }

    to {
        opacity: 1;
        transform: translateY(0);
    }
}


/* ================================================================
   RESPONSIVE — LARGE TABLETS
   ================================================================ */

@media (max-width: 1200px) {

    .sir-page {
        padding: 25px 20px 60px;
    }

    .sir-summary-grid {
        grid-template-columns: repeat(2, 1fr);
    }

    .sir-skill-evidence-grid {
        grid-template-columns: 1fr 1fr;
    }

    .sir-ai-evidence-card {
        grid-column: span 2;
    }

    .sir-competency-grid {
        grid-template-columns: repeat(2, 1fr);
    }

    .sir-profile-grid {
        grid-template-columns: repeat(2, 1fr);
    }

    .sir-certifications-grid {
        grid-template-columns: repeat(2, 1fr);
    }

    .sir-interview-overall {
        grid-template-columns: 1fr 160px 160px;
    }
}


/* ================================================================
   RESPONSIVE — TABLET
   ================================================================ */

@media (max-width: 900px) {

    .sir-header {
        align-items: flex-start;
        flex-direction: column;
    }

    .sir-header-status {
        justify-content: flex-start;
    }

    .sir-action-panel {
        align-items: flex-start;
        flex-direction: column;
    }

    .sir-evaluation-form,
    .sir-run-evaluation-button {
        width: 100%;
    }

    .sir-evaluation-meta {
        grid-template-columns: 1fr;
    }

    .sir-meta-item {
        border-bottom: 1px solid var(--sir-border);
    }

        .sir-meta-item:last-child {
            border-bottom: 0;
        }

    .sir-score-overview {
        grid-template-columns: 1fr;
    }

    .sir-main-score {
        padding-bottom: 10px;
    }

    .sir-skill-summary {
        grid-template-columns: repeat(3, 1fr);
    }

    .sir-skill-summary-progress {
        grid-column: span 3;
    }

    .sir-skill-evidence-grid {
        grid-template-columns: 1fr;
    }

    .sir-ai-evidence-card {
        grid-column: auto;
    }

    .sir-interview-overall {
        grid-template-columns: 1fr 1fr;
    }

    .sir-overall-information {
        grid-column: span 2;
    }

    .sir-decision-options {
        grid-template-columns: 1fr;
    }
}


/* ================================================================
   RESPONSIVE — MOBILE
   ================================================================ */

@media (max-width: 650px) {

    .sir-page {
        padding: 15px 11px 45px;
    }

    .sir-header {
        padding: 20px 17px;
        border-radius: 17px;
    }

    .sir-header-main {
        align-items: flex-start;
        gap: 13px;
    }

    .sir-avatar {
        width: 58px;
        height: 58px;
        flex-basis: 58px;
        border-radius: 16px;
    }

        .sir-avatar span {
            font-size: 22px;
        }

    .sir-header-information h1 {
        font-size: 24px;
    }

    .sir-header-information p {
        font-size: 12px;
    }

    .sir-header-status {
        width: 100%;
