:root {
    --forest-green: #1B5E20;
    --forest-green-dark: #124116;
    --forest-green-light: #2E7D32;
    --lime-green: #8BC34A;
    --lime-light: #DCEDC8;
    --soft-lime-green: #F0FDF4;
    --soft-green: #F7FBF7;
    --border-green: #D5E7D6;
    --black: #111111;
    --dark-text: #263238;
    --muted-green: #607D63;
    --white: #FFFFFF;
    --warning-bg: #FFF8E1;
    --warning-border: #FFE082;
    --warning-text: #795548;
    --success-bg: #E8F5E9;
    --success-border: #A5D6A7;
    --success-text: #1B5E20;
}


/* =========================================================
   GLOBAL POLICY PAGE RESET
   ========================================================= */

.policy-page,
.policy-page * {
    box-sizing: border-box;
}

.policy-page {
    width: 100%;
    max-width: 1100px;
    margin: 35px auto 70px;
    padding: 0 18px;
}


/* =========================================================
   HEADER
   ========================================================= */

.policy-header {
    position: relative;
    width: 100%;
    overflow: hidden;
    background: linear-gradient( 135deg, rgba(220, 237, 200, .95) 0%, rgba(240, 253, 244, .92) 55%, rgba(255, 255, 255, .96) 100% );
    border: 1px solid var(--border-green);
    border-radius: 24px;
    padding: 32px;
    margin-bottom: 25px;
    box-shadow: 0 10px 30px rgba(27, 94, 32, .07), inset 0 1px 0 rgba(255, 255, 255, .75);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
}

    .policy-header::after {
        content: "";
        position: absolute;
        width: 190px;
        height: 190px;
        right: -75px;
        top: -80px;
        border-radius: 50%;
        background: rgba(139, 195, 74, .16);
        pointer-events: none;
    }

.policy-header-content {
    position: relative;
    z-index: 2;
    width: 100%;
    display: flex;
    align-items: flex-start;
    justify-content: flex-start;
    gap: 18px;
}

.policy-icon {
    width: 58px;
    min-width: 58px;
    height: 58px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 17px;
    background: var(--forest-green);
    color: var(--white);
    font-size: 26px;
    margin: 0;
    box-shadow: 0 8px 20px rgba(27, 94, 32, .18);
    flex-shrink: 0;
}

.policy-header-content > div:last-child {
    min-width: 0;
    flex: 1;
}

.policy-header h1 {
    color: var(--forest-green-dark);
    font-size: clamp(1.7rem, 4vw, 2.3rem);
    font-weight: 800;
    margin: 0 0 8px;
    line-height: 1.2;
}

.policy-header p {
    color: var(--muted-green);
    line-height: 1.7;
    max-width: 760px;
    margin: 0;
}


/* =========================================================
   POLICY PROGRESS
   ========================================================= */

.policy-progress {
    position: relative;
    z-index: 2;
    width: 100%;
    margin-top: 25px;
}

.policy-progress-top {
    width: 100%;
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 15px;
    margin-bottom: 9px;
    font-size: .85rem;
}

.policy-progress-label {
    color: var(--forest-green);
    font-weight: 700;
}

.policy-progress-count {
    color: var(--muted-green);
    font-weight: 600;
    text-align: right;
}

.policy-progress-track {
    width: 100%;
    height: 9px;
    background: rgba(139, 195, 74, .20);
    border-radius: 999px;
    overflow: hidden;
}

.policy-progress-bar {
    height: 100%;
    width: 0;
    background: linear-gradient( 90deg, var(--forest-green), var(--lime-green) );
    border-radius: inherit;
    transition: width .35s ease;
}


/* =========================================================
   POLICY LIST
   ========================================================= */

.policies-container {
    width: 100%;
    display: flex;
    flex-direction: column;
    gap: 18px;
}

.policy-card {
    width: 100%;
    background: linear-gradient( 180deg, rgba(255, 255, 255, .98), rgba(247, 251, 247, .97) );
    border: 1px solid var(--border-green);
    border-radius: 20px;
    overflow: hidden;
    box-shadow: 0 8px 24px rgba(27, 94, 32, .05);
    transition: transform .2s ease, box-shadow .2s ease, border-color .2s ease;
}

    .policy-card:hover {
        transform: translateY(-2px);
        box-shadow: 0 13px 30px rgba(27, 94, 32, .08);
        border-color: #BED8C0;
    }

    .policy-card.accepted {
        border-color: var(--success-border);
        box-shadow: 0 8px 24px rgba(27, 94, 32, .07);
    }


/* =========================================================
   POLICY CARD HEADER
   ========================================================= */

.policy-card-header {
    width: 100%;
    padding: 22px 24px;
    background: linear-gradient( 135deg, rgba(247, 251, 247, .98), rgba(255, 255, 255, .98) );
    border-bottom: 1px solid var(--border-green);
}

.policy-title-row {
    width: 100%;
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 18px;
}

    .policy-title-row > div:not(.policy-number) {
        min-width: 0;
        flex: 1;
    }

.policy-number {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 34px;
    width: 34px;
    height: 34px;
    padding: 0;
    border-radius: 10px;
    background: var(--lime-light);
    color: var(--forest-green);
    font-size: .8rem;
    font-weight: 800;
    flex-shrink: 0;
    margin: 0;
}

.policy-title {
    color: var(--forest-green-dark);
    font-size: 1.1rem;
    font-weight: 800;
    margin: 0;
    line-height: 1.4;
    overflow-wrap: anywhere;
}

.policy-card h2.policy-title,
.policy-card h4.policy-title {
    margin: 0;
}


/* =========================================================
   POLICY META
   ========================================================= */

.policy-meta {
    width: 100%;
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 8px;
    margin-top: 10px;
}

.policy-version {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 5px;
    font-size: .76rem;
    background: var(--soft-green);
    color: var(--forest-green-light);
    border: 1px solid var(--border-green);
    padding: 5px 9px;
    border-radius: 8px;
    font-weight: 700;
}

.required-badge {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 5px;
    font-size: .73rem;
    background: var(--warning-bg);
    color: var(--warning-text);
    border: 1px solid var(--warning-border);
    padding: 5px 9px;
    border-radius: 8px;
    font-weight: 750;
}

.policy-status {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    padding: 6px 10px;
    border-radius: 9px;
    font-size: .75rem;
    font-weight: 750;
    white-space: nowrap;
    flex-shrink: 0;
}

    .policy-status.pending {
        background: #F5F7F5;
        color: var(--muted-green);
        border: 1px solid #E1E8E1;
    }

    .policy-status.accepted {
        background: var(--success-bg);
        color: var(--success-text);
        border: 1px solid var(--success-border);
    }


/* =========================================================
   POLICY BODY
   ========================================================= */

.policy-card-body {
    width: 100%;
    padding: 23px 24px;
}

.policy-description {
    width: 100%;
    color: var(--dark-text);
    line-height: 1.75;
    font-size: .92rem;
}

.policy-description-intro {
    width: 100%;
    color: var(--muted-green);
    margin-bottom: 18px;
    padding: 12px 14px;
    background: var(--soft-lime-green);
    border-left: 4px solid var(--lime-green);
    border-radius: 8px;
}

.policy-sections {
    width: 100%;
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.policy-section {
    width: 100%;
    padding: 14px 16px;
    background: var(--soft-green);
    border: 1px solid var(--border-green);
    border-radius: 13px;
    margin-bottom: 0;
}

.policy-section-title {
    color: var(--forest-green);
    font-weight: 800;
    font-size: .9rem;
    margin-bottom: 6px;
    line-height: 1.4;
}

.policy-section-text {
    color: var(--dark-text);
    font-size: .88rem;
    line-height: 1.7;
    margin: 5px 0 0;
    white-space: pre-line;
}

.policy-plain-text {
    color: var(--dark-text);
    font-size: .92rem;
    line-height: 1.75;
    white-space: pre-line;
    margin-top: 12px;
}


/* =========================================================
   POLICY FOOTER
   ========================================================= */

.policy-card-footer {
    width: 100%;
    padding: 17px 24px;
    background: rgba(251, 253, 251, .96);
    border-top: 1px solid var(--border-green);
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 18px;
    flex-wrap: nowrap;
}


/* =========================================================
   FOOTER ACTION GROUPS
   ========================================================= */

.policy-actions {
    display: flex;
    align-items: center;
    justify-content: flex-start;
    flex-wrap: wrap;
    gap: 9px;
    min-width: 0;
}

.policy-card-footer > .policy-actions:last-child {
    margin-left: auto;
    justify-content: flex-end;
}


/* =========================================================
   VIEW DOCUMENT BUTTON
   ========================================================= */

.btn-policy-view {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 7px;
    border: 1px solid var(--forest-green-light);
    background: var(--white);
    color: var(--forest-green);
    font-weight: 750;
    border-radius: 10px;
    padding: 9px 15px;
    text-decoration: none;
    white-space: nowrap;
    transition: background .2s ease, color .2s ease, border-color .2s ease, transform .2s ease;
}

    .btn-policy-view:hover {
        background: var(--soft-green);
        color: var(--forest-green-dark);
        border-color: var(--forest-green);
        transform: translateY(-1px);
    }


/* =========================================================
   ACCEPT POLICY BUTTON
   ========================================================= */

.btn-policy {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 7px;
    background: var(--lime-green);
    border: 1px solid var(--lime-green);
    color: var(--forest-green-dark);
    font-weight: 800;
    border-radius: 10px;
    padding: 9px 17px;
    min-width: 145px;
    white-space: nowrap;
    transition: background .2s ease, border-color .2s ease, color .2s ease, transform .2s ease, box-shadow .2s ease;
}

    .btn-policy:hover {
        background: #7CB342;
        border-color: #7CB342;
        color: var(--forest-green-dark);
        transform: translateY(-1px);
        box-shadow: 0 5px 14px rgba(27, 94, 32, .12);
    }

    .btn-policy:disabled {
        opacity: .7;
        cursor: not-allowed;
        transform: none;
        box-shadow: none;
    }


/* =========================================================
   ACCEPTED MESSAGE
   ========================================================= */

.accepted-message {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 7px;
    color: var(--success-text);
    background: var(--success-bg);
    border: 1px solid var(--success-border);
    border-radius: 10px;
    padding: 9px 14px;
    font-size: .86rem;
    font-weight: 750;
    white-space: nowrap;
}


/* =========================================================
   ACCEPT FORM
   ========================================================= */

.accept-policy-form {
    margin: 0;
    padding: 0;
    display: inline-flex;
    align-items: center;
    justify-content: flex-end;
}


/* =========================================================
   CONTINUE AREA
   ========================================================= */

.continue-card {
    width: 100%;
    margin-top: 25px;
    background: linear-gradient( 135deg, var(--forest-green), var(--forest-green-light) );
    border-radius: 20px;
    padding: 23px 25px;
    color: var(--white);
    box-shadow: 0 12px 30px rgba(27, 94, 32, .16);
}

.continue-card-content {
    width: 100%;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 25px;
}

.continue-card h3,
.continue-card h5 {
    margin: 0 0 5px;
    font-weight: 800;
    color: var(--white);
    line-height: 1.3;
}

.continue-card p {
    margin: 0;
    color: rgba(255, 255, 255, .84);
    font-size: .88rem;
    line-height: 1.6;
}

.continue-actions {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    flex-shrink: 0;
}

.btn-continue {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    background: var(--lime-green);
    color: var(--forest-green-dark);
    border: 1px solid var(--lime-green);
    border-radius: 11px;
    padding: 10px 18px;
    font-weight: 800;
    text-decoration: none;
    white-space: nowrap;
    transition: background .2s ease, color .2s ease, transform .2s ease, box-shadow .2s ease;
}

    .btn-continue:hover {
        background: #9CCC65;
        color: var(--forest-green-dark);
        transform: translateY(-1px);
        box-shadow: 0 6px 16px rgba(0, 0, 0, .14);
    }


/* =========================================================
   EMPTY STATE
   ========================================================= */

.empty-policy {
    width: 100%;
    text-align: center;
    background: var(--white);
    border: 1px solid var(--border-green);
    border-radius: 20px;
    padding: 45px 25px;
}

.empty-policy-icon {
    width: 65px;
    height: 65px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 18px;
    background: var(--soft-green);
    color: var(--forest-green);
    font-size: 27px;
    margin-bottom: 15px;
}

.empty-policy h4 {
    color: var(--forest-green-dark);
    font-weight: 800;
}

.empty-policy p {
    color: var(--muted-green);
    margin-bottom: 0;
}


/* =========================================================
   LOADING
   ========================================================= */

.accept-spinner {
    display: none;
}

.accepting .accept-icon {
    display: none;
}

.accepting .accept-spinner {
    display: inline-block;
}


/* =========================================================
   TOAST
   ========================================================= */

.policy-toast {
    position: fixed;
    right: 22px;
    bottom: 22px;
    z-index: 9999;
    min-width: 280px;
    max-width: 420px;
    padding: 14px 17px;
    border-radius: 13px;
    display: flex;
    align-items: flex-start;
    gap: 11px;
    box-shadow: 0 12px 30px rgba(0, 0, 0, .15);
    transform: translateY(20px);
    opacity: 0;
    pointer-events: none;
    transition: all .25s ease;
}

    .policy-toast.show {
        transform: translateY(0);
        opacity: 1;
        pointer-events: auto;
    }

    .policy-toast.success {
        background: var(--success-bg);
        border: 1px solid var(--success-border);
        color: var(--success-text);
    }

    .policy-toast.error {
        background: #FFF1F0;
        border: 1px solid #FFCDD2;
        color: #B71C1C;
    }

    .policy-toast i {
        font-size: 19px;
        margin-top: 1px;
    }

.policy-toast-content {
    display: flex;
    flex-direction: column;
    gap: 2px;
    min-width: 0;
    flex: 1;
}

    .policy-toast-content strong {
        font-weight: 800;
    }

    .policy-toast-content span {
        line-height: 1.45;
    }

.policy-toast-close {
    border: 0;
    background: transparent;
    color: inherit;
    width: 28px;
    height: 28px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 7px;
    cursor: pointer;
    flex-shrink: 0;
}

    .policy-toast-close:hover {
        background: rgba(0, 0, 0, .06);
    }


/* =========================================================
   TABLET
   ========================================================= */

@media (max-width: 900px) {

    .policy-page {
        max-width: 100%;
        margin-top: 25px;
    }

    .policy-card-footer {
        gap: 14px;
    }

    .continue-card-content {
        gap: 18px;
    }
}


/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width: 768px) {

    .policy-page {
        margin: 20px auto 45px;
        padding: 0 12px;
    }

    .policy-header {
        padding: 24px 20px;
        border-radius: 19px;
    }

    .policy-header-content {
        gap: 14px;
    }

    .policy-icon {
        width: 50px;
        min-width: 50px;
        height: 50px;
        border-radius: 14px;
        font-size: 22px;
    }

    .policy-card {
        border-radius: 17px;
    }

    .policy-card-header,
    .policy-card-body {
        padding: 18px;
    }

    .policy-card-footer {
        padding: 15px 18px;
        flex-direction: column;
        align-items: stretch;
        justify-content: flex-start;
    }

        .policy-card-footer > .policy-actions,
        .policy-card-footer > .policy-actions:last-child {
            width: 100%;
            margin-left: 0;
            justify-content: flex-start;
        }

    .policy-title-row {
        gap: 12px;
    }

    .policy-meta {
        margin-left: 0;
    }

    .policy-status {
        align-self: flex-start;
    }

    .policy-actions {
        width: 100%;
    }

    .accept-policy-form {
        width: 100%;
        justify-content: stretch;
    }

    .btn-policy,
    .btn-policy-view,
    .accepted-message {
        width: 100%;
    }

    .continue-card {
        padding: 20px;
    }

    .continue-card-content {
        flex-direction: column;
        align-items: stretch;
        justify-content: flex-start;
        gap: 18px;
    }

    .continue-actions {
        width: 100%;
        justify-content: stretch;
    }

    .btn-continue {
        width: 100%;
    }

    .policy-toast {
        left: 15px;
        right: 15px;
        bottom: 15px;
        min-width: 0;
        max-width: none;
    }
}


/* =========================================================
   SMALL MOBILE
   ========================================================= */

@media (max-width: 480px) {

    .policy-page {
        padding: 0 9px;
    }

    .policy-header {
        padding: 21px 17px;
    }

    .policy-header-content {
        align-items: flex-start;
        gap: 12px;
    }

    .policy-icon {
        width: 45px;
        min-width: 45px;
        height: 45px;
        border-radius: 13px;
        font-size: 20px;
    }

    .policy-header h1 {
        font-size: 1.55rem;
    }

    .policy-header p {
        font-size: .86rem;
    }

    .policy-progress-top {
        font-size: .78rem;
    }

    .policy-card h4,
    .policy-title {
        font-size: 1rem;
    }

    .policy-number {
        min-width: 30px;
        width: 30px;
        height: 30px;
        font-size: .72rem;
    }

    .policy-card-header,
    .policy-card-body {
        padding: 15px;
    }

    .policy-card-footer {
        padding: 14px 15px;
    }

    .policy-section {
        padding: 12px;
    }

    .policy-section-title {
        font-size: .84rem;
    }

    .policy-section-text {
        font-size: .84rem;
    }

    .btn-policy,
    .btn-policy-view,
    .btn-continue {
        min-height: 43px;
    }
}


/* =========================================================
   VERY SMALL SCREENS
   ========================================================= */

@media (max-width: 360px) {

    .policy-header-content {
        flex-direction: column;
    }

    .policy-icon {
        margin-bottom: 2px;
    }

    .policy-title-row {
        gap: 9px;
    }

    .policy-progress-top {
        flex-direction: column;
        align-items: flex-start;
        gap: 3px;
    }

    .policy-progress-count {
        text-align: left;
    }
}




:root {
    --forest-green: #1B5E20;
    --forest-green-dark: #124116;
    --forest-green-light: #2E7D32;
    --lime-green: #8BC34A;
    --lime-light: #DCEDC8;
    --soft-lime-green: #F0FDF4;
    --soft-green: #F7FBF7;
    --border-green: #D5E7D6;
    --dark-text: #263238;
    --muted-green: #607D63;
    --white: #FFFFFF;
    --success-bg: #E8F5E9;
    --success-border: #A5D6A7;
    --success-text: #1B5E20;
    --warning-bg: #FFF8E1;
    --warning-border: #FFE082;
    --warning-text: #795548;
    --danger-bg: #FFF1F0;
    --danger-border: #FFCDD2;
    --danger-text: #B71C1C;
}

/* =========================================================
           PAGE
           ========================================================= */

.contract-page {
    max-width: 1050px;
    margin: 35px auto 70px;
}


/* =========================================================
           HERO
           ========================================================= */

.contract-hero {
    position: relative;
    overflow: hidden;
    background: linear-gradient( 135deg, var(--lime-light) 0%, var(--soft-lime-green) 52%, var(--white) 100% );
    border: 1px solid var(--border-green);
    border-radius: 24px;
    padding: 32px;
    margin-bottom: 22px;
    box-shadow: 0 12px 35px rgba(27, 94, 32, .07);
}

    .contract-hero::before {
        content: "";
        position: absolute;
        width: 230px;
        height: 230px;
        border-radius: 50%;
        right: -90px;
        top: -110px;
        background: rgba(139, 195, 74, .15);
        pointer-events: none;
    }

    .contract-hero::after {
        content: "";
        position: absolute;
        width: 130px;
        height: 130px;
        border-radius: 50%;
        left: -65px;
        bottom: -75px;
        background: rgba(46, 125, 50, .06);
        pointer-events: none;
    }

.contract-hero-content {
    position: relative;
    z-index: 2;
}

.contract-hero-top {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 25px;
}

.contract-icon {
    width: 66px;
    height: 66px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 18px;
    background: var(--forest-green);
    color: var(--white);
    font-size: 29px;
    margin-bottom: 17px;
    box-shadow: 0 9px 22px rgba(27, 94, 32, .18);
}

.contract-hero h1 {
    color: var(--forest-green-dark);
    font-size: clamp(1.75rem, 4vw, 2.35rem);
    font-weight: 850;
    margin: 0 0 8px;
    letter-spacing: -.4px;
}

.contract-description {
    color: var(--muted-green);
    max-width: 760px;
    line-height: 1.7;
    margin: 0;
    font-size: .94rem;
}

.contract-status-pill {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    background: var(--white);
    color: var(--forest-green);
    border: 1px solid var(--border-green);
    border-radius: 12px;
    padding: 9px 13px;
    font-size: .78rem;
    font-weight: 800;
    white-space: nowrap;
    box-shadow: 0 5px 15px rgba(27, 94, 32, .05);
}

    .contract-status-pill i {
        color: var(--lime-green);
        font-size: 15px;
    }


/* =========================================================
           MAIN CARD
           ========================================================= */

.contract-card {
    background: var(--white);
    border: 1px solid var(--border-green);
    border-radius: 22px;
    overflow: hidden;
    box-shadow: 0 10px 30px rgba(27, 94, 32, .06);
}


/* =========================================================
           NOT GENERATED
           ========================================================= */

.contract-warning {
    margin: 24px;
    padding: 18px 20px;
    display: flex;
    align-items: flex-start;
    gap: 13px;
    background: var(--warning-bg);
    border: 1px solid var(--warning-border);
    border-radius: 14px;
    color: var(--warning-text);
}

.contract-warning-icon {
    width: 36px;
    height: 36px;
    min-width: 36px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: rgba(255, 224, 130, .35);
    border-radius: 10px;
    color: #A67C00;
}

.contract-warning strong {
    display: block;
    color: #6D4C41;
    margin-bottom: 2px;
}

.contract-warning span {
    font-size: .86rem;
    line-height: 1.55;
}


/* =========================================================
           CONTRACT CONTENT
           ========================================================= */

.contract-content {
    padding: 27px;
}

.section-heading {
    display: flex;
    align-items: center;
    gap: 11px;
    margin-bottom: 15px;
}

.section-heading-icon {
    width: 36px;
    height: 36px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 10px;
    background: var(--lime-light);
    color: var(--forest-green);
    flex-shrink: 0;
}

.section-heading h5 {
    color: var(--forest-green-dark);
    font-weight: 850;
    margin: 0;
    font-size: 1rem;
}


/* =========================================================
           CONTRACT DETAILS
           ========================================================= */

.contract-details {
    border: 1px solid var(--border-green);
    border-radius: 16px;
    overflow: hidden;
    background: var(--soft-green);
}

.contract-detail-row {
    display: grid;
    grid-template-columns: 220px 1fr;
    align-items: center;
    min-height: 62px;
    border-bottom: 1px solid var(--border-green);
}

    .contract-detail-row:last-child {
        border-bottom: 0;
    }

.contract-detail-label {
    height: 100%;
    display: flex;
    align-items: center;
    padding: 14px 18px;
    color: var(--muted-green);
    font-size: .82rem;
    font-weight: 750;
    background: rgba(220, 237, 200, .25);
}

    .contract-detail-label i {
        color: var(--forest-green);
    }

.contract-detail-value {
    padding: 14px 18px;
    color: var(--dark-text);
    font-size: .88rem;
    font-weight: 700;
    background: var(--white);
}

.contract-status-value {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    background: var(--success-bg);
    color: var(--success-text);
    border: 1px solid var(--success-border);
    border-radius: 8px;
    padding: 5px 10px;
    font-size: .75rem;
    font-weight: 800;
}


/* =========================================================
           INSTRUCTIONS
           ========================================================= */

.instructions {
    margin-top: 25px;
    padding: 21px;
    border-radius: 16px;
    background: linear-gradient( 135deg, var(--soft-lime-green), var(--white) );
    border: 1px solid var(--border-green);
}

.instructions-heading {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 17px;
}

.instructions-heading-icon {
    width: 35px;
    height: 35px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 10px;
    background: var(--forest-green);
    color: var(--white);
}

.instructions h5 {
    color: var(--forest-green-dark);
    font-weight: 850;
    margin: 0;
    font-size: 1rem;
}

.instructions-list {
    margin: 0;
    padding: 0;
    list-style: none;
    counter-reset: contract-step;
}

    .instructions-list li {
        position: relative;
        display: flex;
        align-items: flex-start;
        gap: 12px;
        color: var(--dark-text);
        font-size: .87rem;
        line-height: 1.6;
        padding: 9px 0;
        counter-increment: contract-step;
    }

        .instructions-list li::before {
            content: counter(contract-step);
            width: 27px;
            height: 27px;
            min-width: 27px;
            display: inline-flex;
            align-items: center;
            justify-content: center;
            background: var(--lime-light);
            color: var(--forest-green);
            border-radius: 50%;
            font-size: .73rem;
            font-weight: 850;
        }


/* =========================================================
           ACTION AREA
           ========================================================= */

.contract-actions {
    display: flex;
    flex-wrap: wrap;
    gap: 11px;
    margin-top: 25px;
}

.btn-contract {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    min-height: 46px;
    padding: 10px 18px;
    border-radius: 11px;
    font-size: .86rem;
    font-weight: 800;
    text-decoration: none;
    transition: all .2s ease;
}

.btn-download {
    background: var(--lime-green);
    border: 1px solid var(--lime-green);
    color: var(--forest-green-dark);
    box-shadow: 0 6px 16px rgba(139, 195, 74, .17);
}

    .btn-download:hover {
        background: #9CCC65;
        border-color: #9CCC65;
        color: var(--forest-green-dark);
        transform: translateY(-1px);
    }

.btn-upload {
    background: var(--white);
    border: 1px solid var(--forest-green);
    color: var(--forest-green);
}

    .btn-upload:hover {
        background: var(--soft-green);
        border-color: var(--forest-green-dark);
        color: var(--forest-green-dark);
        transform: translateY(-1px);
    }


/* =========================================================
           SECURITY NOTE
           ========================================================= */

.download-note {
    top:10px;
    display: flex;
    align-items: flex-start;
    gap: 9px;
    padding: 13px 15px;
    border-radius: 11px;
    background: var(--soft-green);
    border: 1px solid var(--border-green);
    color: var(--muted-green);
    font-size: .78rem;
    line-height: 1.55;
}

    .download-note i {
        color: var(--forest-green);
        font-size: 17px;
        margin-top: 1px;
    }


/* =========================================================
           UPLOADED CONTRACT
           ========================================================= */

.uploaded-contract {
    margin: 0 27px 27px;
    padding: 19px 20px;
    border-radius: 16px;
    background: var(--success-bg);
    border: 1px solid var(--success-border);
}

.uploaded-contract-inner {
    display: flex;
    align-items: flex-start;
    gap: 13px;
}

.uploaded-contract-icon {
    width: 42px;
    height: 42px;
    min-width: 42px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 12px;
    background: var(--white);
    color: var(--success-text);
    font-size: 19px;
    box-shadow: 0 3px 10px rgba(27, 94, 32, .07);
}

.uploaded-contract-title {
    color: var(--success-text);
    font-weight: 850;
    font-size: .92rem;
    margin-bottom: 3px;
}

.uploaded-contract-file {
    color: var(--dark-text);
    font-size: .83rem;
    font-weight: 750;
    word-break: break-word;
}

.uploaded-contract-status {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    margin-top: 7px;
    color: var(--muted-green);
    font-size: .75rem;
}

    .uploaded-contract-status strong {
        color: var(--forest-green);
    }


/* =========================================================
           FOOTER
           ========================================================= */

.contract-footer {
    padding: 18px 27px;
    background: #FBFDFB;
    border-top: 1px solid var(--border-green);
    color: var(--muted-green);
    font-size: .76rem;
    display: flex;
    align-items: center;
    gap: 8px;
}

    .contract-footer i {
        color: var(--forest-green);
    }


/* =========================================================
           RESPONSIVE
           ========================================================= */

@media (max-width: 768px) {

    .contract-page {
        margin: 20px auto 45px;
    }

    .contract-hero {
        padding: 24px 20px;
        border-radius: 19px;
    }

    .contract-hero-top {
        flex-direction: column;
        gap: 15px;
    }

    .contract-status-pill {
        align-self: flex-start;
    }

    .contract-card {
        border-radius: 18px;
    }

    .contract-content {
        padding: 20px;
    }

    .contract-detail-row {
        grid-template-columns: 1fr;
    }

    .contract-detail-label {
        min-height: auto;
        padding: 11px 14px 6px;
        background: var(--soft-green);
    }

    .contract-detail-value {
        padding: 6px 14px 14px;
    }

    .contract-actions {
        flex-direction: column;
    }

    .btn-contract {
        width: 100%;
    }

    .uploaded-contract {
        margin: 0 20px 20px;
    }

    .contract-footer {
        padding: 16px 20px;
    }
}

@media (max-width: 480px) {

    .contract-hero h1 {
        font-size: 1.6rem;
    }

    .contract-description {
        font-size: .87rem;
    }

    .contract-icon {
        width: 58px;
        height: 58px;
        font-size: 25px;
    }

    .instructions {
        padding: 17px;
    }

    .uploaded-contract {
        padding: 16px;
    }
}
/* =========================================================
   SWIFTCARE GLASS DOCUMENTS PAGE
   ========================================================= */

:root {
    --swift-forest: #1B5E20;
    --swift-forest-dark: #124116;
    --swift-green: #2E7D32;
    --swift-lime: #8BC34A;
    --swift-lime-soft: #DCEDC8;
    --swift-mint: #F0FDF4;
    --swift-glass: rgba(255, 255, 255, .72);
    --swift-glass-strong: rgba(255, 255, 255, .88);
    --swift-border: rgba(46, 125, 50, .16);
    --swift-text: #183a24;
    --swift-muted: #68786d;
    --swift-shadow: 0 18px 45px rgba(27, 94, 32, .10);
}


/* =========================================================
   PAGE
   ========================================================= */

.documents-page {
    width: 100%;
    max-width: 1400px;
    margin: 35px auto 70px;
    padding-left: 18px;
    padding-right: 18px;
    position: relative;
}


/* =========================================================
   HEADER
   ========================================================= */

.documents-header {
    position: relative;
    overflow: hidden;
    background: linear-gradient( 135deg, rgba(220, 237, 200, .94), rgba(240, 253, 244, .84) );
    border: 1px solid rgba(139, 195, 74, .28);
    border-radius: 28px;
    padding: 34px 36px;
    margin-bottom: 28px;
    box-shadow: 0 20px 50px rgba(27, 94, 32, .10), inset 0 1px 0 rgba(255, 255, 255, .85);
    backdrop-filter: blur(18px);
    -webkit-backdrop-filter: blur(18px);
}

    .documents-header::before {
        content: "";
        position: absolute;
        width: 210px;
        height: 210px;
        top: -100px;
        right: -70px;
        background: rgba(139, 195, 74, .20);
        border-radius: 50%;
        filter: blur(3px);
        pointer-events: none;
    }

    .documents-header::after {
        content: "";
        position: absolute;
        width: 130px;
        height: 130px;
        bottom: -80px;
        left: 25%;
        background: rgba(46, 125, 50, .08);
        border-radius: 50%;
        pointer-events: none;
    }

    .documents-header h1 {
        position: relative;
        z-index: 1;
        color: var(--swift-forest-dark);
        font-size: 2rem;
        font-weight: 850;
        letter-spacing: -.025em;
        margin-bottom: 8px;
    }

        .documents-header h1 i {
            color: var(--swift-green);
        }

    .documents-header p {
        position: relative;
        z-index: 1;
        color: var(--swift-muted) !important;
        font-size: .96rem;
        line-height: 1.7;
        max-width: 820px;
    }


/* =========================================================
   INFORMATION PANEL
   ========================================================= */

.documents-info {
    display: flex;
    align-items: flex-start;
    gap: 11px;
    width: 100%;
    background: rgba(240, 253, 244, .78);
    border: 1px solid rgba(139, 195, 74, .25);
    color: #49604f;
    border-radius: 16px;
    padding: 15px 18px;
    margin-bottom: 26px;
    box-shadow: 0 8px 25px rgba(27, 94, 32, .05), inset 0 1px 0 rgba(255, 255, 255, .8);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    font-size: .88rem;
    line-height: 1.65;
}

    .documents-info i {
        color: var(--swift-green);
        font-size: 1.05rem;
        margin-top: 2px;
        flex-shrink: 0;
    }

    .documents-info strong {
        color: var(--swift-forest);
    }


/* =========================================================
   BOOTSTRAP ROW SAFETY
   ========================================================= */

.documents-page .row {
    width: 100%;
    margin-left: 0;
    margin-right: 0;
}

    .documents-page .row > [class*="col-"] {
        min-width: 0;
    }


/* =========================================================
   GLASS CARDS
   ========================================================= */

.upload-card,
.documents-card,
.verification-card {
    position: relative;
    overflow: hidden;
    width: 100%;
    height: 100%;
    background: var(--swift-glass);
    border: 1px solid var(--swift-border);
    border-radius: 23px;
    padding: 28px;
    box-shadow: var(--swift-shadow), inset 0 1px 0 rgba(255, 255, 255, .82);
    backdrop-filter: blur(18px);
    -webkit-backdrop-filter: blur(18px);
    transition: transform .25s ease, box-shadow .25s ease, border-color .25s ease;
}

    .upload-card::before,
    .documents-card::before,
    .verification-card::before {
        content: "";
        position: absolute;
        width: 150px;
        height: 150px;
        top: -95px;
        right: -60px;
        border-radius: 50%;
        background: rgba(139, 195, 74, .08);
        pointer-events: none;
    }

    .upload-card:hover,
    .documents-card:hover {
        transform: translateY(-2px);
        border-color: rgba(46, 125, 50, .25);
        box-shadow: 0 22px 55px rgba(27, 94, 32, .13), inset 0 1px 0 rgba(255, 255, 255, .9);
    }

    .upload-card h4,
    .documents-card h4 {
        position: relative;
        z-index: 1;
        color: var(--swift-forest-dark);
        font-weight: 800;
        font-size: 1.08rem;
        letter-spacing: -.01em;
    }

        .upload-card h4 i,
        .documents-card h4 i {
            color: var(--swift-green);
        }


/* =========================================================
   UPLOAD FORM
   ========================================================= */

.form-label {
    color: #31543e;
    font-weight: 700;
    font-size: .87rem;
    margin-bottom: 7px;
}

.form-control,
.form-select {
    width: 100%;
    border: 1px solid rgba(46, 125, 50, .16);
    background: rgba(255, 255, 255, .72);
    color: var(--swift-text);
    border-radius: 12px;
    padding: 11px 13px;
    box-shadow: inset 0 1px 2px rgba(27, 94, 32, .025);
    transition: border-color .2s ease, box-shadow .2s ease, background .2s ease;
}

    .form-control:focus,
    .form-select:focus {
        border-color: rgba(139, 195, 74, .75);
        background: rgba(255, 255, 255, .92);
        box-shadow: 0 0 0 4px rgba(139, 195, 74, .13), 0 5px 18px rgba(27, 94, 32, .06);
        outline: none;
    }

    .form-control::placeholder {
        color: #9aa69d;
    }

.form-text {
    color: #7a887e;
    font-size: .78rem;
    margin-top: 7px;
}


/* =========================================================
   CUSTOM DOTTED FILE UPLOAD
   ========================================================= */

.document-upload-zone {
    position: relative;
    width: 100%;
    min-height: 190px;
    border: 2px dashed rgba(46, 125, 50, .35);
    border-radius: 20px;
    background: linear-gradient( 145deg, rgba(240, 253, 244, .76), rgba(255, 255, 255, .62) );
    display: flex;
    align-items: center;
    justify-content: center;
    text-align: center;
    padding: 25px;
    cursor: pointer;
    overflow: hidden;
    transition: border-color .25s ease, background .25s ease, transform .2s ease, box-shadow .25s ease;
}

    .document-upload-zone::before {
        content: "";
        position: absolute;
        width: 160px;
        height: 160px;
        border-radius: 50%;
        background: rgba(139, 195, 74, .10);
        top: -90px;
        right: -55px;
        pointer-events: none;
    }

    .document-upload-zone::after {
        content: "";
        position: absolute;
        width: 120px;
        height: 120px;
        border-radius: 50%;
        background: rgba(46, 125, 50, .055);
        bottom: -75px;
        left: -40px;
        pointer-events: none;
    }

    .document-upload-zone:hover {
        border-color: rgba(46, 125, 50, .65);
        background: linear-gradient( 145deg, rgba(220, 237, 200, .72), rgba(240, 253, 244, .86) );
        box-shadow: 0 12px 30px rgba(27, 94, 32, .08), inset 0 1px 0 rgba(255, 255, 255, .85);
        transform: translateY(-1px);
    }

    .document-upload-zone.dragover {
        border-color: var(--swift-green);
        background: linear-gradient( 145deg, rgba(220, 237, 200, .92), rgba(240, 253, 244, .96) );
        box-shadow: 0 0 0 5px rgba(139, 195, 74, .12), 0 18px 35px rgba(27, 94, 32, .12);
        transform: scale(1.01);
    }

    .document-upload-zone.has-file {
        border-color: rgba(46, 125, 50, .55);
        background: linear-gradient( 145deg, rgba(220, 237, 200, .68), rgba(255, 255, 255, .82) );
    }

.document-upload-input {
    position: absolute;
    width: 1px;
    height: 1px;
    opacity: 0;
    pointer-events: none;
}

.document-upload-content {
    position: relative;
    z-index: 2;
    width: 100%;
}

.document-upload-icon {
    width: 62px;
    height: 62px;
    margin: 0 auto 14px;
    border-radius: 18px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: linear-gradient( 145deg, rgba(220, 237, 200, .96), rgba(240, 253, 244, .96) );
    border: 1px solid rgba(139, 195, 74, .30);
    color: var(--swift-green);
    box-shadow: 0 8px 20px rgba(27, 94, 32, .08), inset 0 1px 0 rgba(255, 255, 255, .9);
    transition: transform .25s ease;
}

.document-upload-zone:hover .document-upload-icon {
    transform: translateY(-3px);
}

.document-upload-icon i {
    font-size: 1.55rem;
}

.document-upload-title {
    color: var(--swift-forest-dark);
    font-size: .98rem;
    font-weight: 800;
    margin-bottom: 5px;
}

.document-upload-subtitle {
    color: var(--swift-muted);
    font-size: .80rem;
    line-height: 1.55;
}

.document-upload-file-name {
    margin-top: 10px;
    color: var(--swift-green);
    font-size: .80rem;
    font-weight: 750;
    overflow-wrap: anywhere;
    word-break: normal;
}

.document-upload-hint {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    margin-top: 11px;
    padding: 5px 10px;
    border-radius: 999px;
    background: rgba(255, 255, 255, .65);
    border: 1px solid rgba(46, 125, 50, .10);
    color: #637468;
    font-size: .70rem;
}

    .document-upload-hint i {
        color: var(--swift-green);
    }


/* =========================================================
   SWIFT BUTTON
   ========================================================= */

.btn-swift {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 7px;
    background: linear-gradient( 135deg, #8BC34A, #72b82a );
    border: 1px solid rgba(91, 143, 34, .30);
    color: #163d25;
    font-weight: 800;
    border-radius: 12px;
    padding: 11px 19px;
    box-shadow: 0 8px 18px rgba(91, 143, 34, .16), inset 0 1px 0 rgba(255, 255, 255, .45);
    transition: transform .2s ease, box-shadow .2s ease, background .2s ease;
}

    .btn-swift:hover {
        background: linear-gradient( 135deg, #9bd35d, #7fc438 );
        color: #163d25;
        transform: translateY(-1px);
        box-shadow: 0 12px 24px rgba(91, 143, 34, .22), inset 0 1px 0 rgba(255, 255, 255, .5);
    }

    .btn-swift:active {
        transform: translateY(0);
    }

    .btn-swift:disabled {
        opacity: .6;
        cursor: not-allowed;
        transform: none;
        box-shadow: none;
    }


/* =========================================================
   DOCUMENTS CARD
   ========================================================= */

.documents-card {
    min-height: 100%;
}

    .documents-card > h4 {
        padding-bottom: 14px;
        margin-bottom: 0 !important;
        border-bottom: 1px solid rgba(46, 125, 50, .10);
    }

/* =========================================================
   DOCUMENT LIST
   ========================================================= */

.document-list {
    width: 100%;
    min-width: 0;
    display: flex;
    flex-direction: column;
}


/* =========================================================
   DOCUMENT ROW
   ========================================================= */

.document-row {
    width: 100%;
    min-width: 0;
    padding: 18px 4px;
    border-bottom: 1px solid rgba(46, 125, 50, .09);
    transition: background .2s ease, padding .2s ease, border-color .2s ease;
}

    .document-row:last-child {
        border-bottom: none;
        padding-bottom: 4px;
    }

    .document-row:hover {
        background: rgba(240, 253, 244, .42);
        border-radius: 15px;
        padding-left: 12px;
        padding-right: 12px;
    }


/* =========================================================
   DOCUMENT ROW LAYOUT
   ========================================================= */

.document-row-inner {
    width: 100%;
    min-width: 0;
    display: grid;
    /*
       icon | document information | actions
    */
    grid-template-columns: 52px minmax(0, 1fr) auto;
    align-items: center;
    column-gap: 16px;
}


/* =========================================================
   DOCUMENT ICON
   ========================================================= */

.document-icon {
    width: 48px;
    height: 48px;
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 14px;
    background: linear-gradient( 145deg, rgba(220, 237, 200, .95), rgba(240, 253, 244, .95) );
    border: 1px solid rgba(139, 195, 74, .20);
    color: var(--swift-green);
    box-shadow: 0 6px 15px rgba(27, 94, 32, .07), inset 0 1px 0 rgba(255, 255, 255, .85);
}

    .document-icon i {
        font-size: 1.15rem;
    }


/* =========================================================
   DOCUMENT DETAILS
   ========================================================= */

.document-details {
    width: 100%;
    min-width: 0;
    overflow: hidden;
}


/* =========================================================
   DOCUMENT NAME
   ========================================================= */

.document-name {
    display: block;
    width: 100%;
    min-width: 0;
    margin-bottom: 5px;
    color: var(--swift-forest-dark);
    font-size: .94rem;
    font-weight: 750;
    line-height: 1.4;
    /*
       Allow long filenames to wrap naturally.
       NEVER break every character.
    */
    white-space: normal;
    overflow-wrap: anywhere;
    word-break: normal;
}


/* =========================================================
   DOCUMENT META
   ========================================================= */

.document-meta {
    width: 100%;
    min-width: 0;
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    color: var(--swift-muted);
    font-size: .78rem;
    line-height: 1.6;
}


/* =========================================================
   FILE INFORMATION
   ========================================================= */

.document-file-meta {
    column-gap: 5px;
    row-gap: 2px;
}

.document-file-name {
    min-width: 0;
    max-width: 100%;
    overflow-wrap: anywhere;
    word-break: normal;
}

.document-separator {
    flex-shrink: 0;
    color: rgba(46, 125, 50, .40);
    margin: 0 2px;
}


/* =========================================================
   UPLOADED DATE
   ========================================================= */

.document-uploaded-meta {
    margin-top: 2px;
    gap: 4px;
}

    .document-uploaded-meta i {
        flex-shrink: 0;
        color: var(--swift-green);
    }

    .document-uploaded-meta span {
        white-space: normal;
    }


/* =========================================================
   DOCUMENT ACTIONS
   ========================================================= */

.document-actions {
    min-width: 145px;
    max-width: 230px;
    display: flex;
    align-items: center;
    justify-content: flex-end;
    flex-wrap: wrap;
    gap: 9px;
}

    .document-actions .status-badge {
        margin-bottom: 0 !important;
    }


/* =========================================================
   STATUS
   ========================================================= */

.status-badge {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 31px;
    padding: 6px 10px;
    border-radius: 9px;
    background: rgba(238, 243, 234, .85);
    border: 1px solid rgba(46, 125, 50, .08);
    color: #49604f;
    font-size: .74rem;
    font-weight: 750;
    white-space: nowrap;
}


/* =========================================================
   VIEW BUTTON
   ========================================================= */

.document-actions .btn-outline-success {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    white-space: nowrap;
    border-color: rgba(46, 125, 50, .30);
    color: var(--swift-green);
    border-radius: 9px;
    font-weight: 700;
    background: rgba(255, 255, 255, .55);
    transition: background .2s ease, border-color .2s ease, color .2s ease, transform .2s ease, box-shadow .2s ease;
}

    .document-actions .btn-outline-success:hover {
        background: var(--swift-green);
        border-color: var(--swift-green);
        color: #fff;
        transform: translateY(-1px);
        box-shadow: 0 5px 14px rgba(46, 125, 50, .16);
    }


/* =========================================================
   CORRECTION MESSAGE
   ========================================================= */

.document-correction {
    width: calc(100% - 68px);
    margin-top: 14px;
    margin-left: 68px;
}

    .document-correction .alert {
        display: block;
        width: 100%;
        margin: 0;
        border-radius: 14px;
        font-size: .80rem;
