/* =========================================================
   FINAL FIX - DOCUMENT DETAILS MUST NOT COLLAPSE
   ========================================================= */

.documents-card {
    width: 100%;
    min-width: 0;
    overflow: hidden;
}

.document-list {
    width: 100%;
    min-width: 0;
    display: block;
}

.document-row {
    width: 100%;
    min-width: 0;
    display: block;
}

.document-row-inner {
    width: 100%;
    min-width: 0;
    display: grid;
    /*
       NEVER allow the details column to collapse.
       The middle column gets all remaining space.
    */
    grid-template-columns: 52px minmax(250px, 1fr) auto;
    align-items: center;
    column-gap: 16px;
    box-sizing: border-box;
}


/* =========================================================
   DETAILS - FORCE PROPER WIDTH
   ========================================================= */

.document-details {
    display: block;
    width: 100%;
    min-width: 250px;
    max-width: 100%;
    overflow: hidden;
    box-sizing: border-box;
}

.document-name {
    display: block;
    width: 100%;
    max-width: 100%;
    color: var(--swift-forest-dark);
    font-size: .94rem;
    font-weight: 750;
    line-height: 1.4;
    margin: 0 0 5px 0;
    /*
       Normal text wrapping.
       NEVER break individual characters.
    */
    white-space: normal !important;
    word-break: normal !important;
    overflow-wrap: anywhere;
    writing-mode: horizontal-tb !important;
    text-orientation: mixed !important;
}

.document-meta {
    display: flex;
    width: 100%;
    max-width: 100%;
    align-items: center;
    flex-wrap: wrap;
    white-space: normal;
    writing-mode: horizontal-tb !important;
}

.document-file-meta {
    column-gap: 5px;
    row-gap: 2px;
}

.document-file-name {
    display: inline;
    max-width: 100%;
    white-space: normal !important;
    word-break: normal !important;
    overflow-wrap: anywhere;
}

.document-uploaded-meta {
    margin-top: 2px;
}


/* =========================================================
   ACTIONS MUST NOT STEAL THE DETAILS WIDTH
   ========================================================= */

.document-actions {
    flex-shrink: 0;
    min-width: 145px;
    width: auto;
    max-width: 230px;
    display: flex;
    align-items: center;
    justify-content: flex-end;
    flex-wrap: wrap;
    gap: 9px;
}


/* =========================================================
   LARGE SCREEN - GIVE DOCUMENTS MORE SPACE
   ========================================================= */

@media (min-width: 1200px) {

    .document-row-inner {
        grid-template-columns: 52px minmax(350px, 1fr) auto;
    }

    .document-details {
        min-width: 350px;
    }
}


