:root {
    --swift-forest: #1B5E20;
    --swift-forest-dark: #124116;
    --swift-green: #2E7D32;
    --swift-lime: #8BC34A;
    --swift-lime-soft: #DCEDC8;
    --swift-mint: #F0FDF4;
    --swift-text: #183a24;
    --swift-muted: #68786d;
    --swift-border: rgba(46, 125, 50, .15);
    --swift-glass: rgba(255, 255, 255, .72);
    --swift-glass-strong: rgba(255, 255, 255, .84);
    --swift-shadow: 0 18px 45px rgba(27, 94, 32, .09);
}

/* ============================================================
           PAGE
           ============================================================ */

.onboarding-page {
    max-width: 1180px;
    margin: 35px auto 70px;
    position: relative;
}

/* ============================================================
           HERO
           ============================================================ */

.onboarding-hero {
    position: relative;
    overflow: hidden;
    background: linear-gradient( 135deg, rgba(220, 237, 200, .94), rgba(240, 253, 244, .84) );
    border: 1px solid rgba(139, 195, 74, .28);
    border-radius: 28px;
    padding: 34px 36px;
    margin-bottom: 24px;
    box-shadow: 0 20px 50px rgba(27, 94, 32, .10), inset 0 1px 0 rgba(255, 255, 255, .88);
    backdrop-filter: blur(18px);
    -webkit-backdrop-filter: blur(18px);
}

    .onboarding-hero::before {
        content: "";
        position: absolute;
        width: 250px;
        height: 250px;
        right: -95px;
        top: -135px;
        border-radius: 50%;
        background: rgba(139, 195, 74, .19);
        filter: blur(2px);
    }

    .onboarding-hero::after {
        content: "";
        position: absolute;
        width: 150px;
        height: 150px;
        left: 28%;
        bottom: -110px;
        border-radius: 50%;
        background: rgba(46, 125, 50, .08);
    }

.hero-content {
    position: relative;
    z-index: 2;
}

.hero-icon {
    width: 58px;
    height: 58px;
    border-radius: 18px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    background: linear-gradient( 145deg, rgba(139, 195, 74, .95), rgba(46, 125, 50, .90) );
    color: #fff;
    font-size: 1.5rem;
    box-shadow: 0 10px 24px rgba(46, 125, 50, .18), inset 0 1px 0 rgba(255, 255, 255, .35);
    flex-shrink: 0;
}

.onboarding-hero h1 {
    color: var(--swift-forest-dark);
    font-size: 2rem;
    font-weight: 850;
    letter-spacing: -.025em;
    margin: 0 0 7px;
}

.onboarding-hero p {
    color: #526a5a;
    font-size: .94rem;
    line-height: 1.65;
    margin: 0;
}

/* ============================================================
           STATUS
           ============================================================ */

.status-pill {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 7px;
    padding: 8px 14px;
    border-radius: 50px;
    font-size: .76rem;
    font-weight: 800;
    letter-spacing: .01em;
    white-space: nowrap;
    border: 1px solid transparent;
}

.status-info {
    background: rgba(223, 244, 255, .82);
    color: #155d7a;
    border-color: rgba(21, 93, 122, .10);
}

.status-success {
    background: rgba(221, 247, 208, .88);
    color: #28702d;
    border-color: rgba(40, 112, 45, .12);
}

.status-warning {
    background: rgba(255, 241, 199, .90);
    color: #765800;
    border-color: rgba(118, 88, 0, .10);
}

.status-danger {
    background: rgba(255, 224, 223, .90);
    color: #8a2823;
    border-color: rgba(138, 40, 35, .10);
}

/* ============================================================
           PROGRESS
           ============================================================ */

.progress-card {
    position: relative;
    overflow: hidden;
    background: var(--swift-glass);
    border: 1px solid var(--swift-border);
    border-radius: 22px;
    padding: 24px 26px;
    margin-bottom: 20px;
    box-shadow: var(--swift-shadow), inset 0 1px 0 rgba(255, 255, 255, .86);
    backdrop-filter: blur(18px);
    -webkit-backdrop-filter: blur(18px);
}

    .progress-card::after {
        content: "";
        position: absolute;
        width: 130px;
        height: 130px;
        right: -70px;
        bottom: -80px;
        border-radius: 50%;
        background: rgba(139, 195, 74, .09);
    }

.progress-heading {
    color: var(--swift-forest-dark);
    font-weight: 800;
    font-size: .94rem;
}

.progress-step {
    color: var(--swift-muted);
    font-size: .82rem;
    font-weight: 600;
}

.progress {
    height: 11px;
    border-radius: 50px;
    background: rgba(232, 240, 228, .90);
    overflow: hidden;
    box-shadow: inset 0 1px 3px rgba(27, 94, 32, .06);
}

.progress-bar {
    background: linear-gradient( 90deg, #8BC34A, #72b82a, #4f9b39 );
    border-radius: 50px;
    box-shadow: 0 3px 10px rgba(114, 184, 42, .20), inset 0 1px 0 rgba(255, 255, 255, .35);
    transition: width .5s ease;
}

/* ============================================================
           APPLICATION SUMMARY
           ============================================================ */

.application-box {
    position: relative;
    overflow: hidden;
    background: rgba(240, 253, 244, .68);
    border: 1px solid rgba(139, 195, 74, .17);
    border-radius: 19px;
    padding: 19px 21px;
    margin-bottom: 28px;
    box-shadow: 0 9px 25px rgba(27, 94, 32, .05), inset 0 1px 0 rgba(255, 255, 255, .80);
    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);
}

.application-item {
    position: relative;
    padding: 3px 14px;
}

    .application-item:not(:last-child) {
        border-right: 1px solid rgba(46, 125, 50, .10);
    }

.application-label {
    display: block;
    color: #809087;
    font-size: .71rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: .055em;
    margin-bottom: 3px;
}

.application-value {
    color: var(--swift-forest-dark);
    font-size: .91rem;
    font-weight: 800;
}

/* ============================================================
           SECTION TITLE
           ============================================================ */

.steps-heading {
    margin-bottom: 17px;
}

    .steps-heading h3 {
        color: var(--swift-forest-dark);
        font-size: 1.2rem;
        font-weight: 850;
        margin-bottom: 4px;
    }

    .steps-heading p {
        color: var(--swift-muted);
        font-size: .84rem;
        margin: 0;
    }

/* ============================================================
           STEP CARDS
           ============================================================ */

.step-card {
    position: relative;
    overflow: hidden;
    height: 100%;
    background: var(--swift-glass);
    border: 1px solid var(--swift-border);
    border-radius: 23px;
    padding: 25px;
    box-shadow: var(--swift-shadow), inset 0 1px 0 rgba(255, 255, 255, .86);
    backdrop-filter: blur(18px);
    -webkit-backdrop-filter: blur(18px);
    transition: transform .25s ease, box-shadow .25s ease, border-color .25s ease;
}

    .step-card::before {
        content: "";
        position: absolute;
        width: 145px;
        height: 145px;
        top: -90px;
        right: -65px;
        border-radius: 50%;
        background: rgba(139, 195, 74, .08);
        pointer-events: none;
    }

    .step-card:hover {
        transform: translateY(-3px);
        border-color: rgba(46, 125, 50, .25);
        box-shadow: 0 22px 52px rgba(27, 94, 32, .13), inset 0 1px 0 rgba(255, 255, 255, .90);
    }

    .step-card.locked {
        opacity: .72;
        background: rgba(247, 250, 245, .68);
    }

    .step-card.completed {
        border-color: rgba(139, 195, 74, .25);
        background: linear-gradient( 145deg, rgba(240, 253, 244, .82), rgba(255, 255, 255, .68) );
    }

.step-number {
    position: absolute;
    top: 18px;
    right: 19px;
    width: 27px;
    height: 27px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    background: rgba(220, 237, 200, .68);
    color: var(--swift-green);
    font-size: .72rem;
    font-weight: 850;
    border: 1px solid rgba(139, 195, 74, .20);
}

.step-icon {
    position: relative;
    z-index: 1;
    width: 49px;
    height: 49px;
    border-radius: 15px;
    background: linear-gradient( 145deg, rgba(220, 237, 200, .96), rgba(240, 253, 244, .96) );
    color: var(--swift-green);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.2rem;
    margin-bottom: 17px;
    border: 1px solid rgba(139, 195, 74, .20);
    box-shadow: 0 7px 17px rgba(27, 94, 32, .07), inset 0 1px 0 rgba(255, 255, 255, .85);
}

.step-card h5 {
    position: relative;
    z-index: 1;
    color: var(--swift-forest-dark);
    font-size: 1rem;
    font-weight: 800;
    letter-spacing: -.01em;
    margin-bottom: 8px;
}

.step-card p {
    position: relative;
    z-index: 1;
    color: var(--swift-muted);
    font-size: .84rem;
    line-height: 1.65;
    min-height: 56px;
    margin-bottom: 17px;
}

.step-state {
    display: flex;
    align-items: center;
    gap: 7px;
    color: #6e7d72;
    font-size: .78rem;
    font-weight: 700;
}

    .step-state i {
        font-size: .95rem;
    }

    .step-state.completed-state {
        color: #28702d;
    }

    .step-state.locked-state {
        color: #89958c;
    }

/* ============================================================
           BUTTONS
           ============================================================ */

.btn-swift {
    position: relative;
    z-index: 2;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 7px;
    background: linear-gradient( 135deg, #8BC34A, #72b82a );
    border: 1px solid rgba(91, 143, 34, .30);
    color: #163d25;
    font-weight: 800;
    font-size: .82rem;
    border-radius: 11px;
    padding: 10px 16px;
    box-shadow: 0 8px 18px rgba(91, 143, 34, .15), inset 0 1px 0 rgba(255, 255, 255, .45);
    transition: transform .2s ease, box-shadow .2s ease, background .2s ease;
}

    .btn-swift:hover {
        background: linear-gradient( 135deg, #9bd35d, #7fc438 );
        border-color: rgba(91, 143, 34, .38);
        color: #163d25;
        transform: translateY(-1px);
        box-shadow: 0 12px 24px rgba(91, 143, 34, .21), inset 0 1px 0 rgba(255, 255, 255, .50);
    }

    .btn-swift:active {
        transform: translateY(0);
    }

/* ============================================================
           STATUS FOOTER
           ============================================================ */

.onboarding-message {
    position: relative;
    overflow: hidden;
    margin-top: 28px;
    padding: 21px 23px;
    border-radius: 20px;
    border: 1px solid rgba(46, 125, 50, .13);
    background: rgba(255, 255, 255, .66);
    box-shadow: 0 12px 30px rgba(27, 94, 32, .06), inset 0 1px 0 rgba(255, 255, 255, .82);
    backdrop-filter: blur(15px);
    -webkit-backdrop-filter: blur(15px);
}

    .onboarding-message.success-message {
        background: rgba(240, 253, 244, .78);
        border-color: rgba(46, 125, 50, .18);
    }

    .onboarding-message.warning-message {
        background: rgba(255, 249, 229, .78);
        border-color: rgba(180, 135, 25, .16);
    }

    .onboarding-message.danger-message {
        background: rgba(255, 245, 245, .80);
        border-color: rgba(180, 50, 50, .15);
    }

.message-icon {
    width: 43px;
    height: 43px;
    flex-shrink: 0;
    border-radius: 13px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: rgba(220, 237, 200, .80);
    color: var(--swift-green);
    font-size: 1.1rem;
}

.onboarding-message h6 {
    color: var(--swift-forest-dark);
    font-weight: 800;
    margin-bottom: 3px;
}

.onboarding-message p {
    color: var(--swift-muted);
    font-size: .82rem;
    line-height: 1.6;
    margin: 0;
}

