/* =========================================================
           SWIFTCARE VOLUNTEER ONBOARDING
           Matches Volunteer Applications ATS design
           ========================================================= */

.sc-admin-onboarding-page {
    min-height: calc(100vh - 80px);
    padding: 22px 12px 50px;
    background: radial-gradient( circle at 8% 0%, rgba(139, 195, 74, .10), transparent 28% ), radial-gradient( circle at 92% 8%, rgba(46, 125, 50, .08), transparent 30% ), #f8fbf8;
}


.sc-admin-onboarding-container {
    width: 100%;
    max-width: 1500px;
    margin: 0 auto;
}


/* =========================================================
           HEADER
           ========================================================= */

.sc-admin-onboarding-header {
    display: flex;
    align-items: flex-end;
    justify-content: space-between;
    gap: 20px;
    margin-bottom: 22px;
}


.sc-admin-onboarding-heading {
    display: flex;
    align-items: center;
    gap: 16px;
}


.sc-admin-onboarding-icon {
    width: 58px;
    height: 58px;
    flex: 0 0 58px;
    border-radius: 18px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: linear-gradient( 145deg, #e8f8b7, #dff2a0 );
    border: 1px solid #c8e58d;
    color: #176b3a;
    font-size: 25px;
    box-shadow: 0 10px 25px rgba(23, 107, 58, .10);
}


.sc-admin-onboarding-eyebrow {
    margin: 0 0 4px;
    color: #176b3a;
    font-size: 10px;
    font-weight: 900;
    letter-spacing: 2px;
    text-transform: uppercase;
}


.sc-admin-onboarding-title {
    margin: 0;
    color: #064b2a;
    font-size: clamp(27px, 3vw, 36px);
    font-weight: 900;
    letter-spacing: -.7px;
    line-height: 1.05;
}


.sc-admin-onboarding-subtitle {
    margin: 7px 0 0;
    color: #718096;
    font-size: 13px;
    font-weight: 500;
}


.sc-admin-onboarding-actions {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: 10px;
    flex-wrap: wrap;
}


/* =========================================================
           BACK BUTTON
           ========================================================= */

.sc-admin-onboarding-back {
    min-height: 43px;
    padding: 0 17px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    border-radius: 11px;
    background: #ffffff;
    border: 1px solid #176b3a;
    color: #176b3a !important;
    font-size: 12px;
    font-weight: 800;
    text-decoration: none !important;
    box-shadow: 0 5px 16px rgba(23, 107, 58, .08);
    transition: all .2s ease;
}


    .sc-admin-onboarding-back:hover {
        background: #176b3a;
        color: #ffffff !important;
        transform: translateY(-1px);
        box-shadow: 0 8px 20px rgba(23, 107, 58, .18);
    }


/* =========================================================
           SUMMARY CARDS
           ========================================================= */

.sc-admin-onboarding-summary {
    display: grid;
    grid-template-columns: repeat(5, minmax(0, 1fr));
    gap: 15px;
    margin-bottom: 23px;
}


.sc-admin-onboarding-summary-card {
    position: relative;
    min-height: 96px;
    overflow: hidden;
    border-radius: 18px;
    background: #ffffff;
    border: 1px solid #eef2ef;
    box-shadow: 0 8px 28px rgba(20, 70, 42, .07);
    padding: 17px 18px;
}


    .sc-admin-onboarding-summary-card::after {
        content: "";
        position: absolute;
        right: -18px;
        bottom: -30px;
        width: 72px;
        height: 72px;
        border-radius: 50%;
        background: #effaf4;
    }


.sc-onboarding-summary-content {
    position: relative;
    z-index: 2;
    display: flex;
    align-items: center;
    gap: 13px;
}


.sc-onboarding-summary-icon {
    width: 47px;
    height: 47px;
    flex: 0 0 47px;
    border-radius: 14px;
    background: #e8f8ef;
    color: #168345;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 20px;
}


.sc-onboarding-summary-label {
    margin: 0 0 2px;
    color: #738099;
    font-size: 10px;
    line-height: 1.2;
    font-weight: 900;
    letter-spacing: 1.4px;
    text-transform: uppercase;
}


.sc-onboarding-summary-value {
    margin: 0;
    color: #182338;
    font-size: 27px;
    line-height: 1;
    font-weight: 900;
}


/* =========================================================
           MAIN TABLE CARD
           ========================================================= */

.sc-admin-onboarding-card {
    overflow: hidden;
    border-radius: 19px;
    background: #ffffff;
    border: 1px solid #dbe8df;
    box-shadow: 0 12px 35px rgba(20, 70, 42, .08);
}


.sc-admin-onboarding-card-header {
    min-height: 84px;
    padding: 16px 22px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 15px;
    border-bottom: 1px solid #e6eee8;
    background: #ffffff;
}


.sc-admin-onboarding-card-eyebrow {
    margin: 0 0 5px;
    color: #17723e;
    font-size: 9px;
    font-weight: 900;
    letter-spacing: 1.5px;
    text-transform: uppercase;
}


.sc-admin-onboarding-card-title {
    margin: 0;
    color: #064b2a;
    font-size: 20px;
    font-weight: 900;
    letter-spacing: -.25px;
}


.sc-admin-onboarding-count {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    padding: 9px 13px;
    border-radius: 999px;
    background: #f1f8f2;
    border: 1px solid #dcebdc;
    color: #176b3a;
    font-size: 11px;
    font-weight: 800;
    white-space: nowrap;
}


    .sc-admin-onboarding-count i {
        color: #6caa35;
    }


/* =========================================================
           TABLE
           ========================================================= */

.sc-admin-onboarding-table-wrapper {
    width: 100%;
    overflow-x: auto;
    overflow-y: hidden;
    -webkit-overflow-scrolling: touch;
}


.sc-admin-onboarding-table {
    width: 100%;
    min-width: 1260px;
    margin: 0;
    border-collapse: separate;
    border-spacing: 0;
}


    .sc-admin-onboarding-table thead th {
        height: 48px;
        padding: 0 17px;
        background: #f8faf8;
        border-bottom: 1px solid #dfe9e1;
        color: #6d7d74;
        font-size: 9px;
        line-height: 1;
        font-weight: 900;
        letter-spacing: 1.1px;
        text-transform: uppercase;
        white-space: nowrap;
        vertical-align: middle;
    }


    .sc-admin-onboarding-table tbody td {
        height: 68px;
        padding: 9px 17px;
        border-bottom: 1px solid #edf2ee;
        color: #263238;
        background: #ffffff;
        font-size: 12px;
        vertical-align: middle;
        white-space: nowrap;
    }


    .sc-admin-onboarding-table tbody tr {
        transition: background .18s ease;
    }


        .sc-admin-onboarding-table tbody tr:hover td {
            background: #f7fcf8;
        }


        .sc-admin-onboarding-table tbody tr:last-child td {
            border-bottom: 0;
        }


/* =========================================================
           REFERENCE
           ========================================================= */

.sc-onboarding-reference {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    color: #07532d;
    font-size: 11px;
    font-weight: 900;
    letter-spacing: .2px;
}


.sc-onboarding-reference-icon {
    width: 31px;
    height: 31px;
    border-radius: 9px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    background: #edf8d7;
    color: #176b3a;
    font-size: 12px;
    font-weight: 900;
}


/* =========================================================
           APPLICANT
           ========================================================= */

.sc-onboarding-applicant {
    display: flex;
    align-items: center;
    gap: 10px;
    min-width: 205px;
}


.sc-onboarding-avatar {
    width: 36px;
    height: 36px;
    flex: 0 0 36px;
    border-radius: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #edf8e8;
    color: #176b3a;
    font-size: 11px;
    font-weight: 900;
    border: 1px solid #dcebdc;
}


.sc-onboarding-applicant-name {
    margin: 0;
    color: #123d2a;
    font-size: 11px;
    font-weight: 900;
    text-transform: uppercase;
    letter-spacing: .1px;
}


.sc-onboarding-applicant-email {
    max-width: 190px;
    overflow: hidden;
    text-overflow: ellipsis;
    margin: 3px 0 0;
    color: #8a9690;
    font-size: 9px;
    font-weight: 600;
}


/* =========================================================
           OPPORTUNITY
           ========================================================= */

.sc-onboarding-opportunity {
    display: flex;
    align-items: center;
    gap: 9px;
    max-width: 245px;
}


.sc-onboarding-opportunity-icon {
    width: 31px;
    height: 31px;
    flex: 0 0 31px;
    border-radius: 9px;
    background: #edf8e8;
    color: #19733f;
    display: flex;
    align-items: center;
    justify-content: center;
}


.sc-onboarding-opportunity-title {
    max-width: 205px;
    overflow: hidden;
    text-overflow: ellipsis;
    color: #1c4733;
    font-size: 11px;
    font-weight: 800;
}


/* =========================================================
           STEP
           ========================================================= */

.sc-onboarding-step {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    min-height: 30px;
    padding: 5px 10px;
    border-radius: 999px;
    font-size: 10px;
    font-weight: 800;
    white-space: nowrap;
    border: 1px solid transparent;
}


.step-one {
    background: #f1f5f3;
    border-color: #dfe7e2;
    color: #53635a;
}


.step-two {
    background: #f3edff;
    border-color: #dfd0fa;
    color: #7139b7;
}


.step-three {
    background: #eaf5ff;
    border-color: #cce4f6;
    color: #166d9d;
}


.step-four {
    background: #fff8e4;
    border-color: #f1e3b0;
    color: #8b6a00;
}


.step-five {
    background: #e8f7ef;
    border-color: #c4e9d2;
    color: #18753f;
}


.step-six {
    background: #ddf8e9;
    border-color: #b6eacb;
    color: #08723b;
}


.step-default {
    background: #f3f5f4;
    border-color: #e2e8e4;
    color: #65726b;
}


/* =========================================================
           STATUS
           ========================================================= */

.sc-onboarding-status {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    min-height: 29px;
    padding: 5px 10px;
    border-radius: 999px;
    font-size: 10px;
    font-weight: 800;
    white-space: nowrap;
    border: 1px solid transparent;
}


.status-pending {
    background: #fff8e4;
    border-color: #f1e3b0;
    color: #8b6a00;
}


.status-verification {
    background: #f3edff;
    border-color: #dfd0fa;
    color: #7139b7;
}


.status-ready {
    background: #e8f7ef;
    border-color: #c4e9d2;
    color: #18753f;
}


.status-completed {
    background: #ddf8e9;
    border-color: #b6eacb;
    color: #08723b;
}


.status-rejected {
    background: #fff0f0;
    border-color: #f3cccc;
    color: #b53939;
}


.status-neutral {
    background: #f3f5f4;
    border-color: #e2e8e4;
    color: #65726b;
}


/* =========================================================
           DOCUMENT STATUS
           ========================================================= */

.sc-onboarding-document {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    min-height: 29px;
    padding: 5px 10px;
    border-radius: 999px;
    font-size: 10px;
    font-weight: 800;
    white-space: nowrap;
    border: 1px solid transparent;
}


.document-verified {
    background: #ddf8e9;
    border-color: #b6eacb;
    color: #08723b;
}


.document-review {
    background: #fff8e4;
    border-color: #f1e3b0;
    color: #8b6a00;
}


.document-uploaded {
    background: #eaf5ff;
    border-color: #cce4f6;
    color: #166d9d;
}


.document-attention {
    background: #fff0f0;
    border-color: #f3cccc;
    color: #b53939;
}


.document-empty {
    background: #f3f5f4;
    border-color: #e2e8e4;
    color: #65726b;
}


/* =========================================================
           PROGRESS
           ========================================================= */

.sc-onboarding-progress {
    display: flex;
    align-items: center;
    gap: 9px;
    min-width: 105px;
}


.sc-onboarding-progress-track {
    width: 65px;
    height: 6px;
    overflow: hidden;
    border-radius: 999px;
    background: #e7eee9;
}


.sc-onboarding-progress-fill {
    height: 100%;
    border-radius: inherit;
    background: linear-gradient( 90deg, #176b3a, #8bc34a );
}


.sc-onboarding-progress-text {
    color: #65746b;
    font-size: 9px;
    font-weight: 900;
}


/* =========================================================
           DATE
           ========================================================= */

.sc-onboarding-date {
    display: flex;
    align-items: center;
    gap: 7px;
    color: #596860;
    font-size: 10px;
    font-weight: 700;
}


    .sc-onboarding-date i {
        color: #6cae45;
        font-size: 13px;
    }


/* =========================================================
           REVIEW BUTTON
           ========================================================= */

.sc-onboarding-review-button {
    min-height: 31px;
    padding: 0 11px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    border-radius: 9px;
    background: #ffffff;
    border: 1px solid #cfe0d4;
    color: #176b3a !important;
    text-decoration: none !important;
    font-size: 10px;
    font-weight: 900;
    transition: all .18s ease;
}


    .sc-onboarding-review-button:hover {
        background: #176b3a;
        border-color: #176b3a;
        color: #ffffff !important;
        transform: translateY(-1px);
        box-shadow: 0 5px 14px rgba(23, 107, 58, .16);
    }


/* =========================================================
           EMPTY STATE
           ========================================================= */

.sc-admin-onboarding-empty {
    padding: 65px 25px;
    text-align: center;
}


.sc-admin-onboarding-empty-icon {
    width: 70px;
    height: 70px;
    margin: 0 auto 17px;
    border-radius: 20px;
    background: #edf8e8;
    color: #176b3a;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 30px;
}


.sc-admin-onboarding-empty h3 {
    margin: 0 0 7px;
    color: #17472f;
    font-size: 20px;
    font-weight: 900;
}


.sc-admin-onboarding-empty p {
    margin: 0;
    color: #829087;
    font-size: 13px;
}


/* =========================================================
           RESPONSIVE
           ========================================================= */

@media (max-width: 1100px) {

    .sc-admin-onboarding-summary {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }

    .sc-admin-onboarding-header {
        align-items: flex-start;
        flex-direction: column;
    }

    .sc-admin-onboarding-actions {
        width: 100%;
        justify-content: flex-start;
    }
}


@media (max-width: 720px) {

    .sc-admin-onboarding-page {
        padding: 16px 8px 35px;
    }

    .sc-admin-onboarding-summary {
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 10px;
    }

    .sc-admin-onboarding-summary-card {
        min-height: 88px;
        padding: 13px;
    }

    .sc-onboarding-summary-icon {
        width: 40px;
        height: 40px;
        flex-basis: 40px;
        font-size: 17px;
    }

    .sc-onboarding-summary-value {
        font-size: 23px;
    }

    .sc-admin-onboarding-card-header {
        padding: 14px 15px;
    }

    .sc-admin-onboarding-card-title {
        font-size: 17px;
    }

    .sc-admin-onboarding-count {
        display: none;
    }
}


@media (max-width: 520px) {

    .sc-admin-onboarding-heading {
        align-items: flex-start;
    }

    .sc-admin-onboarding-icon {
        width: 48px;
        height: 48px;
        flex-basis: 48px;
        border-radius: 14px;
        font-size: 20px;
    }

    .sc-admin-onboarding-title {
        font-size: 26px;
    }

    .sc-admin-onboarding-subtitle {
        font-size: 12px;
    }

    .sc-admin-onboarding-actions {
        display: grid;
        grid-template-columns: 1fr;
    }

    .sc-admin-onboarding-back {
        width: 100%;
    }

    .sc-admin-onboarding-summary {
        grid-template-columns: 1fr 1fr;
    }

    .sc-onboarding-summary-content {
        gap: 9px;
    }

    .sc-onboarding-summary-label {
        font-size: 8px;
        letter-spacing: 1px;
    }

    .sc-onboarding-summary-value {
        font-size: 21px;
    }
}
/* =========================================================
           PAGE
           ========================================================= */

.onboarding-review-page {
    width: 100%;
    max-width: 1500px;
    margin: 0 auto;
    padding: 18px 12px 60px;
}


/* =========================================================
           HEADER
           ========================================================= */

.review-hero {
    position: relative;
    overflow: hidden;
    border-radius: 26px;
    padding: 28px 30px;
    margin-bottom: 20px;
    background: linear-gradient( 135deg, rgba(240, 253, 244, .94), rgba(220, 237, 200, .78) );
    border: 1px solid rgba(46, 125, 50, .18);
    box-shadow: 0 18px 50px rgba(27, 94, 32, .08), inset 0 1px 0 rgba(255,255,255,.75);
    backdrop-filter: blur(18px);
    -webkit-backdrop-filter: blur(18px);
}

    .review-hero::before {
        content: "";
        position: absolute;
        width: 230px;
        height: 230px;
        border-radius: 50%;
        background: rgba(139, 195, 74, .18);
        right: -75px;
        top: -105px;
        pointer-events: none;
    }

    .review-hero::after {
        content: "";
        position: absolute;
        width: 150px;
        height: 150px;
        border-radius: 50%;
        background: rgba(46, 125, 50, .07);
        left: -55px;
        bottom: -80px;
        pointer-events: none;
    }

.review-hero-content {
    position: relative;
    z-index: 2;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 24px;
}

.review-hero-left {
    min-width: 0;
}

.review-eyebrow {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    color: #17652a;
    font-size: .72rem;
    font-weight: 900;
    letter-spacing: .15em;
    text-transform: uppercase;
    margin-bottom: 8px;
}

    .review-eyebrow i {
        font-size: 1rem;
    }

.review-hero h1 {
    margin: 0;
    color: #073b20;
    font-size: clamp(1.8rem, 3vw, 2.65rem);
    font-weight: 900;
    letter-spacing: -.035em;
    line-height: 1.05;
}

.review-hero-subtitle {
    margin: 9px 0 0;
    color: #557062;
    font-size: .95rem;
    font-weight: 500;
}

.review-status-area {
    display: flex;
    align-items: center;
    gap: 12px;
    flex-shrink: 0;
}


/* =========================================================
           BACK BUTTON
           ========================================================= */

.btn-back-onboarding {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    min-height: 42px;
    padding: 10px 17px;
    border-radius: 12px;
    border: 1px solid #124116;
    background: #124116;
    color: #ffffff !important;
    text-decoration: none !important;
    font-size: .82rem;
    font-weight: 800;
    box-shadow: 0 7px 18px rgba(18, 65, 22, .16);
    transition: transform .2s ease, box-shadow .2s ease, background .2s ease;
}

    .btn-back-onboarding:hover {
        background: #0b3210;
        color: #ffffff !important;
        transform: translateY(-2px);
        box-shadow: 0 11px 24px rgba(18, 65, 22, .22);
    }

    .btn-back-onboarding i {
        font-size: 1rem;
    }


/* =========================================================
           STATUS PILLS
           ========================================================= */

.review-status-pill {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    min-height: 40px;
    padding: 9px 15px;
    border-radius: 999px;
    background: rgba(255,255,255,.72);
    border: 1px solid rgba(46,125,50,.18);
    color: #155724;
    font-size: .78rem;
    font-weight: 850;
    box-shadow: 0 5px 16px rgba(27,94,32,.06);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
}

    .review-status-pill i {
        color: #2e7d32;
    }


/* =========================================================
           SUMMARY CARDS
           ========================================================= */

.review-summary-grid {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 14px;
    margin-bottom: 20px;
}

.review-summary-card {
    position: relative;
    overflow: hidden;
    display: flex;
    align-items: center;
    gap: 13px;
    min-height: 92px;
    padding: 17px;
    border-radius: 18px;
    background: rgba(255,255,255,.72);
    border: 1px solid rgba(46,125,50,.12);
    box-shadow: 0 12px 32px rgba(27,94,32,.055), inset 0 1px 0 rgba(255,255,255,.85);
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
}

    .review-summary-card::after {
        content: "";
        position: absolute;
        width: 85px;
        height: 85px;
        border-radius: 50%;
        right: -28px;
        bottom: -40px;
        background: rgba(139,195,74,.10);
    }

.summary-icon {
    width: 48px;
    height: 48px;
    min-width: 48px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 14px;
    background: linear-gradient( 145deg, #efffd8, #dcf2bd );
    border: 1px solid rgba(139,195,74,.35);
    color: #23752c;
    font-size: 1.25rem;
    position: relative;
    z-index: 2;
}

.summary-content {
    min-width: 0;
    position: relative;
    z-index: 2;
}

.summary-label {
    display: block;
    color: #7b8a80;
    font-size: .66rem;
    font-weight: 850;
    letter-spacing: .11em;
    text-transform: uppercase;
    margin-bottom: 3px;
}

.summary-value {
    color: #123d25;
    font-size: 1.35rem;
    font-weight: 900;
    line-height: 1;
}

    .summary-value small {
        color: #839087;
        font-size: .72rem;
        font-weight: 650;
    }


/* =========================================================
           GLASS CARDS
           ========================================================= */

.review-card {
    position: relative;
    overflow: hidden;
    height: 100%;
    padding: 23px;
    border-radius: 21px;
    background: linear-gradient( 145deg, rgba(255,255,255,.87), rgba(248,253,247,.72) );
    border: 1px solid rgba(46,125,50,.13);
    box-shadow: 0 15px 42px rgba(27,94,32,.055), inset 0 1px 0 rgba(255,255,255,.9);
    backdrop-filter: blur(18px);
    -webkit-backdrop-filter: blur(18px);
}

    .review-card::after {
        content: "";
        position: absolute;
        width: 130px;
        height: 130px;
        border-radius: 50%;
        right: -65px;
        top: -65px;
        background: rgba(139,195,74,.055);
        pointer-events: none;
    }

.review-card-header {
    position: relative;
    z-index: 2;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 14px;
    padding-bottom: 16px;
    margin-bottom: 17px;
    border-bottom: 1px solid rgba(46,125,50,.10);
}

.review-card-title {
    display: flex;
    align-items: center;
    gap: 11px;
    color: #073b20;
    font-size: 1.02rem;
    font-weight: 850;
    margin: 0;
}

.review-card-title-icon {
    width: 37px;
    height: 37px;
    min-width: 37px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 11px;
    background: #e8f8df;
    border: 1px solid #d1ebc4;
    color: #20752d;
    font-size: .95rem;
}


/* =========================================================
           APPLICANT INFORMATION
           ========================================================= */

.applicant-profile {
    display: flex;
    align-items: center;
    gap: 14px;
    padding: 14px;
    margin-bottom: 20px;
    border-radius: 15px;
    background: rgba(240,253,244,.72);
    border: 1px solid rgba(46,125,50,.10);
}

.applicant-avatar {
    width: 52px;
    height: 52px;
    min-width: 52px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 15px;
    background: linear-gradient( 145deg, #8bc34a, #5fa326 );
    color: #123d1c;
    font-size: 1.2rem;
    font-weight: 900;
    box-shadow: 0 7px 18px rgba(95,163,38,.18);
}

.applicant-profile-name {
    color: #123d25;
    font-weight: 850;
    line-height: 1.2;
}

.applicant-profile-role {
    margin-top: 4px;
    color: #708077;
    font-size: .78rem;
}

.info-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 14px;
}

.info-box {
    min-width: 0;
    padding: 12px 13px;
    border-radius: 13px;
    background: rgba(248,251,247,.78);
    border: 1px solid rgba(46,125,50,.08);
}

    .info-box.full-width {
        grid-column: 1 / -1;
    }

.info-label {
    display: block;
    margin-bottom: 4px;
    color: #819087;
    font-size: .65rem;
    font-weight: 850;
    letter-spacing: .09em;
    text-transform: uppercase;
}

.info-value {
    color: #234b31;
    font-size: .87rem;
    font-weight: 750;
    overflow-wrap: anywhere;
}


/* =========================================================
           REQUIREMENTS
           ========================================================= */

.requirements-progress {
    margin-bottom: 17px;
}

.requirements-progress-top {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 7px;
}

.requirements-progress-label {
    color: #637369;
    font-size: .74rem;
    font-weight: 750;
}

.requirements-progress-value {
    color: #23752c;
    font-size: .74rem;
    font-weight: 900;
}

.requirements-progress-bar {
    height: 8px;
    overflow: hidden;
    border-radius: 999px;
    background: #e7efe5;
}

.requirements-progress-fill {
    height: 100%;
    border-radius: inherit;
    background: linear-gradient( 90deg, #2e7d32, #8bc34a );
    transition: width .4s ease;
}

.requirement-item {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 13px 0;
    border-bottom: 1px solid rgba(46,125,50,.08);
}

    .requirement-item:last-child {
        border-bottom: 0;
        padding-bottom: 0;
    }

.requirement-icon {
    width: 35px;
    height: 35px;
    min-width: 35px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 10px;
    background: #f1f5ef;
    color: #87948b;
}

    .requirement-icon.completed {
        background: #e5f6dd;
        color: #20822d;
    }

.requirement-content {
    min-width: 0;
    flex: 1;
}

.requirement-title {
    color: #174d32;
    font-size: .87rem;
    font-weight: 800;
}

.requirement-description {
    display: block;
    margin-top: 3px;
    color: #7b877f;
    font-size: .74rem;
    line-height: 1.45;
}


/* =========================================================
           STATUS BADGES
           ========================================================= */

.status-badge {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 5px;
    padding: 6px 10px;
    border-radius: 999px;
    background: #eef4eb;
    border: 1px solid #dce8d9;
    color: #4b6350;
    font-size: .68rem;
    font-weight: 850;
    white-space: nowrap;
}

    .status-badge.completed,
    .status-badge.verified {
        background: #e5f8df;
        border-color: #c9e9bd;
        color: #19752a;
    }

    .status-badge.pending {
        background: #fff8df;
        border-color: #f2e4ad;
        color: #856d18;
    }

    .status-badge.rejected {
        background: #fff0f0;
        border-color: #f3cccc;
        color: #a42e2e;
    }


/* =========================================================
           DOCUMENTS
           ========================================================= */

.documents-summary {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
}

.document-summary-pill {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 7px 10px;
    border-radius: 999px;
    background: rgba(240,253,244,.75);
    border: 1px solid rgba(46,125,50,.11);
    color: #557060;
    font-size: .7rem;
    font-weight: 800;
}

    .document-summary-pill strong {
        color: #164c29;
    }

.document-item {
    padding: 16px 0;
    border-bottom: 1px solid rgba(46,125,50,.09);
}

    .document-item:last-child {
        border-bottom: 0;
        padding-bottom: 0;
    }

.document-row {
    display: grid;
    grid-template-columns: minmax(260px, 1.7fr) minmax(120px, .7fr) minmax(120px, .7fr) minmax(180px, auto);
    align-items: center;
    gap: 18px;
}

.document-main {
    min-width: 0;
}

.document-icon {
    width: 42px;
    height: 42px;
    min-width: 42px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 12px;
    background: #edf9e7;
    border: 1px solid #d8edca;
    color: #24752e;
    font-size: 1.05rem;
}

.document-name {
    color: #174d32;
    font-size: .88rem;
    font-weight: 850;
    overflow-wrap: anywhere;
}

.document-meta {
    margin-top: 4px;
    color: #829087;
    font-size: .7rem;
    overflow-wrap: anywhere;
}

    .document-meta i {
        margin-right: 3px;
    }

.document-date {
    color: #6d7d73;
    font-size: .75rem;
    font-weight: 650;
}

.document-actions {
    display: flex;
    justify-content: flex-end;
    flex-wrap: wrap;
    gap: 7px;
}


/* =========================================================
           BUTTONS
           ========================================================= */

.btn-swift {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 7px;
    min-height: 39px;
    padding: 9px 15px;
    border: 0;
    border-radius: 11px;
    background: linear-gradient( 135deg, #8bc34a, #70b82e );
    color: #163d25 !important;
    font-size: .78rem;
    font-weight: 850;
    box-shadow: 0 7px 18px rgba(112,184,46,.18);
    transition: transform .2s ease, box-shadow .2s ease;
}

    .btn-swift:hover {
        color: #102d1c !important;
        transform: translateY(-2px);
        box-shadow: 0 10px 23px rgba(112,184,46,.25);
    }

.btn-outline-swift {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 7px;
    min-height: 39px;
    padding: 9px 15px;
    border: 1px solid #2e7d32;
    border-radius: 11px;
    background: rgba(255,255,255,.65);
    color: #1d6d2a !important;
    font-size: .78rem;
    font-weight: 800;
    transition: .2s ease;
}

    .btn-outline-swift:hover {
        background: #eaf8e4;
        color: #155d22 !important;
        transform: translateY(-1px);
    }


/* =========================================================
           VERIFICATION PANEL
           ========================================================= */

.verification-card {
    background: linear-gradient( 135deg, rgba(240,253,244,.88), rgba(255,255,255,.75) );
}

.verification-state {
    display: flex;
    align-items: center;
    gap: 15px;
    padding: 15px 17px;
    margin-bottom: 17px;
    border-radius: 15px;
    background: rgba(255,255,255,.63);
    border: 1px solid rgba(46,125,50,.10);
}

.verification-state-icon {
    width: 45px;
    height: 45px;
    min-width: 45px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 13px;
    background: #e6f7df;
    color: #21802d;
    font-size: 1.15rem;
}

.verification-state-title {
    color: #174d32;
    font-size: .87rem;
    font-weight: 850;
}

.verification-state-text {
    margin-top: 3px;
    color: #718077;
    font-size: .74rem;
}

.verification-actions {
    display: flex;
    flex-wrap: wrap;
    gap: 9px;
}


/* =========================================================
           ACTIVATION
           ========================================================= */

.activation-panel {
    position: relative;
    overflow: hidden;
    padding: 22px;
    border-radius: 17px;
    background: linear-gradient( 135deg, rgba(239,255,220,.94), rgba(248,255,241,.85) );
    border: 1px solid #d3e9bd;
    box-shadow: inset 0 1px 0 rgba(255,255,255,.8);
}

    .activation-panel::after {
        content: "";
        position: absolute;
        width: 150px;
        height: 150px;
        border-radius: 50%;
        right: -65px;
        bottom: -80px;
        background: rgba(139,195,74,.12);
    }

.activation-content {
    position: relative;
    z-index: 2;
}

.activation-icon {
    width: 49px;
    height: 49px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 14px;
    background: #dff3cf;
    color: #21752c;
    font-size: 1.25rem;
    margin-bottom: 12px;
}

.activation-panel h5 {
    color: #174d32;
    font-size: 1rem;
    font-weight: 900;
    margin-bottom: 6px;
}

.activation-panel p {
    color: #65756b;
    font-size: .82rem;
    line-height: 1.55;
    max-width: 720px;
}


/* =========================================================
           EMPTY STATE
           ========================================================= */

.empty-state {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 17px;
    border-radius: 14px;
    background: rgba(247,250,246,.75);
    border: 1px dashed #d7e4d5;
    color: #738077;
    font-size: .8rem;
}

    .empty-state i {
        color: #6e9272;
        font-size: 1.05rem;
    }


/* =========================================================
           ALERT
           ========================================================= */

.document-rejection {
    margin-top: 12px;
    padding: 12px 14px;
    border-radius: 12px;
    background: #fff3f3;
    border: 1px solid #f1d0d0;
    color: #8e3030;
    font-size: .76rem;
    line-height: 1.5;
}

    .document-rejection strong {
        font-weight: 850;
    }



/* =========================================================
   SWIFTCARE MODAL BACKDROP
   Soft glass blur instead of dark Bootstrap overlay
   ========================================================= */
.modal-backdrop {
    background: rgba(240, 253, 244, 0.18) !important;
    backdrop-filter: blur(10px) saturate(115%) !important;
    -webkit-backdrop-filter: blur(10px) saturate(115%) !important;
}

.modal-backdrop.show {
    opacity: 1 !important;
}

/* Keep the page visible through the glass */
body.modal-open .onboarding-review-page {
    filter: none !important;
}

/* =========================================================
   MODAL
   ========================================================= */


.swift-modal {
    width: 100%;
    max-width: 540px;
    margin: 0 auto;
    /* SwiftCare forest-green border */
    border: 2px solid #1B5E20 !important;
    border-radius: 24px !important;
    overflow: hidden;
    background: linear-gradient( 145deg, rgba(255, 255, 255, .96), rgba(240, 253, 244, .93) ) !important;
    box-shadow: 0 30px 90px rgba(18, 65, 22, .18), 0 8px 30px rgba(46, 125, 50, .08), inset 0 1px 0 rgba(255,255,255,.95) !important;
    backdrop-filter: blur(24px);
    -webkit-backdrop-filter: blur(24px);
}

/* =========================================================
   MODAL HEADER
   ========================================================= */
.swift-modal .modal-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 19px 21px;
    border-bottom: 1px solid rgba(46, 125, 50, .10);
    background: linear-gradient( 135deg, rgba(240, 253, 244, .90), rgba(220, 237, 200, .62) );
}

    .swift-modal .modal-title {
        display: flex;
        align-items: center;
        color: #124116;
        font-size: 1rem;
        font-weight: 900;
    }

        .swift-modal .modal-title i {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            width: 36px;
            height: 36px;
            margin-right: 9px;
            border-radius: 11px;
            background: #e4f4d7;
            border: 1px solid #cde6bd;
            color: #23752c;
        }

    /* Softer close button */
    .swift-modal .btn-close {
        width: 34px;
        height: 34px;
        margin: 0;
        border-radius: 10px;
        background-color: rgba(255,255,255,.75);
        opacity: 1;
        transition: background .2s ease, transform .2s ease;
    }

        .swift-modal .btn-close:hover {
            background-color: #e7f5df;
            transform: rotate(4deg);
        }

    /* =========================================================
   MODAL BODY
   IMPORTANT: EVERYTHING STACKS VERTICALLY
   ========================================================= */

    .swift-modal .modal-body {
        display: flex;
        flex-direction: column;
        gap: 19px;
        padding: 22px;
    }

        /* Every form group becomes its own vertical block */
        .swift-modal .modal-body > div {
            width: 100%;
        }

/* =========================================================
   FORM LABELS
   ========================================================= */

.swift-form-label {
    display: block;
    margin-bottom: 8px;
    color: #31563d;
    font-size: .72rem;
    font-weight: 900;
    letter-spacing: .07em;
    text-transform: uppercase;
}

/* =========================================================
   FORM CONTROLS
   ========================================================= */

.swift-form-control,
.swift-form-select {
    display: block;
    width: 100% !important;
    border: 1px solid #d5e5d2 !important;
    border-radius: 13px !important;
    background: rgba(255,255,255,.82) !important;
    color: #234b31 !important;
    font-size: .84rem;
    font-weight: 600;
    box-shadow: inset 0 1px 2px rgba(27,94,32,.025) !important;
    transition: border-color .2s ease, box-shadow .2s ease, background .2s ease;
}

.swift-form-select {
    min-height: 47px;
    padding: 10px 13px;
}

.swift-form-control {
    min-height: 125px;
    padding: 12px 13px;
    resize: vertical;
    line-height: 1.5;
}

    .swift-form-control::placeholder {
        color: #9aa69e;
        font-weight: 500;
    }

    .swift-form-control:focus,
    .swift-form-select:focus {
        border-color: #7dbb56 !important;
        background: rgba(255,255,255,.96) !important;
        box-shadow: 0 0 0 4px rgba(139,195,74,.12), 0 5px 18px rgba(46,125,50,.05) !important;
        outline: none !important;
    }

/* =========================================================
   MODAL FOOTER
   ========================================================= */

.swift-modal .modal-footer {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: 9px;
