/* =============================================================
   TASK DETAILS MODAL ACTION BUTTONS
   ============================================================= */

.vp-task-details-actions {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: 12px;
    margin-top: 28px;
    padding-top: 20px;
    border-top: 1px solid var(--vp-gray-200);
}


/* =============================================================
   CLOSE BUTTON
   ============================================================= */

.vp-task-close-button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    min-height: 46px;
    padding: 0 20px;
    border: 1px solid var(--vp-gray-300);
    border-radius: 12px;
    background: var(--vp-white);
    color: var(--vp-gray-700);
    font-size: 0.88rem;
    font-weight: 800;
    cursor: pointer;
    transition: background 0.2s ease, border-color 0.2s ease, color 0.2s ease, transform 0.2s ease, box-shadow 0.2s ease;
}

    .vp-task-close-button i {
        font-size: 0.9rem;
    }

    .vp-task-close-button:hover {
        background: var(--vp-gray-100);
        border-color: var(--vp-gray-400);
        color: var(--vp-black);
        transform: translateY(-1px);
        box-shadow: var(--vp-shadow-small);
    }

    .vp-task-close-button:active {
        transform: translateY(0);
    }


/* =============================================================
   REMOVE TASK BUTTON
   ============================================================= */

.vp-task-remove-button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    min-height: 46px;
    padding: 0 20px;
    border: 1px solid #fecaca;
    border-radius: 12px;
    background: #fff1f2;
    color: var(--vp-red);
    font-size: 0.88rem;
    font-weight: 800;
    cursor: pointer;
    transition: background 0.2s ease, border-color 0.2s ease, color 0.2s ease, transform 0.2s ease, box-shadow 0.2s ease;
}

    .vp-task-remove-button i {
        font-size: 0.95rem;
    }

    .vp-task-remove-button:hover {
        background: var(--vp-red-soft);
        border-color: #fca5a5;
        color: #b91c1c;
        transform: translateY(-1px);
        box-shadow: 0 8px 22px rgba(220, 38, 38, 0.12);
    }

    .vp-task-remove-button:active {
        transform: translateY(0);
    }

    .vp-task-remove-button:disabled {
        opacity: 0.6;
        cursor: not-allowed;
        transform: none;
        box-shadow: none;
    }


    /* =============================================================
   REMOVE BUTTON LOADING STATE
   ============================================================= */

    .vp-task-remove-button.is-loading {
        pointer-events: none;
        opacity: 0.7;
    }

        .vp-task-remove-button.is-loading i {
            animation: vp-remove-spin 0.8s linear infinite;
        }

@keyframes vp-remove-spin {
    from {
        transform: rotate(0deg);
    }

    to {
        transform: rotate(360deg);
    }
}


