.sc-volunteer-schedule-body {
    padding: 1.15rem;
}

.sc-schedule-section {
    margin-bottom: 1rem;
}

.sc-schedule-label {
    display: block;
    margin-bottom: 0.5rem;
    color: #6b7280;
    font-size: 0.7rem;
    font-weight: 800;
    letter-spacing: 0.08em;
}

.sc-current-shift {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
    padding: 0.9rem;
    border-radius: 12px;
    background: #f0fdf4;
    border: 1px solid #d5e7d6;
}

.sc-shift-time {
    color: #124116;
    font-weight: 700;
    font-size: 0.95rem;
}

    .sc-shift-time i {
        margin-right: 0.3rem;
    }

.sc-day-off {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.9rem;
    border-radius: 12px;
    background: #f8faf8;
    color: #6b7280;
    font-size: 0.88rem;
}

.sc-schedule-stats {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 0.6rem;
    margin-bottom: 1rem;
}

    .sc-schedule-stats > div {
        padding: 0.75rem;
        border-radius: 12px;
        background: #f8faf8;
        text-align: center;
    }

    .sc-schedule-stats strong {
        display: block;
        color: #1b5e20;
        font-size: 1.1rem;
    }

    .sc-schedule-stats span {
        display: block;
        margin-top: 0.15rem;
        color: #6b7280;
        font-size: 0.7rem;
    }

.sc-roster-summary {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.85rem;
    border: 1px solid #d5e7d6;
    border-radius: 12px;
}

.sc-roster-icon {
    width: 38px;
    height: 38px;
    border-radius: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #dc edc8;
    color: #1b5e20;
    flex-shrink: 0;
}

.sc-roster-summary > div:nth-child(2) {
    min-width: 0;
    flex: 1;
}

.sc-roster-summary strong {
    display: block;
    color: #124116;
    font-size: 0.84rem;
}

.sc-roster-summary span {
    display: block;
    color: #6b7280;
    font-size: 0.72rem;
    margin-top: 0.15rem;
}

.sc-volunteer-schedule-footer {
    display: flex;
    gap: 0.6rem;
    padding: 0 1.15rem 1.15rem;
}

    .sc-volunteer-schedule-footer .sc-onboarding-review-button {
        flex: 1;
        justify-content: center;
    }

/* ============================================================
   WEEKLY ROSTER
   ============================================================ */

.sc-week-navigation {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
    margin-bottom: 1.25rem;
}

.sc-week-navigation-info {
    text-align: center;
}

    .sc-week-navigation-info strong {
        display: block;
        color: #124116;
        font-size: 1.1rem;
    }

    .sc-week-navigation-info span {
        color: #6b7280;
        font-size: 0.8rem;
    }

.sc-roster-week-grid {
    display: grid;
    grid-template-columns: repeat(7, minmax(150px, 1fr));
    gap: 0.75rem;
    overflow-x: auto;
}

.sc-roster-day {
    min-width: 150px;
    padding: 0.9rem;
    background: rgba(255, 255, 255, 0.9);
    border: 1px solid #d5e7d6;
    border-radius: 15px;
}

.sc-roster-day-header {
    margin-bottom: 0.8rem;
}

.sc-roster-day-name {
    display: block;
    color: #1b5e20;
    font-size: 0.72rem;
    font-weight: 800;
    text-transform: uppercase;
}

.sc-roster-day-date {
    display: block;
    margin-top: 0.15rem;
    color: #124116;
    font-size: 1rem;
    font-weight: 700;
}

.sc-roster-shift {
    padding: 0.8rem;
    border-radius: 12px;
    background: #f0fdf4;
}

.sc-roster-shift-time {
    color: #124116;
    font-size: 0.82rem;
    font-weight: 700;
}

.sc-roster-shift-status {
    margin-top: 0.35rem;
    color: #6b7280;
    font-size: 0.7rem;
}

.sc-roster-task-list {
    margin-top: 0.75rem;
}

.sc-roster-task {
    padding: 0.65rem;
    margin-top: 0.45rem;
    border-radius: 9px;
    background: white;
    border: 1px solid #e5eee6;
}

.sc-roster-task-title {
    color: #124116;
    font-size: 0.75rem;
    font-weight: 700;
}

.sc-roster-task-time {
    margin-top: 0.2rem;
    color: #6b7280;
    font-size: 0.67rem;
}

.sc-roster-task-priority {
    display: inline-block;
    margin-top: 0.3rem;
    color: #1b5e20;
    font-size: 0.64rem;
    font-weight: 700;
}

.sc-roster-empty {
    padding: 1rem 0.5rem;
    color: #9ca3af;
    text-align: center;
    font-size: 0.75rem;
}

@media (max-width: 900px) {
    .sc-roster-week-grid {
        grid-template-columns: repeat(7, 150px);
    }
}

@media (max-width: 600px) {
    .sc-volunteer-schedule-grid {
        grid-template-columns: 1fr;
    }

    .sc-volunteer-schedule-footer {
        flex-direction: column;
    }

    .sc-schedule-stats {
        gap: 0.4rem;
    }
}

/* ============================================================
   TODAY'S VOLUNTEER ACTIVITIES
   ============================================================ */

.nurse-activities-list {
    display: flex;
    flex-direction: column;
    gap: 12px;
    margin-top: 18px;
}

.nurse-activity-item {
    display: flex;
    align-items: stretch;
    gap: 18px;
    padding: 18px;
    background: #F0FDF4;
    border: 1px solid #D5E7D6;
    border-radius: 14px;
    transition: all 0.2s ease;
}

    .nurse-activity-item:hover {
        transform: translateY(-1px);
        box-shadow: 0 6px 18px rgba(27, 94, 32, 0.08);
    }


/* ============================================================
   ACTIVITY TIME
   ============================================================ */

.nurse-activity-time {
    min-width: 115px;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    padding: 10px 14px;
    background: #DCEDC8;
    border-radius: 10px;
    color: #1B5E20;
    font-size: 14px;
    font-weight: 700;
    white-space: nowrap;
}

    .nurse-activity-time span {
        line-height: 1.5;
    }


/* ============================================================
   ACTIVITY MAIN CONTENT
   ============================================================ */

.nurse-activity-main {
    flex: 1;
    min-width: 0;
    display: flex;
    flex-direction: column;
    justify-content: center;
}

.nurse-activity-title {
    display: flex;
    align-items: center;
    gap: 9px;
    color: #124116;
    font-size: 16px;
    font-weight: 700;
    margin-bottom: 6px;
}

    .nurse-activity-title i {
        color: #2E7D32;
        font-size: 17px;
    }

.nurse-activity-description {
    color: #607564;
    font-size: 13px;
    line-height: 1.5;
    margin-bottom: 10px;
}


/* ============================================================
   VOLUNTEER / LOCATION INFORMATION
   ============================================================ */

.nurse-activity-meta {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 14px;
    color: #607564;
    font-size: 12px;
}

    .nurse-activity-meta span {
        display: inline-flex;
        align-items: center;
        gap: 5px;
    }

    .nurse-activity-meta i {
        color: #2E7D32;
        font-size: 13px;
    }


/* ============================================================
   STATUS / PRIORITY
   ============================================================ */

.nurse-activity-side {
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    justify-content: center;
    gap: 8px;
    min-width: 105px;
}

.nurse-activity-priority,
.nurse-activity-status {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 5px 11px;
    border-radius: 999px;
    font-size: 11px;
    font-weight: 700;
    white-space: nowrap;
}

.nurse-activity-priority {
    background: #DCEDC8;
    color: #1B5E20;
}

.nurse-activity-status {
    background: #E8F5E9;
    color: #2E7D32;
}


/* ============================================================
   RESPONSIVE
   ============================================================ */

@media (max-width: 768px) {

    .nurse-activity-item {
        flex-direction: column;
        gap: 12px;
    }

    .nurse-activity-time {
        min-width: 0;
        width: fit-content;
        flex-direction: row;
        gap: 5px;
    }

    .nurse-activity-side {
        flex-direction: row;
        align-items: center;
        justify-content: flex-start;
        min-width: 0;
    }
}

/* ============================================================
   VOLUNTEER ATTENDANCE — FULL-WIDTH TABLE
   ============================================================ */

.vp-attendance-section,
.vp-attendance-card {
    width: 100%;
    max-width: 100%;
    min-width: 0;
    box-sizing: border-box;
}

.vp-attendance-list {
    display: block;
    width: 100%;
}

.vp-attendance-item {
    width: 100%;
    max-width: 100%;
    box-sizing: border-box;
}

/* Table container */
.vp-attendance-table-wrapper {
    width: 100%;
    overflow-x: auto;
    padding: 0 22px 24px;
    box-sizing: border-box;
}

/* Main table */
.vp-attendance-table {
    width: 100%;
    min-width: 950px;
    border-collapse: separate;
    border-spacing: 0;
    font-size: 13px;
    text-align: left;
}

    .vp-attendance-table thead {
        background: #f0fdf4;
    }

    .vp-attendance-table th {
        padding: 17px 16px;
        color: #1b5e20;
        font-size: 11px;
        font-weight: 800;
        letter-spacing: 0.6px;
        text-transform: uppercase;
        border-top: 1px solid #d5e7d6;
        border-bottom: 1px solid #d5e7d6;
        white-space: nowrap;
    }

        .vp-attendance-table th:first-child {
            border-left: 1px solid #d5e7d6;
            border-top-left-radius: 12px;
        }

        .vp-attendance-table th:last-child {
            border-right: 1px solid #d5e7d6;
            border-top-right-radius: 12px;
        }

    .vp-attendance-table td {
        padding: 18px 16px;
        color: #124116;
        font-weight: 600;
        vertical-align: middle;
        border-bottom: 1px solid #e5eee6;
    }

    .vp-attendance-table tbody tr {
        transition: background 0.2s ease;
    }

        .vp-attendance-table tbody tr:hover {
            background: #f6fcf4;
        }

        .vp-attendance-table tbody tr:last-child td {
            border-bottom: 0;
        }

/* Date */
.vp-attendance-date {
    display: block;
    font-weight: 800;
    color: #124116;
}

.vp-attendance-day {
    display: block;
    margin-top: 4px;
    color: #748675;
    font-size: 11px;
    font-weight: 500;
}

/* Shift time */
.vp-attendance-shift-time {
    white-space: nowrap;
    font-weight: 750;
}

/* Status badges */
.vp-attendance-status {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 7px 12px;
    border-radius: 999px;
    font-size: 11px;
    font-weight: 800;
    white-space: nowrap;
    background: #e8f5e9;
    color: #1b5e20;
}

.vp-attendance-status-late {
    background: #fff3cd;
    color: #946200;
}

.vp-attendance-status-absent {
    background: #ffebee;
    color: #b71c1c;
}

.vp-attendance-status-checkedout {
    background: #e8f5e9;
    color: #2e7d32;
}

/* Verification indicators */
.vp-attendance-verified {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    color: #2e7d32;
    font-size: 12px;
    font-weight: 750;
}

.vp-attendance-not-verified {
    color: #87948a;
    font-size: 12px;
}

/* Mobile horizontal scrolling */
@media (max-width: 900px) {
    .vp-attendance-table-wrapper {
        padding: 0 14px 18px;
    }

    .vp-attendance-table {
        min-width: 950px;
    }
}

/* ============================================================
   VOLUNTEER PROFILE — STATUS PILL
   ============================================================ */

.vp-status-pill {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 7px;

    padding: 8px 15px;

    min-height: 32px;

    border-radius: 999px;

    font-size: 11px;
    font-weight: 800;

    letter-spacing: 0.35px;
    line-height: 1;

    white-space: nowrap;

    border: 1px solid transparent;

    box-sizing: border-box;
}


/* ============================================================
   STATUS ICON
   ============================================================ */

.vp-status-pill i {
    font-size: 13px;
    line-height: 1;
}


/* ============================================================
   NO SHIFT TODAY
   ============================================================ */

.vp-status-pending {
    background: #f3f6f3;
    color: #657568;
    border-color: #dce5dd;
}


/* ============================================================
   SHIFT NOT STARTED
   ============================================================ */

.vp-status-shift-not-started {
    background: #e8f1ff;
    color: #315f91;
    border-color: #c9dcf5;
}


/* ============================================================
   NOT CHECKED IN
   ============================================================ */

.vp-status-not-checked-in {
    background: #fff8e1;
    color: #8a6d1d;
    border-color: #f5df9a;
}


/* ============================================================
   CHECKED IN / PRESENT
   ============================================================ */

.vp-status-completed {
    background: #e8f5e9;
    color: #2e7d32;
    border-color: #c8e6c9;
}


/* ============================================================
   LATE
   ============================================================ */

.vp-status-late {
    background: #fff3cd;
    color: #946200;
    border-color: #ffe08a;
}


/* ============================================================
   CHECKED OUT
   ============================================================ */

.vp-status-checked-out {
    background: #e0f2f1;
    color: #00695c;
    border-color: #b2dfdb;
}


/* ============================================================
   ABSENT
   ============================================================ */

.vp-status-absent {
    background: #ffebee;
    color: #b71c1c;
    border-color: #ffcdd2;
}

.scv-proctoring-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 20px;
    padding: 12px 18px;
    border-bottom: 1px solid #d5e7d6;
    background: #f8fcf8;
}

.scv-proctoring-camera,
.scv-proctoring-status {
    display: flex;
    align-items: center;
    gap: 11px;
}

.scv-proctoring-camera-preview {
    width: 62px;
    height: 44px;
    overflow: hidden;
    border-radius: 9px;
    background: #102015;
}

#scvCameraPreview {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transform: scaleX(-1);
}

.scv-proctoring-camera strong,
.scv-proctoring-status strong {
    display: block;
    color: #124116;
    font-size: 12px;
}

.scv-proctoring-camera span,
.scv-proctoring-status span {
    display: block;
    margin-top: 2px;
    color: #68756d;
    font-size: 11px;
}

.scv-proctoring-status {
    padding-left: 18px;
    border-left: 1px solid #d5e7d6;
}

.scv-proctoring-indicator {
    width: 32px;
    height: 32px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    background: #DCEDC8;
    color: #1B5E20;
}

    .scv-proctoring-indicator.scv-warning {
        background: #fff1d6;
        color: #a36b00;
    }

    .scv-proctoring-indicator.scv-danger {
        background: #fce8e8;
        color: #a12626;
    }

.scv-suspicious-overlay {
    position: fixed;
    inset: 0;
    z-index: 99999;
    display: none;
    align-items: center;
    justify-content: center;
    padding: 20px;
    background: rgba(9, 27, 14, 0.86);
    backdrop-filter: blur(7px);
}

    .scv-suspicious-overlay.scv-visible {
        display: flex;
    }

.scv-suspicious-card {
    width: 100%;
    max-width: 460px;
    padding: 35px;
    text-align: center;
    border-radius: 22px;
    background: white;
    box-shadow: 0 25px 70px rgba(0, 0, 0, 0.3);
}

.scv-suspicious-icon {
    width: 65px;
    height: 65px;
    margin: 0 auto 18px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    background: #fce8e8;
    color: #a12626;
    font-size: 28px;
}

.scv-suspicious-card h2 {
    margin: 0 0 10px;
    color: #18351e;
}

.scv-suspicious-card p {
    margin: 0;
    color: #617067;
    line-height: 1.7;
}

.scv-suspicious-status {
    margin-top: 20px;
    padding: 12px;
    border-radius: 10px;
    background: #f4f8f5;
    color: #526158;
    font-size: 13px;
}

@media (max-width: 650px) {

    .scv-proctoring-bar {
        align-items: flex-start;
        flex-direction: column;
    }

    .scv-proctoring-status {
        padding-left: 0;
        border-left: 0;
    }
}
.voice-interview-video-notice,
.voice-interview-proctoring-notice {
    display: flex;
    gap: 18px;
    align-items: flex-start;
    padding: 20px;
    margin-bottom: 18px;
    border-radius: 18px;
}

.voice-interview-video-notice {
    background: #F0FDF4;
    border: 1px solid #D5E7D6;
}

.voice-interview-proctoring-notice {
    background: #f8fafc;
    border: 1px solid #dbe4ea;
}

.voice-interview-video-notice-icon,
.voice-interview-proctoring-icon {
    width: 46px;
    height: 46px;
    min-width: 46px;
