.voice-interview-video-notice-icon {
    background: #DCEDC8;
    color: #1B5E20;
}

.voice-interview-proctoring-icon {
    background: #e8eef2;
    color: #124116;
}

.voice-interview-video-notice-content,
.voice-interview-proctoring-content {
    display: flex;
    flex-direction: column;
    gap: 6px;
}

    .voice-interview-video-notice-content strong,
    .voice-interview-proctoring-content strong {
        color: #124116;
        font-size: 16px;
    }

    .voice-interview-video-notice-content span,
    .voice-interview-proctoring-content span {
        color: #5d6b62;
        line-height: 1.6;
        font-size: 14px;
    }

.voice-interview-camera-section {
    margin-top: 28px;
    padding: 22px;
    border: 1px solid #D5E7D6;
    border-radius: 20px;
    background: #ffffff;
}

.voice-interview-camera-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 20px;
    margin-bottom: 18px;
}

    .voice-interview-camera-header > div {
        display: flex;
        flex-direction: column;
        gap: 5px;
    }

    .voice-interview-camera-header strong {
        color: #124116;
        font-size: 16px;
    }

    .voice-interview-camera-header span {
        color: #68756d;
        font-size: 13px;
    }

.voice-interview-camera-status {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    padding: 8px 12px;
    border-radius: 999px;
    font-size: 12px !important;
    font-weight: 600;
    white-space: nowrap;
}

    .voice-interview-camera-status.pending {
        background: #f1f5f3;
        color: #66736b;
    }

    .voice-interview-camera-status.success {
        background: #DCEDC8;
        color: #1B5E20;
