    font-size: 11px;
    display: flex;
    align-items: center;
    gap: 5px;
}

/* ============================================================
       VOICE LINE
       ============================================================ */

.scv-voice-line {
    display: flex;
    align-items: center;
    gap: 9px;
    margin-top: 10px;
}

.scv-play {
    width: 38px;
    height: 38px;
    min-width: 38px;
    border: none;
    border-radius: 50%;
    background: #2E7D32;
    color: white;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: all 0.2s ease;
}

    .scv-play:hover {
        background: #1B5E20;
        transform: scale(1.04);
    }

    .scv-play:focus-visible,
    .scv-text-send-button:focus-visible,
    .scv-text-response-input:focus-visible {
        outline: 3px solid rgba(139, 195, 74, 0.45);
        outline-offset: 2px;
    }

.scv-wave {
    display: flex;
    align-items: center;
    gap: 3px;
    height: 28px;
    flex: 1;
    max-width: 160px;
}

    .scv-wave span {
        display: block;
        width: 3px;
        height: 7px;
        border-radius: 5px;
        background: #8BC34A;
        transition: height 0.15s ease;
    }

    .scv-wave.scv-speaking span:nth-child(1) {
        animation: scvWave 0.65s infinite ease-in-out;
    }

    .scv-wave.scv-speaking span:nth-child(2) {
        animation: scvWave 0.65s 0.08s infinite ease-in-out;
    }

    .scv-wave.scv-speaking span:nth-child(3) {
        animation: scvWave 0.65s 0.16s infinite ease-in-out;
    }

    .scv-wave.scv-speaking span:nth-child(4) {
        animation: scvWave 0.65s 0.24s infinite ease-in-out;
    }

    .scv-wave.scv-speaking span:nth-child(5) {
        animation: scvWave 0.65s 0.32s infinite ease-in-out;
    }

    .scv-wave.scv-speaking span:nth-child(6) {
        animation: scvWave 0.65s 0.40s infinite ease-in-out;
    }

    .scv-wave.scv-speaking span:nth-child(7) {
        animation: scvWave 0.65s 0.48s infinite ease-in-out;
    }

    .scv-wave.scv-speaking span:nth-child(8) {
        animation: scvWave 0.65s 0.40s infinite ease-in-out;
    }

    .scv-wave.scv-speaking span:nth-child(9) {
        animation: scvWave 0.65s 0.32s infinite ease-in-out;
    }

    .scv-wave.scv-speaking span:nth-child(10) {
        animation: scvWave 0.65s 0.24s infinite ease-in-out;
    }

    .scv-wave.scv-speaking span:nth-child(11) {
        animation: scvWave 0.65s 0.16s infinite ease-in-out;
    }

    .scv-wave.scv-speaking span:nth-child(12) {
        animation: scvWave 0.65s 0.08s infinite ease-in-out;
    }

@keyframes scvWave {
    0%, 100% {
        height: 7px;
    }

    50% {
        height: 24px;
    }
}

.scv-duration {
    color: #6b7280;
    font-size: 12px;
    white-space: nowrap;
}

