.sir-integrity-log-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 15px;
}

.sir-integrity-log-kicker {
    display: block;
    margin-bottom: 4px;
    color: #6b836f;
    font-size: 0.68rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
}

.sir-integrity-log-header h3 {
    margin: 0;
    color: #124116;
    font-size: 1.15rem;
    font-weight: 700;
}

.sir-integrity-event-count {
    padding: 7px 12px;
    border-radius: 999px;
    background: #DCEDC8;
    color: #1B5E20;
    font-size: 0.72rem;
    font-weight: 700;
}


/* ============================================================
   EVENT LOG
   ============================================================ */

.sir-proctoring-log {
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.sir-proctoring-event {
    display: flex;
    gap: 15px;
    padding: 17px;
    background: #ffffff;
    border: 1px solid #e1ebe2;
    border-left: 4px solid #8BC34A;
    border-radius: 14px;
    transition: box-shadow 0.2s ease, transform 0.2s ease;
}

    .sir-proctoring-event:hover {
        transform: translateX(2px);
        box-shadow: 0 7px 18px rgba(27, 94, 32, 0.07);
    }


    /* Event types */

    .sir-proctoring-event.sir-event-warning {
        border-left-color: #8BC34A;
    }

    .sir-proctoring-event.sir-event-danger {
        border-left-color: #c62828;
        background: #fffdfd;
    }

    .sir-proctoring-event.sir-event-default {
        border-left-color: #2E7D32;
    }


/* ============================================================
   EVENT ICON
   ============================================================ */

.sir-proctoring-event-icon {
    flex-shrink: 0;
    width: 42px;
    height: 42px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 12px;
    background: #F0FDF4;
    color: #2E7D32;
    font-size: 18px;
}

.sir-event-danger .sir-proctoring-event-icon {
    background: #fdecec;
    color: #c62828;
}

.sir-event-warning .sir-proctoring-event-icon {
    background: #f2f8e9;
    color: #5d7d24;
}


/* ============================================================
   EVENT CONTENT
   ============================================================ */

.sir-proctoring-event-content {
    min-width: 0;
    flex: 1;
}

.sir-proctoring-event-top {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 15px;
}

    .sir-proctoring-event-top > div {
        display: flex;
        align-items: center;
        flex-wrap: wrap;
        gap: 8px;
    }

    .sir-proctoring-event-top strong {
        color: #124116;
        font-size: 0.9rem;
    }

    .sir-proctoring-event-top span {
        padding: 4px 8px;
        background: #F0FDF4;
        border: 1px solid #D5E7D6;
        border-radius: 6px;
        color: #53705a;
        font-size: 0.67rem;
        font-weight: 600;
    }

    .sir-proctoring-event-top time {
        flex-shrink: 0;
        color: #7b8d7e;
        font-size: 0.7rem;
    }

.sir-proctoring-event-content > p {
    margin: 8px 0 10px;
    color: #56695a;
    font-size: 0.82rem;
    line-height: 1.55;
}

.sir-event-no-description {
    color: #98a69b !important;
    font-style: italic;
}


/* ============================================================
   EVENT META
   ============================================================ */

.sir-proctoring-event-meta {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
}

    .sir-proctoring-event-meta span {
        display: inline-flex;
        align-items: center;
        gap: 5px;
        padding: 5px 8px;
        background: #f7faf7;
        border: 1px solid #e5ece6;
        border-radius: 7px;
        color: #718175;
        font-size: 0.68rem;
    }

    .sir-proctoring-event-meta i {
        color: #2E7D32;
    }


/* ============================================================
   EMPTY STATE
   ============================================================ */

.sir-integrity-empty {
    padding: 45px 20px;
    text-align: center;
    background: #F0FDF4;
    border: 1px dashed #c8ddca;
    border-radius: 16px;
}

.sir-integrity-empty-icon {
    width: 58px;
    height: 58px;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 auto 15px;
    border-radius: 50%;
    background: #DCEDC8;
    color: #2E7D32;
    font-size: 25px;
}

.sir-integrity-empty h3 {
    margin-bottom: 7px;
    color: #124116;
    font-size: 1rem;
}

.sir-integrity-empty p {
    max-width: 550px;
    margin: 0 auto;
    color: #718175;
    font-size: 0.82rem;
    line-height: 1.6;
}


/* ============================================================
   RESPONSIVE
   ============================================================ */

@media (max-width: 1200px) {

    .sir-integrity-summary {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }
}

@media (max-width: 768px) {

    .sir-integrity-summary {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .sir-integrity-warning {
        align-items: flex-start;
    }

    .sir-proctoring-event-top {
        flex-direction: column;
        gap: 7px;
    }

