/* =========================================================
       ATTENDANCE LOCATION BUTTON
       ========================================================= */

.vp-attendance-location-button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 7px;
    min-width: 76px;
    padding: 8px 12px;
    border: 1px solid rgba(46, 125, 50, 0.20);
    border-radius: 10px;
    background: rgba(240, 253, 244, 0.90);
    color: #1B5E20;
    font-size: 0.78rem;
    font-weight: 700;
    cursor: pointer;
    transition: transform 0.18s ease, box-shadow 0.18s ease, background 0.18s ease, border-color 0.18s ease;
}

    .vp-attendance-location-button:hover {
        transform: translateY(-1px);
        background: #DCEDC8;
        border-color: rgba(46, 125, 50, 0.35);
        box-shadow: 0 8px 20px rgba(27, 94, 32, 0.12);
    }

    .vp-attendance-location-button:active {
        transform: translateY(0);
    }

    .vp-attendance-location-button i {
        font-size: 0.95rem;
    }


/* =========================================================
       MODAL
       ========================================================= */

.vp-attendance-location-modal {
    position: fixed;
    inset: 0;
    z-index: 99999;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 24px;
    opacity: 0;
    visibility: hidden;
    pointer-events: none;
    transition: opacity 0.22s ease, visibility 0.22s ease;
}

    .vp-attendance-location-modal.vp-attendance-location-visible {
        opacity: 1;
        visibility: visible;
        pointer-events: auto;
    }


/* =========================================================
       BLURRY BACKDROP
       ========================================================= */

.vp-attendance-location-backdrop {
    position: absolute;
    inset: 0;
    background: rgba(6, 30, 12, 0.42);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    cursor: pointer;
}


/* =========================================================
       DIALOG
       ========================================================= */

.vp-attendance-location-dialog {
    position: relative;
    z-index: 2;
    width: min(1050px, 96vw);
    height: min(760px, 92vh);
    display: flex;
    flex-direction: column;
    overflow: hidden;
    border: 1px solid rgba(255, 255, 255, 0.60);
    border-radius: 24px;
    background: linear-gradient( 145deg, rgba(255, 255, 255, 0.96), rgba(240, 253, 244, 0.94) );
    box-shadow: 0 30px 90px rgba(0, 0, 0, 0.30), 0 8px 30px rgba(27, 94, 32, 0.16);
    transform: translateY(18px) scale(0.97);
    transition: transform 0.24s ease;
}

.vp-attendance-location-modal.vp-attendance-location-visible
.vp-attendance-location-dialog {
    transform: translateY(0) scale(1);
}


/* =========================================================
       HEADER
       ========================================================= */

.vp-attendance-location-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 20px;
    padding: 22px 24px 18px;
    border-bottom: 1px solid rgba(27, 94, 32, 0.10);
    background: rgba(255, 255, 255, 0.70);
}

.vp-attendance-location-kicker {
    display: block;
    margin-bottom: 4px;
    color: #2E7D32;
    font-size: 0.68rem;
    font-weight: 800;
    letter-spacing: 0.12em;
}

.vp-attendance-location-header h2 {
    margin: 0;
    color: #124116;
    font-size: 1.35rem;
    font-weight: 800;
}

.vp-attendance-location-close {
    width: 40px;
    height: 40px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex: 0 0 auto;
    border: 0;
    border-radius: 12px;
