    border-radius: 16px;
    color: #ffffff;
    box-shadow: 0 10px 25px rgba(3, 53, 36, 0.25), 0 0 0 1px rgba(180, 255, 0, 0.05) inset;
    overflow: hidden;
    transition: transform 0.25s ease, box-shadow 0.25s ease, border-color 0.25s ease;
}


    /* ============================================================
   LIME LIGHT EFFECT
   ============================================================ */

    .sc-track-onboarding-button::before {
        content: "";
        position: absolute;
        top: -80%;
        left: -30%;
        width: 60%;
        height: 260%;
        background: rgba(190, 255, 0, 0.10);
        transform: rotate(25deg);
        transition: left 0.5s ease;
    }


    /* ============================================================
   HOVER
   ============================================================ */

    .sc-track-onboarding-button:hover {
        color: #ffffff;
        text-decoration: none;
        transform: translateY(-3px);
        border-color: rgba(190, 255, 0, 0.75);
        box-shadow: 0 15px 35px rgba(3, 67, 43, 0.35), 0 0 22px rgba(190, 255, 0, 0.12);
    }


        .sc-track-onboarding-button:hover::before {
            left: 120%;
        }


/* ============================================================
   ICON BOX
   ============================================================ */

.sc-track-onboarding-button-icon {
    position: relative;
    z-index: 2;
    flex: 0 0 46px;
    width: 46px;
    height: 46px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 13px;
    background: #b7ff00;
    color: #063b2a;
    box-shadow: 0 6px 16px rgba(183, 255, 0, 0.25);
    transition: transform 0.25s ease, box-shadow 0.25s ease;
}


.sc-track-onboarding-button:hover
.sc-track-onboarding-button-icon {
    transform: scale(1.08) rotate(-3deg);
    box-shadow: 0 8px 22px rgba(183, 255, 0, 0.40);
}


.sc-track-onboarding-button-icon i {
    font-size: 21px;
}


/* ============================================================
   TEXT CONTENT
   ============================================================ */

.sc-track-onboarding-button-content {
    position: relative;
    z-index: 2;
    display: flex;
    flex-direction: column;
    flex: 1;
    text-align: left;
    line-height: 1.2;
}


    .sc-track-onboarding-button-content strong {
        display: block;
        margin-bottom: 5px;
        font-size: 15px;
        font-weight: 800;
        letter-spacing: -0.1px;
        color: #ffffff;
    }


    .sc-track-onboarding-button-content small {
        display: block;
        font-size: 11px;
        font-weight: 500;
        color: rgba(255, 255, 255, 0.68);
        line-height: 1.4;
    }


/* ============================================================
   ARROW
   ============================================================ */

.sc-track-onboarding-arrow {
    position: relative;
    z-index: 2;
    flex: 0 0 36px;
    width: 36px;
    height: 36px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 10px;
    background: rgba(183, 255, 0, 0.12);
    color: #b7ff00;
    font-size: 17px;
    transition: transform 0.25s ease, background 0.25s ease;
}


.sc-track-onboarding-button:hover
.sc-track-onboarding-arrow {
    transform: translateX(5px);
    background: rgba(183, 255, 0, 0.22);
}


/* ============================================================
   ACTIVE / CLICK
   ============================================================ */

.sc-track-onboarding-button:active {
    transform: translateY(-1px) scale(0.99);
}


/* ============================================================
   FOCUS ACCESSIBILITY
   ============================================================ */

.sc-track-onboarding-button:focus-visible {
    outline: none;
    box-shadow: 0 0 0 3px rgba(6, 59, 42, 0.85), 0 0 0 6px rgba(183, 255, 0, 0.75);
}


/* ============================================================
   MOBILE
   ============================================================ */

@media (max-width: 768px) {

    .sc-track-onboarding-action {
        width: 100%;
        margin-top: 18px;
    }

    .sc-track-onboarding-button {
        width: 100%;
        min-width: 0;
    }
}


@media (max-width: 480px) {

    .sc-track-onboarding-button {
        gap: 11px;
        padding: 13px 14px;
        border-radius: 14px;
    }

    .sc-track-onboarding-button-icon {
        flex-basis: 42px;
        width: 42px;
        height: 42px;
    }

    .sc-track-onboarding-button-content strong {
        font-size: 14px;
    }

    .sc-track-onboarding-button-content small {
        font-size: 10px;
    }

    .sc-track-onboarding-arrow {
        flex-basis: 32px;
        width: 32px;
        height: 32px;
    }
}